/*
Shared integer interval domain, premise-ordering oracle, guard narrowing,
ordered values, and mixed-domain and exact-overflow validation
(`proof_contracts::arithmetic_domains`).
*/
pub(crate) mod atomic_observations {
    use super::{ExpressionHandle, Interval, Machine, State};

    pub(crate) fn atomic_resident_interval(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        place: ExpressionHandle,
    ) -> Option<Interval> {
        let reference = crate::declared_place_type_raw(program, machine, state, place)?;
        let primitive = program.primitive_type_reference(reference)?;
        let mut bounds = super::primitive_range(primitive)?;
        if let Some(declared) = super::enforced_declared_range(program, reference) {
            bounds = bounds.intersect(declared);
        }
        if let Some(stated) = state.and_then(|state| {
            crate::proof_contracts::default_domains::stored_field_requires_interval(
                program, machine, state, place,
            )
        }) {
            bounds = bounds.intersect(stated);
        }
        Some(bounds)
    }

    pub(crate) fn atomic_result_interval(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<Interval> {
        let name = program.expression_table.name_path_node(expression)?;
        let (_, local) = program.state_local_declaration(state, name.symbol)?;
        let event = crate::atomic_result_placeholder(program, state, local)?;
        atomic_resident_interval(program, machine, Some(state), event.place)
    }
}
pub(crate) use atomic_observations::{atomic_resident_interval, atomic_result_interval};

pub(crate) mod abstract_shift_count {
    use super::visit_binary_operators;
    use diagnostics::Diagnostic;
    use numerics::arithmetic::ArithmeticDomain;
    use numerics::integer_policy::{IntegerPolicyPrimitive, ShiftCountLaw, integer_policy_bridge};
    use typed_trees::expression::{BinaryOperator, ExpressionHandle};

    use super::ValueEnvironment;
    use super::total_specification::{
        AbstractSpecificationBindings, abstract_specification_builtin_arithmetic,
        abstract_specification_interval, direct_abstract_operand,
    };
    use crate::proof_contracts::arithmetic_domains::integer_ranges::{
        integer_bit_width, primitive_name,
    };

    pub(crate) fn validate(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
        owner: &str,
        bindings: AbstractSpecificationBindings<'_>,
        environment: &ValueEnvironment,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        visit_binary_operators(
            program,
            expression,
            &[BinaryOperator::ShiftLeft, BinaryOperator::ShiftRight],
            |expression, binary| {
                if !abstract_specification_builtin_arithmetic(program, bindings, expression) {
                    return;
                }
                let Some((primitive, domain)) =
                    direct_abstract_operand(program, bindings, expression)
                else {
                    return;
                };
                let shift_primitive_kind = match binary.operator {
                    BinaryOperator::ShiftLeft => IntegerPolicyPrimitive::ShiftLeft,
                    BinaryOperator::ShiftRight => IntegerPolicyPrimitive::ShiftRight,
                    _ => unreachable!("non-shift operator returned above"),
                };
                if integer_policy_bridge(shift_primitive_kind, domain).shift_count_law
                    != ShiftCountLaw::MustBeWithinWidth
                {
                    return;
                }
                let Some(width) = integer_bit_width(primitive) else {
                    return;
                };
                let count =
                    abstract_specification_interval(program, bindings, environment, binary.right);
                let provably_in_range = count.is_some_and(|count| {
                    matches!(count.low(), Some(low) if low >= 0)
                        && matches!(count.high(), Some(high) if high < width)
                });
                if provably_in_range {
                    return;
                }
                let always_out = count.is_some_and(|count| {
                    matches!(count.low(), Some(low) if low >= width)
                        || matches!(count.high(), Some(high) if high < 0)
                });
                let verdict = if always_out {
                    "is provably out of range and can never execute"
                } else {
                    "is not provably below the operand width"
                };
                let saturating_hint = if domain == ArithmeticDomain::Saturating {
                    " (`Saturating` governs value overflow, not count validity -- its count obligation is Exact's)"
                } else {
                    ""
                };
                diagnostics.push(Diagnostic::error(format!(
            "shift count in {owner} {verdict} for `{prim}`{saturating_hint}: exact shifts prove `count < {width}` before the term forms; discharge the count with an independently accepted prior fact, or use `{prim} in Wrapping` for a modulo-{width} count",
            prim = primitive_name(primitive),
        )));
            },
        );
    }
}
pub(crate) mod declared_integer_facts {
    use super::guard_narrowing::projected_facts::{
        ProjectedOperand, contribute_projected_comparison, has_fixed_integer_meaning,
    };
    use super::{ExpressionHandle, ExpressionNode, ValueEnvironment, ordered_values};
    use facts::PlaceSegment;
    use typed_trees::data::DataDefinition;
    use typed_trees::expression::BinaryOperator;
    use typed_trees::types::TypeReferenceHandle;

    pub(crate) fn record_admitted_integer_fields(
        program: &dyn crate::CheckingInput,
        environment: &mut ValueEnvironment,
        subject: &ordered_values::Operand,
        reference: TypeReferenceHandle,
    ) {
        collect(program, environment, subject, reference, &mut Vec::new());
    }

    fn collect(
        program: &dyn crate::CheckingInput,
        environment: &mut ValueEnvironment,
        subject: &ordered_values::Operand,
        reference: TypeReferenceHandle,
        active: &mut Vec<TypeReferenceHandle>,
    ) {
        let Some(reference) = crate::field_domains::readable_type_reference(program, reference)
        else {
            return;
        };
        let Some(definition) =
            crate::field_domains::readable_nominal_definition(program, reference)
        else {
            return;
        };
        if active.contains(&reference) {
            return;
        }
        active.push(reference);
        for fact in program.proof_facts.span_or_empty(definition.requires_facts) {
            if let Some(expression) = fact.as_expression() {
                contribute(
                    program,
                    environment,
                    definition,
                    reference,
                    subject,
                    *expression,
                );
            }
        }
        for field in program
            .data_members(definition)
            .iter()
            .filter_map(|member| member.as_field())
        {
            let segments = [PlaceSegment::Field {
                symbol: field.symbol,
            }];
            let Some(child_type) =
                crate::project_type_reference_from_segments(program, reference, &segments)
            else {
                continue;
            };
            if crate::reference_shell(program, child_type).is_some() {
                continue;
            }
            let child = ordered_values::Operand::Field {
                receiver: Box::new(subject.clone()),
                field: field.symbol,
                name: field.name.as_str().to_owned(),
                primitive: program.primitive_type_reference(child_type),
            };
            collect(program, environment, &child, child_type, active);
        }
        active.pop();
    }

    fn contribute(
        program: &dyn crate::CheckingInput,
        environment: &mut ValueEnvironment,
        definition: &DataDefinition,
        reference: TypeReferenceHandle,
        subject: &ordered_values::Operand,
        expression: ExpressionHandle,
    ) {
        let Some(binary) = program.expression_table.binary_node(expression) else {
            return;
        };
        if binary.operator == BinaryOperator::And {
            for conjunct in [binary.left, binary.right] {
                contribute(
                    program,
                    environment,
                    definition,
                    reference,
                    subject,
                    conjunct,
                );
            }
            return;
        }
        let (Some(left), Some(right)) = (
            side(program, definition, reference, subject, binary.left),
            side(program, definition, reference, subject, binary.right),
        ) else {
            return;
        };
        let Some(spelling) = typed_trees::operator::comparison_operator_spelling(binary.operator)
        else {
            return;
        };
        if !typed_trees::operator::has_builtin_spelled_expression_meaning(
            program,
            definition.symbol,
            expression,
            spelling,
            &[left.declared_type, right.declared_type],
        ) {
            return;
        }
        contribute_projected_comparison(
            program,
            environment,
            binary.operator,
            (&left, binary.left),
            (&right, binary.right),
        );
    }

    fn side(
        program: &dyn crate::CheckingInput,
        definition: &DataDefinition,
        reference: TypeReferenceHandle,
        subject: &ordered_values::Operand,
        expression: ExpressionHandle,
    ) -> Option<ProjectedOperand> {
        if let ExpressionNode::Integer(literal) = program.expression_table.expression(expression) {
            if literal.landing().is_some_and(|landing| {
                landing.landed_type == numerics::literals::LandedIntegerType::Addr
            }) {
                return None;
            }
            let mut result = ProjectedOperand::literal(literal);
            result.declared_type =
                crate::landed_integer_literal_type_reference(program, expression);
            return Some(result);
        }
        let place = crate::canonical_place_from_expression(program, expression)?;
        let root = place.root.as_symbol()?;
        let segments = if root == definition.predicate_subject_symbol
            && definition.predicate_subject_symbol.is_valid()
        {
            place.segments
        } else if place.segments.is_empty() {
            vec![PlaceSegment::Field { symbol: root }]
        } else {
            return None;
        };
        let mut current_type = reference;
        let mut operand = subject.clone();
        for segment in segments {
            let PlaceSegment::Field { symbol } = segment else {
                return None;
            };
            let owner = crate::field_domains::readable_nominal_definition(program, current_type)?;
            let field = program.data_constructor_field(current_type, owner.symbol, symbol)?;
            if !program
                .data_members(owner)
                .iter()
                .filter_map(|member| member.as_field())
                .any(|declared| declared.symbol == field.symbol)
            {
                return None;
            }
            current_type = crate::project_type_reference_from_segments(
                program,
                current_type,
                &[PlaceSegment::Field {
                    symbol: field.symbol,
                }],
            )?;
            if crate::reference_shell(program, current_type).is_some() {
                return None;
            }
            operand = ordered_values::Operand::Field {
                receiver: Box::new(operand),
                field: field.symbol,
                name: field.name.as_str().to_owned(),
                primitive: program.primitive_type_reference(current_type),
            };
        }
        if !has_fixed_integer_meaning(program, current_type) {
            return None;
        }
        Some(ProjectedOperand {
            spelled: None,
            operand: Some(operand),
            declared_type: Some(current_type),
        })
    }
}
pub(crate) use declared_integer_facts::record_admitted_integer_fields;
pub(crate) mod declared_float_facts {
    use super::float_arithmetic::float_bound_from;
    use super::value_environment::ValueEnvironment;
    use crate::proof_contracts::default_domains::FieldRepresentationBound;
    use numerics::bignum::ExactFloat;
    use symbols::SymbolHandle;
    use typed_trees::data::DataMember;
    use typed_trees::types::{PrimitiveType, TypeReferenceHandle, TypeReferenceNode};

    #[derive(Clone)]
    pub struct DeclaredFloatFieldBound {
        pub path: Vec<SymbolHandle>,
        pub primitive: PrimitiveType,
        pub operator: typed_trees::expression::BinaryOperator,
        pub value: f64,
    }

    impl DeclaredFloatFieldBound {
        pub fn predicate(&self) -> Option<facts::FloatPredicate> {
            let format = match self.primitive {
                PrimitiveType::F32 => numerics::literals::FloatFormat::F32,
                PrimitiveType::F64 => numerics::literals::FloatFormat::F64,
                _ => return None,
            };
            facts::FloatPredicate::comparison(
                format,
                self.operator,
                &ExactFloat::from_f64(self.value),
            )
        }
    }

    pub fn declared_float_field_bounds(
        program: &dyn crate::CheckingInput,
        reference: TypeReferenceHandle,
    ) -> Vec<DeclaredFloatFieldBound> {
        if let Some(memos) = crate::frozen_program::frozen_program_memos(program)
            && let Ok(cache) = memos.declared_float_field_bounds.lock()
            && let Some(rows) = cache.get(&reference)
        {
            return rows.clone();
        }
        let mut rows = Vec::new();
        collect(
            program,
            reference,
            &mut Vec::new(),
            &mut Vec::new(),
            &mut rows,
        );
        if let Some(memos) = crate::frozen_program::frozen_program_memos(program)
            && let Ok(mut cache) = memos.declared_float_field_bounds.lock()
        {
            cache.insert(reference, rows.clone());
        }
        rows
    }

    pub(crate) fn record_declared_float_fields(
        program: &dyn crate::CheckingInput,
        environment: &mut ValueEnvironment,
        path: &str,
        reference: TypeReferenceHandle,
    ) {
        for row in declared_float_field_bounds(program, reference) {
            if let Some(interval) = float_bound_from(row.operator, row.value, true, row.primitive) {
                let mut field_path = path.to_owned();
                for symbol in row.path {
                    field_path.push('.');
                    field_path.push_str(program.symbols.name(symbol));
                }
                environment.narrow_float(field_path.clone(), interval);
                environment.mark_non_nan(field_path);
            }
        }
    }

    fn collect(
        program: &dyn crate::CheckingInput,
        mut reference: TypeReferenceHandle,
        path: &mut Vec<SymbolHandle>,
        active: &mut Vec<SymbolHandle>,
        rows: &mut Vec<DeclaredFloatFieldBound>,
    ) {
        for _ in 0..program.type_reference_table.type_reference_count() {
            match program.type_reference_table.type_reference(reference) {
                TypeReferenceNode::Reference {
                    access: language_semantics::ReferenceAccess::WriteOnly,
                    ..
                } => return,
                TypeReferenceNode::Reference { referee, .. }
                | TypeReferenceNode::Constrained {
                    base_type: referee, ..
                } => reference = *referee,
                _ => break,
            }
        }
        let Some(definition) =
            crate::value_custody::places::data_definition_for_type(program, reference)
        else {
            return;
        };
        if active.contains(&definition.symbol) {
            return;
        }
        active.push(definition.symbol);
        if let Some(bounds) =
            crate::proof_contracts::default_domains::data_requires_field_representation_bounds(
                program, definition,
            )
        {
            for bound in bounds {
                let FieldRepresentationBound::FloatLiteral(bound) = bound else {
                    continue;
                };
                let Some(field) = program.data_field(definition, bound.field) else {
                    continue;
                };
                let Some(primitive @ (PrimitiveType::F32 | PrimitiveType::F64)) =
                    program.primitive_type_reference(field.type_reference)
                else {
                    continue;
                };
                let Some(meaning) =
                    crate::proof_contracts::default_domains::float_field_literal_bound_meaning(
                        program,
                        definition,
                        bound.conjunct,
                    )
                else {
                    continue;
                };
                let value = meaning.to_f64();
                if !value.is_finite() {
                    continue;
                }
                let mut field_path = path.clone();
                field_path.push(field.symbol);
                rows.push(DeclaredFloatFieldBound {
                    path: field_path,
                    primitive,
                    operator: bound.operator,
                    value,
                });
            }
        }
        for member in program.data_members(definition) {
            if let DataMember::Field(field) = member {
                path.push(field.symbol);
                collect(program, field.type_reference, path, active, rows);
                path.pop();
            }
        }
        active.pop();
    }
}
pub(crate) use declared_float_facts::record_declared_float_fields;
pub use declared_float_facts::{DeclaredFloatFieldBound, declared_float_field_bounds};
pub(crate) mod assignments {
    use crate::proof_contracts::arithmetic_domains::integer_ranges::{
        is_atomic_type, literal_u64, primitive_name, primitive_range,
        validate_anonymous_integer_primitive_range, validate_value_range,
    };
    use crate::proof_contracts::arithmetic_domains::interval::Interval;
    use crate::proof_contracts::arithmetic_domains::range_constraints::range_constraint_interval;
    use crate::proof_contracts::arithmetic_domains::value_environment::ValueEnvironment;
    use diagnostics::Diagnostic;
    use numerics::arithmetic::ArithmeticDomain;
    use typed_trees::expression::{ExpressionHandle, ExpressionNode};
    use typed_trees::machine::Machine;
    use typed_trees::state::State;
    use typed_trees::types::{PrimitiveType, TypeReferenceHandle};

    pub(crate) fn record_assignment(
        environment: &mut ValueEnvironment,
        path: Option<String>,
        interval: Interval,
        declared_range: Option<Interval>,
    ) {
        if let Some(path) = path {
            environment.invalidate_written_paths(std::slice::from_ref(&path));
            let interval = match declared_range {
                Some(declared) => interval.intersect(declared),
                None => interval,
            };
            environment.set(path, interval);
        }
    }

    pub(crate) fn record_unsigned_literal_assignment(
        program: &dyn crate::CheckingInput,
        environment: &mut ValueEnvironment,
        path: Option<String>,
        primitive: Option<PrimitiveType>,
        value: ExpressionHandle,
    ) {
        if primitive == Some(PrimitiveType::U64)
            && let Some(path) = path
            && let Some(value) = literal_u64(program, value)
        {
            environment.mark_known_u64(path, value);
        }
    }

    pub(crate) struct CapturedFloatAssignment {
        pub(crate) bounds: Option<super::FloatSourceBounds>,
        source_path: Option<String>,
    }

    pub(crate) fn float_source_place_path(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<String> {
        if let Some(path) = super::place_path(program, expression)
            .or_else(|| super::element_place_path(program, expression))
        {
            return Some(path);
        }
        if let ExpressionNode::Match(dispatch) = program.expression_table.expression(expression) {
            let arms = program.expression_table.match_arms(dispatch.arms);
            let first = arms.first()?;
            let candidate = float_source_place_path(program, first.value)?;
            if arms
                .iter()
                .skip(1)
                .all(|arm| float_source_place_path(program, arm.value).as_ref() == Some(&candidate))
            {
                return Some(candidate);
            }
        }
        None
    }

    pub(crate) fn capture_float_assignment(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        destination: Option<PrimitiveType>,
        value: ExpressionHandle,
    ) -> Option<CapturedFloatAssignment> {
        let Some(destination @ (PrimitiveType::F32 | PrimitiveType::F64)) = destination else {
            return None;
        };
        let bounds = if let ExpressionNode::Float(literal) =
            program.expression_table.expression(value)
        {
            let format = match destination {
                PrimitiveType::F32 => numerics::literals::FloatFormat::F32,
                _ => numerics::literals::FloatFormat::F64,
            };
            if literal.landing().is_some_and(|retained| retained != format) {
                None
            } else {
                let value = literal.with_landing(format).landed_f64();
                (!value.is_nan()).then_some(super::FloatSourceBounds {
                    primitive: destination,
                    minimum: value,
                    maximum: value,
                })
            }
        } else {
            super::float_source_bounds(program, machine.symbol, environment, value, &|expression| {
                state
                    .and_then(|state| {
                        crate::expression_result_type_reference(program, machine, state, expression)
                    })
                    .or_else(|| {
                        crate::value_custody::places::declared_place_type_raw(
                            program, machine, state, expression,
                        )
                    })
            })
            .filter(|bounds| bounds.primitive == destination)
        };
        let source_path = float_source_place_path(program, value);
        (bounds.is_some() || source_path.is_some()).then_some(CapturedFloatAssignment {
            bounds,
            source_path,
        })
    }

    pub(crate) fn record_float_assignment(
        environment: &mut ValueEnvironment,
        path: Option<String>,
        captured: Option<CapturedFloatAssignment>,
    ) {
        let (Some(path), Some(captured)) = (path, captured) else {
            return;
        };
        if let Some(bounds) = captured.bounds {
            environment.narrow_float(
                path.clone(),
                super::value_environment::FloatInterval {
                    low: Some(bounds.minimum),
                    high: Some(bounds.maximum),
                },
            );
            environment.mark_non_nan(path.clone());
        }
        if let Some(source_path) = captured.source_path {
            environment.mark_float_alias(path, source_path);
        }
    }

    pub(crate) fn enforced_declared_range(
        program: &dyn crate::CheckingInput,
        handle: TypeReferenceHandle,
    ) -> Option<Interval> {
        if is_atomic_type(program, handle)
            || program.arithmetic_domain_for_type_reference(handle) != ArithmeticDomain::Exact
        {
            return None;
        }
        range_constraint_interval(program, handle)
    }

    fn carrier_spelling(primitive: PrimitiveType, domain: Option<ArithmeticDomain>) -> String {
        match domain {
            Some(domain) if domain != ArithmeticDomain::Exact => {
                format!("{} in {}", primitive_name(primitive), domain.name())
            }
            _ => primitive_name(primitive).to_owned(),
        }
    }

    fn is_direct_suffixed_integer_literal(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
    ) -> bool {
        let mut current = expression;
        loop {
            match program.expression_table.expression(current) {
                ExpressionNode::Borrow(inner) => current = inner.target,
                ExpressionNode::Integer(literal) => return literal.landing().is_some(),
                ExpressionNode::Match(dispatch) => {
                    let arms = program.expression_table.match_arms(dispatch.arms);
                    return !arms.is_empty()
                        && arms
                            .iter()
                            .any(|arm| is_direct_suffixed_integer_literal(program, arm.value));
                }
                _ => return false,
            }
        }
    }

    fn is_unresolved_bare_name(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> bool {
        let Some(path) = program.expression_table.name_path_node(expression) else {
            return false;
        };
        let [first] = program.expression_table.name_path_members(path.members) else {
            return false;
        };
        !path.symbol.is_valid()
            && !path.head_symbol.is_valid()
            && language_semantics::const_value::boolean_literal_spelling(first.as_str()).is_none()
            && super::declared_place_type_raw(program, machine, Some(state), expression).is_none()
    }

    pub(crate) fn expression_reads_unresolved_local_initializer(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
    ) -> bool {
        let Some(state) = state else {
            return false;
        };
        let Some(path) = program.expression_table.name_path_node(expression) else {
            return false;
        };
        let [name] = program.expression_table.name_path_members(path.members) else {
            return false;
        };
        for statement in program.statement_table.statements(state.statement_nodes) {
            let Some(local) = statement.as_local_data() else {
                continue;
            };
            if local.name.as_str() == name.as_str() && local.initial_value.is_valid() {
                return is_unresolved_bare_name(program, machine, state, local.initial_value);
            }
        }
        false
    }

    pub(crate) fn stored_value_carrier(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        value: ExpressionHandle,
        analyzed: Option<PrimitiveType>,
        analyzed_domain: Option<ArithmeticDomain>,
    ) -> (Option<PrimitiveType>, Option<ArithmeticDomain>) {
        if !value.is_valid()
            || is_direct_suffixed_integer_literal(program, value)
            || expression_reads_unresolved_local_initializer(program, machine, state, value)
        {
            return (None, None);
        }
        if analyzed.is_some()
            || crate::value_custody::literals::has_anonymous_numeric_results(program, value)
        {
            return (analyzed, analyzed_domain);
        }
        let Some(reference) = state.and_then(|state| {
            crate::value_custody::expression_types::expression_result_type_reference(
                program, machine, state, value,
            )
        }) else {
            return (analyzed, analyzed_domain);
        };
        let Some(primitive) = program
            .primitive_type_reference(reference)
            .filter(|primitive| primitive_range(*primitive).is_some())
        else {
            return (analyzed, analyzed_domain);
        };
        (Some(primitive), analyzed_domain)
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn check_narrowing_assignment(
        target: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        value: Interval,
        source: Option<PrimitiveType>,
        source_domain: Option<ArithmeticDomain>,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        let Some(primitive) = target.filter(|primitive| *primitive != PrimitiveType::Bool) else {
            return;
        };
        if let Some(source_primitive) = source.filter(|primitive| *primitive != PrimitiveType::Bool)
            && (source_primitive != primitive
                || source_domain.is_some_and(|domain| domain != target_domain))
        {
            let target_spelling = carrier_spelling(primitive, Some(target_domain));
            let weakening = if source_domain
                .is_some_and(|domain| domain != ArithmeticDomain::Exact && domain != target_domain)
            {
                " (implicit domain weakening)"
            } else {
                ""
            };
            diagnostics.push(Diagnostic::error(format!(
            "store in {owner} implicitly converts `{}` to `{target_spelling}`{weakening}; a typed \
             value keeps its type and arithmetic policy -- spell the conversion with \
             `as` (for example `expr as {target_spelling}`)",
            carrier_spelling(source_primitive, source_domain),
        )));
            return;
        }
        let Some(range) = primitive_range(primitive) else {
            return;
        };
        let effective = match source.and_then(primitive_range) {
            Some(source_range) => value.intersect(source_range),
            None => value,
        };
        if effective.low().is_some() && effective.high().is_some() && !range.contains(effective) {
            diagnostics.push(Diagnostic::error(format!(
                "narrowing store in {owner} may not fit `{}`: the value is not provably \
             in range (decision 17 -- a narrowing store is a proof obligation, like exact \
             arithmetic). Truncate explicitly with an `as` cast, or constrain the source's \
             range.",
                primitive_name(primitive),
            )));
        }
    }

    pub(crate) fn check_value_narrowing(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        value: ExpressionHandle,
        target: PrimitiveType,
        target_domain: ArithmeticDomain,
        environment: &ValueEnvironment,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        if let Some(dispatch) = program.expression_table.match_node(value) {
            for arm in program.expression_table.match_arms(dispatch.arms) {
                check_value_narrowing(
                    program,
                    machine,
                    state,
                    arm.value,
                    target,
                    target_domain,
                    environment,
                    owner,
                    diagnostics,
                );
            }
            return;
        }
        if validate_anonymous_integer_primitive_range(program, target, value, owner, diagnostics)
            .is_some()
        {
            return;
        }
        let mut throwaway = Vec::new();
        let (interval, source, source_domain) = validate_value_range(
            program,
            machine,
            state,
            value,
            environment,
            Some(target),
            ArithmeticDomain::Exact,
            owner,
            &mut throwaway,
        );
        if throwaway.is_empty() {
            check_validated_value_narrowing(
                program,
                machine,
                state,
                value,
                target,
                target_domain,
                interval,
                source,
                source_domain,
                owner,
                diagnostics,
            );
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn check_validated_value_narrowing(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        value: ExpressionHandle,
        target: PrimitiveType,
        target_domain: ArithmeticDomain,
        interval: Interval,
        source: Option<PrimitiveType>,
        source_domain: Option<ArithmeticDomain>,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        if validate_anonymous_integer_primitive_range(program, target, value, owner, diagnostics)
            .is_some()
        {
            return;
        }
        let (source, source_domain) =
            stored_value_carrier(program, machine, state, value, source, source_domain);
        check_narrowing_assignment(
            Some(target),
            target_domain,
            interval,
            source,
            source_domain,
            owner,
            diagnostics,
        );
    }
}
pub(crate) mod bigint_interval {
    use numerics::bignum::BigInt;
    use typed_trees::expression::BinaryOperator;

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct BigIntInterval {
        pub low: Option<BigInt>,
        pub high: Option<BigInt>,
    }

    impl BigIntInterval {
        pub fn unbounded() -> Self {
            Self {
                low: None,
                high: None,
            }
        }

        pub fn constant(value: BigInt) -> Self {
            Self {
                low: Some(value.clone()),
                high: Some(value),
            }
        }

        pub fn intersect(&self, other: &Self) -> Self {
            Self {
                low: match (&self.low, &other.low) {
                    (Some(left), Some(right)) => Some(left.clone().max(right.clone())),
                    (Some(value), None) | (None, Some(value)) => Some(value.clone()),
                    (None, None) => None,
                },
                high: match (&self.high, &other.high) {
                    (Some(left), Some(right)) => Some(left.clone().min(right.clone())),
                    (Some(value), None) | (None, Some(value)) => Some(value.clone()),
                    (None, None) => None,
                },
            }
        }

        pub fn add(&self, other: &Self) -> Self {
            Self {
                low: match (&self.low, &other.low) {
                    (Some(a), Some(b)) => Some(a.add(b)),
                    _ => None,
                },
                high: match (&self.high, &other.high) {
                    (Some(a), Some(b)) => Some(a.add(b)),
                    _ => None,
                },
            }
        }

        pub fn subtract(&self, other: &Self) -> Self {
            Self {
                low: self
                    .low
                    .as_ref()
                    .zip(other.high.as_ref())
                    .map(|(left, right)| left.sub(right)),
                high: self
                    .high
                    .as_ref()
                    .zip(other.low.as_ref())
                    .map(|(left, right)| left.sub(right)),
            }
        }

        pub fn union(&self, other: &Self) -> Self {
            Self {
                low: self
                    .low
                    .as_ref()
                    .zip(other.low.as_ref())
                    .map(|(left, right)| left.clone().min(right.clone())),
                high: self
                    .high
                    .as_ref()
                    .zip(other.high.as_ref())
                    .map(|(left, right)| left.clone().max(right.clone())),
            }
        }

        pub fn excludes_zero(&self) -> bool {
            self.low.as_ref().is_some_and(|low| low > &BigInt::zero())
                || self.high.as_ref().is_some_and(BigInt::is_negative)
        }

        pub fn divide(&self, divisor: &Self) -> Self {
            let (dividend, divisor) = if divisor.high.as_ref().is_some_and(BigInt::is_negative) {
                let negative_one = BigInt::from_i64(-1);
                (self.scale(&negative_one), divisor.scale(&negative_one))
            } else {
                (self.clone(), divisor.clone())
            };
            if !divisor
                .low
                .as_ref()
                .is_some_and(|low| low > &BigInt::zero())
            {
                return Self::unbounded();
            }
            let endpoint = |numerator: &Option<BigInt>, lower: bool| {
                let numerator = numerator.as_ref()?;
                let denominator = if lower == numerator.is_negative() {
                    &divisor.low
                } else {
                    &divisor.high
                };
                match denominator {
                    Some(denominator) => {
                        numerator.div_rem(denominator).map(|(quotient, _)| quotient)
                    }
                    None => Some(BigInt::zero()),
                }
            };
            Self {
                low: endpoint(&dividend.low, true),
                high: endpoint(&dividend.high, false),
            }
        }

        pub fn remainder(&self, divisor: &Self) -> Self {
            let dividend = self.union(&Self::constant(BigInt::zero()));
            let Some(magnitude) = divisor
                .low
                .as_ref()
                .zip(divisor.high.as_ref())
                .map(|(low, high)| low.abs().max(high.abs()))
            else {
                return dividend;
            };
            if magnitude.is_zero() {
                return Self::unbounded();
            }
            let bound = magnitude.sub(&BigInt::from_i64(1));
            dividend.intersect(&Self {
                low: Some(bound.negate()),
                high: Some(bound),
            })
        }

        pub fn constant_remainder(&self, modulus: &BigInt, tight_interval: bool) -> Self {
            if modulus.is_zero() {
                return Self::unbounded();
            }
            if tight_interval
                && let (Some(low), Some(high)) = (&self.low, &self.high)
                && let (Some((low_quotient, low_remainder)), Some((high_quotient, high_remainder))) =
                    (low.div_rem(modulus), high.div_rem(modulus))
                && low_quotient == high_quotient
            {
                return Self {
                    low: Some(low_remainder.clone().min(high_remainder.clone())),
                    high: Some(low_remainder.max(high_remainder)),
                };
            }
            self.remainder(&Self::constant(modulus.clone()))
        }

        pub fn shift_right(&self, low_count: u64, high_count: u64) -> Self {
            if low_count > high_count {
                return Self::unbounded();
            }
            let low = self.low.as_ref().and_then(|value| {
                floor_shift_right(value, low_count)
                    .zip(floor_shift_right(value, high_count))
                    .map(|(low, high)| low.min(high))
            });
            let high = self.high.as_ref().and_then(|value| {
                floor_shift_right(value, low_count)
                    .zip(floor_shift_right(value, high_count))
                    .map(|(low, high)| low.max(high))
            });
            Self { low, high }
        }

        pub fn bitwise_and(&self, other: &Self, bits: u32, signed: bool) -> Self {
            let (minimum, maximum) = bitwise_carrier_bounds(bits, signed);
            let left_interval = self;
            let right_interval = other;
            let nonnegative =
                |interval: &Self| !interval.high.as_ref().is_some_and(BigInt::is_negative);
            let negative =
                |interval: &Self| !interval.low.as_ref().is_some_and(|low| !low.is_negative());
            let min_bound = |left: &Option<BigInt>, right: &Option<BigInt>| match (left, right) {
                (Some(left), Some(right)) => Some(left.clone().min(right.clone())),
                (Some(bound), None) | (None, Some(bound)) => Some(bound.clone()),
                (None, None) => None,
            };
            let mut low: Option<BigInt> = None;
            let mut high: Option<BigInt> = None;
            let mut fired = false;
            let mut extend = |quadrant_low: BigInt, quadrant_high: Option<BigInt>| {
                low = Some(match &low {
                    Some(current) => current.clone().min(quadrant_low.clone()),
                    None => quadrant_low,
                });
                high = match quadrant_high {
                    Some(bound) if !fired => Some(bound),
                    Some(bound) => high.clone().map(|current| current.max(bound)),
                    None => None,
                };
                fired = true;
            };
            let (left_nonnegative, left_negative) =
                (nonnegative(left_interval), negative(left_interval));
            let (right_nonnegative, right_negative) =
                (nonnegative(right_interval), negative(right_interval));
            if left_nonnegative && right_nonnegative {
                extend(
                    BigInt::zero(),
                    min_bound(&left_interval.high, &right_interval.high),
                );
            }
            if left_nonnegative && right_negative {
                extend(BigInt::zero(), left_interval.high.clone());
            }
            if left_negative && right_nonnegative {
                extend(BigInt::zero(), right_interval.high.clone());
            }
            if left_negative && right_negative {
                extend(
                    minimum.clone(),
                    min_bound(&left_interval.high, &right_interval.high),
                );
            }
            Self {
                low: low.map(|low| low.max(minimum.clone())).or(Some(minimum)),
                high: high.map(|high| high.min(maximum.clone())).or(Some(maximum)),
            }
        }

        pub fn from_comparison(
            operator: BinaryOperator,
            subject_on_left: bool,
            value: BigInt,
        ) -> Option<Self> {
            let operator = if subject_on_left {
                operator
            } else {
                operator.mirrored()
            };
            let one = BigInt::from_i64(1);
            let (low, high) = match operator {
                BinaryOperator::LessOrEqual => (None, Some(value)),
                BinaryOperator::Less => (None, Some(value.sub(&one))),
                BinaryOperator::GreaterOrEqual => (Some(value), None),
                BinaryOperator::Greater => (Some(value.add(&one)), None),
                BinaryOperator::Equal => (Some(value.clone()), Some(value)),
                _ => return None,
            };
            Some(Self { low, high })
        }

        pub fn from_refuted_comparison(
            operator: BinaryOperator,
            subject_on_left: bool,
            value: BigInt,
        ) -> Option<Self> {
            let refuted = match operator {
                BinaryOperator::Less => BinaryOperator::GreaterOrEqual,
                BinaryOperator::LessOrEqual => BinaryOperator::Greater,
                BinaryOperator::Greater => BinaryOperator::LessOrEqual,
                BinaryOperator::GreaterOrEqual => BinaryOperator::Less,
                _ => return None,
            };
            Self::from_comparison(refuted, subject_on_left, value)
        }

        pub fn refine_closed(&self, range: facts::IntegerRange) -> facts::IntegerRange {
            facts::IntegerRange {
                minimum: match &self.low {
                    Some(low) => range.minimum.max(low.clone()),
                    None => range.minimum,
                },
                maximum: match &self.high {
                    Some(high) => range.maximum.min(high.clone()),
                    None => range.maximum,
                },
            }
        }

        pub fn to_interval(&self) -> Option<super::Interval> {
            let end = |end: &Option<BigInt>| match end {
                Some(value) => value.to_i64().map(Some),
                None => Some(None),
            };
            Some(super::Interval {
                low: end(&self.low)?,
                high: end(&self.high)?,
            })
        }

        pub fn from_closed(range: facts::IntegerRange) -> Self {
            Self {
                low: Some(range.minimum),
                high: Some(range.maximum),
            }
        }

        pub fn into_closed(self) -> Option<facts::IntegerRange> {
            let minimum = self.low?;
            let maximum = self.high?;
            (minimum <= maximum).then_some(facts::IntegerRange { minimum, maximum })
        }

        pub fn scale(&self, factor: &BigInt) -> Self {
            if factor.is_zero() {
                return Self::constant(BigInt::zero());
            }
            let scaled_low = self.low.as_ref().map(|value| value.mul(factor));
            let scaled_high = self.high.as_ref().map(|value| value.mul(factor));
            if factor.is_negative() {
                Self {
                    low: scaled_high,
                    high: scaled_low,
                }
            } else {
                Self {
                    low: scaled_low,
                    high: scaled_high,
                }
            }
        }

        pub fn multiply(&self, other: &Self) -> Self {
            if let (Some(low), Some(high)) = (&self.low, &self.high)
                && low == high
            {
                return other.scale(low);
            }
            if let (Some(low), Some(high)) = (&other.low, &other.high)
                && low == high
            {
                return self.scale(low);
            }
            let (Some(self_low), Some(self_high), Some(other_low), Some(other_high)) =
                (&self.low, &self.high, &other.low, &other.high)
            else {
                return Self::unbounded();
            };
            let candidates = [
                self_low.mul(other_low),
                self_low.mul(other_high),
                self_high.mul(other_low),
                self_high.mul(other_high),
            ];
            Self {
                low: candidates.iter().min().cloned(),
                high: candidates.iter().max().cloned(),
            }
        }

        pub fn correlated_power(&self, power: u32) -> Self {
            if power == 0 {
                return Self::constant(BigInt::from_i64(1));
            }
            if power == 1 {
                return self.clone();
            }
            let (Some(low), Some(high)) = (&self.low, &self.high) else {
                return if power.is_multiple_of(2) {
                    Self {
                        low: Some(BigInt::zero()),
                        high: None,
                    }
                } else {
                    Self::unbounded()
                };
            };
            let corner_low = pow(low, power);
            let corner_high = pow(high, power);
            if power % 2 == 1 {
                return Self {
                    low: Some(corner_low),
                    high: Some(corner_high),
                };
            }
            let max_corner = corner_low.clone().max(corner_high.clone());
            let min_corner = if !low.is_negative() || high.is_negative() {
                corner_low.min(corner_high)
            } else {
                BigInt::zero()
            };
            Self {
                low: Some(min_corner),
                high: Some(max_corner),
            }
        }
    }

    fn pow(base: &BigInt, power: u32) -> BigInt {
        let mut result = BigInt::from_i64(1);
        for _ in 0..power {
            result = result.mul(base);
        }
        result
    }

    pub fn floor_shift_right(value: &BigInt, count: u64) -> Option<BigInt> {
        if count >= value.bit_length() as u64 {
            return Some(if value.is_negative() {
                BigInt::from_i64(-1)
            } else {
                BigInt::zero()
            });
        }
        let divisor = BigInt::from_i64(1).shl_bits(usize::try_from(count).ok()?);
        let (quotient, remainder) = value.div_rem(&divisor)?;
        Some(if remainder.is_negative() {
            quotient.sub(&BigInt::from_i64(1))
        } else {
            quotient
        })
    }

    pub fn bitwise_carrier_bounds(bits: u32, signed: bool) -> (BigInt, BigInt) {
        if signed {
            let half = BigInt::from_i64(1).shl_bits((bits - 1) as usize);
            (half.negate(), half.sub(&BigInt::from_i64(1)))
        } else {
            (
                BigInt::zero(),
                BigInt::from_i64(1)
                    .shl_bits(bits as usize)
                    .sub(&BigInt::from_i64(1)),
            )
        }
    }

    #[cfg(test)]
    mod tests {
        use super::BigIntInterval;
        use numerics::bignum::BigInt;
        use typed_trees::expression::BinaryOperator;

        fn ends(interval: Option<BigIntInterval>) -> Option<(Option<i64>, Option<i64>)> {
            interval.map(|interval| {
                (
                    interval.low.and_then(|low| low.to_i64()),
                    interval.high.and_then(|high| high.to_i64()),
                )
            })
        }

        #[test]
        fn comparisons_bound_the_subject_on_either_side() {
            let five = || BigInt::from_i64(5);
            let read =
                |operator, left| ends(BigIntInterval::from_comparison(operator, left, five()));
            assert_eq!(read(BinaryOperator::Less, true), Some((None, Some(4))));
            assert_eq!(
                read(BinaryOperator::LessOrEqual, true),
                Some((None, Some(5)))
            );
            assert_eq!(read(BinaryOperator::Greater, true), Some((Some(6), None)));
            assert_eq!(
                read(BinaryOperator::GreaterOrEqual, true),
                Some((Some(5), None))
            );
            assert_eq!(read(BinaryOperator::Equal, true), Some((Some(5), Some(5))));
            assert_eq!(read(BinaryOperator::Less, false), Some((Some(6), None)));
            assert_eq!(read(BinaryOperator::NotEqual, true), None);
            assert_eq!(read(BinaryOperator::Add, true), None);
        }

        #[test]
        fn refuted_orderings_bound_the_complement_and_equality_does_not() {
            let five = || BigInt::from_i64(5);
            let read = |operator| {
                ends(BigIntInterval::from_refuted_comparison(
                    operator,
                    true,
                    five(),
                ))
            };
            assert_eq!(read(BinaryOperator::Less), Some((Some(5), None)));
            assert_eq!(read(BinaryOperator::LessOrEqual), Some((Some(6), None)));
            assert_eq!(read(BinaryOperator::Greater), Some((None, Some(5))));
            assert_eq!(read(BinaryOperator::GreaterOrEqual), Some((None, Some(4))));
            assert_eq!(read(BinaryOperator::Equal), None);
            assert_eq!(read(BinaryOperator::NotEqual), None);
        }

        #[test]
        fn closed_refinement_keeps_a_crossed_meet() {
            let range = facts::IntegerRange {
                minimum: BigInt::from_i64(0),
                maximum: BigInt::from_i64(255),
            };
            let below =
                BigIntInterval::from_comparison(BinaryOperator::Less, true, BigInt::from_i64(0))
                    .unwrap();
            let refined = below.refine_closed(range);
            assert_eq!(refined.minimum, BigInt::from_i64(0));
            assert_eq!(refined.maximum, BigInt::from_i64(-1));
        }

        #[test]
        fn machine_width_view_refuses_an_end_outside_i64() {
            let past = BigIntInterval::from_comparison(
                BinaryOperator::Less,
                true,
                BigInt::from_i64(i64::MIN),
            )
            .unwrap();
            assert_eq!(past.to_interval(), None);
            let inside = BigIntInterval::from_comparison(
                BinaryOperator::GreaterOrEqual,
                true,
                BigInt::from_i64(3),
            )
            .unwrap()
            .to_interval()
            .unwrap();
            assert_eq!((inside.low, inside.high), (Some(3), None));
        }
    }
}
pub(crate) mod difference_bounds {
    use numerics::bignum::BigInt;

    #[derive(Clone, Default)]
    pub(crate) struct DifferenceBounds {
        names: Vec<String>,
        lexical_order: Vec<usize>,
        rows: Vec<Vec<(usize, BigInt)>>,
    }

    impl DifferenceBounds {
        pub(crate) fn atom_names(&self) -> impl Iterator<Item = &str> {
            self.lexical_order
                .iter()
                .map(|index| self.names[*index].as_str())
        }

        pub(crate) fn lexical_indices(&self) -> &[usize] {
            &self.lexical_order
        }

        pub(crate) fn position(&self, name: &str) -> Option<usize> {
            self.lexical_order
                .binary_search_by(|index| self.names[*index].as_str().cmp(name))
                .ok()
                .map(|position| self.lexical_order[position])
        }

        pub(crate) fn intern(&mut self, name: &str) -> usize {
            match self
                .lexical_order
                .binary_search_by(|index| self.names[*index].as_str().cmp(name))
            {
                Ok(position) => self.lexical_order[position],
                Err(position) => {
                    let index = self.names.len();
                    self.names.push(name.to_owned());
                    self.rows.push(Vec::new());
                    self.lexical_order.insert(position, index);
                    index
                }
            }
        }

        pub(crate) fn stored_bound_indices(&self, from: usize, to: usize) -> Option<&BigInt> {
            let row = &self.rows[from];
            row.binary_search_by_key(&to, |(destination, _)| *destination)
                .ok()
                .map(|position| &row[position].1)
        }

        pub(crate) fn stored_targets(&self, from: usize) -> impl Iterator<Item = usize> + '_ {
            self.rows[from].iter().map(|(destination, _)| *destination)
        }

        pub(crate) fn record(&mut self, from: &str, to: &str, bound: BigInt) -> bool {
            let from = self.intern(from);
            let to = self.intern(to);
            self.record_indices(from, to, bound)
        }

        pub(crate) fn record_indices(&mut self, from: usize, to: usize, bound: BigInt) -> bool {
            let row = &mut self.rows[from];
            match row.binary_search_by_key(&to, |(destination, _)| *destination) {
                Ok(position) => {
                    if bound > row[position].1 {
                        row[position].1 = bound;
                        true
                    } else {
                        false
                    }
                }
                Err(position) => {
                    row.insert(position, (to, bound));
                    true
                }
            }
        }
        pub(crate) fn bound_indices(
            &self,
            from: usize,
            to: usize,
            zero_atom: &str,
        ) -> Option<BigInt> {
            if from == to {
                return Some(BigInt::zero());
            }
            if let Some(bound) = self.stored_bound_indices(from, to) {
                return Some(bound.clone());
            }
            let zero = self.position(zero_atom)?;
            if from == zero || to == zero {
                return None;
            }
            let through_zero = self.stored_bound_indices(from, zero)?;
            Some(through_zero.add(self.stored_bound_indices(zero, to)?))
        }

        pub(crate) fn close(&mut self, zero_atom: &str) -> bool {
            let mut unsatisfiable = false;
            let zero = self.position(zero_atom);
            let atoms: Vec<usize> = self
                .lexical_indices()
                .iter()
                .copied()
                .filter(|index| Some(*index) != zero)
                .collect();
            let mut lexical_position = vec![0; self.lexical_indices().len()];
            for (position, atom) in atoms.iter().enumerate() {
                lexical_position[*atom] = position;
            }
            let mut parents: Vec<usize> = (0..atoms.len()).collect();
            fn component_root(parents: &mut [usize], mut index: usize) -> usize {
                while parents[index] != index {
                    parents[index] = parents[parents[index]];
                    index = parents[index];
                }
                index
            }
            for from in &atoms {
                let mut destinations: Vec<usize> = self
                    .stored_targets(*from)
                    .filter(|index| Some(*index) != zero)
                    .collect();
                destinations.sort_unstable_by_key(|index| lexical_position[*index]);
                for to in destinations {
                    let left = component_root(&mut parents, lexical_position[*from]);
                    let right = component_root(&mut parents, lexical_position[to]);
                    if left != right {
                        parents[left] = right;
                    }
                }
            }
            let mut components = vec![Vec::new(); atoms.len()];
            for (position, atom) in atoms.into_iter().enumerate() {
                components[component_root(&mut parents, position)].push(atom);
            }
            for mut members in components.into_iter().filter(|members| !members.is_empty()) {
                if let Some(zero) = zero {
                    members.push(zero);
                }
                self.close_members(&members, &mut unsatisfiable);
            }
            unsatisfiable
        }

        fn close_members(&mut self, members: &[usize], unsatisfiable: &mut bool) {
            for via in members {
                for from in members {
                    let Some(first) = self.stored_bound_indices(*from, *via).cloned() else {
                        continue;
                    };
                    for to in members {
                        let Some(second) = self.stored_bound_indices(*via, *to).cloned() else {
                            continue;
                        };
                        let combined = first.add(&second);
                        if from == to {
                            if !combined.is_negative() && !combined.is_zero() {
                                *unsatisfiable = true;
                            }
                            continue;
                        }
                        self.record_indices(*from, *to, combined);
                    }
                }
            }
        }
    }
}
pub(crate) use difference_bounds::DifferenceBounds;
pub(crate) mod bitwise {
    use super::{BinaryOperator, Interval, PrimitiveType};
    use crate::proof_contracts::arithmetic_domains::integer_ranges::{
        integer_bit_width, primitive_range,
    };
    use semantic_vocabulary::{IntegerSign, IntegerType, IntegerValue};

    pub(crate) fn binary(
        operator: BinaryOperator,
        primitive: PrimitiveType,
        left: Interval,
        right: Interval,
        left_known: Option<u64>,
        right_known: Option<u64>,
    ) -> Interval {
        let Some(carrier) = Carrier::new(primitive) else {
            return Interval::UNBOUNDED;
        };
        let left = carrier.value_bounds(left, left_known);
        let right = carrier.value_bounds(right, right_known);
        let bounds = match operator {
            BinaryOperator::BitwiseAnd => carrier.integer.bitwise_and_bounds(left, right),
            BinaryOperator::BitwiseOr => carrier.integer.bitwise_or_bounds(left, right),
            BinaryOperator::BitwiseXor => carrier.integer.bitwise_xor_bounds(left, right),
            _ => None,
        };
        bounds.map_or_else(
            || primitive_range(primitive).unwrap_or(Interval::UNBOUNDED),
            |(low, high)| project(value_number(low), value_number(high)),
        )
    }

    pub(crate) fn shift_right(
        primitive: PrimitiveType,
        value: Interval,
        count: Interval,
        known: Option<u64>,
    ) -> Interval {
        let Some(carrier) = Carrier::new(primitive) else {
            return Interval::UNBOUNDED;
        };
        let complete = primitive_range(primitive).unwrap_or(Interval::UNBOUNDED);
        let (Some(count_low), Some(count_high)) = (count.low, count.high) else {
            return complete;
        };
        let Some(width) = integer_bit_width(primitive) else {
            return complete;
        };
        if count_low < 0 || count_low > count_high || count_high >= width {
            return complete;
        }
        let Ok(count_type) = IntegerType::new(IntegerSign::Unsigned, 64) else {
            return complete;
        };
        carrier
            .integer
            .exact_shift_right_bounds(
                carrier.value_bounds(value, known),
                count_type,
                (
                    IntegerValue::Unsigned(count_low as u128),
                    IntegerValue::Unsigned(count_high as u128),
                ),
            )
            .map_or(complete, |(low, high)| {
                project(value_number(low), value_number(high))
            })
    }

    pub(crate) fn complement(
        primitive: PrimitiveType,
        interval: Interval,
        known: Option<u64>,
    ) -> Interval {
        let Some(carrier) = Carrier::new(primitive) else {
            return Interval::UNBOUNDED;
        };
        if carrier.integer.sign() == IntegerSign::Unsigned
            && let Some(value) = known
        {
            return complement_unsigned_value(primitive, value).map_or_else(
                || primitive_range(primitive).unwrap_or(Interval::UNBOUNDED),
                |value| project(i128::from(value), i128::from(value)),
            );
        }
        let (input_low, input_high) = carrier.bounds(interval);
        let low = carrier.integer.bitwise_not(carrier.value(input_high));
        let high = carrier.integer.bitwise_not(carrier.value(input_low));
        match (low, high) {
            (Some(low), Some(high)) => project(value_number(low), value_number(high)),
            _ => primitive_range(primitive).unwrap_or(Interval::UNBOUNDED),
        }
    }

    pub(crate) fn binary_unsigned_value(
        operator: BinaryOperator,
        primitive: PrimitiveType,
        left: u64,
        right: u64,
    ) -> Option<u64> {
        let carrier = Carrier::new(primitive)?;
        if carrier.integer.sign() != IntegerSign::Unsigned {
            return None;
        }
        let (left, right) = (
            IntegerValue::Unsigned(left.into()),
            IntegerValue::Unsigned(right.into()),
        );
        let value = match operator {
            BinaryOperator::BitwiseAnd => carrier.integer.bitwise_and(left, right),
            BinaryOperator::BitwiseOr => carrier.integer.bitwise_or(left, right),
            BinaryOperator::BitwiseXor => carrier.integer.bitwise_xor(left, right),
            _ => None,
        }?;
        let IntegerValue::Unsigned(value) = value else {
            return None;
        };
        u64::try_from(value).ok()
    }

    pub(crate) fn complement_unsigned_value(primitive: PrimitiveType, value: u64) -> Option<u64> {
        let carrier = Carrier::new(primitive)?;
        if carrier.integer.sign() != IntegerSign::Unsigned {
            return None;
        }
        let value = carrier
            .integer
            .bitwise_not(IntegerValue::Unsigned(value.into()))?;
        let IntegerValue::Unsigned(value) = value else {
            return None;
        };
        u64::try_from(value).ok()
    }

    pub(crate) struct Carrier {
        integer: IntegerType,
    }

    impl Carrier {
        fn new(primitive: PrimitiveType) -> Option<Self> {
            let width = u16::try_from(integer_bit_width(primitive)?).ok()?;
            let sign = if primitive.is_signed_integer() {
                IntegerSign::Signed
            } else {
                IntegerSign::Unsigned
            };
            let integer = IntegerType::new(sign, width).ok()?;
            Some(Self { integer })
        }

        fn bounds(&self, interval: Interval) -> (i128, i128) {
            let minimum = value_number(self.integer.minimum_value());
            let maximum = value_number(self.integer.maximum_value());
            let low = interval.low.map_or(minimum, i128::from);
            let high = interval.high.map_or(maximum, i128::from);
            if low < minimum || high > maximum || low > high {
                (minimum, maximum)
            } else {
                (low, high)
            }
        }

        fn value_bounds(
            &self,
            interval: Interval,
            known: Option<u64>,
        ) -> (IntegerValue, IntegerValue) {
            if self.integer.sign() == IntegerSign::Unsigned
                && let Some(value) = known.map(|value| IntegerValue::Unsigned(u128::from(value)))
                && self.integer.admits(value)
            {
                return (value, value);
            }
            let (low, high) = self.bounds(interval);
            (self.value(low), self.value(high))
        }

        fn value(&self, number: i128) -> IntegerValue {
            match self.integer.sign() {
                IntegerSign::Signed => IntegerValue::Signed(number),
                IntegerSign::Unsigned => IntegerValue::Unsigned(number as u128),
            }
        }
    }

    fn value_number(value: IntegerValue) -> i128 {
        match value {
            IntegerValue::Signed(value) => value,
            IntegerValue::Unsigned(value) => value as i128,
        }
    }

    fn project(low: i128, high: i128) -> Interval {
        Interval {
            low: Some(i64::try_from(low).unwrap_or(i64::MAX)),
            high: i64::try_from(high).ok(),
        }
    }
}
pub(crate) use bitwise::binary as bitwise_binary;
pub(crate) mod call_result_bounds {
    use super::{
        BinaryOperator, ExpressionHandle, ExpressionNode, Interval, SignatureContractKind,
        TypeReferenceHandle, ValueEnvironment, guard_narrowing, range_constraint_interval,
    };
    use crate::machine_calls::calls::CalleeContract;
    use crate::proof_contracts::arithmetic_domains::integer_ranges::{
        literal_interval, primitive_range,
    };
    use symbols::SymbolHandle;

    #[derive(Default)]
    pub(crate) struct ArgumentBounds {
        pub values: Vec<(SymbolHandle, Interval)>,
        pub lengths: Vec<(SymbolHandle, Interval)>,
    }

    pub(crate) fn normal_return_interval(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        declared: Interval,
        actuals: &ArgumentBounds,
    ) -> Interval {
        if !callee
            .contracts
            .iter()
            .any(|contract| contract.kind == SignatureContractKind::Ensures)
        {
            return declared;
        }
        let mut environment = ValueEnvironment::new();
        for parameter in callee.parameters {
            if parameter.is_mutable || parameter.is_const {
                continue;
            }
            let Some(mut interval) = program
                .primitive_type_reference(parameter.type_reference)
                .and_then(primitive_range)
            else {
                continue;
            };
            if let Some(actual) =
                crate::queries::substitutions::actual_for(&actuals.values, parameter.symbol)
            {
                interval = interval.intersect(actual);
            }
            for contract in callee
                .contracts
                .iter()
                .filter(|contract| contract.kind == SignatureContractKind::Requires)
            {
                for fact in program.proof_facts.span_or_empty(contract.facts) {
                    if let Some(expression) = fact.as_expression() {
                        interval = interval.intersect(project(
                            program,
                            callee,
                            &environment,
                            &actuals.lengths,
                            *expression,
                            Some(parameter),
                        ));
                    }
                }
            }
            environment.set(parameter.name.as_str().to_owned(), interval);
        }
        program
            .contract_expressions(callee.contracts.iter(), SignatureContractKind::Ensures)
            .fold(declared, |interval, expression| {
                interval.intersect(project(
                    program,
                    callee,
                    &environment,
                    &actuals.lengths,
                    expression,
                    None,
                ))
            })
    }

    fn project(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        environment: &ValueEnvironment,
        lengths: &[(SymbolHandle, Interval)],
        expression: ExpressionHandle,
        formal: Option<&typed_trees::signature::StateParameter>,
    ) -> Interval {
        project_possible(program, callee, environment, lengths, expression, formal)
            .unwrap_or(Interval::UNBOUNDED)
    }

    fn project_possible(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        environment: &ValueEnvironment,
        lengths: &[(SymbolHandle, Interval)],
        expression: ExpressionHandle,
        formal: Option<&typed_trees::signature::StateParameter>,
    ) -> Option<Interval> {
        if let Some(value) = program.static_boolean_value(expression) {
            return value.then_some(Interval::UNBOUNDED);
        }
        if program
            .prepared_mathematics()
            .is_some_and(|view| view.application(expression).is_some())
        {
            return mathematical_interval(
                program,
                callee,
                environment,
                lengths,
                expression,
                formal,
            );
        }
        let Some(binary) = program.expression_table.binary_node(expression) else {
            return Some(Interval::UNBOUNDED);
        };
        if matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or) {
            if binary.operator == BinaryOperator::And {
                let mut remaining_right_operands = vec![binary.right];
                let mut current_operand = binary.left;
                while program.static_boolean_value(current_operand).is_none()
                    && !program
                        .prepared_mathematics()
                        .is_some_and(|view| view.application(current_operand).is_some())
                {
                    let Some(prefix) = program.expression_table.binary_node(current_operand) else {
                        break;
                    };
                    if prefix.operator != BinaryOperator::And {
                        break;
                    }
                    remaining_right_operands.push(prefix.right);
                    current_operand = prefix.left;
                }
                let mut interval = project_possible(
                    program,
                    callee,
                    environment,
                    lengths,
                    current_operand,
                    formal,
                )?;
                let mut continuing = environment.clone();
                while let Some(right) = remaining_right_operands.pop() {
                    continuing =
                        condition_environment(program, callee, &continuing, current_operand);
                    if continuing.intervals.values().any(|interval| {
                        interval
                            .low
                            .zip(interval.high)
                            .is_some_and(|(low, high)| low > high)
                    }) {
                        return None;
                    }
                    interval = interval.intersect(project_possible(
                        program,
                        callee,
                        &continuing,
                        lengths,
                        right,
                        formal,
                    )?);
                    current_operand = right;
                }
                return Some(interval);
            }
            let left = project_possible(program, callee, environment, lengths, binary.left, formal);
            let right =
                project_possible(program, callee, environment, lengths, binary.right, formal);
            return match (left, right) {
                (Some(left), Some(right)) => Some(left.union(right)),
                (left, right) => left.or(right),
            };
        }
        let result = |expression| {
            if let Some(parameter) = formal {
                matches!(program.expression_table.expression(expression), ExpressionNode::Name(path)
            if parameter.symbol.is_valid() && path.symbol == parameter.symbol && path.head_symbol == parameter.symbol)
            } else {
                crate::reserved_result_owner(program, expression).is_some_and(
                    |(owner, return_type)| {
                        owner == callee.callable && return_type == callee.return_type
                    },
                )
            }
        };
        let (other, subject_on_left) = if result(binary.left) {
            (binary.right, true)
        } else if result(binary.right) {
            (binary.left, false)
        } else {
            return Some(Interval::UNBOUNDED);
        };
        let Some((operand, operand_type)) = operand_interval(
            program,
            callee,
            environment,
            lengths,
            other,
            formal.is_none(),
        ) else {
            return Some(Interval::UNBOUNDED);
        };
        let subject_type = formal.map_or(callee.return_type, |parameter| {
            crate::reference_shell(program, parameter.type_reference)
                .map_or(parameter.type_reference, |shell| shell.referee)
        });
        let operand_types = if subject_on_left {
            [Some(subject_type), operand_type]
        } else {
            [operand_type, Some(subject_type)]
        };
        if !builtin(
            program,
            callee.callable,
            expression,
            binary.operator,
            &operand_types,
        ) {
            return Some(Interval::UNBOUNDED);
        }
        Some(guard_narrowing::comparison_interval(
            binary.operator,
            operand,
            subject_on_left,
        ))
    }

    fn mathematical_interval(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        environment: &ValueEnvironment,
        lengths: &[(SymbolHandle, Interval)],
        expression: ExpressionHandle,
        formal: Option<&typed_trees::signature::StateParameter>,
    ) -> Option<Interval> {
        use checked_trees::CheckedScalarExpression as Scalar;
        let reference = formal.map_or(callee.return_type, |parameter| parameter.type_reference);
        let Some(primitive) = program.primitive_type_reference(reference) else {
            return Some(Interval::UNBOUNDED);
        };
        let mut intervals = vec![Interval::UNBOUNDED];
        let predicate = crate::mathematical_applications::scalar_predicate(
            program,
            expression,
            |capture, source_type| {
                let subject = formal.map_or_else(
            || crate::reserved_result_owner(program, capture).is_some_and(|(owner, reference)| {
                owner == callee.callable && reference == callee.return_type
            }),
            |parameter| matches!(program.expression_table.expression(capture), ExpressionNode::Name(path)
                if path.symbol == parameter.symbol && path.head_symbol == parameter.symbol),
        );
                if subject {
                    return Some(Scalar::Parameter {
                        position: 0,
                        primitive_type: primitive,
                    });
                }
                let (interval, reference) = operand_interval(
                    program,
                    callee,
                    environment,
                    lengths,
                    capture,
                    formal.is_none(),
                )?;
                let primitive =
                    program.primitive_type_reference(reference.unwrap_or(source_type))?;
                let position = intervals.len();
                intervals.push(interval);
                Some(Scalar::Parameter {
                    position,
                    primitive_type: primitive,
                })
            },
        );
        predicate.map_or(Some(Interval::UNBOUNDED), |predicate| {
            projected_interval(&predicate, &intervals, false)
        })
    }

    fn projected_interval(
        predicate: &checked_trees::CheckedBooleanExpression,
        intervals: &[Interval],
        negated: bool,
    ) -> Option<Interval> {
        use checked_trees::{
            CheckedBooleanExpression as Boolean, CheckedIntegerComparisonKind as Comparison,
            CheckedScalarExpression as Scalar,
        };
        match predicate {
            Boolean::Constant(value) => (*value != negated).then_some(Interval::UNBOUNDED),
            Boolean::Not(value) => projected_interval(value, intervals, !negated),
            Boolean::And { left, right } | Boolean::Or { left, right } => {
                let left = projected_interval(left, intervals, negated);
                let right = projected_interval(right, intervals, negated);
                if matches!(predicate, Boolean::And { .. }) != negated {
                    Some(left?.intersect(right?))
                } else {
                    match (left, right) {
                        (Some(left), Some(right)) => Some(left.union(right)),
                        (left, right) => left.or(right),
                    }
                }
            }
            Boolean::IntegerComparison { kind, left, right } => {
                let subject =
                    |value: &Scalar| matches!(value, Scalar::Parameter { position: 0, .. });
                let (operand, subject_on_left) = if subject(left) {
                    (right, true)
                } else if subject(right) {
                    (left, false)
                } else {
                    return Some(Interval::UNBOUNDED);
                };
                let operand = match operand.as_ref() {
                    Scalar::Parameter { position, .. } if *position != 0 => {
                        intervals.get(*position).copied()
                    }
                    Scalar::IntegerLiteral { literal } => {
                        literal.value_i64().map(Interval::constant)
                    }
                    _ => None,
                };
                let operator = match (kind, negated) {
                    (Comparison::Equal, false) => BinaryOperator::Equal,
                    (Comparison::Equal, true) => BinaryOperator::NotEqual,
                    (Comparison::LessThan, false) => BinaryOperator::Less,
                    (Comparison::LessThan, true) => BinaryOperator::GreaterOrEqual,
                    (Comparison::LessOrEqual, false) => BinaryOperator::LessOrEqual,
                    (Comparison::LessOrEqual, true) => BinaryOperator::Greater,
                };
                Some(operand.map_or(Interval::UNBOUNDED, |operand| {
                    guard_narrowing::comparison_interval(operator, operand, subject_on_left)
                }))
            }
            _ => Some(Interval::UNBOUNDED),
        }
    }

    fn condition_environment(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        environment: &ValueEnvironment,
        condition: ExpressionHandle,
    ) -> ValueEnvironment {
        let Some(machine) = program.machine_by_symbol(callee.callable) else {
            return environment.clone();
        };
        guard_narrowing::evaluated_condition_environment(
            program,
            machine,
            program.machine_states(machine).first(),
            condition,
            true,
            environment,
        )
    }

    fn operand_interval(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        environment: &ValueEnvironment,
        lengths: &[(SymbolHandle, Interval)],
        expression: ExpressionHandle,
        allow_formals: bool,
    ) -> Option<(Interval, Option<TypeReferenceHandle>)> {
        if let Some(cast) = program.expression_table.cast_node(expression) {
            if !crate::proof_contracts::arithmetic_domains::cast_ranges::plain_exact_widening_cast(
                program, cast,
            ) {
                return None;
            }
            let (interval, source_type) = operand_interval(
                program,
                callee,
                environment,
                lengths,
                cast.value,
                allow_formals,
            )?;
            let source = program.primitive_type_reference(source_type?)?;
            let target = program.primitive_type_reference(cast.target_type)?;
            return crate::integer_widen_is_total(source, target)
                .then_some((interval, Some(cast.target_type)));
        }
        if let Some(literal) = program.expression_table.integer_node(expression) {
            return Some((literal_interval(literal), None));
        }
        if !allow_formals {
            return None;
        }
        if let Some(binary) = program.expression_table.binary_node(expression) {
            operand_interval(program, callee, environment, lengths, binary.left, true)?;
            operand_interval(program, callee, environment, lengths, binary.right, true)?;
            let machine = program.machine_by_symbol(callee.callable)?;
            let reference = crate::parameter_expression_result_type_reference(
                program,
                callee.callable,
                callee.parameters,
                expression,
            )?;
            program
                .primitive_type_reference(reference)
                .and_then(primitive_range)?;
            let mut diagnostics = Vec::new();
            let analysis = super::expression_analysis::analyze(
                program,
                machine,
                program.machine_states(machine).first(),
                expression,
                environment,
                None,
                super::ArithmeticDomain::Exact,
                "normal-return contract",
                false,
                false,
                &mut diagnostics,
            );
            return diagnostics
                .is_empty()
                .then_some((analysis.value.interval, Some(reference)));
        }
        if let Some(member) = program.expression_table.member_node(expression) {
            use crate::value_custody::places::collection_operations::{
                MeasureReceiver, collection_measure_member,
            };
            let path = program.expression_table.name_path_node(member.receiver)?;
            let parameter = callee.parameters.iter().find(|parameter| {
                parameter.symbol.is_valid()
                    && parameter.symbol == path.symbol
                    && path.symbol == path.head_symbol
                    && !parameter.is_const
            })?;
            if collection_measure_member(
                program,
                member,
                MeasureReceiver::Declared(parameter.type_reference),
            ) != Some(language_semantics::declaration_selection::CollectionMeasure::Length)
            {
                return None;
            }
            let interval = crate::queries::substitutions::actual_for(lengths, parameter.symbol)?;
            let reference = crate::parameter_expression_result_type_reference(
                program,
                callee.callable,
                callee.parameters,
                expression,
            )?;
            return Some((interval, Some(reference)));
        }
        let path = program.expression_table.name_path_node(expression)?;
        if !path.symbol.is_valid() || path.symbol != path.head_symbol {
            return None;
        }
        let Some(parameter) = callee
            .parameters
            .iter()
            .find(|parameter| parameter.symbol == path.symbol)
        else {
            return integer_binder_operand(program, callee, expression);
        };
        if parameter.is_mutable || parameter.is_const {
            return None;
        }
        let primitive = program.primitive_type_reference(parameter.type_reference)?;
        let mut interval = primitive_range(primitive)?;
        if let Some(declared) = range_constraint_interval(program, parameter.type_reference) {
            interval = interval.intersect(declared);
        }
        if let Some(required) = environment.get(parameter.name.as_str()) {
            interval = interval.intersect(required);
        }
        Some((interval, Some(parameter.type_reference)))
    }

    fn integer_binder_operand(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        expression: ExpressionHandle,
    ) -> Option<(Interval, Option<TypeReferenceHandle>)> {
        let machine = program.machine_by_symbol(callee.callable)?;
        let state = program.machine_states(machine).first()?;
        let path = program.expression_table.name_path_node(expression)?;
        if !path.symbol.is_valid() || path.symbol != path.head_symbol {
            return None;
        }
        let binder = program
            .machine_type_parameters(machine)
            .iter()
            .find(|parameter| parameter.symbol == path.symbol)?;
        let type_reference = match binder.kind {
            typed_trees::data::TypeParameterKind::Const { type_reference }
            | typed_trees::data::TypeParameterKind::Value { type_reference } => type_reference,
            _ => return None,
        };
        let interval = super::invariant_bounds::standing_integer_interval(
            program, machine, state, expression,
        )?;
        Some((interval, Some(type_reference)))
    }

    pub(crate) fn builtin(
        program: &dyn crate::CheckingInput,
        scope: SymbolHandle,
        expression: ExpressionHandle,
        operator: BinaryOperator,
        operand_types: &[Option<TypeReferenceHandle>],
    ) -> bool {
        let Some(spelling) = typed_trees::operator::comparison_operator_spelling(operator) else {
            return false;
        };
        typed_trees::operator::has_builtin_spelled_expression_meaning(
            program,
            scope,
            expression,
            spelling,
            operand_types,
        )
    }

    pub(crate) fn normal_return_recipe(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
    ) -> Option<checked_trees::IntegerRangeRecipe> {
        use checked_trees::IntegerRangeRecipe;
        if program.constant_recipes.is_empty() {
            return None;
        }
        let primitive = program.primitive_type_reference(callee.return_type)?;
        let mut pending = program
            .contract_expressions(callee.contracts.iter(), SignatureContractKind::Ensures)
            .collect::<Vec<_>>();
        let mut result: Option<IntegerRangeRecipe> = None;
        while let Some(expression) = pending.pop() {
            let Some(binary) = program.expression_table.binary_node(expression) else {
                continue;
            };
            if binary.operator == BinaryOperator::And {
                pending.extend([binary.left, binary.right]);
                continue;
            }
            let is_result = |expression| {
                crate::reserved_result_owner(program, expression).is_some_and(
                    |(owner, reference)| {
                        owner == callee.callable && reference == callee.return_type
                    },
                )
            };
            let (bound, operator) = if is_result(binary.left) {
                (binary.right, binary.operator)
            } else if is_result(binary.right) {
                (binary.left, binary.operator.mirrored())
            } else {
                continue;
            };
            if !program
                .constant_recipe_for_contract_expression(bound)
                .is_valid()
            {
                continue;
            }
            let bound_type = crate::parameter_expression_result_type_reference(
                program,
                callee.callable,
                callee.parameters,
                bound,
            );
            let operand_types = if is_result(binary.left) {
                [Some(callee.return_type), bound_type]
            } else {
                [bound_type, Some(callee.return_type)]
            };
            if !builtin(
                program,
                callee.callable,
                expression,
                binary.operator,
                &operand_types,
            ) {
                continue;
            }
            let Some(bound_recipe) = super::deferred_bounds::comparison_recipe(
                program,
                callee.callable,
                primitive,
                bound,
                operator,
            ) else {
                continue;
            };
            result = Some(result.map_or_else(
                || bound_recipe.clone(),
                |previous| previous.intersect(&bound_recipe),
            ));
        }
        result
    }
}
pub(crate) mod deferred_bounds {
    use super::{BinaryOperator, ExpressionHandle, PrimitiveType};
    use checked_trees::IntegerRangeRecipe;
    use numerics::bignum::BigInt;
    use symbols::SymbolHandle;

    pub(crate) fn comparison_recipe(
        program: &dyn crate::CheckingInput,
        owner: SymbolHandle,
        primitive: PrimitiveType,
        bound: ExpressionHandle,
        operator: BinaryOperator,
    ) -> Option<IntegerRangeRecipe> {
        if !program
            .constant_recipe_for_contract_expression(bound)
            .is_valid()
        {
            return None;
        }
        let carrier = super::integer_ranges::primitive_range(primitive)?;
        let low = BigInt::from_i64(carrier.low?);
        let high = carrier
            .high
            .map(BigInt::from_i64)
            .or_else(|| (primitive == PrimitiveType::U64).then(|| BigInt::from_u64(u64::MAX)))?;
        let observation = IntegerRangeRecipe::observation(bound, owner);
        let lower = IntegerRangeRecipe::bounds(low.clone(), low.clone());
        let upper = IntegerRangeRecipe::bounds(high.clone(), high.clone());
        let one = IntegerRangeRecipe::bounds(BigInt::from_i64(1), BigInt::from_i64(1));
        let selected = match operator {
            BinaryOperator::LessOrEqual => IntegerRangeRecipe::interval(&lower, &observation),
            BinaryOperator::Less => IntegerRangeRecipe::interval(
                &lower,
                &observation.binary(BinaryOperator::Subtract, &one)?,
            ),
            BinaryOperator::GreaterOrEqual => IntegerRangeRecipe::interval(&observation, &upper),
            BinaryOperator::Greater => IntegerRangeRecipe::interval(
                &observation.binary(BinaryOperator::Add, &one)?,
                &upper,
            ),
            BinaryOperator::Equal => observation,
            _ => return None,
        };
        Some(selected.intersect(&IntegerRangeRecipe::bounds(low, high)))
    }
}
pub(crate) mod deferred_observations {
    use symbols::SymbolHandle;
    use typed_trees::expression::{ExpressionHandle, ExpressionNode};
    use typed_trees::types::PrimitiveType;

    pub(crate) fn deferred_integer_observation(
        program: &dyn crate::CheckingInput,
        owner: SymbolHandle,
        expression: ExpressionHandle,
        primitive: Option<PrimitiveType>,
    ) -> Option<checked_trees::IntegerRangeRecipe> {
        let admitted = match program.expression_table.expression(expression) {
            ExpressionNode::Call(call) => {
                call.layout_query.is_some()
                    || (primitive.is_some_and(|primitive| primitive.integer_bounds().is_some())
                        && program.constant_evaluation_entry(owner).is_some())
            }
            ExpressionNode::Name(path) => program
                .const_declaration_by_symbol(path.symbol)
                .is_some_and(|declaration| {
                    declaration.evaluated_value.is_none()
                        && declaration.materialized_initializer.is_valid()
                }),
            _ => false,
        };
        admitted.then(|| checked_trees::IntegerRangeRecipe::observation(expression, owner))
    }
}

pub(crate) use deferred_observations::deferred_integer_observation;
pub(crate) mod call_result_measures {
    use typed_trees::expression::{
        BinaryOperator, ExpressionHandle, ExpressionNode, TableCallExpression,
    };
    use typed_trees::signature::SignatureContractKind;
    use typed_trees::types::{PrimitiveType, TypeReferenceNode};

    pub fn normal_return_length_collection(
        program: &dyn crate::CheckingInput,
        call: &TableCallExpression,
    ) -> Option<ExpressionHandle> {
        if !call.selects_only_nominal_route() || call.static_machine_parameter.is_valid() {
            return None;
        }
        let callee = crate::machine_calls::calls::call_contract(program, call)?;
        if !program
            .primitive_type_reference(callee.return_type)
            .is_some_and(PrimitiveType::is_fixed_integer)
            || !callee
                .contracts
                .iter()
                .any(|contract| contract.kind == SignatureContractKind::Ensures)
        {
            return None;
        }
        let call_arguments = program.expression_table.expression_handles(call.arguments);
        let total_operands = usize::from(call.receiver.is_valid()) + call_arguments.len();
        if total_operands != callee.leading_operands + callee.parameters.len() {
            return None;
        }
        let arguments: Vec<_> = call
            .receiver
            .is_valid()
            .then_some(call.receiver)
            .into_iter()
            .chain(call_arguments.iter().copied())
            .skip(callee.leading_operands)
            .collect();
        let mut pending: Vec<_> = program
            .contract_expressions(callee.contracts.iter(), SignatureContractKind::Ensures)
            .collect();
        let mut budget = 128;
        while let Some(expression) = pending.pop() {
            if budget == 0 {
                return None;
            }
            budget -= 1;
            let Some(binary) = program.expression_table.binary_node(expression) else {
                continue;
            };
            if binary.operator == BinaryOperator::And {
                pending.extend([binary.left, binary.right]);
                continue;
            }
            if binary.operator != BinaryOperator::Equal {
                continue;
            }
            let is_result = |operand| {
                crate::reserved_result_owner(program, operand).is_some_and(|(owner, reference)| {
                    owner == callee.callable && reference == callee.return_type
                })
            };
            let measure = if is_result(binary.left) {
                binary.right
            } else if is_result(binary.right) {
                binary.left
            } else {
                continue;
            };
            let measure_source = length_measure_source(program, measure);
            let Some(member) = crate::length_member(program, measure_source) else {
                continue;
            };
            let ExpressionNode::Name(path) = program.expression_table.expression(member.receiver)
            else {
                continue;
            };
            let Some(position) = callee.parameters.iter().position(|formal| {
                formal.symbol.is_valid()
                    && path.symbol == formal.symbol
                    && path.head_symbol == formal.symbol
            }) else {
                continue;
            };
            let formal = &callee.parameters[position];
            if formal.is_mutable || formal.is_const {
                continue;
            }
            let TypeReferenceNode::Reference {
                referee, access, ..
            } = program
                .type_reference_table
                .type_reference(formal.type_reference)
            else {
                continue;
            };
            if *access != language_semantics::ReferenceAccess::Shared
                || !matches!(
                    program.type_reference_table.type_reference(*referee),
                    TypeReferenceNode::FixedArray { .. } | TypeReferenceNode::Slice { .. }
                )
            {
                continue;
            }
            let Some(measure_type) = crate::parameter_expression_result_type_reference(
                program,
                callee.callable,
                callee.parameters,
                measure,
            ) else {
                continue;
            };
            let operand_types = if is_result(binary.left) {
                [Some(callee.return_type), Some(measure_type)]
            } else {
                [Some(measure_type), Some(callee.return_type)]
            };
            if !super::call_result_bounds::builtin(
                program,
                callee.callable,
                expression,
                binary.operator,
                &operand_types,
            ) {
                continue;
            }
            let actual = arguments[position];
            return Some(match program.expression_table.expression(actual) {
                ExpressionNode::Borrow(borrow) => borrow.target,
                _ => actual,
            });
        }
        None
    }

    fn length_measure_source(
        program: &dyn crate::CheckingInput,
        mut expression: ExpressionHandle,
    ) -> ExpressionHandle {
        for _ in 0..8 {
            let ExpressionNode::Cast(cast) = program.expression_table.expression(expression) else {
                break;
            };
            if !super::plain_exact_widening_cast(program, cast) {
                break;
            }
            expression = cast.value;
        }
        expression
    }
}
pub use call_result_measures::normal_return_length_collection;
pub(crate) mod cast_ranges {
    use super::ValueEnvironment;
    use crate::proof_contracts::arithmetic_domains::integer_ranges::primitive_range;
    use diagnostics::Diagnostic;
    use typed_trees::expression::ExpressionHandle;
    use typed_trees::machine::Machine;
    use typed_trees::state::State;

    pub(crate) fn validate_range_cast_at_use(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        let Some(cast) = program.expression_table.cast_node(expression) else {
            return;
        };
        if cast.form.is_recast() {
            return;
        }
        let integer_target = program
            .primitive_type_reference(cast.target_type)
            .is_some_and(|primitive| primitive_range(primitive).is_some());
        if !integer_target {
            return;
        }
        let owner = format!(
            "machine `{}` state `{}` cast expression",
            machine.name, state.name
        );
        let mut found = Vec::new();
        super::validate_arithmetic_domains(
            program,
            machine,
            Some(state),
            expression,
            environment,
            None,
            numerics::arithmetic::ArithmeticDomain::Exact,
            &owner,
            &mut found,
        );
        for diagnostic in found {
            let duplicate = diagnostics.iter().any(|existing| {
                existing.source_span == diagnostic.source_span
                    && (existing.message == diagnostic.message
                        || (existing.message.starts_with("cast target range in ")
                            && diagnostic.message.starts_with("cast target range in ")))
            });
            if !duplicate {
                diagnostics.push(diagnostic);
            }
        }
    }

    pub fn plain_exact_widening_cast(
        program: &dyn crate::CheckingInput,
        cast: &typed_trees::expression::TableCastExpression,
    ) -> bool {
        unannotated_exact_cast(cast)
            && matches!(
                program
                    .type_reference_table
                    .type_reference(cast.target_type),
                typed_trees::types::TypeReferenceNode::Named { .. }
            )
    }

    pub fn unannotated_exact_cast(cast: &typed_trees::expression::TableCastExpression) -> bool {
        !cast.form.is_recast()
            && cast.domain == numerics::arithmetic::ArithmeticDomain::Exact
            && cast.semantic_domain.is_empty()
            && cast.semantic_domain_arguments.is_empty()
            && !cast.semantic_domain_symbol.is_valid()
            && !cast.semantic_domain_id.is_valid()
            && !(cast.result_type.is_valid() && cast.result_type != cast.target_type)
    }
}
pub(crate) mod dispatch_environments {

    use super::{Machine, State, ValueEnvironment, guard_narrowing};
    use crate::frozen_program::expression_table;
    use crate::machine_calls::calls::{CallFrameResolver, expression_has_calls};
    use typed_trees::expression::{
        BinaryOperator, ExpressionHandle, MatchPattern, TableBinaryExpression, TableMatchExpression,
    };

    #[derive(Clone, Copy)]
    pub(crate) struct DispatchSelection {
        pub(crate) expression: ExpressionHandle,
        pub(crate) condition: DispatchCondition,
        pub(crate) matched: bool,
    }

    #[derive(Clone, Copy)]
    pub(crate) enum DispatchCondition {
        Equality {
            subject: ExpressionHandle,
            pattern: ExpressionHandle,
        },
        Predicate(ExpressionHandle),
    }

    pub(crate) fn dispatch_arm_contexts<Context: Clone>(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
        dispatch: &TableMatchExpression,
        context: &Context,
        mut form_pattern: impl FnMut(&Context, ExpressionHandle) -> bool,
        mut select: impl FnMut(&mut Context, DispatchSelection),
    ) -> Vec<Context> {
        let mut remaining = context.clone();
        expression_table(program)
            .match_arms(dispatch.arms)
            .iter()
            .map(|arm| {
                dispatch_arm_context(
                    expression,
                    dispatch.subject,
                    arm.pattern,
                    &mut remaining,
                    &mut form_pattern,
                    &mut select,
                )
            })
            .collect()
    }

    /// Select one already-associated authored arm from the remaining paths. The
    /// caller owns its actual operand execution; this step retains only facts
    /// justified by that completed pattern and its exact true or false outcome.
    pub(crate) fn dispatch_arm_context<Context: Clone>(
        expression: ExpressionHandle,
        subject: ExpressionHandle,
        pattern: MatchPattern,
        remaining: &mut Context,
        form_pattern: &mut impl FnMut(&Context, ExpressionHandle) -> bool,
        select: &mut impl FnMut(&mut Context, DispatchSelection),
    ) -> Context {
        let mut selected = remaining.clone();
        let condition = match pattern {
            MatchPattern::Value(pattern) if form_pattern(remaining, pattern) => {
                Some(DispatchCondition::Equality { subject, pattern })
            }
            MatchPattern::Destructure(pattern) if form_pattern(remaining, pattern.condition) => {
                Some(DispatchCondition::Predicate(pattern.condition))
            }
            _ => None,
        };
        if let Some(condition) = condition {
            select(
                &mut selected,
                DispatchSelection {
                    expression,
                    condition,
                    matched: true,
                },
            );
            select(
                remaining,
                DispatchSelection {
                    expression,
                    condition,
                    matched: false,
                },
            );
        }
        selected
    }

    pub(crate) fn dispatch_arm_environments(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        dispatch: &TableMatchExpression,
        environment: &ValueEnvironment,
    ) -> Vec<ValueEnvironment> {
        let writes = if expression_has_calls(program, expression) {
            CallFrameResolver::new(program)
                .and_then(|frames| frames.expression_may_write_paths(machine, expression))
        } else {
            Some(Vec::new())
        };
        dispatch_arm_contexts(
            program,
            expression,
            dispatch,
            environment,
            |_, _| true,
            |selected, selection| {
                narrow_dispatch_selection(program, machine, state, dispatch, selected, selection)
            },
        )
        .into_iter()
        .map(|mut selected| {
            match &writes {
                Some(writes) => selected.invalidate_call_paths(program, state, writes),
                None => selected.invalidate_unknown_writes(program, state),
            }
            selected
        })
        .collect()
    }

    /// Publish the same selected comparison facts for expression checking and
    /// state arrivals. The caller subsequently retires every source consequence
    /// changed by the actual evaluated prefix before an arm can consume it.
    pub(crate) fn narrow_dispatch_selection(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        dispatch: &TableMatchExpression,
        selected: &mut ValueEnvironment,
        selection: DispatchSelection,
    ) {
        match selection.condition {
            DispatchCondition::Equality { subject, pattern } => {
                let comparison = TableBinaryExpression {
                    policy: numerics::arithmetic::ArithmeticDomain::Exact,
                    left: subject,
                    operator: BinaryOperator::Equal,
                    right: pattern,
                };
                guard_narrowing::narrow_environment_by_comparison(
                    program,
                    machine,
                    state,
                    selected,
                    selection.expression,
                    &comparison,
                    selection.matched,
                );
            }
            DispatchCondition::Predicate(condition) => {
                guard_narrowing::narrow_environment_by_condition(
                    program,
                    machine,
                    state,
                    selected,
                    condition,
                    selection.matched,
                );
            }
        }
        // The captured value and its source agree until a write changes
        // the source. Rebind the predicate's captured paths now; the caller's
        // evaluated write frame then withdraws every unstable source consequence
        // before an arm can consume it. Capture paths retain
        // their own identity and never become global source aliases.
        if dispatch.capture.is_valid()
            && let Some(source) = super::place_path(program, dispatch.subject)
        {
            let anchor = expression_table(program)
                .value_capture(dispatch.capture)
                .value_anchor;
            selected.copy_path_facts(&super::place_paths::capture_path(anchor), &source);
        }
    }
}
mod evaluated_writes {
    //! Writes from the subject and patterns that have actually completed. Later
    //! patterns and selected bodies cannot invalidate an earlier arm's premises.
    //! The ordered set indexes candidates; the call-frame owner decides overlap.

    use std::collections::BTreeSet;
    use std::ops::Bound::{Included, Unbounded};

    #[derive(Default)]
    pub(super) struct EvaluatedWritePrefix {
        writes: BTreeSet<String>,
        unknown: bool,
    }

    impl EvaluatedWritePrefix {
        pub(super) fn extend(&mut self, writes: Option<Vec<String>>) {
            if self.unknown {
                return;
            }
            match writes {
                Some(writes) => self.writes.extend(writes),
                None => {
                    self.unknown = true;
                    self.writes.clear();
                }
            }
        }

        pub(super) fn is_unknown(&self) -> bool {
            self.unknown
        }

        pub(super) fn is_empty(&self) -> bool {
            !self.unknown && self.writes.is_empty()
        }

        pub(super) fn overlaps(&self, path: &str) -> bool {
            if self.unknown {
                return true;
            }
            if self.writes.is_empty() {
                return false;
            }
            let agrees =
                |candidate: &str| crate::machine_calls::calls::frame_paths_overlap(path, candidate);
            // An ancestor write must be an exact string prefix. Looking up those
            // prefixes avoids scanning all earlier writes for every new arm.
            if path
                .char_indices()
                .map(|(end, _)| &path[..end])
                .chain(std::iter::once(path))
                .any(|prefix| self.writes.get(prefix).is_some_and(|write| agrees(write)))
            {
                return true;
            }
            let mut candidate = String::with_capacity(path.len() + 3);
            // A collection-content frame also covers its indexed descendants,
            // while its descriptor length remains a separate observation.
            for (position, character) in path.char_indices() {
                if character == '[' {
                    candidate.clear();
                    candidate.push_str(&path[..position]);
                    candidate.push_str("[*]");
                    if self
                        .writes
                        .get(candidate.as_str())
                        .is_some_and(|write| agrees(write))
                    {
                        return true;
                    }
                }
            }
            // The first write in either descendant range suffices: all entries
            // with that prefix are contiguous and the canonical relation covers
            // each. A wildcard read additionally covers the collection's indexes.
            let descendants = [
                (Some(path), "."),
                (Some(path), "["),
                (path.strip_suffix("[*]"), "["),
            ];
            for (parent, separator) in descendants {
                let Some(parent) = parent else { continue };
                candidate.clear();
                candidate.push_str(parent);
                candidate.push_str(separator);
                if self
                    .writes
                    .range::<str, _>((Included(candidate.as_str()), Unbounded))
                    .next()
                    .is_some_and(|write| write.starts_with(candidate.as_str()) && agrees(write))
                {
                    return true;
                }
            }
            false
        }
    }

    #[cfg(test)]
    mod tests {

        use super::EvaluatedWritePrefix;

        #[test]
        fn accumulated_prefix_matches_the_call_frame_overlap_oracle() {
            let observed = [
                "packet",
                "packet.value",
                "packet.value.child",
                "packet.value.child.nested",
                "packet.value_suffix",
                "packets.value",
                "packet.cells",
                "packet.cells[0]",
                "packet.cells[0].field",
                "packet.cells[1].field",
                "packet.cells[*]",
                "packet.cells.len",
                "packet.side",
            ];
            let mut prefix = EvaluatedWritePrefix::default();
            let mut linear = Vec::new();
            for written in [
                vec![],
                vec!["packet.value.child"],
                vec!["packets.value"],
                vec!["packet.cells[0].field"],
                vec!["packet.cells[*]"],
                vec!["packet"],
            ] {
                prefix.extend(Some(
                    written.iter().map(|path| (*path).to_owned()).collect(),
                ));
                linear.extend(written);
                for path in observed {
                    assert_eq!(
                        prefix.overlaps(path),
                        linear.iter().any(
                            |write| crate::machine_calls::calls::frame_paths_overlap(path, write)
                        ),
                        "read {path}, evaluated writes {linear:?}",
                    );
                }
            }
            prefix.extend(None);
            assert!(prefix.is_unknown());
            assert!(!prefix.is_empty());
            prefix.extend(Some(Vec::new()));
            assert!(prefix.is_unknown());
            for path in observed {
                assert!(prefix.overlaps(path));
            }
        }
    }
}
pub(crate) use dispatch_environments::dispatch_arm_environments;
pub(crate) use dispatch_environments::{
    DispatchCondition, DispatchSelection, dispatch_arm_contexts,
};
pub(crate) mod cited_element_bounds {
    use super::guard_narrowing::projected_facts::{
        ProjectedOperand, contribute_projected_comparison,
    };
    use super::ordered_values::{self, Operand};
    use super::{BinaryOperator, ExpressionHandle, Machine, State, ValueEnvironment, place_path};
    use crate::CheckingInput;
    use crate::frozen_program::expression_table;
    use crate::proof_contracts::bound_expression_meaning::has_builtin_binary_expression_meaning;
    use language_semantics::const_value::CanonicalConstValue;
    use language_semantics::const_value::DecodedCanonicalConstValue;
    use typed_trees::data::TypeParameterKind;
    use typed_trees::expression::ExpressionNode;
    use typed_trees::expression::StaticMachineArgument;

    pub(crate) fn element_place_path(
        program: &dyn CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<String> {
        let indexed = expression_table(program).indexed_node(expression)?;
        let index = expression_table(program).constant_integer_value(indexed.index)?;
        let index = u64::try_from(index).ok()?;
        Some(format!(
            "{}[{index}]",
            place_path(program, indexed.collection)?
        ))
    }

    pub(crate) fn stable_element_place_path(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
    ) -> Option<String> {
        let indexed = expression_table(program).indexed_node(expression)?;
        if let Some(element_index) = program
            .closed_integer_expression_value_in(indexed.index, machine.symbol)
            .and_then(|value| value.to_u64())
            .and_then(|value| usize::try_from(value).ok())
        {
            return crate::value_custody::places::canonical_collection_element_place(
                program,
                machine,
                state,
                indexed.collection,
                element_index,
            )
            .map(|place| place.label(program));
        }
        let state = state?;
        let parameter = |operand: ExpressionHandle| {
            let name = expression_table(program).name_path_node(operand)?;
            if !name.symbol.is_valid() || name.symbol != name.head_symbol {
                return None;
            }
            program.state_parameter_by_symbol(state, name.symbol)
        };
        let collection = parameter(indexed.collection)?;
        let index = parameter(indexed.index)?;
        let frozen = matches!(
            program
                .type_reference_table
                .type_reference(collection.type_reference),
            typed_trees::types::TypeReferenceNode::Reference {
                access: language_core::ReferenceAccess::Shared,
                ..
            }
        ) && crate::state_reference_parameter_binding_is_stable(
            program,
            machine,
            state,
            collection.symbol,
        );
        let fixed_index = !index.is_mutable
            && program
                .primitive_type_reference(index.type_reference)
                .is_some_and(|primitive| primitive.accepts_integer_literal());
        (frozen && fixed_index).then(|| {
            Some(format!(
                "{}[{}]",
                place_path(program, indexed.collection)?,
                place_path(program, indexed.index)?
            ))
        })?
    }

    pub(crate) fn seed_cited_element_bounds(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        call: &typed_trees::statement::TableCall,
        written: Option<&[String]>,
        environment: &mut ValueEnvironment,
    ) {
        if !call.receiver.is_empty() || call.static_requirement_dispatch.is_some() {
            return;
        }
        let (target, static_arguments) = if call.authored_machine_application.is_valid() {
            let application = expression_table(program)
                .static_machine_application(call.authored_machine_application);
            (
                application.registration_operation,
                expression_table(program)
                    .static_machine_application_arguments(call.authored_machine_application),
            )
        } else {
            (call.target_symbol, call.machine_arguments.as_ref())
        };
        let Some(callee) = checked_callee(program, target) else {
            return;
        };
        let Some(entry) = program.machine_states(callee).first() else {
            return;
        };
        let parameters = program.state_parameters(entry);
        let arguments = program.statement_table.expression_handles(call.arguments);

        if parameters.len() != arguments.len() {
            return;
        }
        let substitution = Substitution {
            program,
            machine,
            state,
            parameters,
            arguments,
            written,
            static_arguments,
        };
        for expression in crate::proof_contracts::proof_facts::ensures_expression_facts(
            program,
            program.machine_contracts(callee),
        ) {
            seed_conjunct(
                program,
                callee,
                entry,
                &substitution,
                expression,
                environment,
            );
        }
    }

    fn checked_callee(
        program: &dyn CheckingInput,
        symbol: symbols::SymbolHandle,
    ) -> Option<&Machine> {
        if !symbol.is_valid() {
            return None;
        }
        program.machines().iter().find(|machine| {
            machine.attached_data.is_none()
                && machine.supply_mode == language_semantics::MachineSupplyMode::CheckedBody
                && machine.body_is_present
                && (machine.symbol == symbol
                    || program
                        .machine_states(machine)
                        .first()
                        .is_some_and(|entry| entry.symbol == symbol))
        })
    }

    pub(crate) struct Substitution<'program> {
        program: &'program dyn CheckingInput,
        machine: &'program Machine,
        state: Option<&'program State>,
        parameters: &'program [typed_trees::signature::StateParameter],
        arguments: &'program [ExpressionHandle],
        written: Option<&'program [String]>,
        static_arguments: &'program [StaticMachineArgument],
    }

    impl Substitution<'_> {
        fn actual(&self, formal: ExpressionHandle) -> Option<ExpressionHandle> {
            let path = expression_table(self.program).name_path_node(formal)?;
            if !path.symbol.is_valid()
                || expression_table(self.program)
                    .name_path_members(path.members)
                    .len()
                    != 1
            {
                return None;
            }
            let position =
                typed_trees::signature::state_parameter_position(self.parameters, path.symbol)?;
            let parameter = &self.parameters[position];
            let reference = matches!(
                self.program
                    .type_reference_table
                    .type_reference(parameter.type_reference),
                typed_trees::types::TypeReferenceNode::Reference { .. }
            );
            if parameter.is_mutable && !reference {
                return None;
            }
            self.arguments.get(position).copied()
        }

        fn scalar(
            &self,
            callee: &Machine,
            entry: &State,
            expression: ExpressionHandle,
        ) -> Option<ProjectedOperand> {
            let state = self.state?;
            let mut bindings = Vec::new();
            for (parameter, actual) in self.parameters.iter().zip(self.arguments) {
                if parameter.is_mutable
                    || !self
                        .program
                        .primitive_type_reference(parameter.type_reference)
                        .is_some_and(|primitive| primitive.is_fixed_integer())
                {
                    continue;
                }
                let value =
                    ordered_values::operand(self.program, self.machine, state, *actual, None)?;
                if !value.is_immutable_snapshot(self.program, state)
                    && !self.written.is_some_and(|written| value.survives(written))
                {
                    continue;
                }
                bindings.push((Operand::parameter(parameter), value));
            }
            let parameters = self.program.machine_type_parameters(callee);
            if parameters.len() != self.static_arguments.len() {
                return None;
            }
            for (parameter, argument) in parameters.iter().zip(self.static_arguments) {
                if !matches!(
                    parameter.kind,
                    TypeParameterKind::Value { .. } | TypeParameterKind::Const { .. }
                ) {
                    continue;
                }
                let value = self.static_operand(argument)?;
                if !value.is_immutable_snapshot(self.program, state)
                    && !self.written.is_some_and(|written| value.survives(written))
                {
                    continue;
                }
                bindings.push((
                    Operand::Place {
                        root: parameter.symbol,
                        path: parameter.name.as_str().to_owned(),
                    },
                    value,
                ));
            }
            let source = ordered_values::operand(self.program, callee, entry, expression, None)?;
            fn fully_bound(value: &Operand, bindings: &[(Operand, Operand)]) -> bool {
                match value {
                    Operand::Integer(..) => true,
                    Operand::Place { .. } => bindings.iter().any(|(formal, _)| formal == value),
                    Operand::Binary { operands, .. } => {
                        operands.iter().all(|value| fully_bound(value, bindings))
                    }
                    _ => false,
                }
            }
            if !fully_bound(&source, &bindings) {
                return None;
            }
            let values = source.rebound(&bindings);
            let [operand] = values.as_slice() else {
                return None;
            };
            if !operand.is_immutable_snapshot(self.program, state)
                && !self
                    .written
                    .is_some_and(|written| operand.survives(written))
            {
                return None;
            }
            Some(ProjectedOperand {
                operand: Some(operand.clone()),
                spelled: None,
                declared_type: None,
            })
        }

        fn static_operand(&self, argument: &StaticMachineArgument) -> Option<Operand> {
            if let Some(literal) = &argument.const_literal {
                return Some(Operand::Integer(literal.clone(), literal.landing()));
            }
            if argument.type_reference.is_valid()
                && let typed_trees::types::TypeReferenceNode::ConstExpression(expression) = self
                    .program
                    .type_reference_table
                    .type_reference(argument.type_reference)
            {
                return ordered_values::operand(
                    self.program,
                    self.machine,
                    self.state?,
                    *expression,
                    None,
                );
            }
            if argument.symbol.is_valid() {
                let state = self.state?;
                let parameter = self
                    .program
                    .state_parameter_by_symbol(state, argument.symbol);
                let local = self.program.state_local_declaration(state, argument.symbol);
                let static_parameter = self
                    .program
                    .machine_type_parameters(self.machine)
                    .iter()
                    .any(|parameter| {
                        parameter.symbol == argument.symbol
                            && matches!(
                                parameter.kind,
                                TypeParameterKind::Value { .. } | TypeParameterKind::Const { .. }
                            )
                    });
                if parameter.is_none() && local.is_none() && !static_parameter {
                    return None;
                }
                let reference = crate::value_custody::places::declaration_type_reference(
                    self.program,
                    argument.symbol,
                )?;
                if !self
                    .program
                    .primitive_type_reference(reference)
                    .is_some_and(|primitive| primitive.is_fixed_integer())
                {
                    return None;
                }
                return Some(Operand::Place {
                    root: argument.symbol,
                    path: self.program.symbols.name(argument.symbol).to_owned(),
                });
            }
            let spelling = typed_trees::typed_trees::static_const_argument_spelling(
                self.program.typed_program(),
                argument,
            )?;
            let value = if let Some(canonical) = CanonicalConstValue::from_atom(&spelling) {
                match canonical.decode_encoding()? {
                    DecodedCanonicalConstValue::Integer { value, .. } => value,
                    _ => return None,
                }
            } else {
                spelling.parse::<i128>().ok()?
            };
            let literal = numerics::literals::IntegerLiteral::from_parts(
                value < 0,
                numerics::literals::IntegerRadix::Decimal,
                &value.unsigned_abs().to_string(),
            )
            .ok()?;
            Some(Operand::Integer(literal, None))
        }

        fn element(
            &self,
            callee: &Machine,
            entry: &State,
            formal: ExpressionHandle,
        ) -> Option<ProjectedOperand> {
            let indexed = expression_table(self.program).indexed_node(formal)?;
            let array = self.actual(indexed.collection)?;
            let state = self.state?;
            let declared =
                crate::declared_place_type_raw(self.program, callee, Some(entry), formal)?;
            let primitive = self.program.primitive_type_reference(declared)?;
            if !primitive.is_fixed_integer() {
                return None;
            }
            let mut bindings = Vec::new();
            for (parameter, actual) in self.parameters.iter().zip(self.arguments) {
                if parameter.is_mutable
                    || self
                        .program
                        .primitive_type_reference(parameter.type_reference)
                        .is_none()
                {
                    continue;
                }
                let Some(value) =
                    ordered_values::operand(self.program, self.machine, state, *actual, None)
                else {
                    continue;
                };
                if !value.is_immutable_snapshot(self.program, state)
                    && !self.written.is_some_and(|written| value.survives(written))
                {
                    continue;
                }
                bindings.push((Operand::parameter(parameter), value));
            }
            let selector =
                ordered_values::operand(self.program, callee, entry, indexed.index, None)?;
            let selectors = selector.rebound(&bindings);
            let [selector] = selectors.as_slice() else {
                return None;
            };
            let operand = ordered_values::indexed_operand(
                self.program,
                self.machine,
                state,
                array,
                selector.clone(),
                Some(primitive),
                None,
                0,
            )?;
            let spelled = if let Operand::Integer(literal, _) = selector {
                literal
                    .value_u64()
                    .and_then(|value| usize::try_from(value).ok())
                    .and_then(|index| {
                        crate::value_custody::places::canonical_collection_element_place(
                            self.program,
                            self.machine,
                            self.state,
                            array,
                            index,
                        )
                    })
                    .map(|place| place.label(self.program))
            } else {
                None
            };
            Some(ProjectedOperand {
                operand: Some(operand),
                spelled,
                declared_type: Some(declared),
            })
        }
    }

    fn seed_conjunct(
        program: &dyn CheckingInput,
        callee: &Machine,
        entry: &State,
        substitution: &Substitution<'_>,
        conjunct: ExpressionHandle,
        environment: &mut ValueEnvironment,
    ) {
        let Some(comparison) = expression_table(program).binary_node(conjunct) else {
            return;
        };
        if comparison.operator == BinaryOperator::And {
            seed_conjunct(
                program,
                callee,
                entry,
                substitution,
                comparison.left,
                environment,
            );
            seed_conjunct(
                program,
                callee,
                entry,
                substitution,
                comparison.right,
                environment,
            );
            return;
        }
        if !matches!(
            comparison.operator,
            BinaryOperator::Less
                | BinaryOperator::LessOrEqual
                | BinaryOperator::Greater
                | BinaryOperator::GreaterOrEqual
                | BinaryOperator::Equal
        ) || !has_builtin_binary_expression_meaning(program, callee, Some(entry), conjunct)
        {
            return;
        }
        let side = |expression| {
            if let ExpressionNode::Integer(literal) =
                expression_table(program).expression(expression)
            {
                Some(ProjectedOperand::literal(literal))
            } else {
                substitution
                    .element(callee, entry, expression)
                    .or_else(|| substitution.scalar(callee, entry, expression))
            }
        };
        let sides = (side(comparison.left), side(comparison.right));
        let (Some(left), Some(right)) = sides else {
            return;
        };
        contribute_projected_comparison(
            program,
            environment,
            comparison.operator,
            (&left, comparison.left),
            (&right, comparison.right),
        );
    }
}
pub(crate) mod copied_values {
    use super::value_environment::StoredIntegerRange;
    use super::{Interval, ValueEnvironment, ordered_values, place_path};
    use crate::value_custody::places::{CanonicalPlace, canonical_place_from_expression};
    use facts::PlaceSegment;
    use std::collections::BTreeMap;
    use typed_trees::expression::{ExpressionHandle, ExpressionNode};

    pub(crate) mod captured_observations {
        use super::super::ordered_values::{self, Operand};
        use typed_trees::state::State;
        use typed_trees::types::TypeReferenceHandle;

        pub(crate) fn scalar_path_survives(
            program: &dyn crate::CheckingInput,
            reference: TypeReferenceHandle,
            path: Option<&[facts::PlaceSegment]>,
            writes: Option<&[String]>,
        ) -> bool {
            if writes.is_some_and(<[String]>::is_empty) {
                return true;
            }
            if !reference.is_valid() {
                return false;
            }
            let Some(path) = path else {
                return false;
            };
            let mut reference = reference;
            for segment in path {
                if crate::reference_shell(program, reference).is_some() {
                    return false;
                }
                let Some(projected) = crate::project_type_reference_from_segments(
                    program,
                    reference,
                    std::slice::from_ref(segment),
                ) else {
                    return false;
                };
                reference = projected;
            }
            crate::reference_shell(program, reference).is_none()
        }

        pub(crate) struct CapturedValue<'value> {
            pub(crate) operand: &'value Operand,
            pub(crate) type_reference: TypeReferenceHandle,
        }

        impl CapturedValue<'_> {
            pub(crate) fn observation_survives(
                &self,
                program: &dyn crate::CheckingInput,
                state: &State,
                observed: &Operand,
                writes: Option<&[String]>,
            ) -> bool {
                if !super::depends_on(observed, self.operand) {
                    return ordered_values::survives_delivery(
                        program,
                        state,
                        observed,
                        self.operand,
                        writes,
                    );
                }
                if writes.is_some_and(<[String]>::is_empty) {
                    return true;
                }
                if observed == self.operand {
                    return self.type_reference.is_valid()
                        && crate::reference_shell(program, self.type_reference).is_none();
                }
                let survives = |operand| self.observation_survives(program, state, operand, writes);
                match observed {
                    Operand::Field { .. } | Operand::Indexed { .. } => self
                        .owned_projection_type(program, state, observed, writes)
                        .is_some_and(|reference| {
                            crate::reference_shell(program, reference).is_none()
                        }),
                    Operand::CollectionLength(collection) => self
                        .owned_projection_type(program, state, collection, writes)
                        .is_some_and(|reference| {
                            crate::slice_view_shell(program, reference, &[]).is_some()
                        }),
                    Operand::Binary { operands, .. } => operands.iter().all(survives),
                    Operand::Call { arguments, .. } => arguments.iter().all(survives),
                    #[cfg(test)]
                    Operand::CompletedCall { .. } => false,
                    Operand::Place { .. } | Operand::Integer(..) => false,
                }
            }

            fn owned_projection_type(
                &self,
                program: &dyn crate::CheckingInput,
                state: &State,
                observed: &Operand,
                writes: Option<&[String]>,
            ) -> Option<TypeReferenceHandle> {
                if observed == self.operand {
                    return self
                        .type_reference
                        .is_valid()
                        .then_some(self.type_reference);
                }
                let (parent, field) = match observed {
                    Operand::Field {
                        receiver, field, ..
                    } => (receiver.as_ref(), Some(*field)),
                    Operand::Indexed {
                        collection, index, ..
                    } => {
                        if !self.observation_survives(program, state, index, writes) {
                            return None;
                        }
                        (collection.as_ref(), None)
                    }
                    _ => return None,
                };
                let reference = self.owned_projection_type(program, state, parent, writes)?;
                if crate::reference_shell(program, reference).is_some() {
                    return None;
                }
                if let Some(symbol) = field {
                    crate::project_type_reference_from_segments(
                        program,
                        reference,
                        &[facts::PlaceSegment::Field { symbol }],
                    )
                } else {
                    crate::collection_element_type_reference(program, reference)
                }
            }
        }
    }
    pub(crate) mod delivery {
        use typed_trees::expression::{ExpressionHandle, ExpressionNode, TableStructLiteralField};

        pub(crate) fn fields(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
        ) -> Option<&[TableStructLiteralField]> {
            let ExpressionNode::StructLiteral(literal) =
                program.expression_table.expression(expression)
            else {
                return None;
            };
            Some(program.expression_table.struct_fields(literal.fields))
        }

        pub(crate) fn visit_values(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            visitor: &mut impl FnMut(ExpressionHandle),
        ) {
            if !expression.is_valid() {
                return;
            }
            visitor(expression);
            if let Some(fields) = fields(program, expression) {
                for field in fields {
                    visit_values(program, field.value, visitor);
                }
            }
        }
    }
    use captured_observations::CapturedValue;
    pub(crate) mod source_observations {
        use super::super::ordered_values;
        use typed_trees::expression::{ExpressionHandle, ExpressionNode};
        use typed_trees::{machine::Machine, state::State};

        pub(crate) struct SourceObservations<'a> {
            pub(crate) program: &'a dyn crate::CheckingInput,
            machine: &'a Machine,
            state: Option<&'a State>,
            frames: Option<crate::CallFrameResolver<'a>>,
        }

        impl<'a> SourceObservations<'a> {
            pub(crate) fn following_writes(
                &self,
                expressions: impl DoubleEndedIterator<Item = ExpressionHandle>,
                following: Option<&[String]>,
            ) -> Vec<Option<Vec<String>>> {
                let mut written = following.map(<[String]>::to_vec);
                let mut suffixes = Vec::new();
                for expression in expressions.rev() {
                    suffixes.push(written.clone());
                    if let Some(paths) = written.as_mut()
                        && !self.include_effects(expression, paths)
                    {
                        written = None;
                    }
                }
                suffixes.reverse();
                suffixes
            }

            pub(crate) fn effects(&self, expression: ExpressionHandle) -> Option<Vec<String>> {
                let mut written = Vec::new();
                self.include_effects(expression, &mut written)
                    .then_some(written)
            }

            pub(crate) fn new(
                program: &'a dyn crate::CheckingInput,
                machine: &'a Machine,
                state: Option<&'a State>,
                expression: ExpressionHandle,
            ) -> Self {
                let frames = crate::machine_calls::calls::expression_has_calls(program, expression)
                    .then(|| crate::CallFrameResolver::new(program))
                    .flatten();
                Self {
                    program,
                    machine,
                    state,
                    frames,
                }
            }

            pub(crate) fn include_effects(
                &self,
                expression: ExpressionHandle,
                written: &mut Vec<String>,
            ) -> bool {
                if !crate::machine_calls::calls::expression_has_calls(self.program, expression) {
                    return true;
                }
                let Some(paths) = self
                    .frames
                    .as_ref()
                    .and_then(|frames| frames.expression_may_write_paths(self.machine, expression))
                else {
                    return false;
                };
                written.extend(paths);
                true
            }

            pub(crate) fn permits(&self, expression: ExpressionHandle, written: &[String]) -> bool {
                let mut written = written.to_vec();
                if !self.include_effects(expression, &mut written) {
                    return false;
                }
                if written.is_empty()
                    || matches!(
                        self.program.expression_table.expression(expression),
                        ExpressionNode::Integer(_)
                            | ExpressionNode::Float(_)
                            | ExpressionNode::UndeterminedNaN(_)
                            | ExpressionNode::Boolean(_)
                    )
                {
                    return true;
                }
                self.state.is_some_and(|state| {
                    ordered_values::operand(
                        self.program,
                        self.machine,
                        state,
                        expression,
                        self.frames.as_ref(),
                    )
                    .is_some_and(|operand| operand.survives(&written))
                })
            }
        }
    }
    use source_observations::SourceObservations;

    pub(crate) struct CaptureContext<'a> {
        source: SourceObservations<'a>,
        environment: &'a ValueEnvironment,
        checked_values: &'a [super::expression_analysis::CheckedIntegerValue],
    }

    #[derive(Default)]
    pub(crate) struct CopiedIntegerValue {
        recipes: Vec<(Vec<PlaceSegment>, String, checked_trees::IntegerRangeRecipe)>,
        intervals: Vec<CapturedScalarObservation<Interval>>,
        unsigned_values: Vec<CapturedScalarObservation<u64>>,
        float_intervals: Vec<CapturedScalarObservation<super::value_environment::FloatInterval>>,
        non_nan_paths: Vec<CapturedScalarObservation<()>>,
        float_aliases: Vec<CapturedScalarObservation<String>>,
        ordered_relations: Vec<ordered_values::Relation>,
        completed_relations: Vec<ordered_values::Relation>,
    }

    pub(crate) struct CapturedScalarObservation<Value> {
        segments: Option<Vec<PlaceSegment>>,
        suffix: String,
        value: Value,
    }

    impl CopiedIntegerValue {
        pub(crate) fn integer_range_recipe(&self) -> Option<&checked_trees::IntegerRangeRecipe> {
            self.recipes
                .iter()
                .find(|(segments, suffix, _)| segments.is_empty() && suffix.is_empty())
                .map(|(_, _, recipe)| recipe)
        }

        pub(crate) fn visit_delivered_values(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            visitor: &mut impl FnMut(ExpressionHandle),
        ) {
            delivery::visit_values(program, expression, visitor);
        }

        pub(crate) fn capture(
            program: &dyn crate::CheckingInput,
            machine: &typed_trees::machine::Machine,
            state: Option<&typed_trees::state::State>,
            expression: ExpressionHandle,
            receiving_type: typed_trees::types::TypeReferenceHandle,
            environment: &ValueEnvironment,
            checked_values: &[super::expression_analysis::CheckedIntegerValue],
        ) -> Self {
            let mut value = Self::default();
            let context = CaptureContext {
                source: SourceObservations::new(program, machine, state, expression),
                environment,
                checked_values,
            };
            value.capture_at(&context, receiving_type, expression, "", &[], Some(&[]));
            value
        }

        pub(crate) fn capture_local_relations(
            &mut self,
            program: &dyn crate::CheckingInput,
            machine: &typed_trees::machine::Machine,
            state: Option<&typed_trees::state::State>,
            local: &typed_trees::statement::TableLocalData,
            environment: &ValueEnvironment,
        ) {
            let destination = ordered_values::Operand::Place {
                root: local.symbol,
                path: local.name.as_str().to_owned(),
            };
            let written = [local.name.as_str().to_owned()];
            let observed = self.capture_relations(
                program,
                machine,
                state,
                local.initial_value,
                &destination,
                &written,
                environment,
            );
            if program
                .primitive_type_reference(local.type_reference)
                .is_some_and(|primitive| primitive.is_fixed_integer())
            {
                if let Some(observed) = observed {
                    Self::capture_scalar_equality(
                        &mut self.ordered_relations,
                        observed,
                        destination.clone(),
                        &written,
                    );
                }
                if let Some(state) = state
                    && let Some(length) = super::slice_lengths::denoted_collection_length(
                        program,
                        machine,
                        state,
                        environment,
                        local.initial_value,
                    )
                {
                    Self::capture_scalar_equality(
                        &mut self.ordered_relations,
                        length,
                        destination.clone(),
                        &written,
                    );
                }
            }
            if let Some(state) = state {
                self.capture_descendant_observations(
                    program,
                    machine,
                    state,
                    local.initial_value,
                    &destination,
                    &written,
                    environment,
                    local.type_reference,
                );
                self.retain_completed_observations(
                    program,
                    machine,
                    state,
                    local.initial_value,
                    &destination,
                );
            }
        }

        #[allow(clippy::too_many_arguments)]
        pub(crate) fn capture_assignment_relations(
            &mut self,
            program: &dyn crate::CheckingInput,
            machine: &typed_trees::machine::Machine,
            state: &typed_trees::state::State,
            statement: &typed_trees::statement::StatementNode,
            frames: Option<&crate::CallFrameResolver<'_>>,
            written: &[String],
            environment: &ValueEnvironment,
        ) {
            let Some(assignment) = statement.as_assignment() else {
                return;
            };
            if frames.is_some_and(|frames| {
                frames
                    .assignment_replaced_binding(machine, statement)
                    .is_some()
            }) {
                return;
            }
            let primitive =
                super::declared_place_type_raw(program, machine, Some(state), assignment.target)
                    .map(|reference| {
                        crate::value_custody::places::assignment_value_type(program, reference)
                    })
                    .and_then(|reference| program.primitive_type_reference(reference));
            let Some(destination) =
                ordered_values::operand(program, machine, state, assignment.target, None)
            else {
                return;
            };
            if destination.static_path().is_none() {
                return;
            }
            self.capture_descendant_observations(
                program,
                machine,
                state,
                assignment.value,
                &destination,
                written,
                environment,
                crate::assignment_stored_value_type(program, machine, state, assignment)
                    .unwrap_or_default(),
            );
            if primitive.is_some_and(|primitive| primitive.is_fixed_integer())
                && let Some(observed) = self.capture_relations(
                    program,
                    machine,
                    Some(state),
                    assignment.value,
                    &destination,
                    written,
                    environment,
                )
            {
                Self::capture_scalar_equality(
                    &mut self.ordered_relations,
                    observed,
                    destination.clone(),
                    written,
                );
                if let Some(length) = super::slice_lengths::denoted_collection_length(
                    program,
                    machine,
                    state,
                    environment,
                    assignment.value,
                ) {
                    Self::capture_scalar_equality(
                        &mut self.ordered_relations,
                        length,
                        destination.clone(),
                        written,
                    );
                }
            }
            self.retain_completed_observations(
                program,
                machine,
                state,
                assignment.value,
                &destination,
            );
        }

        fn retain_completed_observations(
            &mut self,
            program: &dyn crate::CheckingInput,
            machine: &typed_trees::machine::Machine,
            state: &typed_trees::state::State,
            expression: ExpressionHandle,
            destination: &ordered_values::Operand,
        ) {
            if self.ordered_relations.is_empty() {
                return;
            }
            let writes = if crate::machine_calls::calls::expression_has_calls(program, expression) {
                crate::CallFrameResolver::new(program)
                    .and_then(|frames| frames.expression_may_write_paths(machine, expression))
            } else {
                Some(Vec::new())
            };
            self.ordered_relations.retain(|relation| {
                ordered_values::survives_delivery(
                    program,
                    state,
                    &relation.left,
                    destination,
                    writes.as_deref(),
                ) && ordered_values::survives_delivery(
                    program,
                    state,
                    &relation.right,
                    destination,
                    writes.as_deref(),
                )
            });
        }

        fn capture_relations(
            &mut self,
            program: &dyn crate::CheckingInput,
            machine: &typed_trees::machine::Machine,
            state: Option<&typed_trees::state::State>,
            expression: ExpressionHandle,
            destination: &ordered_values::Operand,
            written: &[String],
            environment: &ValueEnvironment,
        ) -> Option<ordered_values::Operand> {
            let observed = state.and_then(|state| {
                ordered_values::operand(program, machine, state, expression, None)
            })?;
            let mut bindings = Vec::new();
            for relation in &environment.ordered_values {
                retain_places(&relation.left, &observed, &mut bindings);
                retain_places(&relation.right, &observed, &mut bindings);
            }
            bindings.retain(|(source, _)| source.survives(written));
            bindings.push((observed.clone(), destination.clone()));
            self.ordered_relations
                .extend(ordered_values::rebind_relations(
                    &environment.ordered_values,
                    &bindings,
                ));
            Some(observed)
        }

        fn capture_descendant_observations(
            &mut self,
            program: &dyn crate::CheckingInput,
            machine: &typed_trees::machine::Machine,
            state: &typed_trees::state::State,
            expression: ExpressionHandle,
            destination: &ordered_values::Operand,
            written: &[String],
            environment: &ValueEnvironment,
            type_reference: typed_trees::types::TypeReferenceHandle,
        ) {
            let captured = CapturedValue {
                operand: destination,
                type_reference,
            };
            let source = SourceObservations::new(program, machine, Some(state), expression);
            self.capture_descendants(
                program,
                machine,
                state,
                expression,
                destination,
                written,
                environment,
                &captured,
                &source,
                Some(&[]),
            );
        }

        fn capture_descendants(
            &mut self,
            program: &dyn crate::CheckingInput,
            machine: &typed_trees::machine::Machine,
            state: &typed_trees::state::State,
            expression: ExpressionHandle,
            destination: &ordered_values::Operand,
            written: &[String],
            environment: &ValueEnvironment,
            captured: &CapturedValue<'_>,
            source: &SourceObservations<'_>,
            later_writes: Option<&[String]>,
        ) {
            let fields = delivery::fields(program, expression);
            if fields.is_none() {
                let writes = source.effects(expression);
                self.ordered_relations.retain(|relation| {
                    captured.observation_survives(program, state, &relation.left, writes.as_deref())
                        && captured.observation_survives(
                            program,
                            state,
                            &relation.right,
                            writes.as_deref(),
                        )
                });
            }
            self.capture_completed_associations(
                state,
                expression,
                destination,
                written,
                environment,
            );
            if later_writes.is_some_and(|written| source.permits(expression, written))
                && super::declared_place_type_raw(program, machine, Some(state), expression)
                    .is_some_and(|reference| {
                        crate::slice_view_shell(program, reference, &[]).is_some()
                    })
                && let Some(observed) =
                    ordered_values::operand(program, machine, state, expression, None)
            {
                Self::capture_scalar_equality(
                    &mut self.ordered_relations,
                    ordered_values::Operand::CollectionLength(Box::new(observed)),
                    ordered_values::Operand::CollectionLength(Box::new(destination.clone())),
                    written,
                );
            }
            let Some(fields) = fields else {
                return;
            };
            let following =
                source.following_writes(fields.iter().map(|field| field.value), later_writes);
            for (field, following) in fields.iter().zip(&following) {
                let primitive = integer_field_primitive(program, machine, state, field.value);
                let field_operand = ordered_values::Operand::Field {
                    receiver: Box::new(destination.clone()),
                    field: field.field_symbol,
                    name: field.name.as_str().to_owned(),
                    primitive,
                };
                self.capture_descendants(
                    program,
                    machine,
                    state,
                    field.value,
                    &field_operand,
                    written,
                    environment,
                    captured,
                    source,
                    following.as_deref(),
                );
                if primitive.is_some()
                    && following
                        .as_deref()
                        .is_some_and(|written| source.permits(field.value, written))
                {
                    if let Some(observed) =
                        ordered_values::operand(program, machine, state, field.value, None)
                    {
                        Self::capture_scalar_equality(
                            &mut self.ordered_relations,
                            observed,
                            field_operand.clone(),
                            written,
                        );
                    }
                    if let Some(length) = super::slice_lengths::denoted_collection_length(
                        program,
                        machine,
                        state,
                        environment,
                        field.value,
                    ) {
                        Self::capture_scalar_equality(
                            &mut self.ordered_relations,
                            length,
                            field_operand,
                            written,
                        );
                    }
                }
            }
        }

        fn capture_scalar_equality(
            relations: &mut Vec<ordered_values::Relation>,
            observed: ordered_values::Operand,
            destination: ordered_values::Operand,
            written: &[String],
        ) {
            if observed.survives(written) {
                for (left, right) in [
                    (destination.clone(), observed.clone()),
                    (observed, destination),
                ] {
                    relations.push(ordered_values::Relation {
                        left,
                        right,
                        constraint: ordered_values::RelationConstraint::MinimumDifference(0),
                    });
                }
            }
        }

        fn capture_completed_associations(
            &mut self,
            state: &typed_trees::state::State,
            expression: ExpressionHandle,
            destination: &ordered_values::Operand,
            written: &[String],
            environment: &ValueEnvironment,
        ) {
            for association in &environment.numeric_observations.scalar_associations {
                if association.state == state.symbol && association.expression == expression {
                    Self::capture_scalar_equality(
                        &mut self.completed_relations,
                        association.current.clone(),
                        destination.clone(),
                        written,
                    );
                }
            }
        }

        fn capture_at(
            &mut self,
            context: &CaptureContext<'_>,
            receiving_type: typed_trees::types::TypeReferenceHandle,
            expression: ExpressionHandle,
            suffix: &str,
            segments: &[PlaceSegment],
            later_writes: Option<&[String]>,
        ) {
            let program = context.source.program;
            let environment = context.environment;
            let checked_values = context.checked_values;
            match program.expression_table.expression(expression) {
                ExpressionNode::StructLiteral(literal) => {
                    let fields = program.expression_table.struct_fields(literal.fields);
                    let following = context
                        .source
                        .following_writes(fields.iter().map(|field| field.value), later_writes);
                    for (field, following) in fields.iter().zip(&following) {
                        let mut field_segments = segments.to_vec();
                        field_segments.push(PlaceSegment::Field {
                            symbol: field.field_symbol,
                        });
                        self.capture_at(
                            context,
                            receiving_type,
                            field.value,
                            &format!("{suffix}.{}", field.name),
                            &field_segments,
                            following.as_deref(),
                        );
                    }
                }
                ExpressionNode::ArrayLiteral(elements) => {
                    let elements = program.expression_table.expression_handles(*elements);
                    let following = context
                        .source
                        .following_writes(elements.iter().copied(), later_writes);
                    for ((index, element), following) in elements.iter().enumerate().zip(&following)
                    {
                        let mut element_segments = segments.to_vec();
                        element_segments.push(PlaceSegment::FixedIndex { index });
                        self.capture_at(
                            context,
                            receiving_type,
                            *element,
                            &format!("{suffix}[{index}]"),
                            &element_segments,
                            following.as_deref(),
                        );
                    }
                }
                _ => {
                    let writes = context.source.effects(expression);
                    let survives = |path: Option<&[PlaceSegment]>| {
                        captured_observations::scalar_path_survives(
                            program,
                            receiving_type,
                            path,
                            writes.as_deref(),
                        )
                    };
                    self.recipes.retain(|(path, _, _)| survives(Some(path)));
                    self.intervals
                        .retain(|observed| survives(observed.segments.as_deref()));
                    self.unsigned_values
                        .retain(|observed| survives(observed.segments.as_deref()));
                    self.float_intervals
                        .retain(|observed| survives(observed.segments.as_deref()));
                    self.non_nan_paths
                        .retain(|observed| survives(observed.segments.as_deref()));
                    self.float_aliases.retain(|observed| {
                        survives(observed.segments.as_deref())
                            && writes.as_ref().is_some_and(|writes| {
                                writes.iter().all(|written| {
                                    !super::place_paths::place_paths_overlap(
                                        &observed.value,
                                        written,
                                    )
                                })
                            })
                    });
                    let source_is_current = later_writes
                        .is_some_and(|written| context.source.permits(expression, written));
                    if let Some(source) = canonical_place_from_expression(program, expression)
                        && source_is_current
                    {
                        for stored in &environment.integer_ranges {
                            if stored.place.root == source.root
                                && stored.place.segments.starts_with(&source.segments)
                            {
                                let mut destination = segments.to_vec();
                                destination.extend_from_slice(
                                    &stored.place.segments[source.segments.len()..],
                                );
                                let source_label = source.label(program);
                                if let Some(tail) = stored.path.strip_prefix(&source_label) {
                                    self.recipes.push((
                                        destination,
                                        format!("{suffix}{tail}"),
                                        stored.recipe.clone(),
                                    ));
                                }
                            }
                        }
                    }
                    let mut visits = checked_values
                        .iter()
                        .filter(|value| value.expression == expression)
                        .map(|value| &value.recipe);
                    if let Some(Some(first)) = visits.next()
                        && visits.all(|recipe| recipe.as_ref() == Some(first))
                    {
                        self.recipes.retain(|(existing, _, _)| existing != segments);
                        self.recipes
                            .push((segments.to_vec(), suffix.to_owned(), first.clone()));
                    }
                    if let Some(source) = place_path(program, expression)
                        .or_else(|| super::element_place_path(program, expression))
                        .filter(|_| source_is_current)
                    {
                        copy_retained(
                            &environment.intervals,
                            &source,
                            suffix,
                            segments,
                            &mut self.intervals,
                        );
                        copy_retained(
                            &environment.known_u64_values,
                            &source,
                            suffix,
                            segments,
                            &mut self.unsigned_values,
                        );
                        copy_retained(
                            &environment.float_intervals,
                            &source,
                            suffix,
                            segments,
                            &mut self.float_intervals,
                        );
                        for path in environment
                            .non_nan
                            .range(source.clone()..)
                            .take_while(|path| path.starts_with(&source))
                        {
                            if let Some(tail) = path.strip_prefix(&source)
                                && (tail.is_empty()
                                    || tail.starts_with('.')
                                    || tail.starts_with('['))
                            {
                                self.non_nan_paths.push(CapturedScalarObservation {
                                    segments: tail.is_empty().then(|| segments.to_vec()),
                                    suffix: format!("{suffix}{tail}"),
                                    value: (),
                                });
                            }
                        }
                        if !suffix.is_empty() {
                            self.float_aliases.push(CapturedScalarObservation {
                                segments: Some(segments.to_vec()),
                                suffix: suffix.to_owned(),
                                value: source.clone(),
                            });
                        }
                        for (left, right) in &environment.float_aliases {
                            for (candidate, partner) in [(left, right), (right, left)] {
                                if let Some(tail) = candidate.strip_prefix(&source)
                                    && (tail.is_empty()
                                        || tail.starts_with('.')
                                        || tail.starts_with('['))
                                {
                                    self.float_aliases.push(CapturedScalarObservation {
                                        segments: tail.is_empty().then(|| segments.to_vec()),
                                        suffix: format!("{suffix}{tail}"),
                                        value: partner.clone(),
                                    });
                                }
                            }
                        }
                    } else if !suffix.is_empty()
                        && source_is_current
                        && let Some(source) =
                            super::assignments::float_source_place_path(program, expression)
                    {
                        self.float_aliases.push(CapturedScalarObservation {
                            segments: Some(segments.to_vec()),
                            suffix: suffix.to_owned(),
                            value: source,
                        });
                    }
                    if !suffix.is_empty()
                        && let Some(value) =
                            super::float_arithmetic::float_literal_value(program, expression)
                        && !value.is_nan()
                    {
                        self.float_intervals.push(CapturedScalarObservation {
                            segments: Some(segments.to_vec()),
                            suffix: suffix.to_owned(),
                            value: super::value_environment::FloatInterval {
                                low: Some(value),
                                high: Some(value),
                            },
                        });
                        self.non_nan_paths.push(CapturedScalarObservation {
                            segments: Some(segments.to_vec()),
                            suffix: suffix.to_owned(),
                            value: (),
                        });
                    }
                    if !suffix.is_empty()
                        && let Some(interval) = checked_values
                            .iter()
                            .filter_map(|value| {
                                (value.expression == expression).then_some(value.interval)
                            })
                            .reduce(Interval::union)
                    {
                        self.intervals.push(CapturedScalarObservation {
                            segments: Some(segments.to_vec()),
                            suffix: suffix.to_owned(),
                            value: interval,
                        });
                    }
                    if let Some(value) = super::integer_ranges::literal_u64(program, expression) {
                        self.unsigned_values.push(CapturedScalarObservation {
                            segments: Some(segments.to_vec()),
                            suffix: suffix.to_owned(),
                            value,
                        });
                    }
                }
            }
        }

        pub(crate) fn record(
            &self,
            environment: &mut ValueEnvironment,
            path: Option<String>,
            destination: Option<CanonicalPlace>,
        ) {
            let Some(path) = path else { return };
            if let Some(destination) = destination
                && matches!(destination.root, facts::PlaceRoot::Symbol(_))
            {
                for (segments, suffix, recipe) in &self.recipes {
                    let mut place = destination.clone();
                    place.extend_segments(segments);
                    if place.segments.iter().any(|segment| {
                        !matches!(segment, PlaceSegment::Field { symbol } if symbol.is_valid())
                            && !matches!(segment, PlaceSegment::FixedIndex { .. })
                    }) {
                        continue;
                    }
                    environment
                        .integer_ranges
                        .retain(|stored| stored.place != place);
                    environment.integer_ranges.push(StoredIntegerRange {
                        place,
                        path: format!("{path}{suffix}"),
                        recipe: recipe.clone(),
                    });
                }
            }
            for relation in self
                .ordered_relations
                .iter()
                .chain(&self.completed_relations)
            {
                if !environment.ordered_values.contains(relation) {
                    environment.ordered_values.push(relation.clone());
                }
            }
            for observed in &self.intervals {
                if !observed.suffix.is_empty() {
                    environment.set(format!("{path}{}", observed.suffix), observed.value);
                }
            }
            for observed in &self.unsigned_values {
                environment.mark_known_u64(format!("{path}{}", observed.suffix), observed.value);
            }
            for observed in &self.float_intervals {
                environment.narrow_float(format!("{path}{}", observed.suffix), observed.value);
            }
            for observed in &self.non_nan_paths {
                environment.mark_non_nan(format!("{path}{}", observed.suffix));
            }
            for observed in &self.float_aliases {
                environment
                    .mark_float_alias(format!("{path}{}", observed.suffix), observed.value.clone());
            }
        }
    }

    fn integer_field_primitive(
        program: &dyn crate::CheckingInput,
        machine: &typed_trees::machine::Machine,
        state: &typed_trees::state::State,
        expression: ExpressionHandle,
    ) -> Option<typed_trees::types::PrimitiveType> {
        if crate::value_custody::places::collection_length_receiver(
            program,
            machine,
            Some(state),
            expression,
        )
        .is_some()
        {
            return Some(typed_trees::types::PrimitiveType::U64);
        }
        super::declared_place_type_raw(program, machine, Some(state), expression)
            .and_then(|reference| program.primitive_type_reference(reference))
            .filter(|primitive| primitive.is_fixed_integer())
    }

    fn retain_places(
        operand: &ordered_values::Operand,
        observed: &ordered_values::Operand,
        bindings: &mut Vec<(ordered_values::Operand, ordered_values::Operand)>,
    ) {
        use ordered_values::Operand;
        if operand == observed {
            return;
        }
        match operand {
            Operand::Place { .. } => {
                if !bindings.iter().any(|(source, _)| source == operand) {
                    bindings.push((operand.clone(), operand.clone()));
                }
            }
            Operand::Integer(..) => {}
            #[cfg(test)]
            Operand::CompletedCall { .. } => {}
            Operand::CollectionLength(collection) => retain_places(collection, observed, bindings),
            Operand::Field { receiver, .. } => {
                if !depends_on(receiver, observed)
                    && !bindings.iter().any(|(source, _)| source == operand)
                {
                    bindings.push((operand.clone(), operand.clone()));
                } else {
                    retain_places(receiver, observed, bindings);
                }
            }
            Operand::Indexed {
                collection, index, ..
            } => {
                retain_places(collection, observed, bindings);
                retain_places(index, observed, bindings);
            }
            Operand::Call { arguments, .. }
            | Operand::Binary {
                operands: arguments,
                ..
            } => {
                for argument in arguments {
                    retain_places(argument, observed, bindings);
                }
            }
        }
    }

    fn depends_on(operand: &ordered_values::Operand, observed: &ordered_values::Operand) -> bool {
        use ordered_values::Operand;
        operand == observed
            || match operand {
                Operand::Place { .. } | Operand::Integer(..) => false,
                #[cfg(test)]
                Operand::CompletedCall { .. } => false,
                Operand::Field { receiver, .. } => depends_on(receiver, observed),
                Operand::CollectionLength(collection) => depends_on(collection, observed),
                Operand::Indexed {
                    collection, index, ..
                } => depends_on(collection, observed) || depends_on(index, observed),
                Operand::Call { arguments, .. }
                | Operand::Binary {
                    operands: arguments,
                    ..
                } => arguments
                    .iter()
                    .any(|argument| depends_on(argument, observed)),
            }
    }

    fn copy_retained<Value: Copy>(
        retained: &BTreeMap<String, Value>,
        source: &str,
        destination: &str,
        segments: &[PlaceSegment],
        copied: &mut Vec<CapturedScalarObservation<Value>>,
    ) {
        copied.extend(
            retained
                .range(source.to_owned()..)
                .take_while(|(path, _)| path.starts_with(source))
                .filter_map(|(path, value)| {
                    let suffix = path.strip_prefix(source)?;
                    (suffix.is_empty() || suffix.starts_with('.') || suffix.starts_with('[')).then(
                        || CapturedScalarObservation {
                            segments: suffix.is_empty().then(|| segments.to_vec()),
                            suffix: format!("{destination}{suffix}"),
                            value: *value,
                        },
                    )
                }),
        );
    }
}
pub(crate) use copied_values::CopiedIntegerValue;
pub(crate) mod declaration_values {
    use super::{Diagnostic, ExpressionHandle, PrimitiveType, ValueEnvironment};
    use crate::frozen_program::expression_table;
    use crate::proof_contracts::arithmetic_domains::BigIntInterval;
    use symbols::SymbolHandle;
    use typed_trees::expression::ExpressionNode;
    use typed_trees::signature::StateParameter;
    use typed_trees::types::TypeReferenceHandle;

    #[derive(Debug, Clone, Copy)]
    pub(crate) struct LocalValueFormation<'program> {
        pub machine: &'program typed_trees::machine::Machine,
        pub state: Option<&'program typed_trees::state::State>,
        pub environment: &'program ValueEnvironment,
    }

    pub(crate) fn validate_declaration_value_range(
        program: &dyn crate::CheckingInput,
        lexical_owner: SymbolHandle,
        parameters: &[StateParameter],
        prior_facts: &[ExpressionHandle],
        local_formation: Option<LocalValueFormation<'_>>,
        expression: ExpressionHandle,
        target_carrier: TypeReferenceHandle,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
        formation_obligations: &mut Vec<checked_trees::IntegerRangeObligation>,
    ) {
        let target_primitive = program.primitive_type_reference(target_carrier);
        let target_domain = program.arithmetic_domain_for_type_reference(target_carrier);
        crate::proof_contracts::contract_entailment::specification_calls::validate_declaration_expression_formation(
        program, lexical_owner, parameters, expression, prior_facts, owner, diagnostics,
        formation_obligations,
    );
        let mut pending = vec![(
            expression,
            Some(target_carrier).filter(|carrier| carrier.is_valid()),
        )];
        while let Some((operand, expected)) = pending.pop() {
            let node = expression_table(program).expression(operand);
            let missing_formation = match node {
                ExpressionNode::Indexed(_) => Some("indexed access bounds"),
                ExpressionNode::Atomic(_) => Some("atomic access authority"),
                ExpressionNode::Borrow(_) => Some("borrow custody"),
                ExpressionNode::ZeroValue(_) => Some("zero construction membership"),
                ExpressionNode::Cast(cast) if cast.form.is_recast() => {
                    Some("recast access and representation")
                }
                ExpressionNode::Cast(cast) if cast.semantic_domain_symbol.is_valid() => {
                    Some("domain qualification membership")
                }
                ExpressionNode::Member(member) => {
                    let receiver = crate::parameter_expression_result_type_reference(
                        program,
                        lexical_owner,
                        parameters,
                        member.receiver,
                    );
                    receiver
                        .and_then(|reference| crate::reference_shell(program, reference))
                        .filter(|reference| !reference.access.is_readable())
                        .map(|_| "readable projected storage")
                }
                _ => None,
            };
            if let Some(obligation) = missing_formation {
                diagnostics.push(
                    Diagnostic::error(format!(
                        "{owner} has no declaration formation evidence for {obligation}"
                    ))
                    .with_source_span(expression_table(program).source_span(operand)),
                );
            }
            if matches!(
                node,
                ExpressionNode::StructLiteral(_) | ExpressionNode::ArrayLiteral(_)
            ) {
                let reference = crate::parameter_expression_result_type_reference(
                    program,
                    lexical_owner,
                    parameters,
                    operand,
                )
                .or_else(|| {
                    let reference =
                        expression_table(program).constructed_value_type_reference(operand);
                    reference.is_valid().then_some(reference)
                })
                .or(expected);
                let formation = reference.and_then(|reference| {
                    crate::normalize_closed_const_expression(
                        program,
                        lexical_owner,
                        operand,
                        reference,
                    )
                    .transpose()
                });
                match formation {
                Some(Ok(_)) => {}
                Some(Err(reason)) => diagnostics.push(Diagnostic::error(format!(
                    "{owner} has an invalid construction: {reason}"
                ))),
                None => diagnostics.push(Diagnostic::error(format!(
                    "{owner} has an open construction without a declaration construction judgment: {} (carrier: {})",
                    expression_table(program).display_name(operand),
                    reference.map(|reference| program.type_reference_table.display_name(reference))
                        .unwrap_or_else(|| "unresolved".to_owned()),
                )).with_source_span(expression_table(program).source_span(operand))),
            }
            }
            let expected_children = expected_child_carriers(program, operand, node, expected);
            crate::queries::expression_traversal::children(program, node, |child| {
                let expected = expected_children
                    .iter()
                    .find(|(candidate, _)| *candidate == child)
                    .map(|(_, carrier)| *carrier);
                pending.push((child, expected));
            });
        }
        let analysis = if let Some(local) = local_formation {
            super::expression_analysis::analyze(
                program,
                local.machine,
                local.state,
                expression,
                local.environment,
                target_primitive,
                target_domain,
                owner,
                false,
                false,
                diagnostics,
            )
        } else {
            super::expression_analysis::analyze_declaration(
                program,
                lexical_owner,
                parameters,
                prior_facts,
                expression,
                &ValueEnvironment::new(),
                target_primitive,
                target_domain,
                owner,
                diagnostics,
            )
        };
        formation_obligations.extend(analysis.decisions.integer_range_obligations);
    }

    fn expected_child_carriers(
        program: &dyn crate::CheckingInput,
        operand: ExpressionHandle,
        node: &ExpressionNode,
        expected: Option<TypeReferenceHandle>,
    ) -> Vec<(ExpressionHandle, TypeReferenceHandle)> {
        match node {
            ExpressionNode::ArrayLiteral(elements) => {
                let Some((element, _)) = expected.and_then(|carrier| {
                    crate::value_custody::const_expressions::fixed_array_geometry(program, carrier)
                }) else {
                    return Vec::new();
                };
                expression_table(program)
                    .expression_handles(*elements)
                    .iter()
                    .map(|handle| (*handle, element))
                    .collect()
            }
            ExpressionNode::StructLiteral(literal) => expression_table(program)
                .struct_fields(literal.fields)
                .iter()
                .filter_map(|field| {
                    crate::value_custody::struct_literals::selected_construction_field_type(
                        program,
                        operand,
                        literal,
                        field.field_symbol,
                    )
                    .map(|carrier| (field.value, carrier))
                })
                .collect(),
            _ => Vec::new(),
        }
    }

    pub(crate) fn binary_result_fits(
        program: &dyn crate::CheckingInput,
        owner: SymbolHandle,
        parameters: &[StateParameter],
        prior_facts: &[ExpressionHandle],
        expression: ExpressionHandle,
        primitive: PrimitiveType,
    ) -> bool {
        use crate::proof_contracts::contract_entailment::scoped_arithmetic_values_relation_for_declaration;
        use crate::{
            ScopedArithmeticBinder, ScopedArithmeticBinding, ScopedArithmeticExpression,
            ScopedArithmeticHypothesis, ScopedArithmeticValue, StrictArithmeticImplicationJudgment,
        };
        use typed_trees::expression::BinaryOperator;
        if prior_facts.is_empty() {
            return false;
        }
        let Some(binary) = expression_table(program).binary_node(expression) else {
            return false;
        };
        if !matches!(
            binary.operator,
            BinaryOperator::Add | BinaryOperator::Subtract | BinaryOperator::Multiply
        ) {
            return false;
        }
        let Some((minimum, maximum)) = primitive.integer_bounds() else {
            return false;
        };
        let bindings = parameters
            .iter()
            .filter_map(|parameter| {
                let primitive = crate::value_custody::recasts::exact_primitive_type(
                    program,
                    parameter.type_reference,
                )?;
                let (minimum, maximum) = primitive.integer_bounds()?;
                Some(ScopedArithmeticBinding {
                    binder: ScopedArithmeticBinder::Symbol(parameter.symbol),
                    value: ScopedArithmeticValue::BoundedInteger {
                        value: Box::new(ScopedArithmeticValue::Atom {
                            identity: format!("\0declaration-value:{:?}", parameter.symbol),
                            unsigned: !primitive.is_signed_integer(),
                        }),
                        interval: BigIntInterval {
                            low: Some(numerics::bignum::BigInt::from_i128(minimum)),
                            high: Some(numerics::bignum::BigInt::from_i128(maximum)),
                        },
                    },
                })
            })
            .collect::<Vec<_>>();
        let term = |expression| ScopedArithmeticExpression {
            owner,
            expression,
            bindings: bindings.clone(),
        };
        let hypotheses = prior_facts
            .iter()
            .map(|&expression| ScopedArithmeticHypothesis {
                proposition: term(expression),
                holds: true,
            })
            .collect::<Vec<_>>();
        let value = ScopedArithmeticValue::IntegerOperation {
            operator: binary.operator,
            left: Box::new(ScopedArithmeticValue::Term(term(binary.left))),
            right: Box::new(ScopedArithmeticValue::Term(term(binary.right))),
        };
        [
            (BinaryOperator::GreaterOrEqual, minimum),
            (BinaryOperator::LessOrEqual, maximum),
        ]
        .into_iter()
        .all(|(operator, bound)| {
            matches!(
                scoped_arithmetic_values_relation_for_declaration(
                    program,
                    owner,
                    &hypotheses,
                    operator,
                    &value,
                    &ScopedArithmeticValue::Integer(numerics::bignum::BigInt::from_i128(bound)),
                ),
                StrictArithmeticImplicationJudgment::Proven
            )
        })
    }
}
pub(crate) mod division_definedness {
    use super::visit_binary_operators;
    use diagnostics::Diagnostic;
    use numerics::arithmetic::ArithmeticDomain;
    use numerics::integer_policy::{
        IntegerFormationCondition, IntegerPolicyPrimitive, integer_policy_bridge,
    };
    use typed_trees::expression::{BinaryOperator, ExpressionHandle};
    use typed_trees::machine::Machine;
    use typed_trees::state::State;
    use typed_trees::types::PrimitiveType;

    use super::total_specification::{
        AbstractSpecificationBindings, abstract_specification_builtin_arithmetic,
        abstract_specification_interval, direct_abstract_operand,
    };
    use super::{Interval, ValueEnvironment, ordered_values};
    use typed_trees::expression::TableBinaryExpression;

    fn signed_minimum(primitive: PrimitiveType) -> Option<i64> {
        match primitive {
            PrimitiveType::I8 => Some(i8::MIN as i64),
            PrimitiveType::I16 => Some(i16::MIN as i64),
            PrimitiveType::I32 => Some(i32::MIN as i64),
            PrimitiveType::I64 => Some(i64::MIN),
            _ => None,
        }
    }

    fn may_contain(interval: Option<Interval>, value: i64) -> bool {
        let Some(interval) = interval else {
            return true;
        };
        interval.low().is_none_or(|low| low <= value)
            && interval.high().is_none_or(|high| value <= high)
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub(crate) struct ExactDefinednessConditions {
        nonzero_divisor: bool,
        signed_result_representable: bool,
    }

    fn definedness_conditions(
        operator: BinaryOperator,
        domain: ArithmeticDomain,
    ) -> ExactDefinednessConditions {
        let primitive = match operator {
            BinaryOperator::Divide => IntegerPolicyPrimitive::Divide,
            BinaryOperator::Modulo => IntegerPolicyPrimitive::Remainder,
            _ => unreachable!("definedness is only queried for division and remainder"),
        };
        let conditions = integer_policy_bridge(primitive, domain).formation_conditions;
        ExactDefinednessConditions {
            nonzero_divisor: conditions.contains(&IntegerFormationCondition::NonZeroDivisor),
            signed_result_representable: conditions
                .contains(&IntegerFormationCondition::ResultRepresentable),
        }
    }

    pub(crate) struct ProvenDefinedness {
        nonzero_divisor: bool,
        provably_zero_divisor: bool,
        signed_pair_excluded: bool,
    }

    impl ProvenDefinedness {
        fn from_intervals(
            primitive: PrimitiveType,
            left: Option<Interval>,
            right: Option<Interval>,
        ) -> Self {
            Self {
                nonzero_divisor: right.is_some_and(Interval::excludes_zero),
                provably_zero_divisor: right.is_some_and(Interval::is_exactly_zero),
                signed_pair_excluded: !signed_minimum(primitive)
                    .is_some_and(|minimum| may_contain(left, minimum) && may_contain(right, -1)),
            }
        }
    }

    fn report_partial(
        operator: BinaryOperator,
        domain: ArithmeticDomain,
        proven: ProvenDefinedness,
        owner: &str,
        provably_zero_is_prevalidated: bool,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> bool {
        let conditions = definedness_conditions(operator, domain);
        let missing_nonzero = conditions.nonzero_divisor
            && !(proven.nonzero_divisor
                || provably_zero_is_prevalidated && proven.provably_zero_divisor);
        let signed_overflow_pair =
            conditions.signed_result_representable && !proven.signed_pair_excluded;
        if !missing_nonzero && !signed_overflow_pair {
            return (conditions.nonzero_divisor || conditions.signed_result_representable)
                && (!conditions.nonzero_divisor || proven.nonzero_divisor);
        }

        let operation = if operator == BinaryOperator::Divide {
            "division"
        } else {
            "remainder"
        };
        let mut missing = Vec::new();
        if missing_nonzero {
            missing.push("the divisor must be proven nonzero");
        }
        if signed_overflow_pair {
            missing.push("the signed `MIN / -1` primitive pair must be excluded");
        }
        diagnostics.push(Diagnostic::error(format!(
        "partial {} {operation} in {owner}: {}; discharge every definedness condition with independently accepted prior facts",
        domain.name().to_ascii_lowercase(),
        missing.join(" and "),
    )));
        false
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn validate_operands(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
        binary: &TableBinaryExpression,
        domain: ArithmeticDomain,
        primitive: PrimitiveType,
        left: Interval,
        right: Interval,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> bool {
        if !primitive.is_fixed_integer()
            || !matches!(
                binary.operator,
                BinaryOperator::Divide | BinaryOperator::Modulo
            )
        {
            return false;
        }
        let excludes = |expression, value| {
            ordered_values::excludes_integer_value(
                program,
                machine,
                state,
                environment,
                expression,
                value,
            ) || super::declared_place_type_raw(program, machine, state, expression).is_some_and(
                |reference| {
                    super::domain_exclusions::type_excludes_integer(program, reference, value)
                },
            )
        };
        let mut proven = ProvenDefinedness::from_intervals(primitive, Some(left), Some(right));
        proven.nonzero_divisor = proven.nonzero_divisor
            || excludes(binary.right, 0)
            || super::live_integer_constraints::excludes_values(
                program,
                machine,
                state,
                environment,
                &[(binary.right, 0)],
            );
        proven.signed_pair_excluded = proven.signed_pair_excluded
            || signed_minimum(primitive).is_some_and(|minimum| {
                excludes(binary.left, minimum)
                    || excludes(binary.right, -1)
                    || super::live_integer_constraints::excludes_values(
                        program,
                        machine,
                        state,
                        environment,
                        &[(binary.left, minimum), (binary.right, -1)],
                    )
            });
        if let Some(state) = state {
            let excludes = |excluded: [Option<i64>; 2]| {
                crate::proof_contracts::contract_entailment::integer_operands_compare_at_occurrence(
                    program,
                    machine,
                    state,
                    expression,
                    primitive,
                    excluded.map(|value| value.map(|value| (BinaryOperator::NotEqual, value))),
                )
            };
            let conditions = definedness_conditions(binary.operator, domain);
            if conditions.nonzero_divisor && !proven.nonzero_divisor {
                proven.nonzero_divisor = excludes([None, Some(0)]);
            }
            if conditions.signed_result_representable && !proven.signed_pair_excluded {
                proven.signed_pair_excluded = signed_minimum(primitive)
                    .is_some_and(|minimum| excludes([Some(minimum), Some(-1)]));
            }
        }
        report_partial(binary.operator, domain, proven, owner, true, diagnostics)
    }

    pub(crate) fn validate_interval_operands(
        operator: BinaryOperator,
        domain: ArithmeticDomain,
        primitive: PrimitiveType,
        left: Interval,
        right: Interval,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> bool {
        if !matches!(operator, BinaryOperator::Divide | BinaryOperator::Modulo) {
            return false;
        }
        report_partial(
            operator,
            domain,
            ProvenDefinedness::from_intervals(primitive, Some(left), Some(right)),
            owner,
            false,
            diagnostics,
        )
    }

    pub(crate) fn validate_abstract(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
        owner: &str,
        bindings: AbstractSpecificationBindings<'_>,
        environment: &ValueEnvironment,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        visit_binary_operators(
            program,
            expression,
            &[BinaryOperator::Divide, BinaryOperator::Modulo],
            |expression, binary| {
                if !abstract_specification_builtin_arithmetic(program, bindings, expression) {
                    return;
                }
                let Some((primitive, domain)) =
                    direct_abstract_operand(program, bindings, expression)
                else {
                    return;
                };
                if domain != ArithmeticDomain::Exact || !primitive.is_fixed_integer() {
                    return;
                }
                _ = report_partial(
                    binary.operator,
                    ArithmeticDomain::Exact,
                    ProvenDefinedness::from_intervals(
                        primitive,
                        abstract_specification_interval(
                            program,
                            bindings,
                            environment,
                            binary.left,
                        ),
                        abstract_specification_interval(
                            program,
                            bindings,
                            environment,
                            binary.right,
                        ),
                    ),
                    owner,
                    false,
                    diagnostics,
                );
            },
        );
    }

    pub(crate) fn validate_proof_integer(
        program: &dyn crate::CheckingInput,
        owner_symbol: symbols::SymbolHandle,
        binary: &TableBinaryExpression,
        hypotheses: &[ExpressionHandle],
        selections: &[super::DispatchSelection],
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        _ = report_partial(
            binary.operator,
            ArithmeticDomain::Exact,
            ProvenDefinedness {
                nonzero_divisor: crate::proof_contracts::contract_entailment::proof_integer_nonzero(
                    program,
                    owner_symbol,
                    binary.right,
                    hypotheses,
                    selections,
                ),
                provably_zero_divisor: false,
                signed_pair_excluded: true,
            },
            owner,
            false,
            diagnostics,
        );
    }
}
pub(crate) mod domain_exclusions {
    use checked_trees::{
        CheckedBooleanExpression as Boolean, CheckedIntegerComparisonKind as Comparison,
        CheckedScalarExpression as Scalar,
    };
    use numerics::bignum::BigInt;
    use typed_trees::types::{
        PrimitiveType, TypeConstraintNode, TypeReferenceHandle, TypeReferenceNode,
    };

    pub(crate) fn type_excludes_integer(
        program: &dyn crate::CheckingInput,
        mut reference: TypeReferenceHandle,
        value: i64,
    ) -> bool {
        let mut visited = Vec::new();
        let mut domains = Vec::new();
        let primitive = loop {
            if !program
                .type_reference_table
                .contains_type_reference(reference)
                || visited.contains(&reference)
            {
                return false;
            }
            visited.push(reference);
            match program.type_reference_table.type_reference(reference) {
                TypeReferenceNode::Reference { referee, .. } => reference = *referee,
                TypeReferenceNode::Constrained {
                    base_type,
                    constraints,
                } => {
                    let Some(constraints) =
                        program.type_reference_table.constraint_span(*constraints)
                    else {
                        return false;
                    };
                    for constraint in constraints {
                        if let TypeConstraintNode::Domain(domain) = constraint {
                            domains.push(domain);
                        }
                    }
                    reference = *base_type;
                }
                TypeReferenceNode::Named { .. } => {
                    let Some(primitive) =
                        crate::value_custody::recasts::exact_primitive_type(program, reference)
                    else {
                        return false;
                    };
                    break primitive;
                }
                _ => return false,
            }
        };
        if !primitive.is_fixed_integer() {
            return false;
        }
        domains.into_iter().any(|domain| {
            crate::scalar_field_domain_predicate(program, domain, primitive).is_some_and(
                |predicate| predicate_value(&predicate, primitive, value) == Some(false),
            )
        })
    }

    fn predicate_value(predicate: &Boolean, primitive: PrimitiveType, value: i64) -> Option<bool> {
        match predicate {
            Boolean::Constant(value) => Some(*value),
            Boolean::Not(inner) => predicate_value(inner, primitive, value).map(|value| !value),
            Boolean::Equal { left, right } => Some(
                predicate_value(left, primitive, value)?
                    == predicate_value(right, primitive, value)?,
            ),
            Boolean::And { left, right } => match (
                predicate_value(left, primitive, value),
                predicate_value(right, primitive, value),
            ) {
                (Some(false), _) | (_, Some(false)) => Some(false),
                (Some(true), Some(true)) => Some(true),
                _ => None,
            },
            Boolean::Or { left, right } => match (
                predicate_value(left, primitive, value),
                predicate_value(right, primitive, value),
            ) {
                (Some(true), _) | (_, Some(true)) => Some(true),
                (Some(false), Some(false)) => Some(false),
                _ => None,
            },
            Boolean::IntegerComparison { kind, left, right } => {
                let left = scalar_value(left, primitive, value)?;
                let right = scalar_value(right, primitive, value)?;
                Some(match kind {
                    Comparison::Equal => left == right,
                    Comparison::LessThan => left < right,
                    Comparison::LessOrEqual => left <= right,
                })
            }
            _ => None,
        }
    }

    fn scalar_value(expression: &Scalar, primitive: PrimitiveType, value: i64) -> Option<BigInt> {
        match expression {
            Scalar::Parameter {
                position: 0,
                primitive_type,
            } if *primitive_type == primitive => Some(BigInt::from_i64(value)),
            Scalar::IntegerLiteral { literal } => literal.value_bignum(),
            _ => None,
        }
    }
}
pub(crate) mod domain_intervals {
    use crate::frozen_program::expression_table;
    use typed_trees::expression::ExpressionNode;

    pub fn declared_domain_predicate_bounds(
        program: &dyn crate::CheckingInput,
        domain: &typed_trees::types::DomainConstraint,
    ) -> Option<(numerics::bignum::BigInt, numerics::bignum::BigInt)> {
        let interval = predicate_interval(program, domain)?;
        if interval.minimum.is_none() && interval.maximum.is_none() {
            return None;
        }
        let declaration = program.domain_definition(domain.symbol)?;
        let primitive =
            crate::value_custody::recasts::exact_primitive_type(program, declaration.target_type)?;
        let (minimum, maximum) =
            crate::proof_contracts::proof_embeddings::primitive_range(primitive)?;
        Some((
            interval.minimum.unwrap_or(minimum),
            interval.maximum.unwrap_or(maximum),
        ))
    }

    pub fn exact_declared_domain_interval(
        program: &dyn crate::CheckingInput,
        domain: &typed_trees::types::DomainConstraint,
    ) -> Option<(
        Option<numerics::bignum::BigInt>,
        Option<numerics::bignum::BigInt>,
    )> {
        let interval = predicate_interval(program, domain)?;
        let definition = program.domain_definition(domain.symbol)?;
        (interval.exact
            && definition.establishment_routes.is_empty()
            && (interval.minimum.is_some() || interval.maximum.is_some()))
        .then_some((interval.minimum, interval.maximum))
    }

    pub fn exact_declared_domain_carrier_interval(
        program: &dyn crate::CheckingInput,
        carrier: typed_trees::types::PrimitiveType,
        domain: &typed_trees::types::DomainConstraint,
    ) -> Option<(numerics::bignum::BigInt, numerics::bignum::BigInt)> {
        let (minimum, maximum) = exact_declared_domain_interval(program, domain)?;
        let definition = typed_trees::domain::domain_by_symbol(program, domain.symbol)?;
        if crate::value_custody::recasts::exact_primitive_type(program, definition.target_type)?
            != carrier
        {
            return None;
        }
        let (carrier_minimum, carrier_maximum) =
            crate::proof_contracts::proof_embeddings::primitive_range(carrier)?;
        Some((
            minimum.map_or(carrier_minimum.clone(), |minimum| {
                minimum.max(carrier_minimum)
            }),
            maximum.map_or(carrier_maximum.clone(), |maximum| {
                maximum.min(carrier_maximum)
            }),
        ))
    }

    pub(crate) struct PredicateInterval {
        minimum: Option<numerics::bignum::BigInt>,
        maximum: Option<numerics::bignum::BigInt>,
        exact: bool,
    }

    fn predicate_interval(
        program: &dyn crate::CheckingInput,
        domain: &typed_trees::types::DomainConstraint,
    ) -> Option<PredicateInterval> {
        use typed_trees::types::DomainConstraintSubject;
        if domain.subject != DomainConstraintSubject::Declared {
            return None;
        }
        application_predicate_interval(
            program,
            domain.symbol,
            &domain.arguments,
            domain.semantic_id,
        )
    }

    pub(crate) fn membership_predicate_bounds(
        program: &dyn crate::CheckingInput,
        membership: &typed_trees::domain::ProofMembershipFact,
    ) -> Option<(
        Option<numerics::bignum::BigInt>,
        Option<numerics::bignum::BigInt>,
    )> {
        let arguments = program
            .type_reference_table
            .type_reference_handles(membership.domain_arguments);
        if arguments.len() != membership.domain_arguments.len() {
            return None;
        }
        let interval = application_predicate_interval(
            program,
            membership.domain_symbol,
            arguments,
            membership.semantic_domain,
        )?;
        Some((interval.minimum, interval.maximum))
    }

    fn application_predicate_interval(
        program: &dyn crate::CheckingInput,
        symbol: symbols::SymbolHandle,
        arguments: &[typed_trees::types::TypeReferenceHandle],
        semantic_domain: language_semantics::SemanticDomainId,
    ) -> Option<PredicateInterval> {
        let definition = program.domain_definition(symbol)?;
        if definition.alias.is_some() {
            return None;
        }
        let indices = crate::proof_contracts::domains::closed_integer_index_bindings(
            program,
            definition,
            arguments,
            semantic_domain,
        )?;
        let mut interval = PredicateInterval {
            minimum: None,
            maximum: None,
            exact: true,
        };
        for fact in program.proof_facts(definition) {
            let Some(expression) = fact.as_expression() else {
                interval.exact = false;
                continue;
            };
            interval.exact &= self_predicate_bounds(
                program,
                definition,
                *expression,
                &indices,
                &mut |minimum, maximum| {
                    if let Some(minimum) = minimum {
                        interval.minimum = Some(match interval.minimum.take() {
                            Some(prior) => minimum.max(prior),
                            None => minimum,
                        });
                    }
                    if let Some(maximum) = maximum {
                        interval.maximum = Some(match interval.maximum.take() {
                            Some(prior) => maximum.min(prior),
                            None => maximum,
                        });
                    }
                },
            );
        }
        Some(interval)
    }

    fn self_predicate_bounds(
        program: &dyn crate::CheckingInput,
        definition: &typed_trees::domain::DomainDefinition,
        expression: typed_trees::expression::ExpressionHandle,
        indices: &[(symbols::SymbolHandle, numerics::bignum::BigInt)],
        bound: &mut impl FnMut(Option<numerics::bignum::BigInt>, Option<numerics::bignum::BigInt>),
    ) -> bool {
        use typed_trees::expression::BinaryOperator;
        if !crate::has_builtin_domain_decomposed_guard_meaning(program, definition, expression) {
            return false;
        }
        let ExpressionNode::Binary(binary) = expression_table(program).expression(expression)
        else {
            return false;
        };
        if binary.operator == BinaryOperator::And {
            let left = self_predicate_bounds(program, definition, binary.left, indices, bound);
            let right = self_predicate_bounds(program, definition, binary.right, indices, bound);
            return left && right;
        }
        let left_is_self =
            crate::exact_domain_subject_type(program, definition, binary.left).is_some();
        let right_is_self =
            crate::exact_domain_subject_type(program, definition, binary.right).is_some();
        let (literal, subject_on_left) = match (left_is_self, right_is_self) {
            (true, false) => (binary.right, true),
            (false, true) => (binary.left, false),
            _ => return false,
        };
        let Some(value) = crate::closed_integer_range_bound(program, literal).or_else(|| {
            let ExpressionNode::Name(path) = expression_table(program).expression(literal) else {
                return None;
            };
            (expression_table(program)
                .name_path_members(path.members)
                .len()
                == 1)
                .then(|| indices.iter().find(|(symbol, _)| *symbol == path.symbol))
                .flatten()
                .map(|(_, value)| value.clone())
        }) else {
            return false;
        };
        let Some(interval) =
            super::BigIntInterval::from_comparison(binary.operator, subject_on_left, value)
        else {
            return false;
        };
        bound(interval.low, interval.high);
        true
    }
}
pub(crate) mod expression_analysis {
    pub(crate) mod binary {
        use super::unsigned_constants::bitwise_known_unsigned;
        use super::{Analysis, BOOLEAN_INTERVAL, ExpressionWalk};
        use crate::proof_contracts::arithmetic_domains::integer_ranges::{
            exact_unsigned_widened_multiply_fits, integer_bit_width, literal_interval,
            primitive_name, primitive_range, u64_exact_shift_left_fits,
            validate_anonymous_integer_primitive_range,
        };
        use crate::proof_contracts::arithmetic_domains::operand_reports::arithmetic_operator_spelling;
        use crate::proof_contracts::arithmetic_domains::return_ranges::overflow_operand_value_call_target;
        use crate::proof_contracts::arithmetic_domains::{
            ArithmeticDomain, BinaryOperator, Diagnostic, ExpressionHandle, ExpressionNode,
            Interval, PrimitiveType, bitwise, guard_narrowing, is_arithmetic, ordered_values,
            unsigned_representability,
        };
        use crate::proof_contracts::contract_entailment::CompletedIntegerFormation;
        use crate::value_custody::literals;
        use numerics::integer_policy::{
            IntegerFormationCondition, IntegerPolicyBridge, IntegerPolicyPrimitive,
            IntegerTrapPredicate, ShiftCountLaw, integer_policy_bridge,
        };
        use typed_trees::expression::TableBinaryExpression;

        pub(crate) fn analyze(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
            binary: &TableBinaryExpression,
            diagnostics: &mut Vec<Diagnostic>,
            decisions: &mut super::ArithmeticDecisions,
        ) -> Analysis {
            // Preparation rewrites every suffixed policy operator onto
            // policy-qualified operands. One that still carries its suffix
            // here was never typed, and analyzing it as written would give
            // it the bare Exact meaning, so it rejects instead.
            if binary.policy != ArithmeticDomain::Exact {
                diagnostics.push(Diagnostic::error(format!(
                    "the policy operator `{}{}` in {} was not typed against its operand carrier",
                    arithmetic_operator_spelling(binary.operator),
                    binary.policy.operator_suffix(),
                    walk.owner,
                )));
            }
            let mut operation =
                Operation::analyze_operands(walk, expression, binary, diagnostics, decisions);
            if !walk.builtin_binary(expression) {
                return operation.declared_operator_result();
            }
            if let Some(machine) = walk.machine {
                crate::proof_contracts::arithmetic_domains::report_mismatched_integer_operands(
                    walk.program,
                    machine,
                    walk.state,
                    binary.operator,
                    binary.left,
                    binary.right,
                    diagnostics,
                );
            } else if let (Some(left), Some(right)) =
                (operation.left.primitive, operation.right.primitive)
                && left != right
                && !operation.is_shift()
            {
                diagnostics.push(Diagnostic::error(format!(
                    "integer operands in {} have different carriers `{}` and `{}`",
                    walk.owner,
                    primitive_name(left),
                    primitive_name(right)
                )));
            }
            if !operation.is_shift() {
                operation.land_anonymous_operands(diagnostics);
            }
            let operator = binary.operator;
            let bitwise = matches!(
                operator,
                BinaryOperator::BitwiseAnd | BinaryOperator::BitwiseOr | BinaryOperator::BitwiseXor
            );
            if !is_arithmetic(operator) && !bitwise {
                return Analysis {
                    recipe: None,
                    domain: None,
                    interval: BOOLEAN_INTERVAL,
                    primitive: Some(PrimitiveType::Bool),
                };
            }
            operation.reject_provably_zero_divisor(diagnostics);
            operation.reject_address_arithmetic(diagnostics);
            let domain = operation.operand_domain(diagnostics);
            if bitwise {
                return operation.bitwise_result(domain);
            }
            let mut interval = operation.mathematical_interval();
            let primitive = operation.result_primitive(interval);
            let effective_domain = domain.unwrap_or(ArithmeticDomain::Exact);
            let division_formed = primitive.is_some_and(|primitive| {
                walk.division_formation(
                    expression,
                    binary,
                    effective_domain,
                    primitive,
                    operation.left.interval,
                    operation.right.interval,
                    diagnostics,
                )
            });
            if division_formed {
                decisions.decided_formations.push(expression);
            }
            let mut exact_result_proven = false;
            let mut completed = CompletedIntegerFormation::default();
            if effective_domain == ArithmeticDomain::Exact {
                if operation.cancels_to_zero() {
                    interval = Interval {
                        low: Some(0),
                        high: Some(0),
                    };
                }
                if let Some(primitive) = primitive
                    && let Some(range) = primitive_range(primitive)
                    && ((division_formed
                        && operation.landed_operand_carriers == [Some(primitive); 2])
                        || operation.result_fits(primitive, range, interval, false)
                        || operation.relationally_fits_carrier(Some(primitive))
                        || {
                            completed = operation.completed_operands_formation();
                            completed.proven
                        })
                {
                    interval = interval.intersect(range);
                    exact_result_proven = true;
                }
            }
            let policy_bridge = integer_policy_primitive(operator)
                .map(|primitive| integer_policy_bridge(primitive, effective_domain));
            let mut result_representable = false;
            let recipe = if effective_domain == ArithmeticDomain::Exact {
                let flow = operation
                    .left
                    .range_recipe(walk.program, walk.lexical_owner, binary.left)
                    .zip(operation.right.range_recipe(
                        walk.program,
                        walk.lexical_owner,
                        binary.right,
                    ))
                    .and_then(|(left, right)| left.binary(operator, &right))
                    .filter(checked_trees::IntegerRangeRecipe::is_target_dependent);
                match (flow, completed.recipe) {
                    (Some(flow), Some(completed)) => Some(flow.intersect(&completed)),
                    (flow, completed) => flow.or(completed),
                }
            } else {
                None
            };
            if let Some(bridge) = policy_bridge
                && let Some(primitive) = primitive
            {
                operation.warn_unconditional_trap(bridge, primitive, interval, diagnostics);
                let representable = operation.require_representable_result(
                    bridge,
                    primitive,
                    interval,
                    exact_result_proven,
                    recipe.as_ref(),
                    decisions,
                    diagnostics,
                );
                result_representable = representable;
                if representable
                    && matches!(
                        operator,
                        BinaryOperator::Add | BinaryOperator::Subtract | BinaryOperator::Multiply
                    )
                {
                    decisions.decided_formations.push(expression);
                }
            }
            if operation.is_shift()
                && let Some(bridge) = policy_bridge
            {
                let count_proven = operation.require_shift_count_within_width(
                    bridge,
                    effective_domain,
                    diagnostics,
                );
                for pending in &mut decisions.pending_formations {
                    if pending.expression == expression {
                        pending.other_conditions_proven = count_proven;
                    }
                }
                if count_proven
                    && (operator == BinaryOperator::ShiftRight
                        || effective_domain == ArithmeticDomain::Saturating
                        || result_representable)
                {
                    decisions.decided_formations.push(expression);
                }
            }
            if effective_domain == ArithmeticDomain::Trapping
                && walk.checks_trap_coverage
                && let Some(policy_primitive) = integer_policy_primitive(operator)
                && let Some(primitive) =
                    primitive.filter(|primitive| primitive_range(*primitive).is_some())
            {
                let trap_predicates =
                    integer_policy_bridge(policy_primitive, ArithmeticDomain::Trapping)
                        .trap_predicates;
                let cannot_trap = (walk.retain_trap_receipts
                    && walk.checks_occurrence_fit
                    && walk.machine.is_some_and(|machine| {
                        super::trapping_receipts::required(walk.program, machine)
                    })
                    && walk.state.is_some())
                .then(|| operation.forms_exactly(policy_primitive, primitive, interval));
                if let Some(cannot_trap) = cannot_trap {
                    decisions.trapping_decisions.push((expression, cannot_trap));
                }
                walk.require_trap_coverage(
                    expression,
                    || {
                        cannot_trap.unwrap_or_else(|| {
                            operation.forms_exactly(policy_primitive, primitive, interval)
                        })
                    },
                    |covering| Operation::forms_exactly_under(covering, expression, binary),
                    || {
                        format!(
                            "Trapping `{}` of `{}` and `{}` in `{}` traps when {}",
                            arithmetic_operator_spelling(operator),
                            walk.operand_label(binary.left),
                            walk.operand_label(binary.right),
                            primitive_name(primitive),
                            trap_condition(trap_predicates, primitive),
                        )
                    },
                    diagnostics,
                );
            }
            Analysis {
                recipe,
                domain,
                interval: operation.policy_result_interval(effective_domain, primitive, interval),
                primitive,
            }
        }

        fn trap_condition(
            trap_predicates: &[IntegerTrapPredicate],
            primitive: PrimitiveType,
        ) -> String {
            // An unsigned carrier has no negative one, so its quotient is
            // always representable and only the zero divisor can trap.
            let signed = primitive
                .integer_bounds()
                .is_some_and(|(minimum, _)| minimum < 0);
            trap_predicates
                .iter()
                .filter(|predicate| {
                    signed
                        || !matches!(
                            predicate,
                            IntegerTrapPredicate::SignedMinimumDividedByNegativeOne
                        )
                })
                .map(|predicate| match predicate {
                    IntegerTrapPredicate::ResultOutsideCarrier => {
                        format!("its result lies outside `{}`", primitive_name(primitive))
                    }
                    IntegerTrapPredicate::ZeroDivisor => "its divisor is zero".to_owned(),
                    IntegerTrapPredicate::SignedMinimumDividedByNegativeOne => {
                        format!(
                            "it divides the `{}` minimum by `-1`",
                            primitive_name(primitive)
                        )
                    }
                    IntegerTrapPredicate::ShiftCountOutOfRange => format!(
                        "its shift count is not below the `{}` width",
                        primitive_name(primitive)
                    ),
                })
                .collect::<Vec<_>>()
                .join(" or ")
        }

        fn integer_policy_primitive(operator: BinaryOperator) -> Option<IntegerPolicyPrimitive> {
            match operator {
                BinaryOperator::Add => Some(IntegerPolicyPrimitive::Add),
                BinaryOperator::Subtract => Some(IntegerPolicyPrimitive::Subtract),
                BinaryOperator::Multiply => Some(IntegerPolicyPrimitive::Multiply),
                BinaryOperator::Divide => Some(IntegerPolicyPrimitive::Divide),
                BinaryOperator::Modulo => Some(IntegerPolicyPrimitive::Remainder),
                BinaryOperator::ShiftLeft => Some(IntegerPolicyPrimitive::ShiftLeft),
                BinaryOperator::ShiftRight => Some(IntegerPolicyPrimitive::ShiftRight),
                _ => None,
            }
        }

        pub(crate) struct Operation<'w, 'a> {
            walk: &'w ExpressionWalk<'a>,
            expression: ExpressionHandle,
            binary: TableBinaryExpression,
            left: Analysis,
            right: Analysis,
            landed_operand_carriers: [Option<PrimitiveType>; 2],
        }

        impl<'w, 'a> Operation<'w, 'a> {
            fn analyze_operands(
                walk: &'w ExpressionWalk<'a>,
                expression: ExpressionHandle,
                binary: &TableBinaryExpression,
                diagnostics: &mut Vec<Diagnostic>,
                decisions: &mut super::ArithmeticDecisions,
            ) -> Self {
                let left = walk.analyze(binary.left, diagnostics, decisions);
                let right_environment = walk.machine.and_then(|machine| {
                    guard_narrowing::short_circuit_operand_environment(
                        walk.program,
                        machine,
                        walk.state,
                        expression,
                        walk.environment,
                    )
                });
                let right_walk = ExpressionWalk {
                    environment: right_environment.as_ref().unwrap_or(walk.environment),
                    ..*walk
                };
                let right = right_walk.analyze(binary.right, diagnostics, decisions);
                let landed_operand_carriers = [left.primitive, right.primitive];
                Operation {
                    walk,
                    expression,
                    binary: *binary,
                    left,
                    right,
                    landed_operand_carriers,
                }
            }
        }

        impl Operation<'_, '_> {
            fn operator(&self) -> BinaryOperator {
                self.binary.operator
            }

            fn result_primitive(&self, interval: Interval) -> Option<PrimitiveType> {
                if self.has_address_operand() {
                    let left = self.left.primitive.or_else(|| {
                        self.right.primitive.map(|peer| {
                            typed_trees::operator::integer_peer_operand_carrier(
                                self.operator(),
                                peer,
                                false,
                            )
                        })
                    })?;
                    let right = self.right.primitive.or_else(|| {
                        self.left.primitive.map(|peer| {
                            typed_trees::operator::integer_peer_operand_carrier(
                                self.operator(),
                                peer,
                                true,
                            )
                        })
                    })?;
                    return typed_trees::operator::builtin_integer_result_carrier(
                        self.operator(),
                        [left, right],
                    );
                }
                self.left
                    .primitive
                    .filter(|primitive| *primitive != PrimitiveType::Bool)
                    .or_else(|| {
                        self.right
                            .primitive
                            .filter(|primitive| *primitive != PrimitiveType::Bool)
                    })
                    .or_else(|| {
                        if interval.low.is_some() && interval.high.is_some() {
                            self.walk.target_primitive
                        } else {
                            None
                        }
                    })
            }

            fn has_address_operand(&self) -> bool {
                self.left.primitive == Some(PrimitiveType::Addr)
                    || self.right.primitive == Some(PrimitiveType::Addr)
            }

            fn forms_exactly(
                &self,
                policy_primitive: IntegerPolicyPrimitive,
                primitive: PrimitiveType,
                interval: Interval,
            ) -> bool {
                let walk = self.walk;
                let mut unproven = Vec::new();
                if matches!(
                    self.operator(),
                    BinaryOperator::Divide | BinaryOperator::Modulo
                ) {
                    return walk.division_formation(
                        self.expression,
                        &self.binary,
                        ArithmeticDomain::Exact,
                        primitive,
                        self.left.interval,
                        self.right.interval,
                        &mut unproven,
                    );
                }
                let exact = integer_policy_bridge(policy_primitive, ArithmeticDomain::Exact);
                let interval = if self.cancels_to_zero() {
                    Interval {
                        low: Some(0),
                        high: Some(0),
                    }
                } else {
                    interval
                };
                self.require_representable_result(
                    exact,
                    primitive,
                    interval,
                    primitive_range(primitive).is_some_and(|range| {
                        self.result_fits(primitive, range, interval, false)
                            || self.completed_operands_formation().proven
                    }),
                    None,
                    &mut super::ArithmeticDecisions::default(),
                    &mut unproven,
                );
                if self.is_shift() {
                    self.require_shift_count_within_width(
                        exact,
                        ArithmeticDomain::Exact,
                        &mut unproven,
                    );
                }
                !unproven.iter().any(Diagnostic::is_error)
            }

            fn forms_exactly_under(
                walk: &ExpressionWalk,
                expression: ExpressionHandle,
                binary: &TableBinaryExpression,
            ) -> bool {
                let Some(policy_primitive) = integer_policy_primitive(binary.operator) else {
                    return false;
                };
                let mut ignored = Vec::new();
                let mut operation = Operation::analyze_operands(
                    walk,
                    expression,
                    binary,
                    &mut ignored,
                    &mut super::ArithmeticDecisions::default(),
                );
                if !operation.is_shift() {
                    operation.land_anonymous_operands(&mut ignored);
                }
                let interval = operation.mathematical_interval();
                operation
                    .result_primitive(interval)
                    .is_some_and(|primitive| {
                        operation.forms_exactly(policy_primitive, primitive, interval)
                    })
            }

            fn is_shift(&self) -> bool {
                matches!(
                    self.operator(),
                    BinaryOperator::ShiftLeft | BinaryOperator::ShiftRight
                )
            }

            fn declared_operator_result(&self) -> Analysis {
                let walk = self.walk;
                let program = walk.program;
                let result = walk.result_type(self.expression);
                let primitive = result.and_then(|result| program.primitive_type_reference(result));
                Analysis {
                    recipe: None,
                    domain: result
                        .map(|result| program.arithmetic_domain_for_type_reference(result)),
                    interval: primitive
                        .and_then(primitive_range)
                        .unwrap_or(Interval::UNBOUNDED),
                    primitive,
                }
            }

            fn land_anonymous_operands(&mut self, diagnostics: &mut Vec<Diagnostic>) {
                let is_integer = |primitive: &PrimitiveType| primitive.accepts_integer_literal();
                let Some(primitive) = self
                    .left
                    .primitive
                    .filter(is_integer)
                    .or_else(|| self.right.primitive.filter(is_integer))
                else {
                    return;
                };
                let program = self.walk.program;
                let owner = self.walk.owner;
                let operator = self.operator();
                for (position, (operand, analysis)) in [
                    (self.binary.left, &mut self.left),
                    (self.binary.right, &mut self.right),
                ]
                .into_iter()
                .enumerate()
                {
                    let primitive = typed_trees::operator::integer_peer_operand_carrier(
                        operator,
                        primitive,
                        position == 1,
                    );
                    if !primitive.is_fixed_integer() {
                        continue;
                    }
                    if matches!(
                        program.expression_table.expression(operand),
                        ExpressionNode::Match(_)
                    ) {
                        validate_anonymous_integer_primitive_range(
                            program,
                            primitive,
                            operand,
                            owner,
                            diagnostics,
                        );
                        continue;
                    }
                    let Some(evaluated) =
                        literals::anonymous_numeric_value(program, operand, &mut |expression| {
                            literals::has_anonymous_operator_meaning(program, expression)
                        })
                    else {
                        continue;
                    };
                    if let Some(literal) = evaluated
                        .value
                        .to_integer_exact()
                        .and_then(|value| literals::land_integer_value(&value, primitive))
                    {
                        analysis.interval = literal_interval(&literal);
                        if analysis.primitive.is_none() {
                            self.landed_operand_carriers[position] = Some(primitive);
                        }
                    } else {
                        diagnostics.push(
                    Diagnostic::error(format!(
                        "anonymous operand `{}` cannot land exactly in `{}` in {owner}; type an \
                         operand before division if integer division was intended",
                        evaluated.value,
                        primitive.name(),
                    ))
                    .with_source_span(program.expression_table.source_span(operand)),
                );
                    }
                }
            }

            fn reject_provably_zero_divisor(&self, diagnostics: &mut Vec<Diagnostic>) {
                let operation = match self.operator() {
                    BinaryOperator::Divide => "division",
                    BinaryOperator::Modulo => "remainder",
                    _ => return,
                };
                if self.right.interval.low == Some(0) && self.right.interval.high == Some(0) {
                    diagnostics.push(Diagnostic::error(format!(
                "{operation} by zero in {}: the divisor is provably zero, which always traps at \
                 runtime. Remove the operation or use a nonzero divisor.",
                self.walk.owner,
            )));
                }
            }

            fn reject_address_arithmetic(&self, diagnostics: &mut Vec<Diagnostic>) {
                let left_is_addr = self.left.primitive == Some(PrimitiveType::Addr);
                let right_is_addr = self.right.primitive == Some(PrimitiveType::Addr);
                if !left_is_addr && !right_is_addr {
                    return;
                }
                let legal = self.result_primitive(Interval::UNBOUNDED).is_some();
                if !legal {
                    diagnostics.push(Diagnostic::error(format!(
                        "meaningless address arithmetic in {}: `addr` composes with \
                 counts (`addr + u64`, `addr - u64`) or differences with itself \
                 (`addr - addr` is the count between two addresses); `{}` over \
                 these operands conflates the address and count axes.",
                        self.walk.owner,
                        arithmetic_operator_spelling(self.operator()),
                    )));
                }
            }

            fn operand_domain(
                &self,
                diagnostics: &mut Vec<Diagnostic>,
            ) -> Option<ArithmeticDomain> {
                if self.is_shift() {
                    return self.left.domain;
                }
                match (self.left.domain, self.right.domain) {
                    (Some(left_domain), Some(right_domain)) => {
                        if left_domain != right_domain {
                            diagnostics.push(Diagnostic::error(format!(
                        "mixed arithmetic domains in {}: one operand is `{}` and the other is \
                         `{}`. Decision 17 forbids implicit domain mixing -- cross domains with \
                         an explicit `as` cast, or declare both operands in the same domain.",
                        self.walk.owner,
                        left_domain.name(),
                        right_domain.name(),
                    )));
                        }
                        Some(if left_domain == ArithmeticDomain::Exact {
                            right_domain
                        } else {
                            left_domain
                        })
                    }
                    (Some(domain), None) | (None, Some(domain)) => Some(domain),
                    (None, None) => None,
                }
            }

            fn bitwise_result(&self, domain: Option<ArithmeticDomain>) -> Analysis {
                let (left, right) = (&self.left, &self.right);
                let primitive = left
                    .primitive
                    .filter(|primitive| *primitive != PrimitiveType::Bool)
                    .or_else(|| {
                        right
                            .primitive
                            .filter(|primitive| *primitive != PrimitiveType::Bool)
                    })
                    .or_else(|| {
                        (left.interval.low.is_some()
                            && left.interval.high.is_some()
                            && right.interval.low.is_some()
                            && right.interval.high.is_some())
                        .then_some(self.walk.target_primitive)
                        .flatten()
                    });
                Analysis {
                    recipe: None,
                    domain,
                    interval: primitive
                        .map(|primitive| {
                            bitwise::binary(
                                self.operator(),
                                primitive,
                                left.interval,
                                right.interval,
                                self.known_unsigned(primitive, self.binary.left),
                                self.known_unsigned(primitive, self.binary.right),
                            )
                        })
                        .unwrap_or(Interval::UNBOUNDED),
                    primitive,
                }
            }

            fn known_unsigned(
                &self,
                primitive: PrimitiveType,
                operand: ExpressionHandle,
            ) -> Option<u64> {
                bitwise_known_unsigned(
                    self.walk.program,
                    self.walk.environment,
                    primitive,
                    operand,
                    0,
                )
            }

            fn mathematical_interval(&self) -> Interval {
                let walk = self.walk;
                let (program, machine, state) = (walk.program, walk.machine, walk.state);
                let (left, right) = (self.binary.left, self.binary.right);
                let interval = match self.operator() {
                    BinaryOperator::Add => self.left.interval.add(self.right.interval),
                    BinaryOperator::Subtract => self.left.interval.subtract(self.right.interval),
                    BinaryOperator::Multiply => self.left.interval.multiply(self.right.interval),
                    BinaryOperator::Modulo => self.left.interval.modulo(self.right.interval),
                    BinaryOperator::Divide
                        if self.left.primitive.or(self.right.primitive)
                            == Some(PrimitiveType::U64) =>
                    {
                        unsigned_representability::divide_interval(
                            self.left.interval,
                            self.right.interval,
                            self.known_unsigned(PrimitiveType::U64, left),
                            self.known_unsigned(PrimitiveType::U64, right),
                        )
                    }
                    BinaryOperator::Divide => self.left.interval.divide(self.right.interval),
                    BinaryOperator::ShiftLeft => self.left.interval.shift_left(self.right.interval),
                    BinaryOperator::ShiftRight => self.left.primitive.map_or_else(
                        || self.left.interval.shift_right(self.right.interval),
                        |primitive| {
                            bitwise::shift_right(
                                primitive,
                                self.left.interval,
                                self.right.interval,
                                bitwise_known_unsigned(
                                    program,
                                    walk.environment,
                                    primitive,
                                    left,
                                    0,
                                ),
                            )
                        },
                    ),
                    _ => Interval::UNBOUNDED,
                };
                if self.operator() == BinaryOperator::Subtract
                    && let Some(machine) = machine
                    && guard_narrowing::has_builtin_bound_arithmetic(
                        program,
                        machine,
                        state,
                        self.expression,
                    )
                {
                    let captured = state.and_then(|state| {
                        walk.environment
                            .numeric_observations
                            .integer_operations
                            .iter()
                            .find(|observation| {
                                observation.state == state.symbol
                                    && observation.expression == self.expression
                            })
                    });
                    let denotational = ordered_values::subtract_floor(
                        program,
                        machine,
                        state,
                        walk.environment,
                        left,
                        right,
                        captured.is_some_and(|observation| observation.preserves_storage),
                    );
                    let floor = denotational
                        .into_iter()
                        .chain(captured.and_then(|observation| observation.minimum_difference))
                        .max();
                    if let Some(floor) = floor {
                        return interval.intersect(Interval {
                            low: Some(floor),
                            high: None,
                        });
                    }
                }
                interval
            }

            fn cancels_to_zero(&self) -> bool {
                let walk = self.walk;
                self.operator() == BinaryOperator::Subtract
                    && self.left.primitive == self.right.primitive
                    && self
                        .left
                        .primitive
                        .is_some_and(|primitive| integer_bit_width(primitive).is_some())
                    && walk.builtin_binary(self.expression)
                    && walk.machine.is_some_and(|machine| {
                        ordered_values::same_place(
                            walk.program,
                            machine,
                            walk.state,
                            self.binary.left,
                            self.binary.right,
                        )
                    })
            }

            fn relationally_fits_carrier(&self, primitive: Option<PrimitiveType>) -> bool {
                let walk = self.walk;
                let (program, environment) = (walk.program, walk.environment);
                let (left, right) = (self.binary.left, self.binary.right);
                if matches!(
                    self.operator(),
                    BinaryOperator::Add | BinaryOperator::Subtract | BinaryOperator::Multiply
                ) && let Some((minimum, maximum)) =
                    primitive.and_then(PrimitiveType::integer_bounds)
                {
                    let proved = walk
                        .machine
                        .zip(walk.state)
                        .is_some_and(|(machine, state)| {
                            super::super::live_integer_constraints::proves_range(
                                program,
                                machine,
                                state,
                                environment,
                                self.expression,
                                Some(&numerics::bignum::BigInt::from_i128(minimum)),
                                Some(&numerics::bignum::BigInt::from_i128(maximum)),
                            )
                        });
                    if proved {
                        return true;
                    }
                }
                match self.operator() {
                    BinaryOperator::Subtract => {
                        environment.proves_joint_subtract_bound(program, left, right)
                            || environment
                                .proves_signed_joint_subtract_lower_bound(program, left, right)
                            || environment
                                .proves_signed_joint_subtract_upper_bound(program, left, right)
                    }
                    BinaryOperator::Multiply => {
                        environment.proves_joint_multiply_bound(program, left, right)
                            || environment.proves_signed_joint_multiply_bounds(program, left, right)
                            || environment
                                .proves_signed_joint_multiply_negation_bound(program, left, right)
                            || walk.machine.is_some_and(|machine| {
                                exact_unsigned_widened_multiply_fits(
                                    program, machine, walk.state, left, right,
                                )
                            })
                    }
                    BinaryOperator::ShiftLeft => {
                        primitive == Some(PrimitiveType::U64)
                            && u64_exact_shift_left_fits(self.left.interval, self.right.interval)
                    }
                    _ => false,
                }
            }

            fn warn_unconditional_trap(
                &self,
                bridge: IntegerPolicyBridge,
                primitive: PrimitiveType,
                interval: Interval,
                diagnostics: &mut Vec<Diagnostic>,
            ) {
                if !bridge
                    .trap_predicates
                    .contains(&IntegerTrapPredicate::ResultOutsideCarrier)
                {
                    return;
                }
                let Some(range) = primitive_range(primitive) else {
                    return;
                };
                let always_above = matches!(
                    (range.high, interval.low),
                    (Some(bound), Some(low)) if low > bound
                );
                let always_below = matches!(
                    (range.low, interval.high),
                    (Some(bound), Some(high)) if high < bound
                );
                if always_above || always_below {
                    diagnostics.push(Diagnostic::warning(format!(
                        "trapping arithmetic in {} ALWAYS overflows `{}` -- this computation traps \
                 unconditionally at runtime (the trap is an effect and will fire even if the \
                 result is never used)",
                        self.walk.owner,
                        primitive_name(primitive),
                    )));
                }
            }

            fn require_representable_result(
                &self,
                bridge: IntegerPolicyBridge,
                primitive: PrimitiveType,
                interval: Interval,
                exact_result_proven: bool,
                recipe: Option<&checked_trees::IntegerRangeRecipe>,
                decisions: &mut super::ArithmeticDecisions,
                diagnostics: &mut Vec<Diagnostic>,
            ) -> bool {
                if matches!(
                    self.operator(),
                    BinaryOperator::Divide | BinaryOperator::Modulo
                ) || !bridge
                    .formation_conditions
                    .contains(&IntegerFormationCondition::ResultRepresentable)
                {
                    return false;
                }
                let Some(range) = primitive_range(primitive) else {
                    return false;
                };
                if self.result_fits(primitive, range, interval, exact_result_proven) {
                    return true;
                }
                let definitely_outside = range
                    .high
                    .zip(interval.low)
                    .is_some_and(|(high, low)| low > high)
                    || range
                        .low
                        .zip(interval.high)
                        .is_some_and(|(low, high)| high < low);
                if definitely_outside {
                    self.report_unrepresentable(primitive, diagnostics);
                    return false;
                }
                if let Some(recipe) = recipe {
                    use numerics::bignum::BigInt;
                    if let Some(minimum) = range.low {
                        let maximum = range.high.map(BigInt::from_i64).or_else(|| {
                            (primitive == PrimitiveType::U64).then(|| BigInt::from_u64(u64::MAX))
                        });
                        if let Some(maximum) = maximum {
                            decisions.integer_range_obligations.push(
                                checked_trees::IntegerRangeObligation::retain(
                                    self.expression,
                                    self.walk.lexical_owner,
                                    semantic_vocabulary::ScalarConditionRole::Prerequisite,
                                    recipe.clone(),
                                    BigInt::from_i64(minimum),
                                    maximum,
                                    self.walk.owner.to_owned(),
                                ),
                            );
                            return false;
                        }
                    }
                }
                if decisions.allows_pending_formations
                    && self.walk.checks_occurrence_fit
                    && self.walk.specification_facts.is_none()
                    && self.walk.program.storage_graph().is_none()
                    && let Some((machine, state)) = self.walk.machine.zip(self.walk.state)
                {
                    decisions.pending_formations.push(
                        super::super::storage_formations::PendingIntegerFormation {
                            machine: machine.symbol,
                            state: state.symbol,
                            expression: self.expression,
                            other_conditions_proven: !self.is_shift(),
                            diagnostic: self.unrepresentable_diagnostic(primitive),
                        },
                    );
                    return false;
                }
                self.report_unrepresentable(primitive, diagnostics);
                false
            }

            fn result_fits(
                &self,
                primitive: PrimitiveType,
                range: Interval,
                interval: Interval,
                exact_result_proven: bool,
            ) -> bool {
                if self.has_address_operand() {
                    return exact_result_proven;
                }
                if self.left.primitive == Some(primitive)
                    && self.walk.builtin_binary(self.expression)
                    && integer_policy_primitive(self.operator()).is_some_and(|operator| {
                        !integer_policy_bridge(operator, ArithmeticDomain::Exact)
                            .formation_conditions
                            .contains(&IntegerFormationCondition::ResultRepresentable)
                    })
                {
                    return true;
                }
                if self.walk.machine.is_none()
                    && self.walk.builtin_binary(self.expression)
                    && super::super::declaration_values::binary_result_fits(
                        self.walk.program,
                        self.walk.lexical_owner,
                        self.walk.parameters,
                        self.walk.declaration_facts,
                        self.expression,
                        primitive,
                    )
                {
                    return true;
                }
                let operator = self.operator();
                let increase_fits =
                    || operator == BinaryOperator::Add && self.unsigned_increase_fits(range.high);
                if primitive != PrimitiveType::U64 {
                    return exact_result_proven || range.contains(interval) || increase_fits();
                }
                exact_result_proven
                    || (operator == BinaryOperator::Subtract
                        && interval.low.is_some_and(|low| low >= 0))
                    || unsigned_representability::binary_fits(
                        operator,
                        self.left.interval,
                        self.right.interval,
                        None,
                        None,
                    )
                    || unsigned_representability::binary_fits(
                        operator,
                        self.left.interval,
                        self.right.interval,
                        self.known_unsigned(primitive, self.binary.left),
                        self.known_unsigned(primitive, self.binary.right),
                    )
                    || increase_fits()
            }

            fn completed_operands_formation(&self) -> CompletedIntegerFormation {
                if !self.walk.checks_occurrence_fit {
                    return Default::default();
                }
                self.walk
            .machine
            .zip(self.walk.state)
            .map_or_else(Default::default, |(machine, state)| {
                if let Some(prior_facts) = self.walk.specification_facts {
                    return crate::proof_contracts::contract_entailment::exact_binary_formation_in_specification(
                        self.walk.program, machine, state, prior_facts, self.expression,
                    );
                }
                crate::proof_contracts::contract_entailment::exact_binary_formation_at_occurrence(
                    self.walk.program,
                    machine,
                    state,
                    self.expression,
                )
            })
            }

            fn unsigned_increase_fits(&self, ceiling: Option<i64>) -> bool {
                let walk = self.walk;
                let fits = |base, increment: Interval| {
                    walk.machine.is_some_and(|machine| {
                        ordered_values::unsigned_increase_fits(
                            walk.program,
                            machine,
                            walk.state,
                            walk.environment,
                            base,
                            increment,
                            ceiling,
                        )
                    })
                };
                fits(self.binary.left, self.right.interval)
                    || fits(self.binary.right, self.left.interval)
            }

            fn report_unrepresentable(
                &self,
                primitive: PrimitiveType,
                diagnostics: &mut Vec<Diagnostic>,
            ) {
                diagnostics.push(Diagnostic::error(
                    self.unrepresentable_diagnostic(primitive),
                ));
            }

            fn unrepresentable_diagnostic(&self, primitive: PrimitiveType) -> String {
                let program = self.walk.program;
                let call_hint = overflow_operand_value_call_target(program, self.binary.left)
            .or_else(|| overflow_operand_value_call_target(program, self.binary.right))
            .map(|target| {
                format!(
                    " Here the operand `{target}(..)` is a value-machine call whose return range \
                     is unproven -- annotate its return type with a range or domain (e.g. `-> {} \
                     in Wrapping`).",
                    primitive_name(primitive)
                )
            })
            .unwrap_or_default();
                let target_domain = self.walk.target_domain;
                let target_hint = if target_domain != ArithmeticDomain::Exact {
                    format!(
                        " The target's `in {domain}` does not re-domain the value expression (decision \
                 17 is operand-driven): declare the domain on an operand or intermediate (`let \
                 t: {prim} in {domain} = ...`), or re-tag the operand inline (`x as {prim} in \
                 {domain}`).",
                        domain = target_domain.name(),
                        prim = primitive_name(primitive),
                    )
                } else {
                    String::new()
                };
                let terminal_completion = if self.walk.owner.ends_with("return value") {
                    format!(
                        " terminal expression may overflow `{}`.",
                        primitive_name(primitive)
                    )
                } else {
                    String::new()
                };
                format!(
                    "exact arithmetic in {} may overflow `{}`: the operands are not provably in range \
             (decision 17 -- exact arithmetic is a proof obligation). Widen with an `as` cast \
             to a larger type, constrain the operands' range (bound a parameter with a \
             `requires` clause, or narrow a value with a dominating guard), or opt into a \
             defined-overflow domain (`{} in Wrapping`/`Saturating`/`Trapping`).{}{}{}",
                    self.walk.owner,
                    primitive_name(primitive),
                    primitive_name(primitive),
                    call_hint,
                    target_hint,
                    terminal_completion,
                )
            }

            fn require_shift_count_within_width(
                &self,
                bridge: IntegerPolicyBridge,
                effective_domain: ArithmeticDomain,
                diagnostics: &mut Vec<Diagnostic>,
            ) -> bool {
                if bridge.shift_count_law != ShiftCountLaw::MustBeWithinWidth {
                    return false;
                }
                let Some(shift_primitive) = self.left.primitive.or(self.walk.target_primitive)
                else {
                    return false;
                };
                let Some(width) = integer_bit_width(shift_primitive) else {
                    return false;
                };
                let count = self.right.interval;
                let provably_in_range = matches!(count.low, Some(low) if low >= 0)
                    && matches!(count.high, Some(high) if high < width);
                if provably_in_range {
                    return true;
                }
                let relationally_in_range =
                    self.walk
                        .machine
                        .zip(self.walk.state)
                        .is_some_and(|(machine, state)| {
                            super::super::live_integer_constraints::proves_range(
                                self.walk.program,
                                machine,
                                state,
                                self.walk.environment,
                                self.binary.right,
                                Some(&numerics::bignum::BigInt::from_i64(0)),
                                Some(&numerics::bignum::BigInt::from_i64(width - 1)),
                            )
                        });
                if relationally_in_range {
                    return true;
                }
                // A private nested machine that omits `requires` owes its
                // shift-count proof to its arrivals, like its exact additions:
                // the walk above sees only this state's own facts, so ask the
                // occurrence route, which replays every arrival, whether the
                // count operand stays inside `0..width` on all of them. An
                // unproven or unreadable arrival answers false and the
                // diagnostic below is still emitted.
                if self.count_within_width_at_occurrence(width) {
                    return true;
                }
                let always_out = matches!(count.low, Some(low) if low >= width)
                    || matches!(count.high, Some(high) if high < 0);
                let verdict = if always_out {
                    "is provably out of range and can never execute"
                } else {
                    "is not provably below the operand width"
                };
                let saturating_hint = if effective_domain == ArithmeticDomain::Saturating {
                    " (`Saturating` governs value overflow, not count validity -- its count obligation \
             is Exact's)"
                } else {
                    ""
                };
                diagnostics.push(Diagnostic::error(format!(
            "shift count in {owner} {verdict} for `{prim}`{saturating_hint}: exact shifts prove \
             `count < {width}` (ch5 shift-count ruling -- proof-or-policy). Constrain the \
             count's range (a ranged type, a `requires` clause, or a dominating guard), or \
             pick a defined-count policy on the SHIFTED operand (`{prim} in Wrapping` reduces \
             the count modulo {width}, equivalently `count & {mask}` for this carrier; `in \
             Trapping` traps at runtime).",
            owner = self.walk.owner,
            prim = primitive_name(shift_primitive),
            mask = width - 1,
        )));
                false
            }

            fn count_within_width_at_occurrence(&self, width: i64) -> bool {
                let walk = self.walk;
                if !walk.checks_occurrence_fit || walk.specification_facts.is_some() {
                    return false;
                }
                let Some(((machine, state), carrier)) =
                    walk.machine.zip(walk.state).zip(self.right.primitive)
                else {
                    return false;
                };
                let holds = |operator, bound| {
                    crate::proof_contracts::contract_entailment::integer_operands_compare_at_occurrence(
                        walk.program,
                        machine,
                        state,
                        self.expression,
                        carrier,
                        [None, Some((operator, bound))],
                    )
                };
                (matches!(self.right.interval.low, Some(low) if low >= 0)
                    || holds(BinaryOperator::GreaterOrEqual, 0))
                    && holds(BinaryOperator::Less, width)
            }

            fn policy_result_interval(
                &self,
                effective_domain: ArithmeticDomain,
                primitive: Option<PrimitiveType>,
                interval: Interval,
            ) -> Interval {
                if effective_domain == ArithmeticDomain::Exact {
                    return interval;
                }
                let Some(carrier) = primitive.and_then(primitive_range) else {
                    return interval;
                };
                let count_is_ordinary = !self.is_shift()
                    || primitive.and_then(integer_bit_width).is_some_and(|width| {
                        matches!(self.right.interval.low, Some(low) if low >= 0)
                            && matches!(self.right.interval.high, Some(high) if high < width)
                    });
                let proven_in_carrier = carrier.contains(interval)
                    && (carrier.high.is_some() || interval.high.is_some());
                if !count_is_ordinary {
                    carrier
                } else if effective_domain == ArithmeticDomain::Saturating {
                    let clamp = |value: i64| {
                        let value = carrier.low.map_or(value, |low| value.max(low));
                        carrier.high.map_or(value, |high| value.min(high))
                    };
                    Interval {
                        low: interval.low.map(clamp).or(carrier.low),
                        high: interval.high.map(clamp).or(carrier.high),
                    }
                } else if !proven_in_carrier {
                    carrier
                } else {
                    interval
                }
            }
        }
    }
    pub(crate) mod call {
        use super::{Analysis, ExpressionWalk, NEUTRAL};
        use crate::frozen_program::expression_table;
        use crate::proof_contracts::arithmetic_domains::integer_ranges::{
            integer_bit_width, primitive_range,
        };
        use crate::proof_contracts::arithmetic_domains::return_ranges::ensured_call_result_interval;
        use crate::proof_contracts::arithmetic_domains::{
            ArithmeticDomain, ExpressionHandle, Interval, TableCallExpression, call_return_type,
            range_constraint_interval,
        };
        use checked_trees::IntegerRangeRecipe;

        pub(crate) fn analyze(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
            call: &TableCallExpression,
            child_values: Option<&[super::CheckedIntegerValue]>,
        ) -> Analysis {
            let analysis = named_operator_result(walk, call).unwrap_or_else(|| {
                let mut cached_actuals = None;
                [
                    declared_return_range(
                        walk,
                        expression,
                        call,
                        child_values,
                        &mut cached_actuals,
                    ),
                    inferred_return_range(walk, call, child_values, &mut cached_actuals),
                    returned_referent_range(walk, expression, call),
                ]
                .into_iter()
                .flatten()
                .reduce(|accepted, additional| Analysis {
                    recipe: accepted.recipe.or(additional.recipe),
                    interval: accepted.interval.intersect(additional.interval),
                    ..accepted
                })
                .unwrap_or(NEUTRAL)
            });
            let mut analysis = with_result_carrier(walk, expression, analysis);
            if call.layout_query.is_some() || analysis.recipe.is_none() {
                analysis.recipe = super::super::deferred_integer_observation(
                    walk.program,
                    walk.lexical_owner,
                    expression,
                    analysis.primitive,
                );
            }
            analysis
        }

        fn returned_referent_range(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
            call: &TableCallExpression,
        ) -> Option<Analysis> {
            let program = walk.program;
            let result = crate::reference_shell(program, call_return_type(program, call)?)?;
            if !result.access.is_readable() {
                return None;
            }
            let primitive = program.primitive_type_reference(result.referee)?;
            let callee = crate::machine_calls::calls::call_contract(program, call)?;
            let frames = crate::CallFrameResolver::new(program)?;
            let (_, selected_state) =
                crate::machine_calls::calls::machine_state_by_symbol(program, call.target_symbol)?;
            let returned = frames.reference_result_origins(selected_state.symbol)?;
            let actuals = frames.expression_call_write_origins(walk.machine?, expression)?;
            let writes = frames.expression_may_write_paths(walk.machine?, expression)?;
            let arguments = expression_table(program).expression_handles(call.arguments);
            let mut interval = None;
            for source in returned {
                if !source.segments.is_empty()
                    || source.collection_coarse
                    || !source.recasts.is_empty()
                    || source.representation.is_some()
                {
                    return None;
                }
                let position = callee
                    .parameters
                    .iter()
                    .position(|parameter| parameter.symbol == source.root)?;
                let position = position.checked_add(callee.leading_operands)?;
                let origins = actuals.arguments.get(position)?.as_ref()?;
                if origins.is_empty()
                    || origins.iter().any(|origin| {
                        origin.collection_coarse
                            || !origin.recasts.is_empty()
                            || origin.representation.is_some()
                            || writes
                                .iter()
                                .any(|written| crate::frame_paths_overlap(written, &origin.path))
                    })
                {
                    return None;
                }
                let mut actual = *arguments.get(position)?;
                if let Some(borrow) = expression_table(program).borrow_expression(actual) {
                    if !borrow.access.is_readable() {
                        return None;
                    }
                    actual = borrow.target;
                }
                let mut diagnostics = Vec::new();
                let analysis = walk
                    .with_destination(None, ArithmeticDomain::Exact)
                    .analyze(
                        actual,
                        &mut diagnostics,
                        &mut super::ArithmeticDecisions::default(),
                    );
                if !diagnostics.is_empty() || analysis.primitive != Some(primitive) {
                    return None;
                }
                interval = Some(interval.map_or(analysis.interval, |previous: Interval| {
                    previous.union(analysis.interval)
                }));
            }
            Some(Analysis {
                recipe: None,
                interval: interval?,
                primitive: Some(primitive),
                domain: Some(program.arithmetic_domain_for_type_reference(result.referee)),
            })
        }

        fn with_result_carrier(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
            analysis: Analysis,
        ) -> Analysis {
            let program = walk.program;
            let result = walk.result_type(expression);
            let Some(return_type) = result else {
                return analysis;
            };
            let domain = program.arithmetic_domain_for_type_reference(return_type);
            let primitive = analysis
                .primitive
                .or_else(|| program.primitive_type_reference(return_type));
            Analysis {
                recipe: analysis.recipe,
                domain: Some(analysis.domain.unwrap_or(domain)),
                primitive,
                interval: primitive
                    .and_then(primitive_range)
                    .map_or(analysis.interval, |carrier| {
                        analysis.interval.intersect(carrier)
                    }),
            }
        }

        fn named_operator_result(
            walk: &ExpressionWalk,
            call: &TableCallExpression,
        ) -> Option<Analysis> {
            let program = walk.program;
            let operator = typed_trees::operator::resolve_named_expression_call(program, call)?;
            let primitive = program
                .primitive_type_reference(operator.return_type)
                .filter(|primitive| integer_bit_width(*primitive).is_some())?;
            let range = primitive_range(primitive)?;
            let converted = (|| {
                let [operand] = expression_table(program).expression_handles(call.arguments) else {
                    return None;
                };
                let source = super::super::float_source_bounds(
                    program,
                    walk.lexical_owner,
                    walk.environment,
                    *operand,
                    &|value| {
                        walk.result_type(value)
                            .or_else(|| walk.declared_type(value))
                    },
                )?;
                let (minimum, maximum) = crate::float_integer_conversion_bounds(
                    program,
                    operator,
                    source.minimum,
                    source.maximum,
                )?;
                Some(Interval {
                    low: minimum.to_i64(),
                    high: maximum.to_i64(),
                })
            })();
            let declared =
                range_constraint_interval(program, operator.return_type).unwrap_or(range);
            Some(Analysis {
                recipe: None,
                domain: Some(program.arithmetic_domain_for_type_reference(operator.return_type)),
                interval: converted
                    .map_or(declared, |converted| converted.intersect(declared))
                    .intersect(range),
                primitive: Some(primitive),
            })
        }

        fn declared_return_range(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
            call: &TableCallExpression,
            child_values: Option<&[super::CheckedIntegerValue]>,
            cached_actuals: &mut Option<
                Vec<(symbols::SymbolHandle, Interval, Option<IntegerRangeRecipe>)>,
            >,
        ) -> Option<Analysis> {
            let program = walk.program;
            let return_type = call_return_type(program, call)?;
            let primitive = program.primitive_type_reference(return_type);
            let declared = range_constraint_interval(program, return_type);
            let is_independent =
                crate::machine_calls::contract_dependencies::independent_call_application(
                    program,
                    walk.lexical_owner,
                    call.target_symbol,
                    typed_trees::references::StaticArgumentCall::Expression(expression, call),
                );
            let callee = is_independent
                .then(|| crate::machine_calls::calls::call_contract(program, call))
                .flatten();
            let can_have_ensured = is_independent
                && (callee.as_ref().is_some_and(|callee| {
                    callee.contracts.iter().any(|contract| {
                        contract.kind == typed_trees::signature::SignatureContractKind::Ensures
                    })
                }) || crate::machine_calls::calls::machine_state_by_symbol(
                    program,
                    call.target_symbol,
                )
                .is_some_and(|(machine, _)| machine.target_family_interface));
            let ensured = if can_have_ensured {
                let actuals = cached_actuals
                    .get_or_insert_with(|| {
                        exact_ordinary_actual_intervals(walk, call, child_values)
                            .unwrap_or_default()
                    })
                    .as_slice();
                let values: Vec<_> = actuals
                    .iter()
                    .map(|(symbol, interval, _)| (*symbol, *interval))
                    .collect();
                let lengths = argument_collection_lengths(walk, call);
                let concrete = super::super::call_result_bounds::ArgumentBounds { values, lengths };
                ensured_call_result_interval(
                    program,
                    walk.lexical_owner,
                    expression,
                    call,
                    &concrete,
                )
                .map(|ensured| {
                    primitive
                        .and_then(primitive_range)
                        .map_or(ensured, |carrier| ensured.intersect(carrier))
                })
            } else {
                None
            };
            let recipe = callee.as_ref().and_then(|callee| {
                super::super::call_result_bounds::normal_return_recipe(program, callee)
            });
            let interval = match (declared, ensured) {
                (Some(declared), Some(ensured)) => Some(declared.intersect(ensured)),
                (declared, ensured) => declared.or(ensured),
            }
            .or_else(|| {
                recipe
                    .as_ref()
                    .and_then(|_| primitive.and_then(primitive_range))
            })?;
            Some(Analysis {
                recipe,
                domain: None,
                interval,
                primitive,
            })
        }

        fn argument_collection_lengths(
            walk: &ExpressionWalk,
            call: &TableCallExpression,
        ) -> Vec<(symbols::SymbolHandle, Interval)> {
            use typed_trees::types::TypeReferenceNode;
            let Some(state) = walk.state else {
                return Vec::new();
            };
            let Some(callee) = crate::machine_calls::calls::call_contract(walk.program, call)
                .filter(|_| call.selects_only_nominal_route())
            else {
                return Vec::new();
            };
            let arguments = expression_table(walk.program).expression_handles(call.arguments);
            let Some(arguments) = arguments.get(callee.leading_operands..) else {
                return Vec::new();
            };
            if arguments.len() != callee.parameters.len() {
                return Vec::new();
            }
            callee
                .parameters
                .iter()
                .zip(arguments)
                .filter_map(|(parameter, argument)| {
                    if parameter.is_const {
                        return None;
                    }
                    let mut reference = parameter.type_reference;
                    if let TypeReferenceNode::Reference { referee, .. } =
                        walk.program.type_reference_table.type_reference(reference)
                    {
                        let (machine, entry) =
                            crate::machine_calls::calls::machine_state_by_symbol(
                                walk.program,
                                call.target_symbol,
                            )?;
                        if !crate::state_reference_parameter_binding_is_stable(
                            walk.program,
                            machine,
                            entry,
                            parameter.symbol,
                        ) {
                            return None;
                        }
                        reference = *referee;
                    }
                    if !matches!(
                        walk.program.type_reference_table.type_reference(reference),
                        TypeReferenceNode::FixedArray { .. } | TypeReferenceNode::Slice { .. }
                    ) {
                        return None;
                    }
                    let closed = crate::closed_collection_length(
                        walk.program,
                        walk.machine?,
                        state,
                        *argument,
                    )
                    .and_then(|length| i64::try_from(length).ok())
                    .map(Interval::constant);
                    let carried = super::super::carried_slice_length(
                        walk.program,
                        walk.machine?,
                        Some(state),
                        walk.environment,
                        *argument,
                    );
                    let length = match (closed, carried) {
                        (Some(closed), Some(carried)) => closed.intersect(carried),
                        (Some(length), None) | (None, Some(length)) => length,
                        (None, None) => return None,
                    };
                    Some((parameter.symbol, length))
                })
                .collect()
        }

        fn exact_ordinary_actual_intervals(
            walk: &ExpressionWalk,
            call: &TableCallExpression,
            child_values: Option<&[super::CheckedIntegerValue]>,
        ) -> Option<Vec<(symbols::SymbolHandle, Interval, Option<IntegerRangeRecipe>)>> {
            if !call.selects_only_nominal_route() {
                return None;
            }
            let callee = crate::machine_calls::calls::call_contract(walk.program, call)?;
            let parameters = callee.parameters.iter().collect::<Vec<_>>();
            let arguments = expression_table(walk.program)
                .expression_handles(call.arguments)
                .get(callee.leading_operands..)?;
            if parameters.len() != arguments.len() {
                return None;
            }
            let operand_walk = walk.with_destination(None, ArithmeticDomain::Exact);
            let intervals = parameters
                .into_iter()
                .zip(arguments)
                .map(|(parameter, argument)| {
                    if parameter.is_mutable
                        || parameter.is_const
                        || !parameter.symbol.is_valid()
                        || walk
                            .program
                            .primitive_type_reference(parameter.type_reference)
                            .is_none()
                    {
                        return Some(None);
                    }
                    if let Some(values) = child_values
                        && let Some(found) = values
                            .iter()
                            .rev()
                            .find(|value| value.expression == *argument)
                    {
                        return Some(Some((
                            parameter.symbol,
                            found.interval,
                            found.recipe.clone(),
                        )));
                    }
                    let mut diagnostics = Vec::new();
                    let analysis = operand_walk.analyze(
                        *argument,
                        &mut diagnostics,
                        &mut super::ArithmeticDecisions::default(),
                    );
                    diagnostics.is_empty().then_some(Some((
                        parameter.symbol,
                        analysis.interval,
                        analysis.recipe,
                    )))
                })
                .collect::<Option<Vec<_>>>()?;
            Some(intervals.into_iter().flatten().collect())
        }

        fn inferred_return_range(
            walk: &ExpressionWalk,
            call: &TableCallExpression,
            child_values: Option<&[super::CheckedIntegerValue]>,
            cached_actuals: &mut Option<
                Vec<(symbols::SymbolHandle, Interval, Option<IntegerRangeRecipe>)>,
            >,
        ) -> Option<Analysis> {
            let program = walk.program;
            let inference = walk.return_ranges?;
            if !call.selects_only_nominal_route() || !call.machine_arguments.is_empty() {
                return None;
            }
            let (callee, state) =
                crate::machine_calls::calls::machine_state_by_symbol(program, call.target_symbol)?;
            if !program.machine_type_parameters(callee).is_empty() {
                return None;
            }
            let primitive = program.primitive_type_reference(state.return_type)?;
            primitive_range(primitive)?;
            let actuals = cached_actuals
                .get_or_insert_with(|| {
                    exact_ordinary_actual_intervals(walk, call, child_values).unwrap_or_default()
                })
                .as_slice();
            let (interval, recipe) =
                inference.infer(program, callee, state, Some(primitive), actuals)?;
            Some(Analysis {
                recipe,
                domain: None,
                interval,
                primitive: Some(primitive),
            })
        }
    }
    pub(crate) mod cast {
        use super::{Analysis, BOOLEAN_INTERVAL, ExpressionWalk, NEUTRAL};
        use crate::ExactIntegerCastFact;
        use crate::proof_contracts::arithmetic_domains::integer_ranges::{
            integer_bit_width, integer_interval_fits_primitive, literal_interval, primitive_name,
            primitive_range, validate_anonymous_integer_primitive_range,
        };
        use crate::proof_contracts::arithmetic_domains::{
            ArithmeticDomain, Diagnostic, ExpressionNode, Interval, PrimitiveType,
        };
        use crate::value_custody::literals;
        use typed_trees::expression::TableCastExpression;

        pub(crate) fn analyze(
            walk: &ExpressionWalk,
            expression: typed_trees::expression::ExpressionHandle,
            cast: &TableCastExpression,
            diagnostics: &mut Vec<Diagnostic>,
            decisions: &mut super::ArithmeticDecisions,
        ) -> Analysis {
            let first_diagnostic = diagnostics.len();
            let program = walk.program;
            let primitive = program.primitive_type_reference(cast.target_type);
            if cast.form.is_recast() {
                walk.with_destination(None, ArithmeticDomain::Exact)
                    .analyze(cast.value, diagnostics, decisions);
                return Analysis {
                    recipe: None,
                    domain: Some(ArithmeticDomain::Exact),
                    interval: primitive
                        .and_then(primitive_range)
                        .unwrap_or(Interval::UNBOUNDED),
                    primitive,
                };
            }
            if let Some(machine) = walk.machine {
                crate::proof_contracts::arithmetic_domains::validate_anonymous_address_landing(
                    program,
                    machine,
                    walk.state,
                    cast.value,
                    primitive,
                    walk.owner,
                    diagnostics,
                    &mut decisions.integer_range_obligations,
                );
            }
            let source = source_value(walk, cast, primitive, diagnostics, decisions);
            let source_interval = source
                .primitive
                .and_then(primitive_range)
                .map(|carrier| {
                    if carrier.contains(source.interval) {
                        source.interval
                    } else {
                        carrier
                    }
                })
                .unwrap_or(source.interval);

            require_float_to_integer_denotation(walk, cast, &source, primitive, diagnostics);
            let exact_fit =
                require_exact_integer_fit(walk, expression, &source, primitive, diagnostics);
            if !diagnostics[first_diagnostic..]
                .iter()
                .any(Diagnostic::is_error)
                && let (Some(source_type), Some(target_type)) = (source.primitive, primitive)
                && source_type != target_type
                && primitive_range(source_type).is_some()
                && primitive_range(target_type).is_some()
                && exact_fit
                && let Some((minimum, maximum)) =
                    checked_cast_bounds(source_interval, source_type, target_type)
            {
                decisions.exact_integer_casts.push(ExactIntegerCastFact {
                    expression,
                    source_type,
                    target_type,
                    minimum,
                    maximum,
                });
            }
            Analysis {
                domain: Some(cast.domain),
                interval: result_interval(&source, primitive),
                recipe: source
                    .primitive
                    .filter(|source| source.is_fixed_integer())
                    .zip(primitive.filter(|target| target.is_fixed_integer()))
                    .and(source.recipe),
                primitive,
            }
        }

        fn source_value(
            walk: &ExpressionWalk,
            cast: &TableCastExpression,
            primitive: Option<PrimitiveType>,
            diagnostics: &mut Vec<Diagnostic>,
            decisions: &mut super::ArithmeticDecisions,
        ) -> Analysis {
            let program = walk.program;
            if cast.semantic_domain.is_empty()
                && let Some(primitive) = primitive
                && matches!(
                    program.expression_table.expression(cast.value),
                    ExpressionNode::Match(_)
                )
                && literals::has_anonymous_numeric_results(program, cast.value)
            {
                validate_anonymous_integer_primitive_range(
                    program,
                    primitive,
                    cast.value,
                    walk.owner,
                    diagnostics,
                );
            }
            let anonymous =
                literals::anonymous_numeric_value(program, cast.value, &mut |expression| {
                    literals::has_anonymous_operator_meaning(program, expression)
                });
            let integer_target =
                primitive.filter(|primitive| integer_bit_width(*primitive).is_some());
            let (Some(evaluated), Some(primitive)) = (anonymous, integer_target) else {
                return walk
                    .with_destination(None, ArithmeticDomain::Exact)
                    .analyze(cast.value, diagnostics, decisions);
            };
            match evaluated
                .value
                .to_integer_exact()
                .and_then(|value| literals::land_integer_value(&value, primitive))
            {
                Some(literal) => {
                    let interval = literal_interval(&literal);
                    decisions.record_interval(cast.value, interval);
                    Analysis {
                        recipe: None,
                        domain: None,
                        interval,
                        primitive: Some(primitive),
                    }
                }
                None => {
                    diagnostics.push(
                Diagnostic::error(format!(
                    "anonymous value `{}` cannot land exactly in cast target `{}` in {}; type \
                     an operand before division if integer division was intended",
                    evaluated.value,
                    primitive.name(),
                    walk.owner,
                ))
                .with_source_span(program.expression_table.source_span(cast.value)),
            );
                    NEUTRAL
                }
            }
        }

        fn require_float_to_integer_denotation(
            walk: &ExpressionWalk,
            cast: &TableCastExpression,
            source: &Analysis,
            primitive: Option<PrimitiveType>,
            diagnostics: &mut Vec<Diagnostic>,
        ) {
            if !matches!(
                source.primitive,
                Some(PrimitiveType::F32 | PrimitiveType::F64)
            ) {
                return;
            }
            let Some(target) = primitive.filter(|target| integer_bit_width(*target).is_some())
            else {
                return;
            };
            let owner = walk.owner;
            if !super::super::float_source_bounds(
                walk.program,
                walk.lexical_owner,
                walk.environment,
                cast.value,
                &|value| {
                    walk.result_type(value)
                        .or_else(|| walk.declared_type(value))
                },
            )
            .is_some_and(|bounds| bounds.is_exact_integer(target))
            {
                diagnostics.push(Diagnostic::error(format!(
            "Exact float-to-int cast in {owner} is not provably integral and representable in `{}`; \
             prove unchanged denotation or use a named conversion to truncate.",
            primitive_name(target),
        )));
            }
        }

        fn require_exact_integer_fit(
            walk: &ExpressionWalk,
            expression: typed_trees::expression::ExpressionHandle,
            source: &Analysis,
            primitive: Option<PrimitiveType>,
            diagnostics: &mut Vec<Diagnostic>,
        ) -> bool {
            if walk.program.static_type_context_is_unreachable(expression) {
                return false;
            }
            let Some(source_primitive) = source
                .primitive
                .filter(|source| primitive_range(*source).is_some())
            else {
                return false;
            };
            let Some(target) = primitive.filter(|target| primitive_range(*target).is_some()) else {
                return false;
            };
            let fits = integer_interval_fits_primitive(source.interval, source_primitive, target)
        || (walk.checks_occurrence_fit
            && walk
                .machine
                .zip(walk.state)
                .is_some_and(|(machine, state)| {
                    crate::proof_contracts::contract_entailment::exact_cast_fits_at_occurrence(
                        walk.program,
                        machine,
                        state,
                        expression,
                    )
                }));
            if !fits && (walk.checks_occurrence_fit || walk.machine.is_none()) {
                let source_span = walk.program.expression_table.source_span(expression);
                if source_span.span.start < source_span.span.end
                    && diagnostics.iter().any(|existing| {
                        existing.source_span == Some(source_span)
                            && existing.message.starts_with("Exact integer cast in ")
                    })
                {
                    return false;
                }
                diagnostics.push(
            Diagnostic::error(format!(
                "Exact integer cast in machine `{}`{} from `{}` to `{}` is not provably \
                 representable; {}",
                walk.machine.map_or(walk.owner, |machine| machine.name.as_str()),
                walk.state
                    .map(|state| format!(" state `{}`", state.name))
                    .unwrap_or_default(),
                primitive_name(source_primitive),
                primitive_name(target),
                if target == PrimitiveType::Addr {
                    "prove 0 <= embed(source) < addr::Bound at this occurrence; count and address widths are independent."
                } else if source_primitive == PrimitiveType::Addr {
                    "prove the embedded address fits the destination integer range at this occurrence; count and address widths are independent."
                } else {
                    "constrain the source with a range or dominating guard, or use a named Wrapping, Saturating, or Trapping conversion."
                },
            ))
            .with_source_span(source_span),
        );
            }
            fits
        }

        fn checked_cast_bounds(
            interval: Interval,
            source: PrimitiveType,
            target: PrimitiveType,
        ) -> Option<(numerics::bignum::BigInt, numerics::bignum::BigInt)> {
            use numerics::bignum::BigInt;
            let source_bounds = (source != PrimitiveType::Addr)
                .then(|| source.integer_bounds())
                .flatten();
            let target_bounds = (target != PrimitiveType::Addr)
                .then(|| target.integer_bounds())
                .flatten();
            let minimum = interval
                .low
                .map(i128::from)
                .or_else(|| source_bounds.map(|bounds| bounds.0))?
                .max(target_bounds.map_or(0, |bounds| bounds.0));
            let maximum = interval
                .high
                .map(i128::from)
                .or_else(|| source_bounds.map(|bounds| bounds.1))
                .or_else(|| target_bounds.map(|bounds| bounds.1))?;
            let maximum = target_bounds.map_or(maximum, |bounds| maximum.min(bounds.1));
            (minimum <= maximum).then(|| (BigInt::from_i128(minimum), BigInt::from_i128(maximum)))
        }

        fn result_interval(source: &Analysis, primitive: Option<PrimitiveType>) -> Interval {
            let target_is_integer =
                primitive.is_some_and(|target| integer_bit_width(target).is_some());
            if source.primitive == Some(PrimitiveType::Bool) && target_is_integer {
                return BOOLEAN_INTERVAL;
            }
            if let Some(source_primitive) = source.primitive
                && integer_bit_width(source_primitive).is_some()
                && target_is_integer
                && let Some(source_range) = primitive_range(source_primitive)
            {
                return if source_range.contains(source.interval) {
                    source.interval
                } else {
                    source_range
                };
            }
            primitive
                .and_then(primitive_range)
                .unwrap_or(Interval::UNBOUNDED)
        }
    }
    pub(crate) mod dispatch {
        use super::{Analysis, ExpressionWalk, NEUTRAL};
        use crate::frozen_program::expression_table;
        use crate::proof_contracts::arithmetic_domains::{
            ArithmeticDomain, Diagnostic, ExpressionHandle, Interval, dispatch_arm_environments,
        };
        use typed_trees::expression::{MatchPattern, TableMatchExpression};

        pub(crate) fn analyze(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
            dispatch: &TableMatchExpression,
            diagnostics: &mut Vec<Diagnostic>,
            decisions: &mut super::ArithmeticDecisions,
        ) -> Analysis {
            let program = walk.program;
            let operand_walk = walk.with_destination(None, ArithmeticDomain::Exact);
            operand_walk.analyze(dispatch.subject, diagnostics, decisions);
            let result_type = walk.result_type(expression);
            let primitive =
                result_type.and_then(|reference| program.primitive_type_reference(reference));
            let domain = result_type
                .map(|reference| program.arithmetic_domain_for_type_reference(reference));
            let result_walk = walk.with_destination(
                primitive.or(walk.target_primitive),
                domain.unwrap_or(walk.target_domain),
            );
            let mut interval: Option<Interval> = None;
            let mut recipe: Option<checked_trees::IntegerRangeRecipe> = None;

            let environments = walk.machine.map_or_else(
                || {
                    vec![
                        walk.environment.clone();
                        program.expression_table.match_arms(dispatch.arms).len()
                    ]
                },
                |machine| {
                    dispatch_arm_environments(
                        program,
                        machine,
                        walk.state,
                        expression,
                        dispatch,
                        walk.environment,
                    )
                },
            );
            for (arm, selected) in expression_table(program)
                .match_arms(dispatch.arms)
                .iter()
                .zip(&environments)
            {
                if let MatchPattern::Value(pattern) = arm.pattern {
                    operand_walk.analyze(pattern, diagnostics, decisions);
                }
                let arm_walk = ExpressionWalk {
                    environment: selected,
                    ..result_walk
                };
                let arm_value = arm_walk.analyze(arm.value, diagnostics, decisions);
                let arm_recipe = arm_value.range_recipe(program, walk.lexical_owner, arm.value);
                recipe = if interval.is_none() {
                    arm_recipe
                } else {
                    recipe
                        .zip(arm_recipe)
                        .map(|(left, right)| left.union(&right))
                };
                interval = Some(interval.map_or(arm_value.interval, |previous| {
                    previous.union(arm_value.interval)
                }));
            }
            Analysis {
                recipe: recipe.filter(checked_trees::IntegerRangeRecipe::is_target_dependent),
                domain,
                primitive,
                interval: interval.unwrap_or(NEUTRAL.interval),
            }
        }
    }
    pub(crate) mod folded_values {
        use super::{Analysis, ExpressionWalk, NEUTRAL};
        use crate::proof_contracts::arithmetic_domains::integer_ranges::{
            integer_bit_width, literal_interval,
        };
        use crate::proof_contracts::arithmetic_domains::{
            ArithmeticDomain, Diagnostic, ExpressionHandle, Interval, PrimitiveType,
            TypeReferenceNode,
        };
        use crate::value_custody::literals;

        pub(crate) fn analyze(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
            diagnostics: &mut Vec<Diagnostic>,
        ) -> Option<Analysis> {
            if let Some(value) =
                literals::closed_record_integer_projection(walk.program, expression)
                && let Some(primitive) = value.primitive
                && let Some(literal) = literals::land_integer_value(&value.value, primitive)
            {
                return Some(Analysis {
                    recipe: None,
                    domain: Some(ArithmeticDomain::Exact),
                    interval: literal_interval(&literal),
                    primitive: Some(primitive),
                });
            }
            if let Some(interval) = collection_length_interval(walk, expression) {
                let interval = super::super::place_path(walk.program, expression)
                    .and_then(|path| walk.environment.get(&path))
                    .map_or(interval, |retained| interval.intersect(retained));
                let interval = walk.machine.map_or(interval, |machine| {
                    super::super::ordered_values::refine_place_interval(
                        walk.program,
                        machine,
                        walk.state,
                        walk.environment,
                        expression,
                        interval,
                    )
                });
                return Some(Analysis {
                    recipe: None,
                    interval,
                    primitive: Some(PrimitiveType::U64),
                    ..NEUTRAL
                });
            }
            anonymous_value(walk, expression, diagnostics)
        }

        fn collection_length_interval(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
        ) -> Option<Interval> {
            let program = walk.program;
            let mut receiver = if let Some(machine) = walk.machine {
                let receiver =
                    crate::collection_length_receiver(program, machine, walk.state, expression)?;
                if let Some(state) = walk.state
                    && let Some(length) =
                        crate::closed_collection_length(program, machine, state, receiver)
                {
                    let length = i64::try_from(length).ok();
                    return Some(Interval {
                        low: Some(length.unwrap_or(0)),
                        high: length,
                    });
                }
                walk.declared_type(receiver)?
            } else {
                let member = program.expression_table.member_node(expression)?;
                let receiver = walk.result_type(member.receiver)?;
                if crate::collection_operations::collection_measure_member(
                    program,
                    member,
                    crate::collection_operations::MeasureReceiver::Declared(receiver),
                ) != Some(language_semantics::declaration_selection::CollectionMeasure::Length)
                {
                    return None;
                }
                receiver
            };
            loop {
                if let Some(capacity) = crate::bounded_byte_buffer_capacity(program, receiver) {
                    return Some(Interval {
                        low: Some(0),
                        high: i64::try_from(capacity).ok(),
                    });
                }
                match program.type_reference_table.type_reference(receiver) {
                    TypeReferenceNode::Reference { referee, .. } => receiver = *referee,
                    TypeReferenceNode::Constrained { base_type, .. } => receiver = *base_type,
                    TypeReferenceNode::FixedArray {
                        length: typed_trees::types::FixedArrayLength::Literal(length),
                        ..
                    } => {
                        let length = i64::try_from(*length).ok();
                        return Some(Interval {
                            low: Some(length.unwrap_or(0)),
                            high: length,
                        });
                    }
                    TypeReferenceNode::Slice { .. } | TypeReferenceNode::FixedArray { .. } => {
                        return Some(Interval {
                            low: Some(0),
                            high: None,
                        });
                    }
                    _ => return None,
                }
            }
        }

        fn anonymous_value(
            walk: &ExpressionWalk,
            expression: ExpressionHandle,
            diagnostics: &mut Vec<Diagnostic>,
        ) -> Option<Analysis> {
            let program = walk.program;
            let evaluated =
                literals::anonymous_numeric_value(program, expression, &mut |expression| {
                    literals::has_anonymous_operator_meaning(program, expression)
                })?;
            let Some(value) = evaluated.value.to_integer_exact() else {
                if walk
                    .target_primitive
                    .is_some_and(|primitive| integer_bit_width(primitive).is_some())
                {
                    diagnostics.push(
                Diagnostic::error(format!(
                    "anonymous operand `{}` is not an integer in {}; type an operand before \
                     division if integer division was intended",
                    evaluated.value, walk.owner,
                ))
                .with_source_span(program.expression_table.source_span(expression)),
            );
                }
                return Some(NEUTRAL);
            };
            let interval = value
                .to_i64()
                .map_or(Interval::UNBOUNDED, |value| Interval {
                    low: Some(value),
                    high: Some(value),
                });
            Some(Analysis {
                recipe: None,
                domain: None,
                interval,
                primitive: None,
            })
        }
    }
    pub(crate) mod place {
        use super::{Analysis, ExpressionWalk, NEUTRAL};
        use crate::proof_contracts::arithmetic_domains::integer_ranges::{
            is_atomic_type, literal_interval, primitive_range,
        };
        use crate::proof_contracts::arithmetic_domains::{
            ArithmeticDomain, ExpressionHandle, Interval, place_path, range_constraint_interval,
        };
        use crate::value_custody::{constants, literals, places};

        pub(crate) fn analyze(walk: &ExpressionWalk, expression: ExpressionHandle) -> Analysis {
            let program = walk.program;
            let element_path = walk.machine.and_then(|machine| {
                super::super::stable_element_place_path(program, machine, walk.state, expression)
            });
            let element_fact = element_path
                .as_deref()
                .and_then(|path| walk.environment.get(path));
            let Some(handle) = walk.declared_type(expression) else {
                return NEUTRAL;
            };
            let primitive = places::unwrapped_type_reference(program, handle)
                .and_then(|referent| program.primitive_type_reference(referent));
            let type_range = primitive
                .and_then(primitive_range)
                .unwrap_or(Interval::UNBOUNDED);
            let interval = place_path(program, expression)
                .and_then(|path| walk.environment.get(&path))
                .or(element_fact)
                .or_else(|| range_constraint_interval(program, handle))
                .map(|proven| proven.intersect(type_range))
                .unwrap_or(type_range);
            let interval = constants::completed_integer_constant(program, expression)
                .filter(|value| value.primitive == primitive)
                .and_then(|value| {
                    Some(literal_interval(&literals::land_integer_value(
                        &value.value,
                        primitive?,
                    )?))
                })
                .map_or(interval, |closed| interval.intersect(closed));
            let interval = walk
                .state
                .and_then(|state| {
                    walk.environment
                        .captured_integer_interval(state.symbol, expression)
                })
                .map_or(interval, |captured| interval.intersect(captured));
            let interval = walk
                .machine
                .zip(walk.state)
                .and_then(|(machine, state)| {
                    crate::proof_contracts::arithmetic_domains::standing_integer_interval(
                        program, machine, state, expression,
                    )
                })
                .map_or(interval, |standing| interval.intersect(standing));
            let interval = walk.machine.map_or(interval, |machine| {
                super::super::ordered_values::refine_place_interval(
                    program,
                    machine,
                    walk.state,
                    walk.environment,
                    expression,
                    interval,
                )
            });
            if crate::trace_flags::reference_slot_trace()
                && crate::reference_shell(program, handle).is_some()
            {
                eprintln!(
                    "SLOT integer-read machine={:?} expression={expression:?} path={:?} interval={interval:?} direct={:?} captured={:?}",
                    walk.machine.map(|machine| machine.name.as_str()),
                    place_path(program, expression),
                    place_path(program, expression).and_then(|path| walk.environment.get(&path)),
                    walk.state.and_then(|state| walk
                        .environment
                        .captured_integer_interval(state.symbol, expression))
                );
            }
            let domain = if is_atomic_type(program, handle) {
                ArithmeticDomain::Wrapping
            } else {
                program.arithmetic_domain_for_type_reference(handle)
            };
            let recipe = walk
                .environment
                .range_recipe(program, expression)
                .cloned()
                .or_else(|| {
                    super::super::deferred_integer_observation(
                        program,
                        walk.lexical_owner,
                        expression,
                        primitive,
                    )
                });
            Analysis {
                recipe,
                domain: Some(domain),
                interval,
                primitive,
            }
        }
    }
    pub(crate) mod scope {
        use super::ExpressionWalk;
        use crate::proof_contracts::arithmetic_domains::{
            ArithmeticDomain, Diagnostic, ExpressionHandle, Interval, PrimitiveType,
        };
        use typed_trees::types::TypeReferenceHandle;

        impl ExpressionWalk<'_> {
            pub(crate) fn result_type(
                &self,
                expression: ExpressionHandle,
            ) -> Option<TypeReferenceHandle> {
                if let Some((machine, state)) = self.machine.zip(self.state) {
                    return crate::expression_result_type_reference(
                        self.program,
                        machine,
                        state,
                        expression,
                    );
                }
                let parameters = self
                    .machine
                    .and_then(|machine| self.program.machine_states(machine).first())
                    .map_or(self.parameters, |entry| {
                        self.program.state_parameters(entry)
                    });
                crate::parameter_expression_result_type_reference(
                    self.program,
                    self.lexical_owner,
                    parameters,
                    expression,
                )
            }

            pub(crate) fn declared_type(
                &self,
                expression: ExpressionHandle,
            ) -> Option<TypeReferenceHandle> {
                if let Some(machine) = self.machine {
                    return crate::declared_place_type_raw(
                        self.program,
                        machine,
                        self.state,
                        expression,
                    );
                }
                self.result_type(expression)
            }

            pub(crate) fn builtin_binary(&self, expression: ExpressionHandle) -> bool {
                if let Some(machine) = self.machine {
                    return crate::proof_contracts::bound_expression_meaning::has_builtin_binary_expression_meaning(
                self.program, machine, self.state, expression,
            );
                }
                let Some(binary) = self.program.expression_table.binary_node(expression) else {
                    return false;
                };
                let Some(spelling) =
                    typed_trees::operator::binary_operator_spelling(binary.operator)
                else {
                    return false;
                };
                typed_trees::operator::has_builtin_spelled_expression_meaning(
                    self.program,
                    self.lexical_owner,
                    expression,
                    spelling,
                    &[
                        self.result_type(binary.left),
                        self.result_type(binary.right),
                    ],
                )
            }

            pub(crate) fn indexed_builtin(
                &self,
                expression: ExpressionHandle,
                collection: ExpressionHandle,
            ) -> bool {
                if let Some(machine) = self.machine {
                    return crate::value_custody::places::indexed_operation_has_builtin_meaning(
                        self.program,
                        machine,
                        self.state,
                        expression,
                        self.result_type(collection),
                    );
                }
                let Some(indexed) = self.program.expression_table.indexed_node(expression) else {
                    return false;
                };
                typed_trees::operator::has_builtin_spelled_expression_meaning(
                    self.program,
                    self.lexical_owner,
                    expression,
                    language_core::OperatorSpelling::Index,
                    &[
                        self.result_type(collection),
                        self.result_type(indexed.index),
                    ],
                )
            }

            pub(crate) fn division_formation(
                &self,
                expression: ExpressionHandle,
                binary: &typed_trees::expression::TableBinaryExpression,
                domain: ArithmeticDomain,
                primitive: PrimitiveType,
                left: Interval,
                right: Interval,
                diagnostics: &mut Vec<Diagnostic>,
            ) -> bool {
                if let Some(machine) = self.machine {
                    return super::super::division_definedness::validate_operands(
                        self.program,
                        machine,
                        self.state,
                        self.environment,
                        expression,
                        binary,
                        domain,
                        primitive,
                        left,
                        right,
                        self.owner,
                        diagnostics,
                    );
                }
                super::super::division_definedness::validate_interval_operands(
                    binary.operator,
                    domain,
                    primitive,
                    left,
                    right,
                    self.owner,
                    diagnostics,
                )
            }
        }
    }
    pub(crate) mod trap_coverage {
        use super::ExpressionWalk;
        use crate::frozen_program::expression_table;
        use crate::proof_contracts::arithmetic_domains::guard_narrowing::narrow_environment_by_condition;
        use crate::proof_contracts::arithmetic_domains::{
            Diagnostic, ExpressionHandle, ExpressionNode, Machine, ProofFact,
            SignatureContractKind, State, ValueEnvironment,
        };
        use typed_trees::signature::CrashCause;

        pub(crate) enum TrapCeiling {
            Permitted,
            Guarded(Vec<ExpressionHandle>),
        }

        pub(crate) fn trap_ceiling(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
        ) -> TrapCeiling {
            if !program.machine_publishes_crash_ceiling(machine) {
                return TrapCeiling::Permitted;
            }
            let mut routes = Vec::new();
            for contract in program.machine_contracts(machine) {
                if !matches!(
                    contract.kind,
                    SignatureContractKind::Crashes {
                        cause: CrashCause::Trap
                    }
                ) {
                    continue;
                }
                let facts = program.proof_facts.span_or_empty(contract.facts);
                if facts.is_empty()
            || facts.iter().any(|fact| {
                matches!(fact, ProofFact::Expression(route)
                    if matches!(expression_table(program).expression(*route), ExpressionNode::Boolean(true)))
            })
        {
            return TrapCeiling::Permitted;
        }
                routes.extend(facts.iter().filter_map(|fact| match fact {
                    ProofFact::Expression(route) => Some(*route),
                    ProofFact::Membership(_) | ProofFact::Proposition(_) => None,
                }));
            }
            TrapCeiling::Guarded(routes)
        }

        fn reads_only_stable_entry_parameters(
            program: &dyn crate::CheckingInput,
            entry: &State,
            route: ExpressionHandle,
        ) -> bool {
            let mut pending = vec![route];
            while let Some(expression) = pending.pop() {
                match expression_table(program).expression(expression) {
                    ExpressionNode::Integer(_) | ExpressionNode::Boolean(_) => {}
                    ExpressionNode::Unary(unary) => pending.push(unary.operand),
                    ExpressionNode::Binary(binary) => pending.extend([binary.left, binary.right]),
                    ExpressionNode::Name(path)
                        if expression_table(program)
                            .name_path_members(path.members)
                            .len()
                            == 1 =>
                    {
                        let stable = program.state_parameters(entry).iter().any(|parameter| {
                            parameter.symbol == path.symbol
                                && !parameter.is_mutable
                                && program
                                    .primitive_type_reference(parameter.type_reference)
                                    .is_some()
                        });
                        if !stable {
                            return false;
                        }
                    }
                    _ => return false,
                }
            }
            true
        }

        impl ExpressionWalk<'_> {
            pub(crate) fn require_trap_coverage(
                &self,
                expression: ExpressionHandle,
                forms_on_this_path: impl FnOnce() -> bool,
                forms_under: impl FnOnce(&ExpressionWalk) -> bool,
                site: impl FnOnce() -> String,
                diagnostics: &mut Vec<Diagnostic>,
            ) {
                if !self.checks_trap_coverage {
                    return;
                }
                let Some(machine) = self.machine else {
                    if !forms_on_this_path() {
                        diagnostics.push(Diagnostic::error(format!("uncovered Trap crash in {}: {} has no executable crash route in this declaration", self.owner, site())));
                    }
                    return;
                };
                let TrapCeiling::Guarded(routes) = trap_ceiling(self.program, machine) else {
                    return;
                };
                if forms_on_this_path() {
                    return;
                }
                if let Some(complement) = self.route_complement_environment(&routes) {
                    let covering = ExpressionWalk {
                        environment: &complement,
                        checks_trap_coverage: false,
                        ..*self
                    };
                    if forms_under(&covering) {
                        return;
                    }
                }
                let coverage = if routes.is_empty() {
                    format!(
                        "the published crash ceiling of machine `{}` names no `crashes Trap` route",
                        machine.name,
                    )
                } else {
                    "no published `crashes Trap` route covers that condition over these operands"
                        .to_owned()
                };
                diagnostics.push(
                    Diagnostic::error(format!(
                        "uncovered Trap crash in {}: {}, and {coverage}; publish a same-cause \
                 `crashes Trap` route whose guard covers this site, or prove the operation \
                 cannot trap here",
                        self.owner,
                        site(),
                    ))
                    .with_source_span(expression_table(self.program).source_span(expression)),
                );
            }

            pub(crate) fn operand_label(&self, operand: ExpressionHandle) -> String {
                expression_table(self.program)
                    .display_name(operand)
                    .trim_end()
                    .to_owned()
            }

            fn route_complement_environment(
                &self,
                routes: &[ExpressionHandle],
            ) -> Option<ValueEnvironment> {
                let state = self.state?;
                let machine = self.machine?;
                let entry = self.program.machine_states(machine).first()?;
                if entry.symbol != state.symbol {
                    return None;
                }
                let mut complement = self.environment.clone();
                let mut narrowed = false;
                for &route in routes {
                    if !reads_only_stable_entry_parameters(self.program, entry, route) {
                        continue;
                    }
                    narrow_environment_by_condition(
                        self.program,
                        machine,
                        Some(entry),
                        &mut complement,
                        route,
                        false,
                    );
                    narrowed = true;
                }
                narrowed.then_some(complement)
            }
        }
    }
    pub(crate) mod trapping_receipts {
        use super::trap_coverage::{TrapCeiling, trap_ceiling};
        use symbols::{SymbolHandle, SymbolKeyMap};
        use typed_trees::machine::Machine;

        pub(crate) struct TrappingReceiptDemand {
            required: SymbolKeyMap<SymbolHandle, ()>,
        }

        impl TrappingReceiptDemand {
            fn build(program: &dyn crate::CheckingInput) -> Self {
                let invocations = crate::proof_contracts::contract_entailment::structural_prefix::private_invocation_index(program);
                let mut required = SymbolKeyMap::default();
                let mut pending = Vec::new();
                for machine in program.machines() {
                    let precise = match trap_ceiling(program, machine) {
                        TrapCeiling::Guarded(_) => true,
                        TrapCeiling::Permitted => {
                            !program.machine_publishes_crash_ceiling(machine)
                                && !invocations.has_closed_private_uses(program, machine)
                        }
                    };
                    if precise {
                        required.insert(machine.symbol, ());
                        pending.push(machine.symbol);
                    }
                }
                while let Some(caller) = pending.pop() {
                    for &callee in invocations.private_callees(caller) {
                        let Some(machine) = program.machine_by_symbol(callee) else {
                            continue;
                        };
                        if !program.machine_publishes_crash_ceiling(machine)
                            && required.insert(callee, ()).is_none()
                        {
                            pending.push(callee);
                        }
                    }
                }
                Self { required }
            }
        }

        pub(crate) fn required(program: &dyn crate::CheckingInput, machine: &Machine) -> bool {
            let demand = crate::frozen_program::frozen_memo(
                program,
                |memos| &memos.trapping_receipt_demand,
                || TrappingReceiptDemand::build(program),
            );
            demand.required.contains_key(&machine.symbol)
        }
    }
    pub(crate) use trapping_receipts::TrappingReceiptDemand;
    pub(crate) mod unary {
        use super::unsigned_constants::bitwise_known_unsigned;
        use super::{Analysis, BOOLEAN_INTERVAL, ExpressionWalk};
        use crate::proof_contracts::arithmetic_domains::{
            Diagnostic, Interval, PrimitiveType, bitwise,
        };
        use typed_trees::expression::{TableUnaryExpression, UnaryOperator};

        pub(crate) fn analyze(
            walk: &ExpressionWalk,
            unary: &TableUnaryExpression,
            diagnostics: &mut Vec<Diagnostic>,
            decisions: &mut super::ArithmeticDecisions,
        ) -> Analysis {
            let operand = walk.analyze(unary.operand, diagnostics, decisions);
            match unary.operator {
                UnaryOperator::BitwiseNot => {
                    let primitive = operand.primitive.or_else(|| {
                        (operand.interval.low.is_some() && operand.interval.high.is_some())
                            .then_some(walk.target_primitive)
                            .flatten()
                    });
                    Analysis {
                        recipe: None,
                        domain: operand.domain,
                        interval: primitive
                            .map(|primitive| {
                                bitwise::complement(
                                    primitive,
                                    operand.interval,
                                    bitwise_known_unsigned(
                                        walk.program,
                                        walk.environment,
                                        primitive,
                                        unary.operand,
                                        0,
                                    ),
                                )
                            })
                            .unwrap_or(Interval::UNBOUNDED),
                        primitive,
                    }
                }
                UnaryOperator::LogicalNot => Analysis {
                    recipe: None,
                    domain: None,
                    interval: BOOLEAN_INTERVAL,
                    primitive: Some(PrimitiveType::Bool),
                },
            }
        }
    }
    pub(crate) mod unsigned_constants {
        use crate::proof_contracts::arithmetic_domains::integer_ranges::known_u64_value;
        use crate::proof_contracts::arithmetic_domains::{
            ExpressionHandle, ExpressionNode, PrimitiveType, ValueEnvironment, bitwise,
        };

        pub(crate) fn integer_literal_primitive(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
        ) -> Option<PrimitiveType> {
            let literal = program.expression_table.integer_node(expression)?;
            PrimitiveType::non_address_landed_integer(literal.landing()?.landed_type)
        }

        pub(crate) fn bitwise_known_unsigned(
            program: &dyn crate::CheckingInput,
            environment: &ValueEnvironment,
            primitive: PrimitiveType,
            expression: ExpressionHandle,
            depth: usize,
        ) -> Option<u64> {
            if depth >= 64
                || integer_literal_primitive(program, expression)
                    .is_some_and(|literal| literal != primitive)
            {
                return None;
            }
            if let Some(value) = known_u64_value(program, environment, expression) {
                return Some(value);
            }
            match program.expression_table.expression(expression) {
                ExpressionNode::Unary(unary)
                    if unary.operator == typed_trees::expression::UnaryOperator::BitwiseNot =>
                {
                    bitwise::complement_unsigned_value(
                        primitive,
                        bitwise_known_unsigned(
                            program,
                            environment,
                            primitive,
                            unary.operand,
                            depth + 1,
                        )?,
                    )
                }
                ExpressionNode::Binary(binary)
                    if matches!(
                        binary.operator,
                        typed_trees::expression::BinaryOperator::BitwiseAnd
                            | typed_trees::expression::BinaryOperator::BitwiseOr
                            | typed_trees::expression::BinaryOperator::BitwiseXor
                    ) =>
                {
                    bitwise::binary_unsigned_value(
                        binary.operator,
                        primitive,
                        bitwise_known_unsigned(
                            program,
                            environment,
                            primitive,
                            binary.left,
                            depth + 1,
                        )?,
                        bitwise_known_unsigned(
                            program,
                            environment,
                            primitive,
                            binary.right,
                            depth + 1,
                        )?,
                    )
                }
                _ => None,
            }
        }
    }

    use super::{
        ArithmeticDomain, Diagnostic, ExpressionHandle, ExpressionNode, Interval, Machine,
        PrimitiveType, State, ValueEnvironment, integer_ranges::literal_interval,
    };
    use checked_trees::IntegerRangeRecipe;

    pub(crate) struct Analysis {
        pub(crate) recipe: Option<IntegerRangeRecipe>,
        pub(crate) domain: Option<ArithmeticDomain>,
        pub(crate) interval: Interval,
        pub(crate) primitive: Option<PrimitiveType>,
    }

    impl Analysis {
        pub(crate) fn range_recipe(
            &self,
            program: &dyn crate::CheckingInput,
            owner: symbols::SymbolHandle,
            expression: ExpressionHandle,
        ) -> Option<IntegerRangeRecipe> {
            use numerics::bignum::BigInt;
            if let Some(recipe) = &self.recipe {
                return Some(recipe.clone());
            }
            if let Some(value) = program.closed_integer_expression_value_in(expression, owner) {
                return Some(IntegerRangeRecipe::bounds(value.clone(), value));
            }
            let low = self.interval.low.map(BigInt::from_i64)?;
            let high = match self.interval.high {
                Some(high) => BigInt::from_i64(high),
                None if self.primitive == Some(PrimitiveType::U64) => BigInt::from_u64(u64::MAX),
                None => return None,
            };
            Some(IntegerRangeRecipe::bounds(low, high))
        }
    }

    pub(crate) struct CheckedAnalysis {
        pub(crate) value: Analysis,
        pub(crate) decisions: ArithmeticDecisions,
    }

    #[derive(Debug, Default)]
    pub(crate) struct ArithmeticDecisions {
        pub(crate) allows_pending_formations: bool,
        pub(crate) pending_formations: Vec<super::storage_formations::PendingIntegerFormation>,
        pub(crate) integer_range_obligations: Vec<checked_trees::IntegerRangeObligation>,
        pub(crate) exact_integer_casts: Vec<crate::ExactIntegerCastFact>,
        pub(crate) integer_assignments: Vec<checked_trees::CheckedIntegerAssignmentDecision>,
        pub(crate) decided_formations: Vec<ExpressionHandle>,
        pub(crate) trapping_decisions: Vec<(ExpressionHandle, bool)>,
        pub(crate) expression_values: Vec<CheckedIntegerValue>,
    }

    impl ArithmeticDecisions {
        pub(crate) fn extend(&mut self, other: Self) {
            self.pending_formations.extend(other.pending_formations);
            self.integer_range_obligations
                .extend(other.integer_range_obligations);
            self.exact_integer_casts.extend(other.exact_integer_casts);
            self.integer_assignments.extend(other.integer_assignments);
            self.decided_formations.extend(other.decided_formations);
            self.trapping_decisions.extend(other.trapping_decisions);
            self.expression_values.extend(other.expression_values);
        }
    }

    #[derive(Debug, Clone)]
    pub(crate) struct CheckedIntegerValue {
        pub(crate) expression: ExpressionHandle,
        pub(crate) interval: Interval,
        pub(crate) recipe: Option<IntegerRangeRecipe>,
    }

    impl ArithmeticDecisions {
        pub(crate) fn record_interval(&mut self, expression: ExpressionHandle, interval: Interval) {
            self.expression_values.push(CheckedIntegerValue {
                expression,
                interval,
                recipe: None,
            });
        }
    }

    const NEUTRAL: Analysis = Analysis {
        recipe: None,
        domain: None,
        interval: Interval::UNBOUNDED,
        primitive: None,
    };

    const BOOLEAN_INTERVAL: Interval = Interval {
        low: Some(0),
        high: Some(1),
    };

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn analyze(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        target_primitive: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        owner: &str,
        infer_call_bodies: bool,
        retain_trap_receipts: bool,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> CheckedAnalysis {
        let mut decisions = ArithmeticDecisions {
            allows_pending_formations: retain_trap_receipts,
            ..ArithmeticDecisions::default()
        };
        let return_ranges = super::ReturnInference::default();
        let value = ExpressionWalk {
            program,
            machine: Some(machine),
            lexical_owner: machine.symbol,
            parameters: &[],
            declaration_facts: &[],
            specification_facts: None,
            state,
            environment,
            target_primitive,
            target_domain,
            owner,
            return_ranges: infer_call_bodies.then_some(&return_ranges),
            checks_trap_coverage: true,
            checks_occurrence_fit: true,
            retain_trap_receipts,
        }
        .analyze(expression, diagnostics, &mut decisions);
        CheckedAnalysis { value, decisions }
    }

    pub(crate) fn analyze_specification(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        prior_facts: &[ExpressionHandle],
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> CheckedAnalysis {
        let mut decisions = ArithmeticDecisions::default();
        let return_ranges = super::ReturnInference::default();
        let value = ExpressionWalk {
            program,
            machine: Some(machine),
            lexical_owner: machine.symbol,
            parameters: &[],
            declaration_facts: &[],
            specification_facts: Some(prior_facts),
            state,
            environment,
            target_primitive: None,
            target_domain: ArithmeticDomain::Exact,
            owner,
            return_ranges: Some(&return_ranges),
            checks_trap_coverage: true,
            checks_occurrence_fit: true,
            retain_trap_receipts: false,
        }
        .analyze(expression, diagnostics, &mut decisions);
        CheckedAnalysis { value, decisions }
    }

    pub(crate) fn analyze_declaration(
        program: &dyn crate::CheckingInput,
        lexical_owner: symbols::SymbolHandle,
        parameters: &[typed_trees::signature::StateParameter],
        prior_facts: &[ExpressionHandle],
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        target_primitive: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> CheckedAnalysis {
        let mut decisions = ArithmeticDecisions::default();
        let value = ExpressionWalk {
            program,
            machine: None,
            lexical_owner,
            parameters,
            declaration_facts: prior_facts,
            specification_facts: None,
            state: None,
            environment,
            target_primitive,
            target_domain,
            owner,
            return_ranges: None,
            checks_trap_coverage: true,
            checks_occurrence_fit: false,
            retain_trap_receipts: false,
        }
        .analyze(expression, diagnostics, &mut decisions);
        CheckedAnalysis { value, decisions }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn analyze_arrival(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        target_primitive: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        owner: &str,
        return_ranges: Option<&super::ReturnInference<'_>>,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> CheckedAnalysis {
        let mut decisions = ArithmeticDecisions::default();
        let value = ExpressionWalk {
            program,
            machine: Some(machine),
            lexical_owner: machine.symbol,
            parameters: &[],
            declaration_facts: &[],
            specification_facts: None,
            state,
            environment,
            target_primitive,
            target_domain,
            owner,
            return_ranges,
            checks_trap_coverage: false,
            checks_occurrence_fit: false,
            retain_trap_receipts: false,
        }
        .analyze(expression, diagnostics, &mut decisions);
        CheckedAnalysis { value, decisions }
    }

    pub(crate) fn analyze_meaning(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        owner: &str,
    ) -> CheckedAnalysis {
        let mut decisions = ArithmeticDecisions::default();
        let value = ExpressionWalk {
            program,
            machine: Some(machine),
            lexical_owner: machine.symbol,
            parameters: &[],
            declaration_facts: &[],
            specification_facts: None,
            state,
            environment: &ValueEnvironment::new(),
            target_primitive: None,
            target_domain: ArithmeticDomain::Exact,
            owner,
            return_ranges: None,
            checks_trap_coverage: false,
            checks_occurrence_fit: false,
            retain_trap_receipts: false,
        }
        .analyze(expression, &mut Vec::new(), &mut decisions);
        CheckedAnalysis { value, decisions }
    }

    #[derive(Clone, Copy)]
    pub(crate) struct ExpressionWalk<'a> {
        checks_occurrence_fit: bool,
        retain_trap_receipts: bool,
        program: &'a dyn crate::CheckingInput,
        machine: Option<&'a Machine>,
        lexical_owner: symbols::SymbolHandle,
        parameters: &'a [typed_trees::signature::StateParameter],
        declaration_facts: &'a [ExpressionHandle],
        specification_facts: Option<&'a [ExpressionHandle]>,
        state: Option<&'a State>,
        environment: &'a ValueEnvironment,
        target_primitive: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        owner: &'a str,
        return_ranges: Option<&'a super::ReturnInference<'a>>,
        checks_trap_coverage: bool,
    }

    impl ExpressionWalk<'_> {
        fn with_destination(
            &self,
            target_primitive: Option<PrimitiveType>,
            target_domain: ArithmeticDomain,
        ) -> Self {
            Self {
                target_primitive,
                target_domain,
                ..*self
            }
        }

        fn analyze(
            &self,
            expression: ExpressionHandle,
            diagnostics: &mut Vec<Diagnostic>,
            decisions: &mut ArithmeticDecisions,
        ) -> Analysis {
            let node = self.program.expression_table.expression(expression);
            let before_children_diagnostics = diagnostics.len();
            let before_children_values = decisions.expression_values.len();
            if !matches!(
                node,
                ExpressionNode::Binary(_)
                    | ExpressionNode::Unary(_)
                    | ExpressionNode::Cast(_)
                    | ExpressionNode::Match(_)
            ) {
                let child_walk = self.with_destination(None, ArithmeticDomain::Exact);
                let mut analyze_child = |child: ExpressionHandle| {
                    if child.is_valid() {
                        child_walk.analyze(child, diagnostics, decisions);
                    }
                };
                if matches!(node, ExpressionNode::Atomic(_)) {
                    if let Some(operands) =
                        crate::value_custody::atomic_operations::atomic_value_operands(
                            self.program,
                            expression,
                        )
                    {
                        for operand in operands {
                            analyze_child(operand);
                        }
                    } else {
                        diagnostics.push(Diagnostic::error(format!(
                        "invalid atomic operation carrier in {}: cannot identify its evaluated operands",
                        self.owner,
                    )));
                    }
                } else {
                    crate::queries::expression_traversal::children(
                        self.program,
                        node,
                        analyze_child,
                    );
                }
            }
            if let ExpressionNode::Indexed(indexed) = node
                && self.indexed_builtin(expression, indexed.collection)
            {
                let endpoints = match self.program.expression_table.expression(indexed.index) {
                    ExpressionNode::Range(range) => [range.start, range.end],
                    _ => [indexed.index, ExpressionHandle::invalid()],
                };
                for endpoint in endpoints.into_iter().filter(|endpoint| endpoint.is_valid()) {
                    super::integer_ranges::validate_anonymous_integer_primitive_range(
                        self.program,
                        PrimitiveType::U64,
                        endpoint,
                        self.owner,
                        diagnostics,
                    );
                }
            }
            let analysis = self.analyze_value(
                expression,
                node,
                diagnostics,
                decisions,
                before_children_diagnostics,
                before_children_values,
            );
            decisions.expression_values.push(CheckedIntegerValue {
                expression,
                interval: analysis.interval,
                recipe: analysis.recipe.clone(),
            });
            analysis
        }

        fn atomic_load(&self, expression: ExpressionHandle) -> Analysis {
            let Some(carrier) = crate::atomic_load_carrier(self.program, expression) else {
                return NEUTRAL;
            };
            let Some(machine) = self.machine else {
                return NEUTRAL;
            };
            let Some(reference) =
                crate::declared_place_type_raw(self.program, machine, self.state, carrier.place)
            else {
                return NEUTRAL;
            };
            let Some(primitive) = self.program.primitive_type_reference(reference) else {
                return NEUTRAL;
            };
            let interval =
                super::atomic_resident_interval(self.program, machine, self.state, carrier.place)
                    .unwrap_or(Interval::UNBOUNDED);
            Analysis {
                recipe: None,
                domain: Some(self.program.arithmetic_domain_for_type_reference(reference)),
                interval,
                primitive: Some(primitive),
            }
        }

        fn analyze_value(
            &self,
            expression: ExpressionHandle,
            node: &ExpressionNode,
            diagnostics: &mut Vec<Diagnostic>,
            decisions: &mut ArithmeticDecisions,
            before_children_diagnostics: usize,
            before_children_values: usize,
        ) -> Analysis {
            if let Some(folded) = folded_values::analyze(self, expression, diagnostics) {
                return folded;
            }
            match node {
                ExpressionNode::Binary(binary) => {
                    binary::analyze(self, expression, binary, diagnostics, decisions)
                }
                ExpressionNode::Unary(unary) => unary::analyze(self, unary, diagnostics, decisions),
                ExpressionNode::Cast(cast) => {
                    cast::analyze(self, expression, cast, diagnostics, decisions)
                }
                ExpressionNode::Atomic(_) => self.atomic_load(expression),
                ExpressionNode::Call(call) => {
                    let child_values = (diagnostics.len() == before_children_diagnostics)
                        .then(|| &decisions.expression_values[before_children_values..]);
                    call::analyze(self, expression, call, child_values)
                }
                ExpressionNode::Match(dispatch) => {
                    dispatch::analyze(self, expression, dispatch, diagnostics, decisions)
                }
                ExpressionNode::Integer(value) => Analysis {
                    recipe: None,
                    domain: None,
                    interval: literal_interval(value),
                    primitive: unsigned_constants::integer_literal_primitive(
                        self.program,
                        expression,
                    ),
                },
                ExpressionNode::Float(_) | ExpressionNode::Boolean(_) => NEUTRAL,
                _ => place::analyze(self, expression),
            }
        }
    }
}
pub(crate) use declaration_values::{LocalValueFormation, validate_declaration_value_range};
pub(crate) use expression_analysis::TrappingReceiptDemand;
pub(crate) mod float_arithmetic {
    use crate::frozen_program::expression_table;
    use crate::proof_contracts::arithmetic_domains::integer_ranges::primitive_range;
    use crate::proof_contracts::arithmetic_domains::place_paths::place_path;
    use crate::proof_contracts::arithmetic_domains::value_environment::{
        FloatInterval, ValueEnvironment,
    };
    use crate::value_custody::places::declared_place_type_raw;
    use typed_trees::expression::{BinaryOperator, ExpressionHandle, ExpressionNode};
    use typed_trees::machine::Machine;
    use typed_trees::state::State;
    use typed_trees::types::{PrimitiveType, TypeReferenceHandle};

    pub(crate) fn float_literal_value(
        program: &dyn crate::CheckingInput,
        value: ExpressionHandle,
    ) -> Option<f64> {
        let node = expression_table(program).peeled_expression(value);
        match node {
            ExpressionNode::Float(literal) => Some(literal.landed_f64()),
            ExpressionNode::Cast(cast) => {
                if cast.form.is_recast() {
                    return None;
                }
                let value = float_literal_value(program, cast.value)?;
                let target = program.primitive_type_reference(cast.target_type)?;
                let format = match target {
                    PrimitiveType::F32 => numerics::float_semantics::FloatFormat::BINARY32,
                    PrimitiveType::F64 => numerics::float_semantics::FloatFormat::BINARY64,
                    _ => return None,
                };
                let meaning = numerics::float_semantics::FloatMeaning::from_f64(value);
                let converted =
                    numerics::float_semantics::FloatSemantics::convert(format, &meaning);
                (converted == meaning).then_some(converted.to_f64())
            }
            ExpressionNode::Call(call) => {
                let operator = typed_trees::operator::resolve_named_expression_call(program, call)?;
                let (source, target) = crate::numeric_float_conversion_contract(program, operator)?;
                if !matches!(source, PrimitiveType::F32 | PrimitiveType::F64) {
                    return None;
                }
                let [operand] = expression_table(program).expression_handles(call.arguments) else {
                    return None;
                };
                let value = float_literal_value(program, *operand)?;
                let format = match target {
                    PrimitiveType::F32 => numerics::float_semantics::FloatFormat::BINARY32,
                    PrimitiveType::F64 => numerics::float_semantics::FloatFormat::BINARY64,
                    _ => return None,
                };
                Some(
                    numerics::float_semantics::FloatSemantics::convert(
                        format,
                        &numerics::float_semantics::FloatMeaning::from_f64(value),
                    )
                    .to_f64(),
                )
            }
            _ => None,
        }
    }

    pub(crate) fn float_source_proves_integer_conversion(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        value: ExpressionHandle,
        target: PrimitiveType,
    ) -> bool {
        float_source_bounds(program, machine.symbol, environment, value, &|value| {
            state
                .and_then(|state| {
                    crate::value_custody::expression_types::expression_result_type_reference(
                        program, machine, state, value,
                    )
                })
                .or_else(|| declared_place_type_raw(program, machine, state, value))
        })
        .is_some_and(|bounds| bounds.proves_integer_conversion(target))
    }

    pub(crate) struct FloatSourceBounds {
        pub(crate) primitive: PrimitiveType,
        pub(crate) minimum: f64,
        pub(crate) maximum: f64,
    }

    impl FloatSourceBounds {
        pub(crate) fn from_comparison(
            primitive: PrimitiveType,
            operator: BinaryOperator,
            bound: f64,
            subject_on_left: bool,
        ) -> Option<Self> {
            if !matches!(primitive, PrimitiveType::F32 | PrimitiveType::F64) || !bound.is_finite() {
                return None;
            }
            let interval = float_bound_from(operator, bound, subject_on_left, primitive)?;
            Some(Self {
                primitive,
                minimum: interval.low.unwrap_or(f64::NEG_INFINITY),
                maximum: interval.high.unwrap_or(f64::INFINITY),
            })
        }

        pub(crate) fn intersect(self, other: Self) -> Option<Self> {
            if self.primitive != other.primitive {
                return None;
            }
            let minimum = self.minimum.max(other.minimum);
            let maximum = self.maximum.min(other.maximum);
            (minimum <= maximum).then_some(Self {
                primitive: self.primitive,
                minimum,
                maximum,
            })
        }

        pub(crate) fn proves_integer_conversion(&self, target: PrimitiveType) -> bool {
            self.minimum.is_finite()
                && self.maximum.is_finite()
                && float_interval_fits_integer(self.minimum.trunc(), self.maximum.trunc(), target)
        }

        pub(crate) fn is_exact_integer(&self, target: PrimitiveType) -> bool {
            self.is_integral() && float_interval_fits_integer(self.minimum, self.maximum, target)
        }

        pub(crate) fn is_integral(&self) -> bool {
            if !self.minimum.is_finite() || !self.maximum.is_finite() {
                return false;
            }
            if self.minimum == self.maximum {
                return self.minimum.trunc() == self.minimum;
            }
            let unit_spacing = match self.primitive {
                PrimitiveType::F32 => 8388608.0,
                PrimitiveType::F64 => 4503599627370496.0,
                _ => return false,
            };
            self.minimum >= unit_spacing || self.maximum <= -unit_spacing
        }
    }

    pub(crate) fn float_source_bounds(
        program: &dyn crate::CheckingInput,
        caller: symbols::SymbolHandle,
        environment: &ValueEnvironment,
        value: ExpressionHandle,
        result_type: &dyn Fn(ExpressionHandle) -> Option<TypeReferenceHandle>,
    ) -> Option<FloatSourceBounds> {
        let reference = result_type(value);
        let primitive = reference
            .and_then(|reference| program.primitive_type_reference(reference))
            .filter(|primitive| matches!(primitive, PrimitiveType::F32 | PrimitiveType::F64))?;
        if let ExpressionNode::Match(dispatch) = expression_table(program).expression(value) {
            let arms = expression_table(program).match_arms(dispatch.arms);
            if !arms.is_empty() {
                let mut minimum = f64::INFINITY;
                let mut maximum = f64::NEG_INFINITY;
                let mut all_bounded = true;
                for arm in arms {
                    let Some(bounds) =
                        float_source_bounds(program, caller, environment, arm.value, result_type)
                            .filter(|bounds| bounds.primitive == primitive)
                    else {
                        all_bounded = false;
                        break;
                    };
                    minimum = minimum.min(bounds.minimum);
                    maximum = maximum.max(bounds.maximum);
                }
                if all_bounded && minimum <= maximum {
                    return Some(FloatSourceBounds {
                        primitive,
                        minimum,
                        maximum,
                    });
                }
            }
        }
        let declared = expression_table(program)
            .call_node(value)
            .filter(|call| call.selects_only_nominal_route())
            .and_then(|call| {
                super::float_contracts::normal_return_interval(program, caller, value, call)
            });
        let (flow, non_nan) = place_path(program, value)
            .map(|path| environment.float_fact(&path))
            .or_else(|| {
                super::place_paths::element_place(program, value)
                    .map(|element| environment.float_element_fact(&element))
            })
            .unwrap_or((FloatInterval::UNBOUNDED, false));
        let converted = numeric_conversion_bounds(program, caller, environment, value, result_type);
        let literal = match expression_table(program).peeled_expression(value) {
            ExpressionNode::Float(literal) if literal.landing().is_none() => {
                Some(match primitive {
                    PrimitiveType::F32 => f64::from(literal.value_f32()),
                    PrimitiveType::F64 => literal.value_f64(),
                    _ => return None,
                })
            }
            _ => float_literal_value(program, value),
        };
        let range = if let Some(value) = literal {
            if value.is_nan() {
                return None;
            }
            FloatInterval {
                low: Some(value),
                high: Some(value),
            }
        } else {
            if declared.is_none() && converted.is_none() && !non_nan {
                return None;
            }
            let range = declared.map_or(flow, |declared| declared.intersect(flow));
            converted.map_or(range, |converted| range.intersect(converted))
        };
        let minimum = range.low.unwrap_or(f64::NEG_INFINITY);
        let maximum = range.high.unwrap_or(f64::INFINITY);
        (minimum <= maximum).then_some(FloatSourceBounds {
            primitive,
            minimum,
            maximum,
        })
    }

    fn numeric_conversion_bounds(
        program: &dyn crate::CheckingInput,
        caller: symbols::SymbolHandle,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
        result_type: &dyn Fn(ExpressionHandle) -> Option<TypeReferenceHandle>,
    ) -> Option<FloatInterval> {
        if let Some(cast) = expression_table(program).cast_node(expression) {
            if cast.form.is_recast() {
                return None;
            }
            let target = program.primitive_type_reference(cast.target_type)?;
            let bounds =
                float_source_bounds(program, caller, environment, cast.value, result_type)?;
            return converted_float_interval(&bounds, target);
        }
        let call = expression_table(program).call_node(expression)?;
        let operator = typed_trees::operator::resolve_named_expression_call(program, call)?;
        let (source, target) = crate::numeric_float_conversion_contract(program, operator)?;
        let [operand] = expression_table(program).expression_handles(call.arguments) else {
            return None;
        };
        if let Some((integer, converted, minimum, maximum)) =
            crate::integer_float_conversion_bounds(program, operator)
        {
            if integer != source
                || converted != target
                || result_type(*operand)
                    .and_then(|reference| program.primitive_type_reference(reference))
                    != Some(source)
            {
                return None;
            }
            return Some(FloatInterval {
                low: Some(minimum.to_f64()),
                high: Some(maximum.to_f64()),
            });
        }
        let bounds = float_source_bounds(program, caller, environment, *operand, result_type)?;
        if bounds.primitive != source {
            return None;
        }
        converted_float_interval(&bounds, target)
    }

    fn converted_float_interval(
        bounds: &FloatSourceBounds,
        target: PrimitiveType,
    ) -> Option<FloatInterval> {
        let format = match target {
            PrimitiveType::F32 => numerics::float_semantics::FloatFormat::BINARY32,
            PrimitiveType::F64 => numerics::float_semantics::FloatFormat::BINARY64,
            _ => return None,
        };
        let convert = |value| {
            numerics::float_semantics::FloatSemantics::convert(
                format,
                &numerics::float_semantics::FloatMeaning::from_f64(value),
            )
            .to_f64()
        };
        Some(FloatInterval {
            low: Some(convert(bounds.minimum)),
            high: Some(convert(bounds.maximum)),
        })
    }

    pub(crate) fn float_interval_fits_integer(low: f64, high: f64, target: PrimitiveType) -> bool {
        match target {
            PrimitiveType::I64 => low >= -9223372036854775808.0 && high < 9223372036854775808.0,
            PrimitiveType::U64 => low >= 0.0 && high < 18446744073709551616.0,
            _ => primitive_range(target).is_some_and(|range| {
                matches!((range.low, range.high), (Some(target_low), Some(target_high))
                if low >= target_low as f64 && high <= target_high as f64)
            }),
        }
    }

    pub(crate) fn float_bound_from(
        operator: BinaryOperator,
        literal: f64,
        name_on_left: bool,
        primitive: PrimitiveType,
    ) -> Option<FloatInterval> {
        let operator = if name_on_left {
            operator
        } else {
            match operator {
                BinaryOperator::Equal => BinaryOperator::Equal,
                BinaryOperator::Less => BinaryOperator::Greater,
                BinaryOperator::LessOrEqual => BinaryOperator::GreaterOrEqual,
                BinaryOperator::Greater => BinaryOperator::Less,
                BinaryOperator::GreaterOrEqual => BinaryOperator::LessOrEqual,
                _ => return None,
            }
        };
        Some(match operator {
            BinaryOperator::Equal => FloatInterval {
                low: Some(literal),
                high: Some(literal),
            },
            BinaryOperator::Less => FloatInterval {
                low: None,
                high: Some(adjacent(literal, primitive, false)),
            },
            BinaryOperator::LessOrEqual => FloatInterval {
                low: None,
                high: Some(literal),
            },
            BinaryOperator::Greater => FloatInterval {
                low: Some(adjacent(literal, primitive, true)),
                high: None,
            },
            BinaryOperator::GreaterOrEqual => FloatInterval {
                low: Some(literal),
                high: None,
            },
            _ => return None,
        })
    }

    fn adjacent(value: f64, primitive: PrimitiveType, upward: bool) -> f64 {
        if primitive == PrimitiveType::F32 {
            let value = value as f32;
            f64::from(if upward {
                value.next_up()
            } else {
                value.next_down()
            })
        } else {
            if upward {
                value.next_up()
            } else {
                value.next_down()
            }
        }
    }

    pub(crate) fn record_float_comparison_bounds(
        program: &dyn crate::CheckingInput,
        environment: &mut ValueEnvironment,
        comparison: &typed_trees::expression::TableBinaryExpression,
        place_type: &dyn Fn(ExpressionHandle) -> Option<TypeReferenceHandle>,
    ) -> bool {
        if comparison.operator == BinaryOperator::Equal
            && let (Some(left), Some(right)) = (
                place_path(program, comparison.left),
                place_path(program, comparison.right),
            )
            && left == right
            && place_type(comparison.left).is_some_and(|handle| {
                matches!(
                    program.primitive_type_reference(handle),
                    Some(PrimitiveType::F32 | PrimitiveType::F64)
                )
            })
        {
            environment.mark_non_nan(left);
            return true;
        }
        if comparison.operator == BinaryOperator::Equal
            && let (Some(left), Some(right)) = (
                super::place_paths::element_place(program, comparison.left),
                super::place_paths::element_place(program, comparison.right),
            )
            && left == right
            && place_type(comparison.left).is_some_and(|handle| {
                matches!(
                    program.primitive_type_reference(handle),
                    Some(PrimitiveType::F32 | PrimitiveType::F64)
                )
            })
        {
            environment.mark_non_nan_element(left);
            return true;
        }
        let float_sides = if let Some(literal) = float_literal_value(program, comparison.right) {
            Some((comparison.left, literal, true))
        } else {
            float_literal_value(program, comparison.left)
                .map(|literal| (comparison.right, literal, false))
        };
        if let Some((place_expression, literal, name_on_left)) = float_sides
            && literal.is_finite()
            && let Some(handle) = place_type(place_expression)
            && let Some(primitive @ (PrimitiveType::F32 | PrimitiveType::F64)) =
                program.primitive_type_reference(handle)
            && let Some(name) = place_path(program, place_expression)
            && let Some(interval) =
                float_bound_from(comparison.operator, literal, name_on_left, primitive)
        {
            environment.narrow_float(name.clone(), interval);
            environment.mark_non_nan(name);
            return true;
        }
        if let Some((element_expression, literal, element_on_left)) = float_sides
            && literal.is_finite()
            && let Some(handle) = place_type(element_expression)
            && let Some(primitive @ (PrimitiveType::F32 | PrimitiveType::F64)) =
                program.primitive_type_reference(handle)
            && let Some(element) = super::place_paths::element_place(program, element_expression)
            && let Some(interval) =
                float_bound_from(comparison.operator, literal, element_on_left, primitive)
        {
            environment.narrow_float_element(element.clone(), interval);
            environment.mark_non_nan_element(element);
            return true;
        }
        false
    }
}
pub(crate) mod float_contracts {
    use super::float_arithmetic::{
        FloatSourceBounds, float_bound_from, float_literal_value, float_source_bounds,
    };
    use super::value_environment::FloatInterval;
    use crate::machine_calls::calls::CalleeContract;
    use typed_trees::expression::{BinaryOperator, ExpressionHandle};
    use typed_trees::signature::SignatureContractKind;
    use typed_trees::types::{PrimitiveType, TypeReferenceHandle};

    pub fn normal_return_float_predicates(
        program: &dyn crate::CheckingInput,
        caller: symbols::SymbolHandle,
        expression: ExpressionHandle,
        call: &typed_trees::expression::TableCallExpression,
        predicates: &mut Vec<facts::FloatPredicate>,
    ) {
        if !call.selects_only_nominal_route() {
            return;
        }
        let Some(callee) = crate::machine_calls::calls::call_contract(program, call) else {
            return;
        };
        let Some(interval) = normal_return_interval(program, caller, expression, call) else {
            return;
        };
        let format = match program.primitive_type_reference(callee.return_type) {
            Some(PrimitiveType::F32) => numerics::literals::FloatFormat::F32,
            Some(PrimitiveType::F64) => numerics::literals::FloatFormat::F64,
            _ => return,
        };
        if let (Some(minimum), Some(maximum)) = (interval.low, interval.high)
            && minimum == maximum
            && let Some(predicate) = facts::FloatPredicate::comparison(
                format,
                BinaryOperator::Equal,
                &numerics::bignum::ExactFloat::from_f64(minimum),
            )
        {
            predicates.push(predicate);
            return;
        }
        for (operator, bound) in [
            (BinaryOperator::GreaterOrEqual, interval.low),
            (BinaryOperator::LessOrEqual, interval.high),
        ] {
            if let Some(predicate) = bound.and_then(|bound| {
                facts::FloatPredicate::comparison(
                    format,
                    operator,
                    &numerics::bignum::ExactFloat::from_f64(bound),
                )
            }) {
                predicates.push(predicate);
            }
        }
    }

    pub(crate) fn normal_return_interval(
        program: &dyn crate::CheckingInput,
        caller: symbols::SymbolHandle,
        expression: ExpressionHandle,
        call: &typed_trees::expression::TableCallExpression,
    ) -> Option<FloatInterval> {
        if !call.selects_only_nominal_route()
            || !crate::machine_calls::contract_dependencies::independent_call_application(
                program,
                caller,
                call.target_symbol,
                typed_trees::references::StaticArgumentCall::Expression(expression, call),
            )
        {
            return None;
        }
        let callee = crate::machine_calls::calls::call_contract(program, call)?;
        let primitive = program.primitive_type_reference(callee.return_type)?;
        if !matches!(primitive, PrimitiveType::F32 | PrimitiveType::F64) {
            return None;
        }
        if let Some(machine) = program.machine_by_symbol(callee.callable)
            && machine.target_family_interface
        {
            let mut possible: Option<FloatInterval> = None;
            for member in crate::machine_calls::calls::target_family_members(program, machine)? {
                let body = program.machine(member.machine)?;
                let entry = program.machine_states(body).first()?;
                let target =
                    crate::machine_calls::calls::callee_entry_contract(program, entry.symbol)?;
                if program.primitive_type_reference(target.return_type) != Some(primitive) {
                    return None;
                }
                let interval = declared_result_interval(program, &target, primitive);
                possible = Some(possible.map_or(interval, |previous| previous.union(interval)));
            }
            let interval = possible?;
            return (interval != FloatInterval::UNBOUNDED).then_some(interval);
        }
        let interval = declared_result_interval(program, &callee, primitive);
        (interval != FloatInterval::UNBOUNDED).then_some(interval)
    }

    fn declared_result_interval(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        primitive: PrimitiveType,
    ) -> FloatInterval {
        program
            .contract_expressions(callee.contracts.iter(), SignatureContractKind::Ensures)
            .fold(FloatInterval::UNBOUNDED, |interval, expression| {
                interval.intersect(project(program, callee, expression, primitive))
            })
    }

    fn project(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        expression: ExpressionHandle,
        primitive: PrimitiveType,
    ) -> FloatInterval {
        let Some(binary) = program.expression_table.binary_node(expression) else {
            if let Some(predicates) =
                crate::mathematical_applications::float_predicates(program, expression)
            {
                return predicates.into_iter().fold(
                    FloatInterval::UNBOUNDED,
                    |interval, projection| {
                        if crate::reserved_result_owner(program, projection.subject).is_some_and(
                            |(owner, reference)| {
                                owner == callee.callable && reference == callee.return_type
                            },
                        ) && matches!(
                            (primitive, projection.predicate.format()),
                            (PrimitiveType::F32, numerics::literals::FloatFormat::F32)
                                | (PrimitiveType::F64, numerics::literals::FloatFormat::F64)
                        ) {
                            interval.intersect(
                                float_bound_from(
                                    projection.operator,
                                    projection.bound.to_f64(),
                                    true,
                                    primitive,
                                )
                                .unwrap_or(FloatInterval::UNBOUNDED),
                            )
                        } else {
                            interval
                        }
                    },
                );
            }
            return FloatInterval::UNBOUNDED;
        };
        if matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or) {
            let left = project(program, callee, binary.left, primitive);
            let right = project(program, callee, binary.right, primitive);
            return if binary.operator == BinaryOperator::And {
                left.intersect(right)
            } else {
                left.union(right)
            };
        }
        let result = |expression| {
            crate::reserved_result_owner(program, expression).is_some_and(|(owner, reference)| {
                owner == callee.callable && reference == callee.return_type
            })
        };
        let (other, result_on_left) = if result(binary.left) {
            (binary.right, true)
        } else if result(binary.right) {
            (binary.left, false)
        } else {
            return FloatInterval::UNBOUNDED;
        };
        let other_type = crate::parameter_expression_result_type_reference(
            program,
            callee.callable,
            callee.parameters,
            other,
        );
        let operand_types = if result_on_left {
            [Some(callee.return_type), other_type]
        } else {
            [other_type, Some(callee.return_type)]
        };
        if !comparison_meaning(
            program,
            callee.callable,
            expression,
            binary.operator,
            &operand_types,
        ) {
            return FloatInterval::UNBOUNDED;
        }
        if let Some(literal) = float_literal_value(program, other)
            && let Some(interval) =
                float_bound_from(binary.operator, literal, result_on_left, primitive)
        {
            return interval;
        }
        let Some(parameter_interval) =
            callee_parameter_interval(program, callee, other, other_type, primitive)
        else {
            return FloatInterval::UNBOUNDED;
        };
        let operator = if result_on_left {
            binary.operator
        } else {
            binary.operator.mirrored()
        };
        match operator {
            BinaryOperator::Equal => parameter_interval,
            BinaryOperator::GreaterOrEqual => FloatInterval {
                low: parameter_interval.low,
                high: None,
            },
            BinaryOperator::Greater => FloatInterval {
                low: parameter_interval.low.and_then(|low| {
                    float_bound_from(BinaryOperator::Greater, low, true, primitive)?.low
                }),
                high: None,
            },
            BinaryOperator::LessOrEqual => FloatInterval {
                low: None,
                high: parameter_interval.high,
            },
            BinaryOperator::Less => FloatInterval {
                low: None,
                high: parameter_interval.high.and_then(|high| {
                    float_bound_from(BinaryOperator::Less, high, true, primitive)?.high
                }),
            },
            _ => FloatInterval::UNBOUNDED,
        }
    }

    fn callee_parameter_interval(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        other: ExpressionHandle,
        _other_type: Option<TypeReferenceHandle>,
        primitive: PrimitiveType,
    ) -> Option<FloatInterval> {
        let path = super::place_path(program, other)?;
        let parameter = callee
            .parameters
            .iter()
            .find(|parameter| parameter.name.as_str() == path)?;
        let interval = program
            .contract_expressions(callee.contracts.iter(), SignatureContractKind::Requires)
            .fold(FloatInterval::UNBOUNDED, |interval, expression| {
                interval.intersect(project_parameter(
                    program,
                    callee,
                    expression,
                    &path,
                    parameter.type_reference,
                    primitive,
                ))
            });
        (interval != FloatInterval::UNBOUNDED).then_some(interval)
    }

    fn project_parameter(
        program: &dyn crate::CheckingInput,
        callee: &CalleeContract<'_>,
        expression: ExpressionHandle,
        parameter_name: &str,
        parameter_type: TypeReferenceHandle,
        primitive: PrimitiveType,
    ) -> FloatInterval {
        let Some(binary) = program.expression_table.binary_node(expression) else {
            return FloatInterval::UNBOUNDED;
        };
        if matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or) {
            let left = project_parameter(
                program,
                callee,
                binary.left,
                parameter_name,
                parameter_type,
                primitive,
            );
            let right = project_parameter(
                program,
                callee,
                binary.right,
                parameter_name,
                parameter_type,
                primitive,
            );
            return if binary.operator == BinaryOperator::And {
                left.intersect(right)
            } else {
                left.union(right)
            };
        }
        let matches_parameter =
            |operand| super::place_path(program, operand).as_deref() == Some(parameter_name);
        let (other, parameter_on_left) = if matches_parameter(binary.left) {
            (binary.right, true)
        } else if matches_parameter(binary.right) {
            (binary.left, false)
        } else {
            return FloatInterval::UNBOUNDED;
        };
        let other_type = crate::parameter_expression_result_type_reference(
            program,
            callee.callable,
            callee.parameters,
            other,
        );
        let operand_types = if parameter_on_left {
            [Some(parameter_type), other_type]
        } else {
            [other_type, Some(parameter_type)]
        };
        if !comparison_meaning(
            program,
            callee.callable,
            expression,
            binary.operator,
            &operand_types,
        ) {
            return FloatInterval::UNBOUNDED;
        }
        float_literal_value(program, other)
            .and_then(|literal| {
                float_bound_from(binary.operator, literal, parameter_on_left, primitive)
            })
            .unwrap_or(FloatInterval::UNBOUNDED)
    }

    fn comparison_meaning(
        program: &dyn crate::CheckingInput,
        owner: symbols::SymbolHandle,
        expression: ExpressionHandle,
        operator: BinaryOperator,
        operand_types: &[Option<TypeReferenceHandle>],
    ) -> bool {
        crate::has_builtin_or_sealed_float_comparison_meaning(
            program,
            owner,
            expression,
            operator,
            operand_types,
        )
    }

    pub fn float_return_postcondition(
        program: &dyn crate::CheckingInput,
        machine: &typed_trees::machine::Machine,
        state: &typed_trees::state::State,
        returned: ExpressionHandle,
        condition: ExpressionHandle,
    ) -> Option<bool> {
        if !has_float_comparison(program, machine, state, condition) {
            return None;
        }
        let environment =
            super::occurrence_value_environment(program, machine.symbol, state.symbol, returned)?;
        let is_result = |expression| {
            crate::reserved_result_owner(program, expression)
                .is_some_and(|(owner, _)| owner == machine.symbol || owner == state.symbol)
        };
        let actual = |expression| {
            if is_result(expression) {
                returned
            } else {
                expression
            }
        };
        let result_type = |expression| {
            crate::expression_result_type_reference(program, machine, state, actual(expression))
        };
        let source_bounds = |expression, reference| {
            let landed_type = |value| {
                result_type(value).or_else(|| {
                    matches!(program.expression_table.peeled_expression(value),
                    typed_trees::expression::ExpressionNode::Float(literal)
                        if literal.landing().is_none())
                    .then_some(reference)
                })
            };
            float_source_bounds(
                program,
                machine.symbol,
                &environment,
                actual(expression),
                &landed_type,
            )
        };
        predicate(
            program,
            machine.symbol,
            condition,
            &actual,
            &source_bounds,
            &result_type,
        )
    }

    fn has_float_comparison(
        program: &dyn crate::CheckingInput,
        machine: &typed_trees::machine::Machine,
        state: &typed_trees::state::State,
        expression: ExpressionHandle,
    ) -> bool {
        if crate::mathematical_applications::float_predicates(program, expression)
            .is_some_and(|predicates| !predicates.is_empty())
        {
            return true;
        }
        let Some(binary) = program.expression_table.binary_node(expression) else {
            return false;
        };
        if matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or) {
            return has_float_comparison(program, machine, state, binary.left)
                || has_float_comparison(program, machine, state, binary.right);
        }
        [binary.left, binary.right].into_iter().any(|operand| {
            crate::reserved_result_owner(program, operand)
                .map(|(_, reference)| reference)
                .or_else(|| {
                    crate::expression_result_type_reference(program, machine, state, operand)
                })
                .and_then(|reference| program.primitive_type_reference(reference))
                .is_some_and(|primitive| {
                    matches!(primitive, PrimitiveType::F32 | PrimitiveType::F64)
                })
        })
    }

    fn predicate(
        program: &dyn crate::CheckingInput,
        owner: symbols::SymbolHandle,
        expression: ExpressionHandle,
        actual: &dyn Fn(ExpressionHandle) -> ExpressionHandle,
        source_bounds: &dyn Fn(ExpressionHandle, TypeReferenceHandle) -> Option<FloatSourceBounds>,
        result_type: &dyn Fn(ExpressionHandle) -> Option<TypeReferenceHandle>,
    ) -> Option<bool> {
        if let Some(predicates) =
            crate::mathematical_applications::float_predicates(program, expression)
        {
            let mut unknown = false;
            for projection in predicates {
                let source = source_bounds(projection.subject, projection.reference)?;
                if !matches!(
                    (source.primitive, projection.predicate.format()),
                    (PrimitiveType::F32, numerics::literals::FloatFormat::F32)
                        | (PrimitiveType::F64, numerics::literals::FloatFormat::F64)
                ) {
                    return None;
                }
                let endpoint = projection.bound.to_f64();
                let bound = FloatSourceBounds {
                    primitive: source.primitive,
                    minimum: endpoint,
                    maximum: endpoint,
                };
                match compare(projection.operator, &source, &bound) {
                    Some(false) => return Some(false),
                    None => unknown = true,
                    Some(true) => {}
                }
            }
            return (!unknown).then_some(true);
        }
        let binary = program.expression_table.binary_node(expression)?;
        if matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or) {
            let left = predicate(
                program,
                owner,
                binary.left,
                actual,
                source_bounds,
                result_type,
            );
            let right = predicate(
                program,
                owner,
                binary.right,
                actual,
                source_bounds,
                result_type,
            );
            return match (left, right, binary.operator) {
                (Some(false), _, BinaryOperator::And) | (_, Some(false), BinaryOperator::And) => {
                    Some(false)
                }
                (Some(true), Some(true), BinaryOperator::And) => Some(true),
                (Some(true), _, BinaryOperator::Or) | (_, Some(true), BinaryOperator::Or) => {
                    Some(true)
                }
                (Some(false), Some(false), BinaryOperator::Or) => Some(false),
                _ => None,
            };
        }
        let authored_type = |operand| {
            crate::reserved_result_owner(program, operand)
                .map(|(_, reference)| reference)
                .or_else(|| result_type(operand))
        };
        let operand_types = [authored_type(binary.left), authored_type(binary.right)];
        let reference = operand_types[0].or(operand_types[1])?;
        let primitive = program.primitive_type_reference(reference)?;
        if !matches!(primitive, PrimitiveType::F32 | PrimitiveType::F64)
            || !comparison_meaning(program, owner, expression, binary.operator, &operand_types)
        {
            return None;
        }
        let left = source_bounds(binary.left, reference)?;
        let right = source_bounds(binary.right, reference)?;
        if left.primitive != right.primitive {
            return None;
        }
        if matches!(
            binary.operator,
            BinaryOperator::Equal | BinaryOperator::NotEqual
        ) && super::place_path(program, actual(binary.left)).is_some_and(|left_path| {
            super::place_path(program, actual(binary.right)).as_deref() == Some(left_path.as_str())
        }) {
            return Some(binary.operator == BinaryOperator::Equal);
        }
        compare(binary.operator, &left, &right)
    }

    fn compare(
        operator: BinaryOperator,
        left: &FloatSourceBounds,
        right: &FloatSourceBounds,
    ) -> Option<bool> {
        use BinaryOperator::*;
        let same_point = left.minimum == left.maximum
            && right.minimum == right.maximum
            && left.minimum == right.minimum;
        let disjoint = left.maximum < right.minimum || right.maximum < left.minimum;
        match operator {
            Equal if same_point => Some(true),
            Equal if disjoint => Some(false),
            NotEqual if disjoint => Some(true),
            NotEqual if same_point => Some(false),
            Less if left.maximum < right.minimum => Some(true),
            Less if left.minimum >= right.maximum => Some(false),
            LessOrEqual if left.maximum <= right.minimum => Some(true),
            LessOrEqual if left.minimum > right.maximum => Some(false),
            Greater => compare(Less, right, left),
            GreaterOrEqual => compare(LessOrEqual, right, left),
            _ => None,
        }
    }
}
pub use float_contracts::{float_return_postcondition, normal_return_float_predicates};
pub(crate) mod guard_narrowing {
    use super::{
        ArithmeticDomain, BinaryOperator, ExpressionHandle, ExpressionNode, Interval, Machine,
        PrimitiveType, SignatureContractKind, State, ValueEnvironment, declared_place_type_raw,
        literal_i64, ordered_values, place_path, range_constraint_interval,
    };
    use std::collections::BTreeMap;
    use typed_trees::expression::TableBinaryExpression;

    pub(crate) mod arrivals {

        use super::super::{
            TypeReferenceHandle, TypeReferenceNode, enforced_declared_range, record_assignment,
            record_unsigned_literal_assignment,
        };
        use super::{
            ArithmeticDomain, BinaryOperator, ExpressionHandle, ExpressionNode, Interval, Machine,
            State, ValueEnvironment, declared_place_type_raw, incoming_guard_environment,
            narrow_environment_by_condition, ordered_values, place_path,
        };
        use crate::CallFrameResolver;
        use crate::frozen_program::expression_table;
        use crate::proof_contracts::arithmetic_domains::CopiedIntegerValue;
        use crate::proof_contracts::arithmetic_domains::expression_analysis::{
            CheckedAnalysis, analyze, analyze_arrival,
        };
        use checked_trees::IntegerRangeRecipe;
        use std::collections::BTreeMap;
        use symbols::SymbolHandle;
        use typed_trees::statement::{StatementNode, TransitionGuardNode, TransitionTargetNode};

        use super::requirements::{RequirementSeeds, machine_written_paths};

        pub(crate) mod normal_returns {
            use super::{
                ArrivalWalk, ExpressionObservation, ValueObservationSite, incoming_environments,
            };
            use crate::proof_contracts::arithmetic_domains::{Interval, Machine, State};
            use crate::{CallFrameResolver, DependencyBodyRead};
            use checked_trees::IntegerRangeRecipe;
            use symbols::SymbolHandle;
            use typed_trees::statement::{StatementNode, TransitionExit, TransitionTargetNode};

            #[derive(Default)]
            pub(crate) enum ReturnInference<'request> {
                #[default]
                Root,
                Active {
                    parent: &'request ReturnInference<'request>,
                    identity: (SymbolHandle, SymbolHandle),
                },
            }

            impl ReturnInference<'_> {
                fn contains(&self, identity: (SymbolHandle, SymbolHandle)) -> bool {
                    let mut current = self;
                    while let Self::Active {
                        parent,
                        identity: active,
                    } = current
                    {
                        if *active == identity {
                            return true;
                        }
                        current = parent;
                    }
                    false
                }

                pub(crate) fn infer(
                    &self,
                    program: &dyn crate::CheckingInput,
                    machine: &Machine,
                    entry: &State,
                    target_primitive: Option<typed_trees::types::PrimitiveType>,
                    actuals: &[ActualRange],
                ) -> Option<(Interval, Option<IntegerRangeRecipe>)> {
                    inferred_normal_return_interval_in(
                        program,
                        machine,
                        entry,
                        target_primitive,
                        actuals,
                        self,
                    )
                }
            }

            pub(crate) type ActualRange = (SymbolHandle, Interval, Option<IntegerRangeRecipe>);

            pub(crate) fn inferred_normal_return_interval(
                program: &dyn crate::CheckingInput,
                machine: &Machine,
                entry: &State,
                target_primitive: Option<typed_trees::types::PrimitiveType>,
                actuals: &[ActualRange],
            ) -> Option<(Interval, Option<IntegerRangeRecipe>)> {
                crate::note_dependency_body_read(
                    program,
                    machine.symbol,
                    DependencyBodyRead::ReturnInterval,
                );
                ReturnInference::default().infer(program, machine, entry, target_primitive, actuals)
            }

            fn join_return(
                combined: &mut Option<Interval>,
                combined_recipe: &mut Option<IntegerRangeRecipe>,
                interval: Interval,
                recipe: Option<IntegerRangeRecipe>,
            ) {
                *combined_recipe = if combined.is_none() {
                    recipe
                } else {
                    combined_recipe
                        .take()
                        .zip(recipe)
                        .map(|(left, right)| left.union(&right))
                };
                *combined = Some(combined.map_or(interval, |previous| previous.union(interval)));
            }

            fn inferred_normal_return_interval_in(
                program: &dyn crate::CheckingInput,
                machine: &Machine,
                entry: &State,
                target_primitive: Option<typed_trees::types::PrimitiveType>,
                actuals: &[ActualRange],
                inference: &ReturnInference<'_>,
            ) -> Option<(Interval, Option<IntegerRangeRecipe>)> {
                let primitive = target_primitive?;
                crate::proof_contracts::arithmetic_domains::integer_ranges::primitive_range(
                    primitive,
                )?;
                let memos = crate::frozen_program::frozen_program_memos(program).filter(|_| {
                    actuals.iter().all(|(_, _, recipe)| recipe.is_none())
                        && program
                            .machine(machine.symbol)
                            .is_some_and(|stored| std::ptr::eq(stored, machine))
                        && program
                            .state_in_machine(machine, entry.symbol)
                            .is_some_and(|stored| std::ptr::eq(stored, entry))
                });
                let key = (
                    machine.symbol,
                    entry.symbol,
                    primitive as u8,
                    actuals
                        .iter()
                        .map(|(symbol, interval, _)| (*symbol, *interval))
                        .collect::<Vec<_>>(),
                );
                if let Some(memos) = memos
                    && let Ok(intervals) = memos.normal_return_intervals.lock()
                    && let Some(interval) = intervals.get(&key)
                {
                    return interval.clone();
                }
                let identity = (machine.symbol, entry.symbol);
                if inference.contains(identity) {
                    return None;
                }
                let active = ReturnInference::Active {
                    parent: inference,
                    identity,
                };
                let interval = discover_normal_return_interval(
                    program,
                    machine,
                    entry,
                    target_primitive,
                    actuals,
                    &active,
                );
                if interval.is_none() && crate::proof_contracts::contract_entailment::struct_trace()
                {
                    eprintln!(
                        "STRUCT integer-return unknown owner={} entry={:?} primitive={target_primitive:?} supply={:?} all-exits={}",
                        machine.name,
                        entry.symbol,
                        machine.supply_mode,
                        crate::proof_contracts::contract_entailment::entailment_covers_all_exits(
                            program, machine
                        )
                    );
                    for state in program.machine_states(machine) {
                        let last = program
                            .statement_table
                            .statements(state.statement_nodes)
                            .last();
                        eprintln!(
                            "STRUCT integer-return state={:?} primitive={:?} last={last:?}",
                            state.symbol,
                            program.primitive_type_reference(state.return_type)
                        );
                        if let Some(StatementNode::Transition(transition)) = last {
                            for target in transition.targets() {
                                eprintln!(
                                    "STRUCT integer-return target={:?}",
                                    program.statement_table.transition_target(target)
                                );
                            }
                        }
                    }
                }

                if interval.is_some()
                    && let Some(memos) = memos
                    && let Ok(mut intervals) = memos.normal_return_intervals.lock()
                {
                    intervals.insert(key, interval.clone());
                }
                interval
            }

            fn discover_normal_return_interval(
                program: &dyn crate::CheckingInput,
                machine: &Machine,
                entry: &State,
                target_primitive: Option<typed_trees::types::PrimitiveType>,
                actuals: &[ActualRange],
                inference: &ReturnInference<'_>,
            ) -> Option<(Interval, Option<IntegerRangeRecipe>)> {
                if machine.target_family_interface
                    && program.machine_states(machine).first()?.symbol == entry.symbol
                {
                    let parameters = program.state_parameters(entry);
                    let members =
                        crate::machine_calls::calls::target_family_members(program, machine)?;
                    let mut combined: Option<Interval> = None;
                    let mut combined_recipe: Option<IntegerRangeRecipe> = None;
                    for member in members {
                        let member_machine = program.machine(member.machine)?;
                        let member_entry = program.machine_states(member_machine).first()?;
                        let member_parameters = program.state_parameters(member_entry);
                        if member_parameters.len() != parameters.len() {
                            return None;
                        }
                        let member_actuals = parameters
                            .iter()
                            .zip(member_parameters)
                            .filter_map(|(interface_param, member_param)| {
                                actuals
                                    .iter()
                                    .find(|(symbol, _, _)| *symbol == interface_param.symbol)
                                    .map(|(_, interval, recipe)| {
                                        (member_param.symbol, *interval, recipe.clone())
                                    })
                            })
                            .collect::<Vec<_>>();
                        let (interval, recipe) = inferred_normal_return_interval_in(
                            program,
                            member_machine,
                            member_entry,
                            target_primitive,
                            &member_actuals,
                            inference,
                        )?;
                        combined_recipe = if combined.is_none() {
                            recipe
                        } else {
                            combined_recipe
                                .zip(recipe)
                                .map(|(left, right)| left.union(&right))
                        };
                        combined =
                            Some(combined.map_or(interval, |previous| previous.union(interval)));
                    }
                    let combined = combined?;
                    return (combined_recipe.is_some()
                        || (combined.low.is_some() && combined.high.is_some()))
                    .then_some((combined, combined_recipe));
                }
                if machine.supply_mode != language_semantics::MachineSupplyMode::CheckedBody
                    || !crate::proof_contracts::contract_entailment::entailment_covers_all_exits(
                        program, machine,
                    )
                {
                    return None;
                }
                let mut state_returns = Vec::new();
                for state in program.machine_states(machine) {
                    let statements = program.statement_table.statements(state.statement_nodes);
                    let order = program
                        .statement_table
                        .finite_execution_order(state.statement_nodes)
                        .ok()??;
                    let last = order.last().map(|index| &statements[*index]);
                    if program.primitive_type_reference(state.return_type) != target_primitive {
                        return None;
                    }
                    if !matches!(
                        last,
                        Some(StatementNode::Expression(_) | StatementNode::Transition(_))
                    ) {
                        return None;
                    }
                    let mut returns = Vec::new();
                    if let Some(StatementNode::Expression(expression)) = last {
                        returns.push(ExpressionObservation::bounds(*expression));
                    }
                    for statement in order.iter().map(|index| &statements[*index]) {
                        let Some(transition) = statement.as_transition() else {
                            continue;
                        };
                        if !matches!(transition.exit, TransitionExit::Ordinary) {
                            continue;
                        }
                        for target in transition.targets() {
                            match program.statement_table.transition_target(target) {
                                TransitionTargetNode::Value(expression) => {
                                    if !returns
                                        .iter()
                                        .any(|observed| observed.expression() == Some(*expression))
                                    {
                                        returns.push(ExpressionObservation::bounds(*expression));
                                    }
                                }
                                TransitionTargetNode::Named {
                                    path,
                                    static_machine_parameter,
                                    evidence_arguments,
                                    ..
                                } => {
                                    if static_machine_parameter.is_valid()
                                        || !evidence_arguments.is_empty()
                                    {
                                        return None;
                                    }
                                    if typed_trees::state::state_by_symbol(
                                        program.machine_states(machine),
                                        path.symbol,
                                    )
                                    .is_none()
                                    {
                                        returns.push(ExpressionObservation::invocation(target));
                                    }
                                }
                                TransitionTargetNode::Terminal => return None,
                            }
                        }
                    }
                    if !returns.is_empty() {
                        state_returns.push((state, returns));
                    }
                }
                if state_returns.is_empty() {
                    return None;
                }
                let frames = CallFrameResolver::new(program);
                let incoming = incoming_environments(
                    program,
                    machine,
                    frames.as_ref(),
                    Some((entry, actuals)),
                    Some(inference),
                );
                let mut combined: Option<Interval> = None;
                let mut combined_recipe: Option<IntegerRangeRecipe> = None;
                for (state, mut returns) in state_returns {
                    returns.sort_unstable_by_key(ExpressionObservation::key);
                    let mut environment = incoming.iter().find_map(|(symbol, environment)| {
                        (*symbol == state.symbol).then(|| environment.clone())
                    })?;
                    let mut walk = ArrivalWalk {
                        program,
                        machine,
                        frames: frames.as_ref(),
                        arrivals: Vec::new(),
                        observations: returns,
                        completed_children: Default::default(),
                        return_ranges: Some(inference),
                        collect_arrivals: false,
                    };
                    walk.state(state, &mut environment);
                    for observed in walk.observations {
                        match observed.site {
                            ValueObservationSite::Expression(_) => {
                                join_return(
                                    &mut combined,
                                    &mut combined_recipe,
                                    observed.interval?,
                                    observed.recipe,
                                );
                            }
                            ValueObservationSite::Invocation { target, arrivals } => {
                                if arrivals.is_empty() {
                                    return None;
                                }
                                let TransitionTargetNode::Named { path, .. } =
                                    program.statement_table.transition_target(target)
                                else {
                                    return None;
                                };
                                let (callee, entry) =
                                    crate::machine_calls::calls::machine_state_by_symbol(
                                        program,
                                        path.symbol,
                                    )?;
                                let parameters = program.state_parameters(entry);
                                for arrival in arrivals {
                                    if arrival.len() != parameters.len() {
                                        return None;
                                    }
                                    let actuals = parameters
                                        .iter()
                                        .zip(arrival)
                                        .filter_map(|(parameter, (interval, recipe))| {
                                            (!parameter.is_const
                                                && !parameter.is_mutable
                                                && program
                                                    .primitive_type_reference(
                                                        parameter.type_reference,
                                                    )
                                                    .is_some())
                                            .then_some((parameter.symbol, interval, recipe))
                                        })
                                        .collect::<Vec<_>>();
                                    let (interval, recipe) = inferred_normal_return_interval_in(
                                        program,
                                        callee,
                                        entry,
                                        target_primitive,
                                        &actuals,
                                        inference,
                                    )?;
                                    join_return(
                                        &mut combined,
                                        &mut combined_recipe,
                                        interval,
                                        recipe,
                                    );
                                }
                            }
                        }
                    }
                }
                let combined = combined?;
                (combined_recipe.is_some() || (combined.low.is_some() && combined.high.is_some()))
                    .then_some((combined, combined_recipe))
            }
        }
        pub(crate) mod transition_arguments {
            use super::super::meaning;
            use super::{
                ArithmeticDomain, BinaryOperator, ExpressionHandle, ExpressionNode, Machine, State,
                TransitionGuardNode, TransitionTargetNode, ValueEnvironment, analyze,
                narrow_environment_by_condition,
            };
            use crate::frozen_program::expression_table;
            use typed_trees::expression::UnaryOperator;
            use typed_trees::statement::TableTransition;

            pub(crate) fn integer_bounds(
                program: &dyn crate::CheckingInput,
                machine: &Machine,
                state: &State,
                transition: &TableTransition,
                expression: ExpressionHandle,
            ) -> Option<(i64, i64)> {
                let TransitionTargetNode::Named { arguments, .. } =
                    program.statement_table.transition_target(transition.target)
                else {
                    return None;
                };
                let arguments = program.statement_table.expression_handles(*arguments);
                if !arguments.contains(&expression)
                    || !arguments
                        .iter()
                        .all(|argument| stable_builtin_value(program, machine, state, *argument, 0))
                {
                    return None;
                }
                let mut environment = ValueEnvironment::new();
                if let TransitionGuardNode::When(condition) = transition.guard {
                    if !stable_builtin_value(program, machine, state, condition, 0) {
                        return None;
                    }
                    narrow_environment_by_condition(
                        program,
                        machine,
                        Some(state),
                        &mut environment,
                        condition,
                        true,
                    );
                }
                let mut diagnostics = Vec::new();
                let value = analyze(
                    program,
                    machine,
                    Some(state),
                    expression,
                    &environment,
                    None,
                    ArithmeticDomain::Exact,
                    "transition argument",
                    true,
                    false,
                    &mut diagnostics,
                )
                .value;
                let (minimum, maximum) = (value.interval.low?, value.interval.high?);
                (diagnostics.is_empty() && minimum <= maximum).then_some((minimum, maximum))
            }

            fn stable_builtin_value(
                program: &dyn crate::CheckingInput,
                machine: &Machine,
                state: &State,
                expression: ExpressionHandle,
                depth: usize,
            ) -> bool {
                let Some(node) = expression_table(program).expression_at_depth(expression, depth)
                else {
                    return false;
                };
                let stable =
                    |value| stable_builtin_value(program, machine, state, value, depth + 1);
                match node {
                    ExpressionNode::Name(_) => {
                        let Some(symbol) =
                            crate::queries::expression_traversal::single_segment_name_symbol(
                                program, expression,
                            )
                        else {
                            return false;
                        };
                        let is_parameter =
                            program.state_parameter_by_symbol(state, symbol).is_some();
                        let is_local = program.state_local_declaration(state, symbol).is_some();
                        is_parameter || is_local
                    }
                    ExpressionNode::Integer(_) | ExpressionNode::Boolean(_) => true,
                    ExpressionNode::Binary(binary) => {
                        let division_is_not_anonymous = binary.operator != BinaryOperator::Divide
                            || crate::value_custody::literals::anonymous_numeric_value(
                                program,
                                expression,
                                &mut |value| {
                                    crate::value_custody::literals::has_anonymous_operator_meaning(
                                        program, value,
                                    )
                                },
                            )
                            .is_none();
                        division_is_not_anonymous
                            && meaning::has_builtin_decomposed_guard_meaning(
                                program,
                                machine,
                                Some(state),
                                expression,
                            )
                            && stable(binary.left)
                            && stable(binary.right)
                    }
                    ExpressionNode::Unary(unary) if unary.operator == UnaryOperator::LogicalNot => {
                        stable(unary.operand)
                    }
                    ExpressionNode::Atomic(atomic) => stable(atomic.value),
                    _ => false,
                }
            }
        }
        pub(crate) use normal_returns::{ReturnInference, inferred_normal_return_interval};

        pub(crate) struct EvaluatedValue {
            interval: Interval,
            copied: CopiedIntegerValue,
        }

        pub fn arrival_integer_expression_bounds(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: usize,
            expression: ExpressionHandle,
        ) -> Option<(i64, i64)> {
            let (machine, state) = program.machine_state(machine_symbol, state_symbol)?;
            let statements = program.statement_table.statements(state.statement_nodes);
            if let Some(StatementNode::Transition(transition)) = statements.get(statement_index) {
                return transition_arguments::integer_bounds(
                    program, machine, state, transition, expression,
                );
            }
            if !matches!(statements.get(statement_index), Some(StatementNode::Expression(value)) if *value == expression)
            {
                return None;
            }
            occurrence_integer_expression_bounds(
                program,
                machine_symbol,
                state_symbol,
                statement_index,
                expression,
            )
        }

        pub fn occurrence_integer_expression_bounds(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: usize,
            expression: ExpressionHandle,
        ) -> Option<(i64, i64)> {
            occurrence_integer_bounds(
                program,
                machine_symbol,
                state_symbol,
                statement_index,
                vec![expression],
            )
            .get(expression)
        }

        #[derive(Default)]
        pub struct OccurrenceIntegerBounds {
            bounds: Vec<(ExpressionHandle, Option<(i64, i64)>)>,
        }

        impl OccurrenceIntegerBounds {
            pub fn get(&self, expression: ExpressionHandle) -> Option<(i64, i64)> {
                let position = self
                    .bounds
                    .binary_search_by_key(
                        &(expression.arena_index(), expression.generation()),
                        |(expression, _)| (expression.arena_index(), expression.generation()),
                    )
                    .ok()?;
                self.bounds[position].1
            }
        }

        pub fn occurrence_integer_bounds(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: usize,
            mut expressions: Vec<ExpressionHandle>,
        ) -> OccurrenceIntegerBounds {
            expressions.retain(|expression| expression.is_valid());
            expressions.sort_unstable_by_key(|expression| {
                (expression.arena_index(), expression.generation())
            });
            expressions.dedup();
            if expressions.is_empty() {
                return OccurrenceIntegerBounds::default();
            }
            let observations = expressions
                .into_iter()
                .map(ExpressionObservation::bounds)
                .collect();
            let Some(observations) = expression_observations(
                program,
                machine_symbol,
                state_symbol,
                Some(statement_index),
                observations,
            ) else {
                return OccurrenceIntegerBounds::default();
            };
            OccurrenceIntegerBounds {
                bounds: observations
                    .into_iter()
                    .filter_map(|observation| {
                        let expression = observation.expression()?;
                        let bounds = observation.interval.and_then(|interval| {
                            let (low, high) = (interval.low?, interval.high?);
                            (low <= high).then_some((low, high))
                        });
                        Some((expression, bounds))
                    })
                    .collect(),
            }
        }

        pub fn occurrence_integer_expression_recipe(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: usize,
            expression: ExpressionHandle,
        ) -> Option<IntegerRangeRecipe> {
            expression_observation(
                program,
                machine_symbol,
                state_symbol,
                Some(statement_index),
                expression,
            )?
            .recipe
        }

        pub(crate) fn occurrence_integer_child_values(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: usize,
            expression: ExpressionHandle,
        ) -> Option<Vec<super::super::expression_analysis::CheckedIntegerValue>> {
            Some(
                expression_observation(
                    program,
                    machine_symbol,
                    state_symbol,
                    Some(statement_index),
                    expression,
                )?
                .completed_children
                .into_values()
                .collect(),
            )
        }

        pub fn occurrence_integer_expressions_bounds(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: usize,
            expressions: &[ExpressionHandle],
        ) -> Vec<(ExpressionHandle, Option<(i64, i64)>)> {
            let bounds = occurrence_integer_bounds(
                program,
                machine_symbol,
                state_symbol,
                statement_index,
                expressions.to_vec(),
            );
            expressions
                .iter()
                .map(|expression| (*expression, bounds.get(*expression)))
                .collect()
        }

        pub fn occurrence_integer_expression_fits_range(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: usize,
            expression: ExpressionHandle,
            minimum: &numerics::bignum::BigInt,
            maximum: &numerics::bignum::BigInt,
        ) -> bool {
            let Some(observation) = expression_observation(
                program,
                machine_symbol,
                state_symbol,
                Some(statement_index),
                expression,
            ) else {
                return false;
            };
            let lower_proven = observation.interval.is_some_and(|interval| {
                interval
                    .low
                    .is_some_and(|low| numerics::bignum::BigInt::from_i64(low) >= *minimum)
            });
            let upper_proven = observation.interval.is_some_and(|interval| {
                interval
                    .high
                    .is_some_and(|high| numerics::bignum::BigInt::from_i64(high) <= *maximum)
            });
            if lower_proven && upper_proven {
                return true;
            }
            let Some(environment) = observation.environment else {
                return false;
            };
            let Some(machine) = program.machine(machine_symbol) else {
                return false;
            };
            let Some(state) = program.state_in_machine(machine, state_symbol) else {
                return false;
            };
            super::super::live_integer_constraints::proves_range(
                program,
                machine,
                state,
                &environment,
                expression,
                (!lower_proven).then_some(minimum),
                (!upper_proven).then_some(maximum),
            )
        }

        pub fn occurrence_collection_footprint_fits(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: usize,
            expression: ExpressionHandle,
            width: i64,
        ) -> bool {
            let Some(indexed) = expression_table(program).indexed_node(expression) else {
                return false;
            };
            let Some(environment) = expression_observation(
                program,
                machine_symbol,
                state_symbol,
                Some(statement_index),
                expression,
            )
            .and_then(|observation| observation.environment) else {
                return false;
            };
            let Some((machine, state)) = program.machine_state(machine_symbol, state_symbol) else {
                return false;
            };
            super::super::live_integer_constraints::proves_collection_footprint(
                program,
                machine,
                state,
                &environment,
                indexed.collection,
                indexed.index,
                width,
            )
        }

        pub(crate) fn occurrence_value_environment(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            expression: ExpressionHandle,
        ) -> Option<ValueEnvironment> {
            occurrence_value_environments(program, machine_symbol, state_symbol, vec![expression])
                .get(expression)
                .cloned()
        }

        #[derive(Default)]
        pub(crate) struct OccurrenceValueEnvironments {
            observations: Vec<ExpressionObservation>,
        }

        impl OccurrenceValueEnvironments {
            pub(crate) fn get(&self, expression: ExpressionHandle) -> Option<&ValueEnvironment> {
                let position = self
                    .observations
                    .binary_search_by_key(
                        &(0, expression.arena_index(), expression.generation()),
                        ExpressionObservation::key,
                    )
                    .ok()?;
                self.observations[position].environment.as_ref()
            }
        }

        pub(crate) fn occurrence_value_environments(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            mut expressions: Vec<ExpressionHandle>,
        ) -> OccurrenceValueEnvironments {
            expressions.retain(|expression| expression.is_valid());
            expressions.sort_unstable_by_key(|expression| {
                (expression.arena_index(), expression.generation())
            });
            expressions.dedup();
            if expressions.is_empty() {
                return OccurrenceValueEnvironments::default();
            }
            let Some((machine, state)) = program.machine_state(machine_symbol, state_symbol) else {
                return OccurrenceValueEnvironments::default();
            };
            let frames = CallFrameResolver::new(program);
            let mut environment =
                incoming_guard_environment(program, machine, state, frames.as_ref());
            let return_ranges = ReturnInference::default();
            let mut walk = ArrivalWalk {
                program,
                machine,
                frames: frames.as_ref(),
                arrivals: Vec::new(),
                observations: expressions
                    .into_iter()
                    .map(ExpressionObservation::environment)
                    .collect(),
                completed_children: Default::default(),
                return_ranges: Some(&return_ranges),
                collect_arrivals: false,
            };
            walk.state(state, &mut environment);
            OccurrenceValueEnvironments {
                observations: walk.observations,
            }
        }

        fn expression_observation(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: Option<usize>,
            expression: ExpressionHandle,
        ) -> Option<ExpressionObservation> {
            expression_observations(
                program,
                machine_symbol,
                state_symbol,
                statement_index,
                vec![ExpressionObservation::bounds(expression)],
            )?
            .pop()
        }

        fn expression_observations(
            program: &dyn crate::CheckingInput,
            machine_symbol: SymbolHandle,
            state_symbol: SymbolHandle,
            statement_index: Option<usize>,
            observations: Vec<ExpressionObservation>,
        ) -> Option<Vec<ExpressionObservation>> {
            let (machine, state) = program.machine_state(machine_symbol, state_symbol)?;
            let statements = program.statement_table.statements(state.statement_nodes);
            let order = program
                .statement_table
                .finite_execution_order(state.statement_nodes)
                .ok()??;
            let (prefix, single_target) = match statement_index {
                Some(index) => {
                    let position = order.iter().position(|source| *source == index)?;
                    (&order[..position], Some((index, &statements[index])))
                }
                None => (&order[..0], None),
            };
            let frames = CallFrameResolver::new(program);
            let mut environment =
                incoming_guard_environment(program, machine, state, frames.as_ref());
            let return_ranges = ReturnInference::default();
            let mut walk = ArrivalWalk {
                program,
                machine,
                frames: frames.as_ref(),
                arrivals: Vec::new(),
                observations: Vec::new(),
                completed_children: Default::default(),
                return_ranges: Some(&return_ranges),
                collect_arrivals: false,
            };
            if !walk.statements(
                state,
                prefix.iter().map(|index| (*index, &statements[*index])),
                &mut environment,
            ) {
                return None;
            }
            walk.observations = observations;
            if let Some((statement_index, statement)) = single_target {
                walk.observe_single_statement(state, statement_index, statement, &mut environment);
            } else {
                walk.statements(
                    state,
                    order.iter().map(|index| (*index, &statements[*index])),
                    &mut environment,
                );
            }
            Some(walk.observations)
        }

        pub(crate) fn incoming_environments(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            frames: Option<&CallFrameResolver>,
            invocation: Option<(
                &State,
                &[(SymbolHandle, Interval, Option<IntegerRangeRecipe>)],
            )>,
            return_ranges: Option<&ReturnInference<'_>>,
        ) -> Vec<(SymbolHandle, ValueEnvironment)> {
            let root_ranges = ReturnInference::default();
            let return_ranges =
                return_ranges.or_else(|| invocation.is_none().then_some(&root_ranges));
            let states = program.machine_states(machine);
            let mut current = states
                .iter()
                .map(|state| (state.symbol, ValueEnvironment::new()))
                .collect::<Vec<_>>();
            let machine_written = (states.len() > 1)
                .then(|| machine_written_paths(program, machine, frames))
                .flatten();
            let seeds = states
                .iter()
                .enumerate()
                .map(|(index, state)| {
                    RequirementSeeds::new(
                        program,
                        machine,
                        state,
                        frames,
                        index == 0,
                        machine_written.as_deref(),
                    )
                })
                .collect::<Vec<_>>();
            let has_in_machine_arrivals = states
                .iter()
                .map(|state| state_has_in_machine_arrivals(program, machine, state))
                .collect::<Vec<_>>();
            let external_index = invocation
                .and_then(|(entry, _)| typed_trees::state::state_position(states, entry.symbol))
                .unwrap_or(0);
            let external = states
                .get(external_index)
                .zip(seeds.get(external_index))
                .map(|(entry, entry_seeds)| {
                    let mut external = ValueEnvironment::new();
                    entry_seeds.apply(program, machine, entry, &mut external);
                    for parameter in program.state_parameters(entry) {
                        super::super::record_admitted_integer_fields(
                            program,
                            &mut external,
                            &super::ordered_values::Operand::parameter(parameter),
                            parameter.type_reference,
                        );
                        super::super::record_declared_float_fields(
                            program,
                            &mut external,
                            parameter.name.as_str(),
                            parameter.type_reference,
                        );
                    }
                    if let Some((_, actuals)) = invocation {
                        for parameter in program.state_parameters(entry) {
                            if parameter.is_mutable || parameter.is_const {
                                continue;
                            }
                            if let Some(carrier) = program
                                .primitive_type_reference(parameter.type_reference)
                                .and_then(super::super::primitive_range)
                                && let Some((_, actual, recipe)) = actuals
                                    .iter()
                                    .find(|(symbol, _, _)| *symbol == parameter.symbol)
                            {
                                external.narrow(
                                    parameter.name.as_str().to_owned(),
                                    carrier.intersect(*actual),
                                );
                                if let Some(recipe) = recipe {
                                    external.integer_ranges.push(
                                        super::super::value_environment::StoredIntegerRange {
                                            place: crate::value_custody::places::CanonicalPlace {
                                                root: facts::PlaceRoot::Symbol(parameter.symbol),
                                                segments: Vec::new(),
                                            },
                                            path: parameter.name.as_str().to_owned(),
                                            recipe: recipe.clone(),
                                        },
                                    );
                                }
                            }
                        }
                    }
                    external
                });
            if let Some(external) = &external
                && let Some((_, slot)) = current.get_mut(external_index)
            {
                *slot = external.clone();
            }
            let mut external_received_arrival = false;
            if has_in_machine_arrivals.iter().any(|&has| has) {
                let mut arrivals = vec![Vec::new(); states.len()];
                let mut stale = vec![true; states.len()];
                for round in 0..=states.len() {
                    for (index, ((state, (_, environment)), state_seeds)) in
                        states.iter().zip(&current).zip(&seeds).enumerate()
                    {
                        if !stale[index] || !has_in_machine_arrivals[index] {
                            continue;
                        }
                        let mut walk = ArrivalWalk {
                            program,
                            machine,
                            frames,
                            arrivals: Vec::new(),
                            observations: Vec::new(),
                            completed_children: Default::default(),
                            return_ranges,
                            collect_arrivals: true,
                        };
                        let mut environment = environment.clone();
                        if round > 0 || index != external_index || invocation.is_some() {
                            state_seeds.apply(program, machine, state, &mut environment);
                        }
                        walk.state(state, &mut environment);
                        arrivals[index] = walk.arrivals;
                    }
                    let mut joined: Vec<Option<ValueEnvironment>> = vec![None; states.len()];
                    if let Some(external) = &external {
                        joined[external_index] = Some(external.clone());
                    }
                    external_received_arrival = false;
                    for (target, environment) in arrivals.iter().flatten() {
                        if *target == external_index {
                            external_received_arrival = true;
                        }
                        joined[*target] = Some(match joined[*target].take() {
                            Some(previous) => previous.join(environment),
                            None => environment.clone(),
                        });
                    }
                    let next = states
                        .iter()
                        .zip(joined)
                        .map(|(state, environment)| (state.symbol, environment.unwrap_or_default()))
                        .collect::<Vec<_>>();
                    if next == current {
                        current = next;
                        break;
                    }
                    for ((stale, (_, next)), (_, current)) in
                        stale.iter_mut().zip(&next).zip(&current)
                    {
                        *stale = next != current;
                    }
                    current = next;
                }
            }
            for (index, ((state, (_, environment)), state_seeds)) in
                states.iter().zip(&mut current).zip(&seeds).enumerate()
            {
                if index == external_index && invocation.is_none() && !external_received_arrival {
                    continue;
                }
                state_seeds.apply(program, machine, state, environment);
            }
            current
        }

        pub(crate) enum ValueObservationSite {
            Expression(ExpressionHandle),
            Invocation {
                target: typed_trees::statement::TransitionTargetHandle,
                arrivals: Vec<Vec<(Interval, Option<IntegerRangeRecipe>)>>,
            },
        }

        pub(crate) struct ExpressionObservation {
            include_bounds: bool,
            recipe: Option<IntegerRangeRecipe>,
            site: ValueObservationSite,
            interval: Option<Interval>,
            environment: Option<ValueEnvironment>,
            completed_children:
                BTreeMap<(u32, u32), super::super::expression_analysis::CheckedIntegerValue>,
        }

        impl ExpressionObservation {
            fn invocation(target: typed_trees::statement::TransitionTargetHandle) -> Self {
                Self {
                    site: ValueObservationSite::Invocation {
                        target,
                        arrivals: Vec::new(),
                    },
                    ..Self::bounds(ExpressionHandle::invalid())
                }
            }

            fn expression(&self) -> Option<ExpressionHandle> {
                match self.site {
                    ValueObservationSite::Expression(expression) => Some(expression),
                    ValueObservationSite::Invocation { .. } => None,
                }
            }

            fn key(&self) -> (u8, u32, u32) {
                match self.site {
                    ValueObservationSite::Expression(expression) => {
                        (0, expression.arena_index(), expression.generation())
                    }
                    ValueObservationSite::Invocation { target, .. } => {
                        (1, target.arena_index(), target.generation())
                    }
                }
            }

            fn bounds(expression: ExpressionHandle) -> Self {
                Self {
                    include_bounds: true,
                    recipe: None,
                    site: ValueObservationSite::Expression(expression),
                    interval: None,
                    environment: None,
                    completed_children: Default::default(),
                }
            }

            fn environment(expression: ExpressionHandle) -> Self {
                Self {
                    include_bounds: false,
                    recipe: None,
                    site: ValueObservationSite::Expression(expression),
                    interval: None,
                    environment: None,
                    completed_children: Default::default(),
                }
            }
        }

        pub(crate) struct ArrivalWalk<'program, 'frames> {
            program: &'program dyn crate::CheckingInput,
            machine: &'program Machine,
            frames: Option<&'frames CallFrameResolver<'program>>,
            arrivals: Vec<(usize, ValueEnvironment)>,
            observations: Vec<ExpressionObservation>,
            completed_children:
                BTreeMap<(u32, u32), super::super::expression_analysis::CheckedIntegerValue>,
            return_ranges: Option<&'frames ReturnInference<'frames>>,
            collect_arrivals: bool,
        }

        impl ArrivalWalk<'_, '_> {
            fn join(&mut self, symbol: SymbolHandle, environment: ValueEnvironment) {
                if !symbol.is_valid() {
                    return;
                }
                let Some(index) = typed_trees::state::state_position(
                    self.program.machine_states(self.machine),
                    symbol,
                ) else {
                    return;
                };
                self.arrivals.push((index, environment));
            }

            fn evaluated_value(
                &self,
                source: &State,
                expression: ExpressionHandle,
                environment: &ValueEnvironment,
            ) -> EvaluatedValue {
                match self.checked_value(source, expression, environment) {
                    Some(analysis) => {
                        let mut values = analysis.decisions.expression_values;
                        if matches!(
                            expression_table(self.program).expression(expression),
                            ExpressionNode::StructLiteral(_) | ExpressionNode::ArrayLiteral(_)
                        ) {
                            values.retain(|value| {
                                !self.completed_children.contains_key(&(
                                    value.expression.arena_index(),
                                    value.expression.generation(),
                                ))
                            });
                            values.extend(self.completed_children.values().cloned());
                        }
                        EvaluatedValue {
                            interval: analysis.value.interval,
                            copied: CopiedIntegerValue::capture(
                                self.program,
                                self.machine,
                                Some(source),
                                expression,
                                declared_place_type_raw(
                                    self.program,
                                    self.machine,
                                    Some(source),
                                    expression,
                                )
                                .unwrap_or_default(),
                                environment,
                                &values,
                            ),
                        }
                    }
                    None => EvaluatedValue {
                        interval: Interval::UNBOUNDED,
                        copied: CopiedIntegerValue::default(),
                    },
                }
            }

            fn capture_completed_child(
                &mut self,
                source: &State,
                expression: ExpressionHandle,
                environment: &ValueEnvironment,
            ) {
                let primitive = crate::expression_result_type_reference(
                    self.program,
                    self.machine,
                    source,
                    expression,
                )
                .and_then(|reference| self.program.primitive_type_reference(reference));
                if !primitive.is_some_and(|primitive| primitive.is_fixed_integer()) {
                    return;
                }
                let analyzed = self.checked_value(source, expression, environment);
                let interval = analyzed
                    .as_ref()
                    .map_or(Interval::UNBOUNDED, |value| value.value.interval);
                let recipe = analyzed.and_then(|value| {
                    value
                        .value
                        .range_recipe(self.program, self.machine.symbol, expression)
                });
                let key = (expression.arena_index(), expression.generation());
                if let Some(previous) = self.completed_children.get_mut(&key) {
                    previous.interval = previous.interval.union(interval);
                    previous.recipe = previous
                        .recipe
                        .take()
                        .zip(recipe)
                        .map(|(left, right)| left.union(&right));
                } else {
                    self.completed_children.insert(
                        key,
                        super::super::expression_analysis::CheckedIntegerValue {
                            expression,
                            interval,
                            recipe,
                        },
                    );
                }
            }

            fn checked_value(
                &self,
                source: &State,
                expression: ExpressionHandle,
                environment: &ValueEnvironment,
            ) -> Option<CheckedAnalysis> {
                let mut diagnostics = Vec::new();
                let analysis = analyze_arrival(
                    self.program,
                    self.machine,
                    Some(source),
                    expression,
                    environment,
                    None,
                    ArithmeticDomain::Exact,
                    "state arrival",
                    self.return_ranges,
                    &mut diagnostics,
                );
                diagnostics.is_empty().then_some(analysis)
            }

            fn cross_writes(
                &self,
                source: &State,
                environment: &mut ValueEnvironment,
                written: Option<Vec<String>>,
            ) {
                if let Some(written) = written {
                    environment.invalidate_call_paths(self.program, Some(source), &written);
                } else {
                    environment.invalidate_unknown_writes(self.program, Some(source));
                }
            }

            /*
                A value that dies inside the statement (the one an assignment
                displaces, an unnamed temporary of an initializer) runs its
                `dropped by` hook, which may store through exclusive references
                the value held. Those places are neither the destination nor a
                call's summary, so they are retired here. Without a resolver the
                dying values cannot be named: a statement that builds or calls
                anything then has an unknown footprint.
            */
            fn statement_cleanup_writes(
                &self,
                source: &State,
                statement: &StatementNode,
                value: ExpressionHandle,
                environment: &mut ValueEnvironment,
            ) {
                match self.frames {
                    Some(frames) => {
                        let frame = frames.statement_cleanup_write_frame(self.machine, statement);
                        match frame.complete_paths() {
                            Some([]) => {}
                            Some(paths) => {
                                environment.invalidate_call_paths(self.program, Some(source), paths)
                            }
                            None => {
                                environment.invalidate_unknown_writes(self.program, Some(source))
                            }
                        }
                    }
                    None => {
                        if self.program.cleanup_selections().next().is_some()
                            && crate::executable_subtree_any(
                                self.program,
                                value,
                                typed_trees::SubtreeEdges::VALUES,
                                |_, node| match node {
                                    typed_trees::expression::ExpressionNode::Call(_)
                                    | typed_trees::expression::ExpressionNode::StructLiteral(_) => {
                                        typed_trees::SubtreeVisit::Found
                                    }
                                    _ => typed_trees::SubtreeVisit::Descend,
                                },
                            )
                        {
                            environment.invalidate_unknown_writes(self.program, Some(source));
                        }
                    }
                }
            }

            fn expression_effects(
                &self,
                source: &State,
                expression: ExpressionHandle,
                environment: &mut ValueEnvironment,
            ) {
                self.cross_writes(source, environment, self.expression_writes(expression));
            }

            fn expression_writes(&self, expression: ExpressionHandle) -> Option<Vec<String>> {
                self.frames
                    .and_then(|frames| frames.expression_may_write_paths(self.machine, expression))
            }

            fn should_arrive(&self, symbol: SymbolHandle) -> bool {
                self.collect_arrivals
                    && symbol.is_valid()
                    && self
                        .program
                        .machine_states(self.machine)
                        .iter()
                        .any(|state| state.symbol == symbol)
            }

            fn visit_call_or_target(
                &mut self,
                source: &State,
                symbol: SymbolHandle,
                arguments: &[ExpressionHandle],
                environment: &mut ValueEnvironment,
            ) {
                if self.should_arrive(symbol) {
                    let intervals = self.arguments(source, arguments, environment);
                    self.arrive(source, symbol, arguments, &intervals, environment);
                } else {
                    for argument in arguments {
                        self.expression(source, *argument, environment);
                    }
                }
            }

            fn arguments(
                &mut self,
                source: &State,
                arguments: &[ExpressionHandle],
                environment: &mut ValueEnvironment,
            ) -> Vec<EvaluatedValue> {
                arguments
                    .iter()
                    .map(|argument| {
                        self.expression(source, *argument, environment);
                        self.evaluated_value(source, *argument, environment)
                    })
                    .collect()
            }

            fn arrive(
                &mut self,
                source: &State,
                symbol: SymbolHandle,
                arguments: &[ExpressionHandle],
                values: &[EvaluatedValue],
                environment: &ValueEnvironment,
            ) {
                let Some(target) = self
                    .program
                    .machine_states(self.machine)
                    .iter()
                    .find(|state| state.symbol == symbol && symbol.is_valid())
                else {
                    return;
                };
                let parameters = self.program.state_parameters(target);
                if parameters.len() != arguments.len() {
                    self.join(symbol, ValueEnvironment::new());
                    return;
                }
                let mut bindings = Vec::new();
                let mut exact_bindings = Vec::new();
                for (parameter, argument) in parameters.iter().zip(arguments) {
                    if let Some(path) = self.bound_place(source, *argument) {
                        bindings.push((path, parameter.name.as_str().to_owned()));
                    }
                    if (!environment.ordered_values.is_empty()
                        || !environment.boolean_values.is_empty())
                        && let Some(value) = ordered_values::operand(
                            self.program,
                            self.machine,
                            source,
                            *argument,
                            self.frames,
                        )
                    {
                        exact_bindings.push((value, ordered_values::Operand::parameter(parameter)));
                    }
                }
                let mut rebound = environment.rebind(&bindings);
                for value in &environment.boolean_values {
                    rebound
                        .boolean_values
                        .extend(value.rebound(&bindings, &exact_bindings));
                }
                rebound.ordered_values =
                    ordered_values::rebind_relations(&environment.ordered_values, &exact_bindings);
                for (parameter, value) in parameters.iter().zip(values) {
                    if !is_reference(self.program, parameter.type_reference) {
                        let interval =
                            match enforced_declared_range(self.program, parameter.type_reference) {
                                Some(declared) => value.interval.intersect(declared),
                                None => value.interval,
                            };
                        rebound.set(parameter.name.as_str().to_owned(), interval);
                        value.copied.record(
                            &mut rebound,
                            Some(parameter.name.as_str().to_owned()),
                            Some(crate::value_custody::places::CanonicalPlace {
                                root: facts::PlaceRoot::Symbol(parameter.symbol),
                                segments: Vec::new(),
                            }),
                        );
                    }
                }
                self.join(symbol, rebound);
            }

            fn bound_place(&self, source: &State, expression: ExpressionHandle) -> Option<String> {
                match expression_table(self.program).expression(expression) {
                    ExpressionNode::Name(path)
                        if path.symbol.is_valid() && path.head_symbol.is_valid() =>
                    {
                        let root = self
                            .program
                            .state_parameter_by_symbol(source, path.head_symbol)
                            .is_some()
                            || self
                                .program
                                .state_local_declaration(source, path.head_symbol)
                                .is_some();
                        root.then(|| place_path(self.program, expression)).flatten()
                    }
                    ExpressionNode::Member(member) if member.member_symbol.is_valid() => {
                        self.bound_place(source, member.receiver)?;
                        place_path(self.program, expression)
                    }
                    ExpressionNode::Borrow(borrow) => self.bound_place(source, borrow.target),
                    _ => None,
                }
            }

            fn target_needs_walk(
                &self,
                target: typed_trees::statement::TransitionTargetHandle,
            ) -> bool {
                if !target.is_valid() {
                    return false;
                }
                match self.program.statement_table.transition_target(target) {
                    TransitionTargetNode::Terminal => false,
                    TransitionTargetNode::Named {
                        path, arguments, ..
                    } => {
                        !self.observations.is_empty()
                            || self.should_arrive(path.symbol)
                            || (self.collect_arrivals
                                && self
                                    .program
                                    .statement_table
                                    .expression_handles(*arguments)
                                    .iter()
                                    .any(|argument| {
                                        crate::machine_calls::calls::expression_has_calls(
                                            self.program,
                                            *argument,
                                        )
                                    }))
                    }
                    TransitionTargetNode::Value(expression) => {
                        !self.observations.is_empty()
                            || (self.collect_arrivals
                                && crate::machine_calls::calls::expression_has_calls(
                                    self.program,
                                    *expression,
                                ))
                    }
                }
            }

            fn target(
                &mut self,
                source: &State,
                target: typed_trees::statement::TransitionTargetHandle,
                environment: &mut ValueEnvironment,
            ) {
                if !target.is_valid() {
                    return;
                }
                match self.program.statement_table.transition_target(target) {
                    TransitionTargetNode::Named {
                        path, arguments, ..
                    } => {
                        let arguments = self.program.statement_table.expression_handles(*arguments);
                        if let Ok(position) = self.observations.binary_search_by_key(
                            &(1, target.arena_index(), target.generation()),
                            ExpressionObservation::key,
                        ) {
                            let values = self.arguments(source, arguments, environment);
                            if let ValueObservationSite::Invocation { arrivals, .. } =
                                &mut self.observations[position].site
                            {
                                arrivals.push(
                                    values
                                        .into_iter()
                                        .map(|value| {
                                            (
                                                value.interval,
                                                value.copied.integer_range_recipe().cloned(),
                                            )
                                        })
                                        .collect(),
                                );
                            }
                        } else {
                            self.visit_call_or_target(source, path.symbol, arguments, environment);
                        }
                    }
                    TransitionTargetNode::Value(expression) => {
                        self.expression(source, *expression, environment)
                    }
                    TransitionTargetNode::Terminal => {}
                }
            }

            fn state(&mut self, source: &State, environment: &mut ValueEnvironment) -> bool {
                let Ok(Some(order)) = self
                    .program
                    .statement_table
                    .finite_execution_order(source.statement_nodes)
                else {
                    return false;
                };
                let statements = self
                    .program
                    .statement_table
                    .statements(source.statement_nodes);
                self.statements(
                    source,
                    order.iter().map(|index| (*index, &statements[*index])),
                    environment,
                )
            }

            fn statements<'statement>(
                &mut self,
                source: &State,
                statements: impl IntoIterator<Item = (usize, &'statement StatementNode)>,
                environment: &mut ValueEnvironment,
            ) -> bool {
                for (statement_index, statement) in statements {
                    self.completed_children.clear();
                    match statement {
                        StatementNode::Transition(transition) => {
                            let target_needs_walk = self.target_needs_walk(transition.target);
                            let continuation_needs_walk =
                                self.target_needs_walk(transition.continuation);
                            let continues_to_next_statement = !transition.continuation.is_valid()
                                && transition.guard != TransitionGuardNode::Always;
                            let condition_needs_walk = match transition.guard {
                                TransitionGuardNode::When(condition) => {
                                    !self.observations.is_empty()
                                        || (self.collect_arrivals
                                            && crate::machine_calls::calls::expression_has_calls(
                                                self.program,
                                                condition,
                                            ))
                                }
                                TransitionGuardNode::Always => false,
                            };
                            if !target_needs_walk
                                && !continuation_needs_walk
                                && !continues_to_next_statement
                                && !condition_needs_walk
                            {
                                return false;
                            }
                            environment.prepare_numeric_observations(
                                self.program,
                                self.machine,
                                source,
                                statement_index,
                            );
                            let mut selected = None;
                            let mut fallback = None;
                            if let TransitionGuardNode::When(condition) = transition.guard {
                                if target_needs_walk {
                                    selected = Some(super::evaluated_condition_environment(
                                        self.program,
                                        self.machine,
                                        Some(source),
                                        condition,
                                        true,
                                        environment,
                                    ));
                                }
                                if continuation_needs_walk || continues_to_next_statement {
                                    fallback = Some(super::evaluated_condition_environment(
                                        self.program,
                                        self.machine,
                                        Some(source),
                                        condition,
                                        false,
                                        environment,
                                    ));
                                }
                                if condition_needs_walk {
                                    self.expression(source, condition, environment);
                                }
                            }
                            if target_needs_walk {
                                let mut selected_env =
                                    selected.unwrap_or_else(|| environment.clone());
                                self.target(source, transition.target, &mut selected_env);
                            }
                            if continuation_needs_walk {
                                let mut fallback_env = fallback
                                    .as_ref()
                                    .cloned()
                                    .unwrap_or_else(|| environment.clone());
                                self.target(source, transition.continuation, &mut fallback_env);
                            }
                            if !continues_to_next_statement {
                                return false;
                            }
                            if let Some(fallback_env) = fallback {
                                *environment = fallback_env;
                            }
                            continue;
                        }
                        StatementNode::Expression(expression) => {
                            if self.observations.is_empty()
                                && !(self.collect_arrivals
                                    && crate::machine_calls::calls::expression_has_calls(
                                        self.program,
                                        *expression,
                                    ))
                            {
                                continue;
                            }
                        }
                        StatementNode::Assembly(_) | StatementNode::AssemblyFact(_) => {
                            continue;
                        }
                        _ => {}
                    }
                    environment.prepare_numeric_observations(
                        self.program,
                        self.machine,
                        source,
                        statement_index,
                    );
                    match statement {
                        StatementNode::Transition(_) => unreachable!(),
                        StatementNode::LocalData(local) => {
                            if local.role == language_core::LocalBindingRole::AtomicObservedResult {
                                record_assignment(
                                    environment,
                                    Some(local.name.to_string()),
                                    Interval::UNBOUNDED,
                                    None,
                                );
                                continue;
                            }
                            self.expression(source, local.initial_value, environment);
                            let copied_float = super::super::capture_float_assignment(
                                self.program,
                                self.machine,
                                Some(source),
                                environment,
                                self.program.primitive_type_reference(local.type_reference),
                                local.initial_value,
                            );
                            let mut value =
                                self.evaluated_value(source, local.initial_value, environment);
                            let path = local.name.as_str().to_owned();
                            value.copied.capture_local_relations(
                                self.program,
                                self.machine,
                                Some(source),
                                local,
                                environment,
                            );
                            self.statement_cleanup_writes(
                                source,
                                statement,
                                local.initial_value,
                                environment,
                            );
                            environment.invalidate_written_paths(std::slice::from_ref(&path));
                            environment.set(path.clone(), value.interval);
                            super::super::publish_slice_length(
                                self.program,
                                self.machine,
                                Some(source),
                                environment,
                                &path,
                                local.symbol,
                                local.initial_value,
                            );
                            value.copied.record(
                                environment,
                                Some(path.clone()),
                                Some(crate::value_custody::places::CanonicalPlace {
                                    root: facts::PlaceRoot::Symbol(local.symbol),
                                    segments: Vec::new(),
                                }),
                            );
                            super::super::record_float_assignment(
                                environment,
                                Some(path.clone()),
                                copied_float,
                            );
                            if local.initial_value.is_valid() {
                                if crate::reference_shell(self.program, local.type_reference)
                                    .is_none()
                                {
                                    super::super::record_admitted_integer_fields(
                                        self.program,
                                        environment,
                                        &super::ordered_values::Operand::Place {
                                            root: local.symbol,
                                            path: path.clone(),
                                        },
                                        local.type_reference,
                                    );
                                }
                                super::super::record_declared_float_fields(
                                    self.program,
                                    environment,
                                    &path,
                                    local.type_reference,
                                );
                            }
                            super::boolean_values::record_boolean_local(
                                self.program,
                                self.machine,
                                Some(source),
                                environment,
                                local,
                            );
                            record_unsigned_literal_assignment(
                                self.program,
                                environment,
                                Some(path),
                                self.program.primitive_type_reference(local.type_reference),
                                local.initial_value,
                            );
                        }
                        StatementNode::Assignment(assignment) => {
                            self.expression(source, assignment.target, environment);
                            self.expression(source, assignment.value, environment);
                            if let Some(event) =
                                crate::atomic_assignment_carrier(self.program, assignment)
                            {
                                let written = self.frames.and_then(|frames| {
                                    frames
                                        .assignment_write_frame(self.machine, statement)
                                        .into_complete_paths()
                                });
                                if let Some(written) = written {
                                    environment.invalidate_assignment_paths(
                                        self.program,
                                        self.machine,
                                        Some(source),
                                        statement,
                                        self.frames,
                                        &written,
                                    );
                                } else {
                                    environment
                                        .invalidate_unknown_writes(self.program, Some(source));
                                }
                                let observed = super::super::atomic_resident_interval(
                                    self.program,
                                    self.machine,
                                    Some(source),
                                    event.place,
                                )
                                .unwrap_or(Interval::UNBOUNDED);
                                record_assignment(
                                    environment,
                                    place_path(self.program, event.place),
                                    observed,
                                    None,
                                );
                                if event.result.is_valid() {
                                    record_assignment(
                                        environment,
                                        place_path(self.program, event.result),
                                        observed,
                                        None,
                                    );
                                }
                                continue;
                            }

                            let copied_float = super::super::capture_float_assignment(
                                self.program,
                                self.machine,
                                Some(source),
                                environment,
                                declared_place_type_raw(
                                    self.program,
                                    self.machine,
                                    Some(source),
                                    assignment.target,
                                )
                                .map(|reference| {
                                    crate::value_custody::places::assignment_value_type(
                                        self.program,
                                        reference,
                                    )
                                })
                                .and_then(|reference| {
                                    self.program.primitive_type_reference(reference)
                                }),
                                assignment.value,
                            );
                            let mut value =
                                self.evaluated_value(source, assignment.value, environment);
                            let written = self.frames.and_then(|frames| {
                                frames
                                    .assignment_write_frame(self.machine, statement)
                                    .into_complete_paths()
                            });
                            let destination_is_current = written.is_some()
                                && self.frames.is_some_and(|frames| {
                                    frames.assignment_destination_remains_current(
                                        self.machine,
                                        statement,
                                    )
                                });
                            if let Some(written) = written {
                                value.copied.capture_assignment_relations(
                                    self.program,
                                    self.machine,
                                    source,
                                    statement,
                                    self.frames,
                                    &written,
                                    environment,
                                );
                                environment.invalidate_assignment_paths(
                                    self.program,
                                    self.machine,
                                    Some(source),
                                    statement,
                                    self.frames,
                                    &written,
                                );
                            } else {
                                environment.invalidate_unknown_writes(self.program, Some(source));
                            }
                            self.statement_cleanup_writes(
                                source,
                                statement,
                                assignment.value,
                                environment,
                            );
                            if destination_is_current {
                                let path =
                                    self.bound_place(source, assignment.target).or_else(|| {
                                        crate::exact_self_field(
                                            self.program,
                                            self.machine,
                                            assignment.target,
                                        )
                                        .and_then(|_| place_path(self.program, assignment.target))
                                    });
                                let reference = declared_place_type_raw(
                                    self.program,
                                    self.machine,
                                    Some(source),
                                    assignment.target,
                                )
                                .map(|reference| {
                                    crate::value_custody::places::assignment_value_type(
                                        self.program,
                                        reference,
                                    )
                                });
                                record_assignment(
                                    environment,
                                    path.clone(),
                                    value.interval,
                                    reference.and_then(|reference| {
                                        enforced_declared_range(self.program, reference)
                                    }),
                                );
                                if let Some(path) = path.as_deref() {
                                    super::super::publish_slice_length(
                                        self.program,
                                        self.machine,
                                        Some(source),
                                        environment,
                                        path,
                                        root_symbol(self.program, assignment.target, path),
                                        assignment.value,
                                    );
                                }
                                value.copied.record(
                                    environment,
                                    path.clone(),
                                    crate::value_custody::places::canonical_place_from_expression(
                                        self.program,
                                        assignment.target,
                                    ),
                                );
                                super::super::record_float_assignment(
                                    environment,
                                    path.clone(),
                                    copied_float,
                                );
                                if let (Some(path), Some(reference)) = (path.as_deref(), reference)
                                {
                                    if crate::reference_shell(self.program, reference).is_none()
                                        && let Some(destination) = super::ordered_values::operand(
                                            self.program,
                                            self.machine,
                                            source,
                                            assignment.target,
                                            None,
                                        )
                                    {
                                        super::super::record_admitted_integer_fields(
                                            self.program,
                                            environment,
                                            &destination,
                                            reference,
                                        );
                                    }
                                    super::super::record_declared_float_fields(
                                        self.program,
                                        environment,
                                        path,
                                        reference,
                                    );
                                }
                                let primitive = reference.and_then(|reference| {
                                    self.program.primitive_type_reference(reference)
                                });
                                super::boolean_values::record_boolean_assignment(
                                    self.program,
                                    self.machine,
                                    Some(source),
                                    environment,
                                    assignment.target,
                                    assignment.value,
                                );
                                record_unsigned_literal_assignment(
                                    self.program,
                                    environment,
                                    path,
                                    primitive,
                                    assignment.value,
                                );
                            }
                        }
                        StatementNode::Call(call) => {
                            let operand_written = self.frames.and_then(|frames| {
                                frames.statement_value_may_write_paths(self.machine, statement)
                            });
                            let arguments = self
                                .program
                                .statement_table
                                .expression_handles(call.arguments);
                            self.visit_call_or_target(
                                source,
                                call.target_symbol,
                                arguments,
                                environment,
                            );
                            self.cross_writes(
                                source,
                                environment,
                                self.frames
                                    .and_then(|frames| frames.may_write_paths(self.machine, call)),
                            );
                            if let Some(signature) =
                                crate::machine_calls::calls::boundary_trait_signature(
                                    self.program,
                                    self.machine,
                                    call,
                                )
                            {
                                super::seed_out_param_ensures(
                                    self.program,
                                    self.machine,
                                    Some(source),
                                    call,
                                    signature,
                                    environment,
                                );
                            } else {
                                super::super::seed_cited_element_bounds(
                                    self.program,
                                    self.machine,
                                    Some(source),
                                    call,
                                    operand_written.as_deref(),
                                    environment,
                                );
                            }
                        }
                        StatementNode::Expression(expression) => {
                            self.expression(source, *expression, environment)
                        }
                        StatementNode::Assembly(_) | StatementNode::AssemblyFact(_) => {}
                    }
                }
                true
            }

            fn observe_single_statement(
                &mut self,
                source: &State,
                statement_index: usize,
                statement: &StatementNode,
                environment: &mut ValueEnvironment,
            ) {
                self.completed_children.clear();
                if !matches!(statement, StatementNode::Transition(_)) {
                    environment.prepare_numeric_observations(
                        self.program,
                        self.machine,
                        source,
                        statement_index,
                    );
                }
                match statement {
                    StatementNode::Transition(_) => {
                        self.statements(
                            source,
                            std::iter::once((statement_index, statement)),
                            environment,
                        );
                    }
                    StatementNode::LocalData(local) => {
                        if let Some(initializer) = local.ordinary_value_initializer() {
                            self.expression(source, initializer, environment);
                        }
                    }
                    StatementNode::Assignment(assignment) => {
                        self.expression(source, assignment.target, environment);
                        self.expression(source, assignment.value, environment);
                    }
                    StatementNode::Call(call) => {
                        let arguments = self
                            .program
                            .statement_table
                            .expression_handles(call.arguments);
                        for argument in arguments {
                            self.expression(source, *argument, environment);
                        }
                    }
                    StatementNode::Expression(expression) => {
                        self.expression(source, *expression, environment);
                    }
                    StatementNode::Assembly(_) | StatementNode::AssemblyFact(_) => {}
                }
            }

            fn expression(
                &mut self,
                source: &State,
                expression: ExpressionHandle,
                environment: &mut ValueEnvironment,
            ) {
                if !expression.is_valid() {
                    return;
                }
                match expression_table(self.program).expression(expression) {
                    ExpressionNode::Match(dispatch) => {
                        self.expression(source, dispatch.subject, environment);
                        let mut prefix =
                            super::super::evaluated_writes::EvaluatedWritePrefix::default();
                        prefix.extend(self.expression_writes(dispatch.subject));
                        let mut remaining = environment.clone();
                        let mut joined: Option<ValueEnvironment> = None;
                        let mut boolean_values = [false; 2];
                        for arm in expression_table(self.program).match_arms(dispatch.arms) {
                            let pattern = match arm.pattern {
                                typed_trees::expression::MatchPattern::Value(pattern) => {
                                    if let Some(value) =
                                        expression_table(self.program).boolean_node(pattern)
                                    {
                                        boolean_values[usize::from(*value)] = true;
                                    }
                                    Some(pattern)
                                }
                                typed_trees::expression::MatchPattern::Destructure(pattern) => {
                                    Some(pattern.condition)
                                }
                                typed_trees::expression::MatchPattern::Wildcard => None,
                            };
                            if let Some(pattern) = pattern {
                                self.expression(source, pattern, &mut remaining);
                                prefix.extend(self.expression_writes(pattern));
                            }
                            let mut selected =
                                super::super::dispatch_environments::dispatch_arm_context(
                                    expression,
                                    dispatch.subject,
                                    arm.pattern,
                                    &mut remaining,
                                    &mut |_, _| true,
                                    &mut |selected, selection| {
                                        super::super::dispatch_environments::narrow_dispatch_selection(
                                        self.program,
                                        self.machine,
                                        Some(source),
                                        dispatch,
                                        selected,
                                        selection,
                                    );
                                        selected.invalidate_call_prefix(
                                            self.program,
                                            Some(source),
                                            &prefix,
                                        );
                                    },
                                );
                            self.expression(source, arm.value, &mut selected);
                            joined =
                                Some(joined.map_or_else(
                                    || selected.clone(),
                                    |joined| joined.join(&selected),
                                ));
                            if matches!(
                                arm.pattern,
                                typed_trees::expression::MatchPattern::Wildcard
                            ) || boolean_values == [true, true]
                            {
                                break;
                            }
                        }
                        if let Some(joined) = joined {
                            *environment = joined;
                        }
                    }
                    ExpressionNode::Call(call) => {
                        self.expression(source, call.receiver, environment);
                        let arguments =
                            expression_table(self.program).expression_handles(call.arguments);
                        self.visit_call_or_target(
                            source,
                            call.target_symbol,
                            arguments,
                            environment,
                        );
                        self.expression_effects(source, expression, environment);
                    }
                    ExpressionNode::Binary(binary) => {
                        self.expression(source, binary.left, environment);
                        if matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or) {
                            let skipped = environment.clone();
                            self.expression(source, binary.right, environment);
                            *environment = skipped.join(environment);
                        } else {
                            self.expression(source, binary.right, environment);
                        }
                    }
                    ExpressionNode::Unary(unary) => {
                        self.expression(source, unary.operand, environment)
                    }
                    ExpressionNode::Member(member) => {
                        self.expression(source, member.receiver, environment)
                    }
                    ExpressionNode::Indexed(indexed) => {
                        self.expression(source, indexed.collection, environment);
                        self.expression(source, indexed.index, environment);
                    }
                    ExpressionNode::Atomic(atomic) => {
                        self.expression(source, atomic.value, environment)
                    }
                    ExpressionNode::Cast(cast) => self.expression(source, cast.value, environment),
                    ExpressionNode::Borrow(borrow) => {
                        self.expression(source, borrow.target, environment)
                    }
                    ExpressionNode::Range(range) => {
                        self.expression(source, range.start, environment);
                        self.expression(source, range.end, environment);
                    }
                    ExpressionNode::ArrayLiteral(values) => {
                        let capture_children =
                            self.observations.iter().any(|obs| obs.include_bounds)
                                || crate::machine_calls::calls::expression_has_calls(
                                    self.program,
                                    expression,
                                );
                        for value in expression_table(self.program).expression_handles(*values) {
                            self.expression(source, *value, environment);
                            if capture_children {
                                self.capture_completed_child(source, *value, environment);
                            }
                        }
                    }
                    ExpressionNode::StructLiteral(literal) => {
                        let capture_children =
                            self.observations.iter().any(|obs| obs.include_bounds)
                                || crate::machine_calls::calls::expression_has_calls(
                                    self.program,
                                    expression,
                                );
                        for field in expression_table(self.program).struct_fields(literal.fields) {
                            self.expression(source, field.value, environment);
                            if capture_children {
                                self.capture_completed_child(source, field.value, environment);
                            }
                        }
                    }
                    ExpressionNode::TypeExpression(_)
                    | ExpressionNode::SavedSubject(_)
                    | typed_trees::literal_expression_pattern!() => {}
                }
                if let Ok(position) = self.observations.binary_search_by_key(
                    &(0, expression.arena_index(), expression.generation()),
                    ExpressionObservation::key,
                ) {
                    let mut observed = environment.clone();
                    self.expression_effects(source, expression, &mut observed);
                    let include_bounds = self.observations[position].include_bounds;
                    let analyzed = include_bounds
                        .then(|| self.checked_value(source, expression, &observed))
                        .flatten();
                    let interval = analyzed
                        .as_ref()
                        .map_or(Interval::UNBOUNDED, |value| value.value.interval);
                    let recipe = analyzed.and_then(|value| {
                        value
                            .value
                            .range_recipe(self.program, self.machine.symbol, expression)
                    });
                    let observation = &mut self.observations[position];
                    if include_bounds
                        && matches!(
                            expression_table(self.program).expression(expression),
                            ExpressionNode::StructLiteral(_) | ExpressionNode::ArrayLiteral(_)
                        )
                    {
                        for (key, value) in &self.completed_children {
                            if let Some(previous) = observation.completed_children.get_mut(key) {
                                previous.interval = previous.interval.union(value.interval);
                                previous.recipe = previous
                                    .recipe
                                    .take()
                                    .zip(value.recipe.clone())
                                    .map(|(left, right)| left.union(&right));
                            } else {
                                observation.completed_children.insert(*key, value.clone());
                            }
                        }
                    }
                    if include_bounds {
                        observation.recipe = if observation.interval.is_none() {
                            recipe
                        } else {
                            observation
                                .recipe
                                .take()
                                .zip(recipe)
                                .map(|(left, right)| left.union(&right))
                        };
                        observation.interval = Some(
                            observation
                                .interval
                                .map_or(interval, |prior| prior.union(interval)),
                        );
                    }
                    observation.environment = Some(match observation.environment.take() {
                        Some(prior) => prior.join(&observed),
                        None => observed,
                    });
                }
            }
        }

        fn root_symbol(
            program: &dyn crate::CheckingInput,
            target: typed_trees::expression::ExpressionHandle,
            path: &str,
        ) -> symbols::SymbolHandle {
            let Some(place) =
                crate::value_custody::places::canonical_place_from_expression(program, target)
            else {
                return symbols::SymbolHandle::default();
            };
            let facts::PlaceRoot::Symbol(symbol) = place.root else {
                return symbols::SymbolHandle::default();
            };
            if !place.segments.is_empty() || place.label(program) != path {
                return symbols::SymbolHandle::default();
            }
            symbol
        }

        fn is_reference(
            program: &dyn crate::CheckingInput,
            reference: TypeReferenceHandle,
        ) -> bool {
            match program.type_reference_table.type_reference(reference) {
                TypeReferenceNode::Reference { .. } => true,
                TypeReferenceNode::Constrained { base_type, .. } => {
                    is_reference(program, *base_type)
                }
                _ => false,
            }
        }

        fn state_has_in_machine_arrivals(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
        ) -> bool {
            let states = program.machine_states(machine);
            let is_machine_state = |symbol: SymbolHandle| {
                symbol.is_valid() && states.iter().any(|candidate| candidate.symbol == symbol)
            };
            let mut stack = Vec::new();
            for statement in program.statement_table.statements(state.statement_nodes) {
                match statement {
                    StatementNode::Transition(transition) => {
                        if let TransitionGuardNode::When(condition) = transition.guard {
                            stack.push(condition);
                        }
                        for target in [transition.target, transition.continuation] {
                            if !target.is_valid() {
                                continue;
                            }
                            match program.statement_table.transition_target(target) {
                                TransitionTargetNode::Named {
                                    path, arguments, ..
                                } => {
                                    if is_machine_state(path.symbol) {
                                        return true;
                                    }
                                    stack.extend_from_slice(
                                        program.statement_table.expression_handles(*arguments),
                                    );
                                }
                                TransitionTargetNode::Value(expression) => stack.push(*expression),
                                TransitionTargetNode::Terminal => {}
                            }
                        }
                    }
                    StatementNode::LocalData(local) => {
                        if let Some(initializer) = local.ordinary_value_initializer() {
                            stack.push(initializer);
                        }
                    }
                    StatementNode::Assignment(assignment) => {
                        stack.push(assignment.target);
                        stack.push(assignment.value);
                    }
                    StatementNode::Call(call) => {
                        if is_machine_state(call.target_symbol) {
                            return true;
                        }
                        stack.extend_from_slice(
                            program.statement_table.expression_handles(call.arguments),
                        );
                    }
                    StatementNode::Expression(expression) => stack.push(*expression),
                    StatementNode::Assembly(_) | StatementNode::AssemblyFact(_) => {}
                }
            }
            while let Some(expression) = stack.pop() {
                if !expression.is_valid() {
                    continue;
                }
                match expression_table(program).expression(expression) {
                    ExpressionNode::Match(dispatch) => {
                        stack.push(dispatch.subject);
                        for arm in expression_table(program).match_arms(dispatch.arms) {
                            if let typed_trees::expression::MatchPattern::Value(pattern) =
                                arm.pattern
                            {
                                stack.push(pattern);
                            }
                            stack.push(arm.value);
                        }
                    }
                    ExpressionNode::Call(call) => {
                        if is_machine_state(call.target_symbol) {
                            return true;
                        }
                        stack.push(call.receiver);
                        stack.extend_from_slice(
                            expression_table(program).expression_handles(call.arguments),
                        );
                    }
                    ExpressionNode::Binary(binary) => {
                        stack.push(binary.left);
                        stack.push(binary.right);
                    }
                    ExpressionNode::Unary(unary) => stack.push(unary.operand),
                    ExpressionNode::Member(member) => stack.push(member.receiver),
                    ExpressionNode::Indexed(indexed) => {
                        stack.push(indexed.collection);
                        stack.push(indexed.index);
                    }
                    ExpressionNode::Atomic(atomic) => stack.push(atomic.value),
                    ExpressionNode::Cast(cast) => stack.push(cast.value),
                    ExpressionNode::Borrow(borrow) => stack.push(borrow.target),
                    ExpressionNode::Range(range) => {
                        stack.push(range.start);
                        stack.push(range.end);
                    }
                    ExpressionNode::ArrayLiteral(values) => {
                        stack.extend_from_slice(
                            expression_table(program).expression_handles(*values),
                        );
                    }
                    ExpressionNode::StructLiteral(literal) => {
                        for field in expression_table(program).struct_fields(literal.fields) {
                            stack.push(field.value);
                        }
                    }
                    ExpressionNode::TypeExpression(_)
                    | ExpressionNode::SavedSubject(_)
                    | typed_trees::literal_expression_pattern!() => {}
                }
            }
            false
        }

        #[cfg(test)]
        pub(crate) mod tests {
            use super::*;
            use checked_trees::IntegerRangeRecipe;
            use numerics::{bignum::BigInt, literals::IntegerLiteral};

            #[test]
            fn scalar_reevaluation_does_not_consume_an_earlier_child_recipe() {
                let mut program = typed_trees::TypedTrees::default();
                let expression = program
                    .expression_table
                    .insert(ExpressionNode::Integer(IntegerLiteral::from_value(8)));
                let machine = Machine::default();
                let state = State::default();
                let mut walk = ArrivalWalk {
                    program: &program,
                    machine: &machine,
                    frames: None,
                    arrivals: Vec::new(),
                    observations: Vec::new(),
                    completed_children: Default::default(),
                    return_ranges: None,
                    collect_arrivals: false,
                };
                walk.completed_children.insert(
                    (expression.arena_index(), expression.generation()),
                    super::super::super::expression_analysis::CheckedIntegerValue {
                        expression,
                        interval: Interval {
                            low: Some(7),
                            high: Some(7),
                        },
                        recipe: Some(IntegerRangeRecipe::bounds(
                            BigInt::from_i64(7),
                            BigInt::from_i64(7),
                        )),
                    },
                );
                let current = walk.evaluated_value(&state, expression, &ValueEnvironment::new());
                assert_eq!(
                    current.interval,
                    Interval {
                        low: Some(8),
                        high: Some(8)
                    }
                );
                let mut destination = ValueEnvironment::new();
                current.copied.record(
                    &mut destination,
                    Some("destination".to_owned()),
                    Some(crate::CanonicalPlace {
                        root: facts::PlaceRoot::Symbol(SymbolHandle::from_arena_index(1)),
                        segments: Vec::new(),
                    }),
                );
                assert!(
                    destination.integer_ranges.is_empty(),
                    "an ordinary scalar consumed stale child recipe7"
                );
            }
        }
    }
    pub(crate) mod boolean_values {
        use super::super::ordered_values::{Operand, Relation, rebind_relations};
        use super::super::value_environment::{IeeeConditionalFacts, rebound_paths};
        use super::{ExpressionHandle, Machine, State, ValueEnvironment};
        use typed_trees::types::PrimitiveType;

        #[derive(Debug, Clone, PartialEq)]
        pub(crate) struct ConditionalEvidence {
            pub(crate) relations: Vec<Relation>,
            pub(crate) ieee: IeeeConditionalFacts,
        }

        impl ConditionalEvidence {
            fn is_empty(&self) -> bool {
                self.relations.is_empty() && self.ieee.is_empty()
            }
        }

        #[derive(Debug, Clone, PartialEq)]
        pub(crate) struct BooleanValue {
            pub(crate) binding: Operand,
            pub(crate) alternatives: [ConditionalEvidence; 2],
        }

        impl BooleanValue {
            pub(crate) fn rebound(
                &self,
                bindings: &[(String, String)],
                exact_bindings: &[(Operand, Operand)],
            ) -> Vec<Self> {
                let targets = self.binding.rebound(exact_bindings);
                if targets.is_empty() {
                    return Vec::new();
                }
                let paths = |path: &str| rebound_paths(path, bindings);
                let alternatives = self.alternatives.each_ref().map(|evidence| {
                    let relations = rebind_relations(&evidence.relations, exact_bindings);
                    ConditionalEvidence {
                        relations,
                        ieee: evidence.ieee.rebound(&paths),
                    }
                });
                targets
                    .into_iter()
                    .map(|binding| Self {
                        binding,
                        alternatives: alternatives.clone(),
                    })
                    .collect()
            }
        }

        pub(crate) fn record_boolean_local(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            environment: &mut ValueEnvironment,
            local: &typed_trees::statement::TableLocalData,
        ) {
            if !local.symbol.is_valid() {
                return;
            }
            record_binding(
                program,
                machine,
                state,
                environment,
                Operand::Place {
                    root: local.symbol,
                    path: local.name.as_str().to_owned(),
                },
                program.primitive_type_reference(local.type_reference),
                local.initial_value,
            );
        }

        pub(crate) fn record_boolean_assignment(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            environment: &mut ValueEnvironment,
            target: ExpressionHandle,
            expression: ExpressionHandle,
        ) {
            let Some(state) = state else {
                return;
            };
            let primitive = super::declared_place_type_raw(program, machine, Some(state), target)
                .and_then(|reference| program.primitive_type_reference(reference));
            if primitive != Some(PrimitiveType::Bool) {
                return;
            }
            let Some(binding) =
                super::ordered_values::operand(program, machine, state, target, None)
            else {
                return;
            };
            record_binding(
                program,
                machine,
                Some(state),
                environment,
                binding,
                primitive,
                expression,
            );
        }

        fn record_binding(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            environment: &mut ValueEnvironment,
            binding: Operand,
            primitive: Option<PrimitiveType>,
            expression: ExpressionHandle,
        ) {
            if primitive != Some(PrimitiveType::Bool) || !expression.is_valid() {
                return;
            }
            if crate::machine_calls::calls::expression_has_calls(program, expression)
                && !crate::CallFrameResolver::new(program).is_some_and(|frames| {
                    frames
                        .expression_may_write_paths(machine, expression)
                        .is_some_and(|paths| paths.is_empty())
                })
            {
                return;
            }
            let alternatives = [false, true].map(|positive| {
                let mut selected = environment.clone();
                super::narrow_environment_by_condition(
                    program,
                    machine,
                    state,
                    &mut selected,
                    expression,
                    positive,
                );
                ConditionalEvidence {
                    relations: std::mem::take(&mut selected.ordered_values),
                    ieee: selected.ieee_conditional_facts(),
                }
            });
            if alternatives.iter().all(ConditionalEvidence::is_empty) {
                return;
            }
            environment
                .boolean_values
                .retain(|value| value.binding != binding);
            environment.boolean_values.push(BooleanValue {
                binding,
                alternatives,
            });
        }

        pub(crate) fn select(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            environment: &mut ValueEnvironment,
            expression: ExpressionHandle,
            positive: bool,
        ) -> bool {
            if environment.boolean_values.is_empty()
                || super::declared_place_type_raw(program, machine, state, expression)
                    .and_then(|reference| program.primitive_type_reference(reference))
                    != Some(PrimitiveType::Bool)
            {
                return false;
            }
            let Some(binding) = state.and_then(|state| {
                super::ordered_values::operand(program, machine, state, expression, None)
            }) else {
                return false;
            };
            let Some(evidence) = environment
                .boolean_values
                .iter()
                .find(|value| value.binding == binding)
                .map(|value| value.alternatives[usize::from(positive)].clone())
            else {
                return false;
            };
            for relation in &evidence.relations {
                if !environment.ordered_values.contains(relation) {
                    environment.ordered_values.push(relation.clone());
                }
            }
            evidence.ieee.apply_to(environment);
            true
        }
    }
    use crate::proof_contracts::arithmetic_domains::integer_ranges::{
        known_u64_value, literal_u64, primitive_range,
    };
    use crate::proof_contracts::bound_expression_meaning as meaning;
    pub(crate) use boolean_values::BooleanValue;
    pub(crate) use boolean_values::{record_boolean_assignment, record_boolean_local};
    pub(crate) mod case_facts {
        use super::projected_facts::{
            ProjectedOperand, contribute_projected_comparison, has_fixed_integer_meaning,
        };
        use super::{
            BinaryOperator, ExpressionHandle, ExpressionNode, Machine, State, ValueEnvironment,
            meaning, ordered_values,
        };
        use crate::CheckingInput;
        use crate::frozen_program::expression_table;
        use typed_trees::data::{DataDefinition, DataMember, DataVariant};

        pub(crate) fn contribute_case_requirements(
            program: &dyn CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            environment: &mut ValueEnvironment,
            subject: ExpressionHandle,
            condition: ExpressionHandle,
            comparison: &typed_trees::expression::TableBinaryExpression,
        ) {
            let Some(state) = state else {
                return;
            };
            let Some(selected) = meaning::applied_case_membership_variant(
                program,
                machine,
                Some(state),
                condition,
                comparison,
            ) else {
                return;
            };
            let Some((owner_index, _)) = program.data_variant_position_for_symbol(selected) else {
                return;
            };
            let owner = &program.data_definitions()[owner_index as usize];
            let Some(variant) = program.data_variant(owner, selected) else {
                return;
            };
            let requirements = crate::proof_contracts::default_domains::selected_case_requirements(
                program, owner, selected,
            );
            if requirements.is_empty() {
                return;
            }
            let Some(subject) = ordered_values::operand(program, machine, state, subject, None)
            else {
                return;
            };
            for requirement in requirements {
                contribute_fact_expression(
                    program,
                    owner,
                    variant,
                    &subject,
                    environment,
                    requirement,
                );
            }
        }

        fn contribute_fact_expression(
            program: &dyn CheckingInput,
            owner: &DataDefinition,
            variant: &DataVariant,
            subject: &ordered_values::Operand,
            environment: &mut ValueEnvironment,
            expression: ExpressionHandle,
        ) {
            let Some(comparison) = expression_table(program).binary_node(expression) else {
                return;
            };
            if comparison.operator == BinaryOperator::And {
                contribute_fact_expression(
                    program,
                    owner,
                    variant,
                    subject,
                    environment,
                    comparison.left,
                );
                contribute_fact_expression(
                    program,
                    owner,
                    variant,
                    subject,
                    environment,
                    comparison.right,
                );
                return;
            }
            let (Some(left), Some(right)) = (
                fact_side(program, owner, variant, subject, comparison.left),
                fact_side(program, owner, variant, subject, comparison.right),
            ) else {
                return;
            };
            contribute_projected_comparison(
                program,
                environment,
                comparison.operator,
                (&left, comparison.left),
                (&right, comparison.right),
            );
        }

        fn fact_side(
            program: &dyn CheckingInput,
            owner: &DataDefinition,
            variant: &DataVariant,
            subject: &ordered_values::Operand,
            expression: ExpressionHandle,
        ) -> Option<ProjectedOperand> {
            match expression_table(program).expression(expression) {
                ExpressionNode::Integer(literal)
                    if literal.landing().is_none_or(|landing| {
                        landing.landed_type != numerics::literals::LandedIntegerType::Addr
                    }) =>
                {
                    Some(ProjectedOperand::literal(literal))
                }
                ExpressionNode::Name(path) => {
                    field_operand(program, owner, variant, subject, path.symbol)
                }
                ExpressionNode::Member(member)
                    if names_predicate_subject(program, owner, member.receiver) =>
                {
                    field_operand(program, owner, variant, subject, member.member_symbol)
                }
                _ => None,
            }
        }

        fn names_predicate_subject(
            program: &dyn CheckingInput,
            owner: &DataDefinition,
            receiver: ExpressionHandle,
        ) -> bool {
            let Some(path) = expression_table(program).name_path_node(receiver) else {
                return false;
            };
            owner.predicate_subject_symbol.is_valid()
                && path.symbol == owner.predicate_subject_symbol
                && expression_table(program)
                    .name_path_members(path.members)
                    .len()
                    == 1
        }

        fn field_operand(
            program: &dyn CheckingInput,
            owner: &DataDefinition,
            variant: &DataVariant,
            subject: &ordered_values::Operand,
            symbol: symbols::SymbolHandle,
        ) -> Option<ProjectedOperand> {
            let field = program.data_constructor_field(
                owner.predicate_subject_type,
                owner.symbol,
                symbol,
            )?;
            if !payload_field(program, variant)
                .chain(common_fields(program, owner))
                .any(|selected| selected.symbol == field.symbol)
            {
                return None;
            }
            if !has_fixed_integer_meaning(program, field.type_reference) {
                return None;
            }
            let operand = ordered_values::Operand::Field {
                receiver: Box::new(subject.clone()),
                field: field.symbol,
                name: field.name.as_str().to_owned(),
                primitive: program.primitive_type_reference(field.type_reference),
            };
            let spelled = field_name_unique(program, owner, field.name.as_str())
                .then(|| operand.static_path())
                .flatten();
            Some(ProjectedOperand {
                operand: Some(operand),
                spelled,
                declared_type: Some(field.type_reference),
            })
        }

        fn payload_field<'a, 'program>(
            program: &'program dyn CheckingInput,
            variant: &'a DataVariant,
        ) -> impl Iterator<Item = &'program typed_trees::data::DataField> + 'a
        where
            'program: 'a,
        {
            program.data_payload_fields(variant).iter()
        }

        fn common_fields<'a, 'program>(
            program: &'program dyn CheckingInput,
            owner: &'a DataDefinition,
        ) -> impl Iterator<Item = &'program typed_trees::data::DataField> + 'a
        where
            'program: 'a,
        {
            program.data_members(owner).iter().filter_map(|member| {
                let field = member.as_field()?;
                Some(field)
            })
        }

        fn field_name_unique(
            program: &dyn CheckingInput,
            owner: &DataDefinition,
            name: &str,
        ) -> bool {
            let mut count = 0usize;
            for member in program.data_members(owner) {
                match member {
                    DataMember::Field(field) if field.name.as_str() == name => count += 1,
                    DataMember::Variant(variant) => {
                        count += program
                            .data_payload_fields(variant)
                            .iter()
                            .filter(|field| field.name.as_str() == name)
                            .count();
                    }
                    _ => {}
                }
            }
            count == 1
        }
    }
    pub(crate) mod parameter_bounds {
        use super::{
            ExpressionHandle, Machine, State, ValueEnvironment, comparison_interval,
            negate_comparison, place_path,
        };
        pub(crate) fn narrow(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            environment: &mut ValueEnvironment,
            condition: ExpressionHandle,
            positive: bool,
        ) {
            let Some(state) = state else {
                return;
            };
            let Some(comparison) = program.expression_table.binary_node(condition) else {
                return;
            };
            let Some((left, right)) = super::super::invariant_bounds::builtin_comparison_intervals(
                program, machine, state, condition,
            ) else {
                return;
            };
            let operator = if positive {
                comparison.operator
            } else {
                let Some(operator) = negate_comparison(comparison.operator) else {
                    return;
                };
                operator
            };
            for (subject, subject_bounds, operand_bounds, subject_on_left) in [
                (comparison.left, left, right, true),
                (comparison.right, right, left, false),
            ] {
                let Some(_) = program.expression_table.name_path_node(subject) else {
                    continue;
                };
                let Some(name) = place_path(program, subject) else {
                    continue;
                };
                let interval = comparison_interval(operator, operand_bounds, subject_on_left)
                    .intersect(subject_bounds);
                environment.narrow(name, interval);
            }
        }

        pub(crate) fn narrow_recipe(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            environment: &mut ValueEnvironment,
            comparison: &typed_trees::expression::TableBinaryExpression,
            positive: bool,
        ) {
            let operator = if positive {
                comparison.operator
            } else {
                let Some(operator) = negate_comparison(comparison.operator) else {
                    return;
                };
                operator
            };
            for (subject, bound, operator) in [
                (comparison.left, comparison.right, operator),
                (comparison.right, comparison.left, operator.mirrored()),
            ] {
                let Some(place) =
                    crate::value_custody::places::canonical_place_from_expression(program, subject)
                else {
                    continue;
                };
                let Some(path) = place_path(program, subject) else {
                    continue;
                };
                let Some(primitive) =
                    super::super::declared_place_type_raw(program, machine, state, subject)
                        .and_then(|reference| program.primitive_type_reference(reference))
                else {
                    continue;
                };
                let Some(recipe) = super::super::deferred_bounds::comparison_recipe(
                    program,
                    machine.symbol,
                    primitive,
                    bound,
                    operator,
                ) else {
                    continue;
                };
                if let Some(stored) = environment
                    .integer_ranges
                    .iter_mut()
                    .find(|stored| stored.place == place)
                {
                    stored.recipe = stored.recipe.intersect(&recipe);
                } else {
                    environment.integer_ranges.push(
                        super::super::value_environment::StoredIntegerRange {
                            place,
                            path,
                            recipe,
                        },
                    );
                }
            }
        }
    }
    pub(crate) mod predicate_facts {
        use super::super::ordered_values::{Operand, Relation, RelationConstraint};
        use super::{ExpressionHandle, Interval, Machine, State, ValueEnvironment};
        use crate::proof_contracts::collection_predicates;
        use numerics::literals::IntegerLiteral;

        pub(crate) fn narrow(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            environment: &mut ValueEnvironment,
            condition: ExpressionHandle,
        ) -> bool {
            let Some(state) = state else {
                return false;
            };
            let Some(application) =
                collection_predicates::predicate_application(program, machine.symbol, condition)
            else {
                return false;
            };
            if application.arguments.iter().any(|argument| {
                crate::machine_calls::calls::expression_has_calls(program, *argument)
            }) && !crate::CallFrameResolver::new(program).is_some_and(|frames| {
                frames
                    .expression_may_write_paths(machine, condition)
                    .is_some_and(|paths| paths.is_empty())
            }) {
                return false;
            }
            let Some(consequences) =
                collection_predicates::interval_consequences(program, &application)
            else {
                return false;
            };
            for consequence in consequences {
                let extent = consequence.extent;
                let (low, high) = (consequence.low, consequence.high);
                let subject = super::super::ordered_values::operand(
                    program,
                    machine,
                    state,
                    consequence.argument,
                    None,
                );
                let path = super::super::place_path(program, consequence.argument)
                    .or_else(|| subject.as_ref().and_then(Operand::static_path))
                    .map(|path| if extent { format!("{path}.len") } else { path });
                let interval = Interval {
                    low: i64::try_from(low).ok(),
                    high: i64::try_from(high).ok(),
                };
                if let Some(path) = path {
                    environment.narrow(path, interval);
                }
                let Some(mut subject) = subject else { continue };
                if extent {
                    subject = Operand::CollectionLength(Box::new(subject));
                }
                for (bound, lower) in [(interval.low, true), (interval.high, false)] {
                    let Some(bound) = bound else {
                        continue;
                    };
                    let bound = Operand::Integer(IntegerLiteral::from_value(bound), None);
                    let relation = Relation {
                        left: if lower {
                            subject.clone()
                        } else {
                            bound.clone()
                        },
                        right: if lower { bound } else { subject.clone() },
                        constraint: RelationConstraint::MinimumDifference(0),
                    };
                    if !environment.ordered_values.contains(&relation) {
                        environment.ordered_values.push(relation);
                    }
                }
            }
            true
        }
    }
    pub(crate) mod projected_facts {
        use super::super::TypeReferenceHandle;
        use super::{
            ArithmeticDomain, BinaryOperator, ExpressionHandle, Interval, PrimitiveType,
            ValueEnvironment, comparison_interval, literal_i64, ordered_values, primitive_range,
            range_constraint_interval,
        };

        pub(crate) struct ProjectedOperand {
            pub(crate) operand: Option<ordered_values::Operand>,
            pub(crate) spelled: Option<String>,
            pub(crate) declared_type: Option<TypeReferenceHandle>,
        }

        impl ProjectedOperand {
            pub(crate) fn literal(literal: &numerics::literals::IntegerLiteral) -> Self {
                Self {
                    operand: Some(ordered_values::Operand::Integer(
                        literal.clone(),
                        literal.landing(),
                    )),
                    spelled: None,
                    declared_type: None,
                }
            }
        }

        pub(crate) fn contribute_projected_comparison(
            program: &dyn crate::CheckingInput,
            environment: &mut ValueEnvironment,
            operator: BinaryOperator,
            (left, left_expression): (&ProjectedOperand, ExpressionHandle),
            (right, right_expression): (&ProjectedOperand, ExpressionHandle),
        ) {
            match operator {
                BinaryOperator::Less
                | BinaryOperator::LessOrEqual
                | BinaryOperator::Greater
                | BinaryOperator::GreaterOrEqual => {
                    let (high, low, strict) = match operator {
                        BinaryOperator::LessOrEqual => (right, left, false),
                        BinaryOperator::Less => (right, left, true),
                        BinaryOperator::GreaterOrEqual => (left, right, false),
                        _ => (left, right, true),
                    };
                    push_order(environment, high, low, i64::from(strict));
                    if !strict
                        && let (Some(high_path), Some(low_path)) =
                            (high.spelled.as_ref(), low.spelled.as_ref())
                        && let (Some(high_type), Some(low_type)) =
                            (high.declared_type, low.declared_type)
                        && program
                            .primitive_type_reference(high_type)
                            .is_some_and(|primitive| {
                                matches!(
                                    primitive,
                                    PrimitiveType::U8
                                        | PrimitiveType::U16
                                        | PrimitiveType::U32
                                        | PrimitiveType::U64
                                ) && program.primitive_type_reference(low_type) == Some(primitive)
                                    && program.arithmetic_domain_for_type_reference(high_type)
                                        == ArithmeticDomain::Exact
                                    && program.arithmetic_domain_for_type_reference(low_type)
                                        == ArithmeticDomain::Exact
                            })
                    {
                        environment.mark_joint_subtract_bound(high_path.clone(), low_path.clone());
                    }
                    narrow_literal_sides(
                        program,
                        environment,
                        operator,
                        (left, left_expression),
                        (right, right_expression),
                    );
                }
                BinaryOperator::Equal => {
                    push_order(environment, left, right, 0);
                    push_order(environment, right, left, 0);
                    narrow_literal_sides(
                        program,
                        environment,
                        operator,
                        (left, left_expression),
                        (right, right_expression),
                    );
                    for (place, literal_expression) in
                        [(left, right_expression), (right, left_expression)]
                    {
                        if let (Some(path), Some(declared_type), Some(literal)) = (
                            place.spelled.as_ref(),
                            place.declared_type,
                            literal_i64(program, literal_expression),
                        ) && program.primitive_type_reference(declared_type)
                            == Some(PrimitiveType::U64)
                            && let Ok(value) = u64::try_from(literal)
                        {
                            environment.mark_known_u64(path.clone(), value);
                        }
                    }
                }
                BinaryOperator::NotEqual => {
                    if let (Some(left), Some(right)) = (&left.operand, &right.operand) {
                        let relation = ordered_values::Relation {
                            left: left.clone(),
                            right: right.clone(),
                            constraint: ordered_values::RelationConstraint::Unequal,
                        };
                        if !environment.ordered_values.contains(&relation) {
                            environment.ordered_values.push(relation);
                        }
                    }
                }
                _ => {}
            }
        }

        fn push_order(
            environment: &mut ValueEnvironment,
            high: &ProjectedOperand,
            low: &ProjectedOperand,
            floor: i64,
        ) {
            let (Some(high), Some(low)) = (&high.operand, &low.operand) else {
                return;
            };
            let relation = ordered_values::Relation {
                left: high.clone(),
                right: low.clone(),
                constraint: ordered_values::RelationConstraint::MinimumDifference(floor),
            };
            if !environment.ordered_values.contains(&relation) {
                environment.ordered_values.push(relation);
            }
        }

        fn narrow_literal_sides(
            program: &dyn crate::CheckingInput,
            environment: &mut ValueEnvironment,
            operator: BinaryOperator,
            (left, left_expression): (&ProjectedOperand, ExpressionHandle),
            (right, right_expression): (&ProjectedOperand, ExpressionHandle),
        ) {
            for (place, literal_expression, place_on_left) in [
                (left, right_expression, true),
                (right, left_expression, false),
            ] {
                let (Some(path), Some(literal)) = (
                    place.spelled.as_ref(),
                    literal_i64(program, literal_expression),
                ) else {
                    continue;
                };
                let mut interval = comparison_interval(
                    operator,
                    Interval {
                        low: Some(literal),
                        high: Some(literal),
                    },
                    place_on_left,
                );
                if let Some(declared_type) = place.declared_type {
                    if let Some(type_interval) = program
                        .primitive_type_reference(declared_type)
                        .and_then(primitive_range)
                    {
                        interval = interval.intersect(type_interval);
                    }
                    if let Some(declared) = range_constraint_interval(program, declared_type) {
                        interval = interval.intersect(declared);
                    }
                }
                environment.narrow(path.clone(), interval);
            }
        }

        pub(crate) fn has_fixed_integer_meaning(
            program: &dyn crate::CheckingInput,
            type_reference: TypeReferenceHandle,
        ) -> bool {
            crate::value_custody::places::unwrapped_type_reference(program, type_reference)
                .and_then(|reference| {
                    crate::value_custody::recasts::exact_primitive_type(program, reference)
                })
                .is_some_and(|primitive| primitive.is_fixed_integer())
        }
    }
    pub(crate) mod requirements {
        use super::{
            ExpressionHandle, ExpressionNode, Interval, Machine, SignatureContractKind, State,
            ValueEnvironment, literal_i64, narrow_environment_by_condition, ordered_values,
            place_path,
        };
        use crate::CallFrameResolver;

        pub(crate) fn seed_state_requirements(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
            frames: Option<&CallFrameResolver>,
            environment: &mut ValueEnvironment,
        ) {
            let is_entry = program
                .machine_states(machine)
                .first()
                .is_some_and(|entry| entry.symbol == state.symbol);
            let machine_written = (!is_entry)
                .then(|| machine_written_paths(program, machine, frames))
                .flatten();
            RequirementSeeds::new(
                program,
                machine,
                state,
                frames,
                is_entry,
                machine_written.as_deref(),
            )
            .apply(program, machine, state, environment);
            seed_arriving_data_field_bounds(program, state, environment);
        }

        fn seed_arriving_data_field_bounds(
            program: &dyn crate::CheckingInput,
            state: &State,
            environment: &mut ValueEnvironment,
        ) {
            for parameter in program.state_parameters(state) {
                let Some(definition) = parameter_record(program, parameter) else {
                    continue;
                };
                let Some(bounds) = crate::data_requires_field_intervals(program, definition) else {
                    continue;
                };
                for (symbol, low, high) in bounds {
                    let Some(field) = program.data_members(definition).iter().find_map(|member| {
                        member.as_field().filter(|field| field.symbol == symbol)
                    }) else {
                        continue;
                    };
                    let path = format!("{}.{}", parameter.name.as_str(), field.name.as_str());
                    let declared = Interval { low, high };
                    let interval = environment
                        .get(&path)
                        .map_or(declared, |existing| existing.intersect(declared));
                    environment.set(path, interval);
                }
            }
        }

        fn parameter_record<'a>(
            program: &'a dyn crate::CheckingInput,
            parameter: &typed_trees::signature::StateParameter,
        ) -> Option<&'a typed_trees::data::DataDefinition> {
            let mut reference = parameter.type_reference;
            if let Some(shell) = crate::reference_shell(program, reference) {
                reference = shell.referee;
            }
            reference = program.unwrapped_type_reference(reference)?;
            let symbol = match program.type_reference_table.type_reference(reference) {
                typed_trees::types::TypeReferenceNode::Named { symbol, .. } => *symbol,
                typed_trees::types::TypeReferenceNode::Generic { base_symbol, .. } => *base_symbol,
                _ => return None,
            };
            program.data_definition_by_symbol(symbol)
        }

        pub(crate) fn machine_written_paths(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            frames: Option<&CallFrameResolver>,
        ) -> Option<Vec<String>> {
            let has_machine_requires = program
                .machine_contracts(machine)
                .iter()
                .any(|contract| contract.kind == SignatureContractKind::Requires);
            if !has_machine_requires {
                return None;
            }
            frames.and_then(|frames| {
                frames
                    .inferred_machine_state_write_frames(machine)
                    .into_iter()
                    .map(|frame| frame.into_complete_paths())
                    .collect::<Option<Vec<_>>>()
                    .map(|paths| paths.concat())
            })
        }

        pub(crate) struct RequirementSeeds {
            conditions: Vec<ExpressionHandle>,
            memberships: Vec<(String, Interval)>,
        }

        impl RequirementSeeds {
            pub(crate) fn new(
                program: &dyn crate::CheckingInput,
                machine: &Machine,
                state: &State,
                frames: Option<&CallFrameResolver>,
                is_entry: bool,
                machine_written: Option<&[String]>,
            ) -> Self {
                let mut conditions = Vec::new();
                for condition in program.contract_expressions(
                    program.machine_contracts(machine).iter(),
                    SignatureContractKind::Requires,
                ) {
                    if condition_belongs_to_state(program, machine, state, condition, frames)
                        && (is_entry
                            || machine_requires_survives(
                                program,
                                machine,
                                state,
                                machine_written,
                                condition,
                            ))
                    {
                        conditions.push(condition);
                    }
                }
                for condition in program.contract_expressions(
                    program.state_contracts(state).iter(),
                    SignatureContractKind::Requires,
                ) {
                    if condition_belongs_to_state(program, machine, state, condition, frames) {
                        conditions.push(condition);
                    }
                }
                let mut memberships = Vec::new();
                for (contract, machine_level) in program
                    .machine_contracts(machine)
                    .iter()
                    .map(|contract| (contract, true))
                    .chain(
                        program
                            .state_contracts(state)
                            .iter()
                            .map(|contract| (contract, false)),
                    )
                    .filter(|(contract, _)| {
                        contract.kind == SignatureContractKind::Requires
                            && contract.binding.is_none()
                    })
                {
                    for fact in program.proof_facts.span_or_empty(contract.facts) {
                        let Some(membership) = fact.as_membership() else {
                            continue;
                        };
                        if !condition_belongs_to_state(
                            program,
                            machine,
                            state,
                            membership.value,
                            frames,
                        ) {
                            continue;
                        }
                        let Some((low, high)) =
                            super::super::domain_intervals::membership_predicate_bounds(
                                program, membership,
                            )
                        else {
                            continue;
                        };
                        let interval = Interval {
                            low: low.and_then(|value| value.to_i64()),
                            high: high.and_then(|value| value.to_i64()),
                        };
                        if interval.low.is_none() && interval.high.is_none() {
                            continue;
                        }
                        let Some(path) = place_path(program, membership.value) else {
                            continue;
                        };
                        if machine_level && !is_entry {
                            let Some(written) = machine_written else {
                                continue;
                            };
                            let mut seeded = ValueEnvironment::new();
                            seeded.narrow(path.clone(), interval);
                            let mut retained = seeded.clone();
                            retained.invalidate_written_paths(written);
                            if retained != seeded {
                                continue;
                            }
                        }
                        memberships.push((path, interval));
                    }
                }
                Self {
                    conditions,
                    memberships,
                }
            }

            pub(crate) fn apply(
                &self,
                program: &dyn crate::CheckingInput,
                machine: &Machine,
                state: &State,
                environment: &mut ValueEnvironment,
            ) {
                for condition in &self.conditions {
                    narrow_environment_by_condition(
                        program,
                        machine,
                        Some(state),
                        environment,
                        *condition,
                        true,
                    );
                }
                for (path, interval) in &self.memberships {
                    environment.narrow(path.clone(), *interval);
                }
                if environment.intervals.values().any(|interval| {
                    interval
                        .low
                        .zip(interval.high)
                        .is_some_and(|(low, high)| low > high)
                }) {
                    let mut required = ValueEnvironment::new();
                    for condition in &self.conditions {
                        narrow_environment_by_condition(
                            program,
                            machine,
                            Some(state),
                            &mut required,
                            *condition,
                            true,
                        );
                    }
                    for (path, interval) in &self.memberships {
                        required.narrow(path.clone(), *interval);
                    }
                    *environment = required;
                }
            }
        }

        fn machine_requires_survives(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
            machine_written: Option<&[String]>,
            condition: ExpressionHandle,
        ) -> bool {
            let Some(written) = machine_written else {
                return false;
            };
            let mut seeded = ValueEnvironment::new();
            narrow_environment_by_condition(
                program,
                machine,
                Some(state),
                &mut seeded,
                condition,
                true,
            );
            let mut retained = seeded.clone();
            retained.invalidate_written_paths(written);
            retained == seeded
        }

        fn condition_belongs_to_state(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
            expression: ExpressionHandle,
            frames: Option<&CallFrameResolver>,
        ) -> bool {
            if program
                .constant_recipe_for_contract_expression(expression)
                .is_valid()
            {
                return true;
            }
            if literal_i64(program, expression).is_some() {
                return true;
            }
            match program.expression_table.expression(expression) {
                ExpressionNode::Name(path) => {
                    if program.symbols.builtin_type_member(path.symbol).is_some() {
                        return true;
                    }
                    path.symbol.is_valid()
                && path.head_symbol.is_valid()
                && ((program
                    .state_parameter_by_symbol(state, path.head_symbol)
                    .is_some())
                    || (path.symbol == path.head_symbol
                        && program
                            .machine_type_parameters(machine)
                            .iter()
                            .any(|parameter| {
                                parameter.symbol == path.symbol
                                    && matches!(
                                        parameter.kind,
                                        typed_trees::data::TypeParameterKind::Value { .. }
                                            | typed_trees::data::TypeParameterKind::Const { .. }
                                    )
                            })))
                }
                ExpressionNode::Member(member) => {
                    (member.member_symbol.is_valid()
                        || crate::value_custody::places::collection_length_receiver(
                            program,
                            machine,
                            Some(state),
                            expression,
                        )
                        .is_some())
                        && condition_belongs_to_state(
                            program,
                            machine,
                            state,
                            member.receiver,
                            frames,
                        )
                }
                ExpressionNode::Indexed(indexed) => {
                    crate::place_has_builtin_coordinates(program, machine, Some(state), expression)
                        && condition_belongs_to_state(
                            program,
                            machine,
                            state,
                            indexed.collection,
                            frames,
                        )
                        && condition_belongs_to_state(
                            program,
                            machine,
                            state,
                            indexed.index,
                            frames,
                        )
                }
                ExpressionNode::Binary(binary) => {
                    condition_belongs_to_state(program, machine, state, binary.left, frames)
                        && condition_belongs_to_state(program, machine, state, binary.right, frames)
                }
                ExpressionNode::Cast(cast) => {
                    condition_belongs_to_state(program, machine, state, cast.value, frames)
                }
                ExpressionNode::Unary(unary) => {
                    condition_belongs_to_state(program, machine, state, unary.operand, frames)
                }
                ExpressionNode::Integer(_)
                | ExpressionNode::Boolean(_)
                | ExpressionNode::Float(_)
                | ExpressionNode::UndeterminedNaN(_) => true,
                ExpressionNode::Call(_) => {
                    if let Some(application) =
                        crate::proof_contracts::collection_predicates::predicate_application(
                            program,
                            machine.symbol,
                            expression,
                        )
                    {
                        return application.arguments.iter().all(|argument| {
                            condition_belongs_to_state(program, machine, state, *argument, frames)
                        });
                    }
                    if let Some((_, argument)) =
                        crate::integer_embedding_argument(program, expression)
                    {
                        condition_belongs_to_state(program, machine, state, argument, frames)
                    } else {
                        ordered_values::operand(program, machine, state, expression, frames)
                            .is_some()
                    }
                }
                _ => false,
            }
        }
    }
    pub use arrivals::{
        OccurrenceIntegerBounds, arrival_integer_expression_bounds,
        occurrence_collection_footprint_fits, occurrence_integer_bounds,
        occurrence_integer_expression_bounds, occurrence_integer_expression_fits_range,
        occurrence_integer_expression_recipe, occurrence_integer_expressions_bounds,
    };
    pub(crate) use arrivals::{
        OccurrenceValueEnvironments, ReturnInference, inferred_normal_return_interval,
        occurrence_integer_child_values, occurrence_value_environment,
        occurrence_value_environments,
    };
    use projected_facts::ProjectedOperand;

    pub(crate) fn has_builtin_ordering(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
    ) -> bool {
        let Some(comparison) = program.expression_table.binary_node(expression) else {
            return false;
        };
        meaning::builtin_ordering(program, machine, state, expression, comparison)
            && meaning::folded_constant_is_builtin(program, machine, state, comparison.left)
            && meaning::folded_constant_is_builtin(program, machine, state, comparison.right)
    }

    pub(crate) fn has_builtin_equality(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
    ) -> bool {
        let Some(comparison) = program.expression_table.binary_node(expression) else {
            return false;
        };
        meaning::builtin_boolean_equality(program, machine, state, expression, comparison)
            && meaning::folded_constant_is_builtin(program, machine, state, comparison.left)
            && meaning::folded_constant_is_builtin(program, machine, state, comparison.right)
    }

    pub(crate) fn has_builtin_bound_arithmetic(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
    ) -> bool {
        meaning::builtin_arithmetic(program, machine, state, expression)
    }

    pub(crate) fn requires_value_environment(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        entry_state: &State,
    ) -> ValueEnvironment {
        let comparison_meaning_is_available = |expression| {
            let Some(comparison) = program.expression_table.binary_node(expression) else {
                return true;
            };
            match comparison.operator {
                BinaryOperator::Equal | BinaryOperator::NotEqual => {
                    has_builtin_equality(program, machine, Some(entry_state), expression)
                }
                BinaryOperator::Less
                | BinaryOperator::LessOrEqual
                | BinaryOperator::Greater
                | BinaryOperator::GreaterOrEqual => {
                    has_builtin_ordering(program, machine, Some(entry_state), expression)
                }
                _ => true,
            }
        };
        let mut bounds: BTreeMap<String, (Option<i64>, Option<i64>)> = BTreeMap::new();
        let each_available_comparison = |body: &mut dyn FnMut(ExpressionHandle)| {
            for expression in program.contract_expressions(
                program.machine_contracts(machine).iter(),
                SignatureContractKind::Requires,
            ) {
                if !comparison_meaning_is_available(expression) {
                    continue;
                }
                body(expression);
            }
        };
        each_available_comparison(&mut |expression| {
            if let Some((name, low, high)) = comparison_bound(program, expression) {
                let entry = bounds.entry(name).or_insert((None, None));
                if let Some(low) = low {
                    entry.0 = Some(entry.0.map_or(low, |existing| existing.max(low)));
                }
                if let Some(high) = high {
                    entry.1 = Some(entry.1.map_or(high, |existing| existing.min(high)));
                }
            }
        });
        let mut environment = ValueEnvironment::new();
        for (name, (low, high)) in bounds {
            environment.set(name, Interval { low, high });
        }
        each_available_comparison(&mut |expression| {
            let Some(comparison) = program.expression_table.binary_node(expression) else {
                return;
            };
            parameter_bounds::narrow_recipe(
                program,
                machine,
                Some(entry_state),
                &mut environment,
                comparison,
                true,
            );
            if let Some((left, right)) =
                joint_subtract_guard(program, machine, Some(entry_state), comparison)
            {
                environment.mark_joint_subtract_bound(left, right);
            }
            if let Some((left, right)) = signed_joint_subtract_guard(
                program,
                machine,
                Some(entry_state),
                &environment,
                comparison,
                true,
            ) {
                environment.mark_signed_joint_subtract_lower_bound(left, right);
            }
            if let Some((left, right)) = signed_joint_subtract_guard(
                program,
                machine,
                Some(entry_state),
                &environment,
                comparison,
                false,
            ) {
                environment.mark_signed_joint_subtract_upper_bound(left, right);
            }
            if let Some((left, right)) = joint_multiply_guard(
                program,
                machine,
                Some(entry_state),
                &environment,
                comparison,
            ) {
                environment.mark_joint_multiply_bound(left, right);
            }
            if let Some((left, right)) = signed_joint_multiply_lower_guard(
                program,
                machine,
                Some(entry_state),
                &environment,
                comparison,
            ) {
                environment.mark_signed_joint_multiply_lower_bound(left, right);
            }
            if let Some((left, right)) = signed_joint_multiply_upper_guard(
                program,
                machine,
                Some(entry_state),
                &environment,
                comparison,
            ) {
                environment.mark_signed_joint_multiply_upper_bound(left, right);
            }
        });
        for parameter in program.state_parameters(entry_state) {
            super::record_admitted_integer_fields(
                program,
                &mut environment,
                &ordered_values::Operand::parameter(parameter),
                parameter.type_reference,
            );
            super::record_declared_float_fields(
                program,
                &mut environment,
                parameter.name.as_str(),
                parameter.type_reference,
            );
        }
        requirements::seed_state_requirements(
            program,
            machine,
            entry_state,
            None,
            &mut environment,
        );
        environment
    }

    pub(crate) fn comparison_bound(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<(String, Option<i64>, Option<i64>)> {
        let binary = program.expression_table.binary_node(expression)?;
        if let (Some(name), Some(literal)) = (
            place_path(program, binary.left),
            literal_i64(program, binary.right),
        ) {
            return Some(bound_from(name, binary.operator, literal, true));
        }
        if let (Some(name), Some(literal)) = (
            place_path(program, binary.right),
            literal_i64(program, binary.left),
        ) {
            return Some(bound_from(name, binary.operator, literal, false));
        }
        None
    }

    fn bound_from(
        name: String,
        operator: BinaryOperator,
        literal: i64,
        name_on_left: bool,
    ) -> (String, Option<i64>, Option<i64>) {
        let interval = comparison_interval(
            operator,
            Interval {
                low: Some(literal),
                high: Some(literal),
            },
            name_on_left,
        );
        (name, interval.low, interval.high)
    }

    pub(crate) fn comparison_interval(
        operator: BinaryOperator,
        operand: Interval,
        subject_on_left: bool,
    ) -> Interval {
        let operator = if subject_on_left {
            operator
        } else {
            operator.mirrored()
        };
        let (low, high) = match operator {
            BinaryOperator::LessOrEqual => (None, operand.high),
            BinaryOperator::Less => (None, operand.high.map(|value| value.saturating_sub(1))),
            BinaryOperator::GreaterOrEqual => (operand.low, None),
            BinaryOperator::Greater => (operand.low.map(|value| value.saturating_add(1)), None),
            BinaryOperator::Equal => (operand.low, operand.high),
            _ => (None, None),
        };
        Interval { low, high }
    }

    fn negate_comparison(operator: BinaryOperator) -> Option<BinaryOperator> {
        Some(match operator {
            BinaryOperator::Less => BinaryOperator::GreaterOrEqual,
            BinaryOperator::LessOrEqual => BinaryOperator::Greater,
            BinaryOperator::Greater => BinaryOperator::LessOrEqual,
            BinaryOperator::GreaterOrEqual => BinaryOperator::Less,
            BinaryOperator::NotEqual => BinaryOperator::Equal,
            _ => return None,
        })
    }

    pub(crate) fn short_circuit_operand_environment(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
    ) -> Option<ValueEnvironment> {
        let binary = program.expression_table.binary_node(expression)?;
        if !matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or)
            || !meaning::has_builtin_binary_expression_meaning(program, machine, state, expression)
        {
            return None;
        }
        Some(evaluated_condition_environment(
            program,
            machine,
            state,
            binary.left,
            binary.operator == BinaryOperator::And,
            environment,
        ))
    }

    pub(crate) fn evaluated_condition_environment(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        condition: ExpressionHandle,
        positive: bool,
        environment: &ValueEnvironment,
    ) -> ValueEnvironment {
        let frames = crate::machine_calls::calls::expression_has_calls(program, condition)
            .then(|| crate::CallFrameResolver::new(program))
            .flatten();
        evaluated_condition_with_frames(
            program,
            machine,
            state,
            condition,
            positive,
            environment,
            frames.as_ref(),
        )
    }

    fn evaluated_condition_with_frames(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        condition: ExpressionHandle,
        positive: bool,
        environment: &ValueEnvironment,
        frames: Option<&crate::CallFrameResolver<'_>>,
    ) -> ValueEnvironment {
        let evaluate = |operand, truth, before: &ValueEnvironment| {
            evaluated_condition_with_frames(program, machine, state, operand, truth, before, frames)
        };
        if let ExpressionNode::Unary(unary) = program.expression_table.expression(condition)
            && unary.operator == typed_trees::expression::UnaryOperator::LogicalNot
        {
            return evaluate(unary.operand, !positive, environment);
        }
        if let Some(binary) = program.expression_table.binary_node(condition) {
            if matches!(binary.operator, BinaryOperator::And | BinaryOperator::Or)
                && meaning::has_builtin_binary_expression_meaning(
                    program, machine, state, condition,
                )
            {
                let continuing_truth = binary.operator == BinaryOperator::And;
                let continuing = evaluate(binary.left, continuing_truth, environment);
                let completed = evaluate(binary.right, positive, &continuing);
                if positive == continuing_truth {
                    return completed;
                }
                let skipped = evaluate(binary.left, !continuing_truth, environment);
                return skipped.join(&completed);
            }
            if matches!(
                binary.operator,
                BinaryOperator::Equal | BinaryOperator::NotEqual
            ) && meaning::builtin_boolean_equality(program, machine, state, condition, binary)
            {
                let wrapped = match (
                    program.expression_table.expression(binary.left),
                    program.expression_table.expression(binary.right),
                ) {
                    (_, ExpressionNode::Boolean(value)) => Some((binary.left, *value)),
                    (ExpressionNode::Boolean(value), _) => Some((binary.right, *value)),
                    _ => None,
                };
                if let Some((operand, value)) = wrapped {
                    return evaluate(
                        operand,
                        positive == (value == (binary.operator == BinaryOperator::Equal)),
                        environment,
                    );
                }
            }
        }
        let writes = if crate::machine_calls::calls::expression_has_calls(program, condition) {
            frames.and_then(|frames| frames.expression_may_write_paths(machine, condition))
        } else {
            Some(Vec::new())
        };
        let cross_writes = |values: &mut ValueEnvironment| match &writes {
            Some(writes) => values.invalidate_call_paths(program, state, writes),
            None => values.invalidate_unknown_writes(program, state),
        };
        let mut selected = environment.clone();
        cross_writes(&mut selected);
        narrow_environment_by_condition(
            program,
            machine,
            state,
            &mut selected,
            condition,
            positive,
        );
        cross_writes(&mut selected);
        selected
    }

    pub(crate) fn guard_narrowed_environment(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        guard: &typed_trees::statement::TransitionGuardNode,
        base: &ValueEnvironment,
    ) -> ValueEnvironment {
        use typed_trees::statement::TransitionGuardNode;
        let environment = base.clone();
        let TransitionGuardNode::When(condition) = guard else {
            return environment;
        };
        evaluated_condition_environment(program, machine, state, *condition, true, &environment)
    }

    pub(crate) fn fall_through_narrowed_environment(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        guard: &typed_trees::statement::TransitionGuardNode,
        base: &ValueEnvironment,
    ) -> ValueEnvironment {
        use typed_trees::statement::TransitionGuardNode;
        let environment = base.clone();
        let TransitionGuardNode::When(guard_expr) = guard else {
            return environment;
        };
        evaluated_condition_environment(program, machine, state, *guard_expr, false, &environment)
    }

    pub(crate) fn narrow_environment_by_condition(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &mut ValueEnvironment,
        condition: ExpressionHandle,
        positive: bool,
    ) {
        if boolean_values::select(program, machine, state, environment, condition, positive) {
            return;
        }
        if positive && predicate_facts::narrow(program, machine, state, environment, condition) {
            return;
        }
        if let ExpressionNode::Unary(unary) = program.expression_table.expression(condition)
            && unary.operator == typed_trees::expression::UnaryOperator::LogicalNot
        {
            narrow_environment_by_condition(
                program,
                machine,
                state,
                environment,
                unary.operand,
                !positive,
            );
            return;
        }
        if let Some(arm_value) = meaning::match_result_unique_arm(program, condition, positive) {
            narrow_environment_by_condition(
                program,
                machine,
                state,
                environment,
                arm_value,
                positive,
            );
            return;
        }
        let Some(comparison) =
            meaning::guard_comparison(program, machine.symbol, condition, &|operand| {
                crate::proof_contracts::bound_expression_meaning::operand_type(
                    program, machine, state, operand,
                )
            })
        else {
            return;
        };
        narrow_environment_by_comparison(
            program,
            machine,
            state,
            environment,
            condition,
            &comparison,
            positive,
        );
    }

    pub(crate) fn narrow_environment_by_comparison(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &mut ValueEnvironment,
        condition: ExpressionHandle,
        comparison: &TableBinaryExpression,
        positive: bool,
    ) {
        if matches!(
            comparison.operator,
            BinaryOperator::Equal | BinaryOperator::NotEqual
        ) {
            let wrapped = match (
                program.expression_table.expression(comparison.left),
                program.expression_table.expression(comparison.right),
            ) {
                (_, ExpressionNode::Boolean(value)) => Some((comparison.left, *value)),
                (ExpressionNode::Boolean(value), _) => Some((comparison.right, *value)),
                _ => None,
            };
            if let Some((operand, value)) = wrapped {
                if !meaning::builtin_boolean_equality(
                    program, machine, state, condition, comparison,
                ) {
                    return;
                }
                let operand_positive =
                    positive == (value == (comparison.operator == BinaryOperator::Equal));
                narrow_environment_by_condition(
                    program,
                    machine,
                    state,
                    environment,
                    operand,
                    operand_positive,
                );
                return;
            }
        }
        match comparison.operator {
            BinaryOperator::And if positive => {
                let (left, right) = (comparison.left, comparison.right);
                narrow_environment_by_condition(program, machine, state, environment, left, true);
                narrow_environment_by_condition(program, machine, state, environment, right, true);
                return;
            }
            BinaryOperator::Or if !positive => {
                let (left, right) = (comparison.left, comparison.right);
                narrow_environment_by_condition(program, machine, state, environment, left, false);
                narrow_environment_by_condition(program, machine, state, environment, right, false);
                return;
            }
            BinaryOperator::And | BinaryOperator::Or => return,
            _ => {}
        }
        let membership_subject = match comparison.operator {
            BinaryOperator::CaseMembership => Some(comparison.left),
            BinaryOperator::Equal
                if meaning::exact_case_reference_owner(program, comparison.right).is_some() =>
            {
                Some(comparison.left)
            }
            _ => None,
        };
        if positive && let Some(subject) = membership_subject {
            case_facts::contribute_case_requirements(
                program,
                machine,
                state,
                environment,
                subject,
                condition,
                comparison,
            );
            return;
        }
        let folded_operands_are_builtin = || {
            meaning::folded_constant_is_builtin(program, machine, state, comparison.left)
                && meaning::folded_constant_is_builtin(program, machine, state, comparison.right)
        };
        if matches!(
            comparison.operator,
            BinaryOperator::Less
                | BinaryOperator::LessOrEqual
                | BinaryOperator::Greater
                | BinaryOperator::GreaterOrEqual
        ) && !(meaning::builtin_ordering(program, machine, state, condition, comparison)
            && folded_operands_are_builtin())
            && !meaning::sealed_float_comparison(program, machine, state, condition, comparison)
        {
            return;
        }
        if matches!(
            comparison.operator,
            BinaryOperator::Equal | BinaryOperator::NotEqual
        ) && !(meaning::builtin_boolean_equality(program, machine, state, condition, comparison)
            && folded_operands_are_builtin())
            && !meaning::sealed_float_comparison(program, machine, state, condition, comparison)
        {
            return;
        }
        let comparison = *comparison;
        if let Some(state) = state {
            ordered_values::record(program, machine, state, environment, &comparison, positive);
        }
        if positive {
            if let Some((left, right)) = joint_subtract_guard(program, machine, state, &comparison)
            {
                environment.mark_joint_subtract_bound(left, right);
            }
            if let Some((left, right)) =
                signed_joint_subtract_guard(program, machine, state, environment, &comparison, true)
            {
                environment.mark_signed_joint_subtract_lower_bound(left, right);
            }
            if let Some((left, right)) = signed_joint_subtract_guard(
                program,
                machine,
                state,
                environment,
                &comparison,
                false,
            ) {
                environment.mark_signed_joint_subtract_upper_bound(left, right);
            }
            if let Some((left, right)) =
                joint_multiply_guard(program, machine, state, environment, &comparison)
            {
                environment.mark_joint_multiply_bound(left, right);
            }
            if let Some((left, right)) =
                signed_joint_multiply_lower_guard(program, machine, state, environment, &comparison)
            {
                environment.mark_signed_joint_multiply_lower_bound(left, right);
            }
            if let Some((left, right)) =
                signed_joint_multiply_upper_guard(program, machine, state, environment, &comparison)
            {
                environment.mark_signed_joint_multiply_upper_bound(left, right);
            }
            if let Some(value) =
                signed_joint_multiply_negation_guard(program, machine, state, &comparison)
            {
                environment.mark_signed_joint_multiply_negation_bound(value);
            }
            if comparison.operator == BinaryOperator::Equal {
                for (place, literal) in [
                    (comparison.left, comparison.right),
                    (comparison.right, comparison.left),
                ] {
                    let Some(path) = place_path(program, place) else {
                        continue;
                    };
                    let Some(value) = literal_u64(program, literal) else {
                        continue;
                    };
                    if declared_place_type_raw(program, machine, state, place).is_some_and(
                        |handle| {
                            program.primitive_type_reference(handle) == Some(PrimitiveType::U64)
                        },
                    ) {
                        environment.mark_known_u64(path, value);
                    }
                }
            }
            if super::float_arithmetic::record_float_comparison_bounds(
                program,
                environment,
                &comparison,
                &|place| declared_place_type_raw(program, machine, state, place),
            ) {
                return;
            }
        }
        parameter_bounds::narrow_recipe(
            program,
            machine,
            state,
            environment,
            &comparison,
            positive,
        );
        parameter_bounds::narrow(program, machine, state, environment, condition, positive);
        let integer_bound = |expression| {
            literal_i64(program, expression).or_else(|| {
                let (low, high) = super::immutable_integer_expression_bounds(
                    program, machine, state?, expression,
                )?;
                (low == high).then_some(low)
            })
        };
        let standing_bound = |bound: ExpressionHandle, place: ExpressionHandle| {
            place_path(program, place)?;
            super::standing_integer_interval(program, machine, state?, bound)
        };
        let (place_expr, bound, name_on_left) =
            if let Some(literal) = integer_bound(comparison.right) {
                (comparison.left, Interval::constant(literal), true)
            } else if let Some(literal) = integer_bound(comparison.left) {
                (comparison.right, Interval::constant(literal), false)
            } else if let Some(bound) = standing_bound(comparison.right, comparison.left) {
                (comparison.left, bound, true)
            } else if let Some(bound) = standing_bound(comparison.left, comparison.right) {
                (comparison.right, bound, false)
            } else {
                return;
            };
        let point_exclusion = matches!(
            (comparison.operator, positive),
            (BinaryOperator::Equal, false) | (BinaryOperator::NotEqual, true)
        );
        let operator = if positive || point_exclusion {
            comparison.operator
        } else {
            let Some(negated) = negate_comparison(comparison.operator) else {
                return;
            };
            negated
        };
        let Some(name) = place_path(program, place_expr)
            .or_else(|| super::stable_element_place_path(program, machine, state, place_expr))
        else {
            return;
        };
        if point_exclusion {
            if declared_place_type_raw(program, machine, state, place_expr)
                .and_then(|reference| program.primitive_type_reference(reference))
                .and_then(primitive_range)
                .is_none()
            {
                return;
            }
            let Some(literal) = bound.low.filter(|low| bound.high == Some(*low)) else {
                return;
            };
            let mut interval = environment.get(&name).unwrap_or(Interval::UNBOUNDED);
            intersect_declared_place_ranges(program, machine, state, place_expr, &mut interval);
            if interval.low == Some(literal) {
                interval.low = literal.checked_add(1);
            }
            if interval.high == Some(literal) {
                interval.high = literal.checked_sub(1);
            }
            environment.narrow(name, interval);
            return;
        }
        let mut interval = comparison_interval(operator, bound, name_on_left);
        intersect_declared_place_ranges(program, machine, state, place_expr, &mut interval);
        environment.narrow(name, interval);
    }

    fn intersect_declared_place_ranges(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        place_expr: ExpressionHandle,
        interval: &mut Interval,
    ) {
        let Some(handle) = declared_place_type_raw(program, machine, state, place_expr) else {
            return;
        };
        if let Some(type_interval) = program
            .primitive_type_reference(handle)
            .and_then(primitive_range)
        {
            *interval = interval.intersect(type_interval);
        }
        if let Some(declared_range) = range_constraint_interval(program, handle) {
            *interval = interval.intersect(declared_range);
        }
    }

    fn shared_exact_primitive(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        left: ExpressionHandle,
        right: ExpressionHandle,
    ) -> Option<PrimitiveType> {
        let left_type = declared_place_type_raw(program, machine, state, left)?;
        let right_type = declared_place_type_raw(program, machine, state, right)?;
        let left_primitive = program.primitive_type_reference(left_type)?;
        if program.primitive_type_reference(right_type) != Some(left_primitive)
            || program.arithmetic_domain_for_type_reference(left_type) != ArithmeticDomain::Exact
            || program.arithmetic_domain_for_type_reference(right_type) != ArithmeticDomain::Exact
        {
            return None;
        }
        Some(left_primitive)
    }

    fn exact_bound_binary<'program>(
        program: &'program dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        left: ExpressionHandle,
        bound: ExpressionHandle,
        operator: BinaryOperator,
    ) -> Option<(&'program TableBinaryExpression, PrimitiveType)> {
        let binary = program.expression_table.binary_node(bound)?;
        if binary.operator != operator
            || !meaning::builtin_arithmetic(program, machine, state, bound)
        {
            return None;
        }
        let left_primitive = shared_exact_primitive(program, machine, state, left, binary.right)?;
        Some((binary, left_primitive))
    }

    fn directed_comparison_operands(
        comparison: &TableBinaryExpression,
    ) -> Option<(ExpressionHandle, ExpressionHandle)> {
        match comparison.operator {
            BinaryOperator::LessOrEqual => Some((comparison.left, comparison.right)),
            BinaryOperator::GreaterOrEqual => Some((comparison.right, comparison.left)),
            _ => None,
        }
    }

    fn joint_subtract_guard(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        comparison: &TableBinaryExpression,
    ) -> Option<(String, String)> {
        let (right, left) = match comparison.operator {
            BinaryOperator::LessOrEqual => (comparison.left, comparison.right),
            BinaryOperator::GreaterOrEqual => (comparison.right, comparison.left),
            _ => return None,
        };
        let left_primitive = shared_exact_primitive(program, machine, state, left, right)?;
        if !matches!(
            left_primitive,
            typed_trees::unsigned_integer_primitive_pattern!()
        ) {
            return None;
        }
        Some((place_path(program, left)?, place_path(program, right)?))
    }

    fn signed_joint_subtract_guard(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        comparison: &TableBinaryExpression,
        lower: bool,
    ) -> Option<(String, String)> {
        let (bound, left) = match (comparison.operator, lower) {
            (BinaryOperator::LessOrEqual, true) => (comparison.left, comparison.right),
            (BinaryOperator::GreaterOrEqual, true) => (comparison.right, comparison.left),
            (BinaryOperator::LessOrEqual, false) => (comparison.right, comparison.left),
            (BinaryOperator::GreaterOrEqual, false) => (comparison.left, comparison.right),
            _ => return None,
        };
        let add = program.expression_table.binary_node(bound)?;
        if add.operator != BinaryOperator::Add
            || !meaning::builtin_arithmetic(program, machine, state, bound)
        {
            return None;
        }
        let (extreme_literal, right) = if literal_i64(program, add.left).is_some() {
            (add.left, add.right)
        } else {
            (add.right, add.left)
        };
        let left_primitive = shared_exact_primitive(program, machine, state, left, right)?;
        let right_path = place_path(program, right)?;
        let interval = environment.get(&right_path)?;
        if if lower {
            !(interval.low? >= 0)
        } else {
            !(interval.high? <= 0)
        } {
            return None;
        }
        let extreme = signed_primitive_bound(left_primitive, lower)?;
        if literal_i64(program, extreme_literal) != Some(extreme) {
            return None;
        }
        Some((place_path(program, left)?, right_path))
    }

    fn joint_multiply_guard(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        comparison: &TableBinaryExpression,
    ) -> Option<(String, String)> {
        let (left, bound) = directed_comparison_operands(comparison)?;
        let (divide, left_primitive) =
            exact_bound_binary(program, machine, state, left, bound, BinaryOperator::Divide)?;
        if !matches!(
            left_primitive,
            typed_trees::unsigned_integer_primitive_pattern!()
        ) {
            return None;
        }
        let right_path = place_path(program, divide.right)?;
        if environment.get(&right_path)?.low? < 1 {
            return None;
        }
        let maximum_matches = match left_primitive {
            PrimitiveType::U8 => literal_i64(program, divide.left) == Some(u8::MAX as i64),
            PrimitiveType::U16 => literal_i64(program, divide.left) == Some(u16::MAX as i64),
            PrimitiveType::U32 => literal_i64(program, divide.left) == Some(u32::MAX as i64),
            PrimitiveType::U64 => {
                known_u64_value(program, environment, divide.left) == Some(u64::MAX)
            }
            _ => false,
        };
        if !maximum_matches {
            return None;
        }
        Some((place_path(program, left)?, right_path))
    }

    fn signed_joint_multiply_lower_guard(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        comparison: &TableBinaryExpression,
    ) -> Option<(String, String)> {
        let (bound, left) = directed_comparison_operands(comparison)?;
        signed_joint_multiply_quotient_guard(
            program,
            machine,
            state,
            environment,
            left,
            bound,
            true,
        )
    }

    fn signed_joint_multiply_upper_guard(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        comparison: &TableBinaryExpression,
    ) -> Option<(String, String)> {
        let (left, bound) = directed_comparison_operands(comparison)?;
        signed_joint_multiply_quotient_guard(
            program,
            machine,
            state,
            environment,
            left,
            bound,
            false,
        )
    }

    fn signed_joint_multiply_quotient_guard(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        left: ExpressionHandle,
        bound: ExpressionHandle,
        lower_bound: bool,
    ) -> Option<(String, String)> {
        let (divide, left_primitive) =
            exact_bound_binary(program, machine, state, left, bound, BinaryOperator::Divide)?;
        let right_path = place_path(program, divide.right)?;
        let interval = environment.get(&right_path)?;
        let positive = interval.low.is_some_and(|low| low >= 1);
        let negative = interval.high.is_some_and(|high| high <= -2);
        if !positive && !negative {
            return None;
        }
        let use_minimum = if positive { lower_bound } else { !lower_bound };
        let boundary = signed_primitive_bound(left_primitive, use_minimum)?;
        if literal_i64(program, divide.left) != Some(boundary) {
            return None;
        }
        Some((place_path(program, left)?, right_path))
    }

    fn signed_primitive_bound(primitive: PrimitiveType, minimum: bool) -> Option<i64> {
        Some(match (primitive, minimum) {
            (PrimitiveType::I8, true) => i8::MIN as i64,
            (PrimitiveType::I16, true) => i16::MIN as i64,
            (PrimitiveType::I32, true) => i32::MIN as i64,
            (PrimitiveType::I64, true) => i64::MIN,
            (PrimitiveType::I8, false) => i8::MAX as i64,
            (PrimitiveType::I16, false) => i16::MAX as i64,
            (PrimitiveType::I32, false) => i32::MAX as i64,
            (PrimitiveType::I64, false) => i64::MAX,
            _ => return None,
        })
    }

    fn signed_joint_multiply_negation_guard(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        comparison: &TableBinaryExpression,
    ) -> Option<String> {
        let (boundary, value) = match comparison.operator {
            BinaryOperator::LessOrEqual => (comparison.left, comparison.right),
            BinaryOperator::GreaterOrEqual => (comparison.right, comparison.left),
            _ => return None,
        };
        let value_type = declared_place_type_raw(program, machine, state, value)?;
        let primitive = program.primitive_type_reference(value_type)?;
        if program.arithmetic_domain_for_type_reference(value_type) != ArithmeticDomain::Exact {
            return None;
        }
        let minimum_plus_one = match primitive {
            PrimitiveType::I8 => i8::MIN as i64 + 1,
            PrimitiveType::I16 => i16::MIN as i64 + 1,
            PrimitiveType::I32 => i32::MIN as i64 + 1,
            PrimitiveType::I64 => i64::MIN + 1,
            _ => return None,
        };
        if literal_i64(program, boundary) != Some(minimum_plus_one) {
            return None;
        }
        place_path(program, value)
    }

    pub(crate) fn seed_out_param_ensures(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        call: &typed_trees::statement::TableCall,
        signature: &typed_trees::signature::StateSignature,
        environment: &mut ValueEnvironment,
    ) {
        use typed_trees::signature::SignatureContractKind;
        let arguments = program.statement_table.expression_handles(call.arguments);
        let parameters: Vec<&typed_trees::signature::StateParameter> = program
            .state_signature_parameters(signature)
            .iter()
            .collect();
        let projection = EnsuresProjection {
            program,
            machine,
            state,
            parameters: &parameters,
            arguments,
        };
        for contract in program
            .signature_contracts
            .span_or_empty(signature.contracts)
        {
            if !matches!(contract.kind, SignatureContractKind::Ensures) {
                continue;
            }
            for fact in program.proof_facts.span_or_empty(contract.facts) {
                let Some(expression) = fact.as_expression() else {
                    continue;
                };
                projection.seed_conjunct(*expression, environment);
            }
        }
    }

    pub(crate) struct EnsuresProjection<'a> {
        program: &'a dyn crate::CheckingInput,
        machine: &'a Machine,
        state: Option<&'a State>,
        parameters: &'a [&'a typed_trees::signature::StateParameter],
        arguments: &'a [ExpressionHandle],
    }

    impl EnsuresProjection<'_> {
        fn seed_conjunct(&self, conjunct: ExpressionHandle, environment: &mut ValueEnvironment) {
            let Some(comparison) = self.program.expression_table.binary_node(conjunct) else {
                return;
            };
            if comparison.operator == BinaryOperator::And {
                self.seed_conjunct(comparison.left, environment);
                self.seed_conjunct(comparison.right, environment);
                return;
            }
            let (Some(left), Some(right)) =
                (self.side(comparison.left), self.side(comparison.right))
            else {
                return;
            };
            projected_facts::contribute_projected_comparison(
                self.program,
                environment,
                comparison.operator,
                (&left, comparison.left),
                (&right, comparison.right),
            );
        }

        fn side(&self, expression: ExpressionHandle) -> Option<ProjectedOperand> {
            let program = self.program;
            if literal_i64(program, expression).is_some() {
                return Some(match program.expression_table.expression(expression) {
                    ExpressionNode::Integer(literal) => ProjectedOperand::literal(literal),
                    _ => ProjectedOperand {
                        operand: None,
                        spelled: None,
                        declared_type: None,
                    },
                });
            }
            let path = program.expression_table.name_path_node(expression)?;
            let [parameter_name] = program.expression_table.name_path_members(path.members) else {
                return None;
            };
            let position = self
                .parameters
                .iter()
                .position(|parameter| parameter.name.as_str() == parameter_name.as_str())?;
            crate::reference_shell(program, self.parameters[position].type_reference)?;
            let argument = self.arguments.get(position).copied()?;
            let place = match program.expression_table.expression(argument) {
                ExpressionNode::Borrow(inner) => inner.target,
                _ => argument,
            };
            let spelled = place_path(program, place)?;
            let declared_type = declared_place_type_raw(program, self.machine, self.state, place);
            let operand = self
                .state
                .filter(|_| {
                    declared_type.is_some_and(|declared| {
                        projected_facts::has_fixed_integer_meaning(program, declared)
                    })
                })
                .and_then(|state| {
                    ordered_values::operand(program, self.machine, state, place, None)
                });
            Some(ProjectedOperand {
                operand,
                spelled: Some(spelled),
                declared_type,
            })
        }
    }

    pub(crate) fn incoming_guard_environments(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        frames: Option<&crate::CallFrameResolver>,
    ) -> std::sync::Arc<Vec<(symbols::SymbolHandle, ValueEnvironment)>> {
        let memos = frames.is_some().then(|| program.checking_memos()).flatten();
        if let Some(cached) = memos.and_then(|memos| {
            memos
                .incoming_guard_environments
                .lock()
                .ok()
                .and_then(|environments| environments.get(&machine.symbol).cloned())
        }) {
            return cached;
        }
        let environments = std::sync::Arc::new(arrivals::incoming_environments(
            program, machine, frames, None, None,
        ));
        if let Some(memos) = memos
            && let Ok(mut cached) = memos.incoming_guard_environments.lock()
        {
            cached.insert(machine.symbol, environments.clone());
        }
        environments
    }

    pub(crate) fn incoming_guard_environment(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        frames: Option<&crate::CallFrameResolver>,
    ) -> ValueEnvironment {
        if frames.is_some() && program.checking_memos().is_some() {
            let environments = incoming_guard_environments(program, machine, frames);
            if let Some((_, environment)) = environments
                .iter()
                .find(|(symbol, _)| *symbol == state.symbol)
            {
                return environment.clone();
            }
        }
        arrivals::incoming_environments(program, machine, frames, None, None)
            .into_iter()
            .find_map(|(symbol, environment)| (symbol == state.symbol).then_some(environment))
            .unwrap_or_default()
    }
}
pub(crate) use guard_narrowing::ReturnInference;
pub(crate) mod guard_requirements {
    use super::{ExpressionHandle, Machine, State, ValueEnvironment, ordered_values};
    use crate::CallFrameResolver;
    use crate::machine_calls::calls::CallSite;
    use typed_trees::statement::{StatementNode, TransitionGuardNode, TransitionTargetNode};

    #[allow(clippy::too_many_arguments)]
    pub fn evaluated_call_requires_proven(
        program: &dyn crate::CheckingInput,
        caller: &Machine,
        state: &State,
        statement_index: usize,
        site: CallSite<'_>,
        callee_owner: symbols::SymbolHandle,
        parameters: &[typed_trees::signature::StateParameter],
        arguments: &[ExpressionHandle],
        expression: ExpressionHandle,
    ) -> bool {
        let selected = program
            .machine_holding_state(callee_owner)
            .and_then(|machine| {
                program
                    .state_in_machine(machine, callee_owner)
                    .map(|state| (machine, state))
            })
            .or_else(|| {
                program.machine_by_symbol(callee_owner).and_then(|machine| {
                    program
                        .machine_states(machine)
                        .first()
                        .map(|state| (machine, state))
                })
            });
        let Some((callee, callee_state)) = selected else {
            return false;
        };
        if parameters.len() != arguments.len() {
            return false;
        }
        let has_calls = arguments
            .iter()
            .any(|argument| crate::machine_calls::calls::expression_has_calls(program, *argument));
        let frames = has_calls.then(|| CallFrameResolver::new(program)).flatten();
        let mut evaluated = if !arguments
            .iter()
            .any(|argument| crate::machine_calls::calls::expression_has_calls(program, *argument))
        {
            arguments.last().and_then(|argument| {
                super::guard_narrowing::occurrence_value_environment(
                    program,
                    caller.symbol,
                    state.symbol,
                    *argument,
                )
            })
        } else {
            None
        };
        if evaluated.is_none() {
            evaluated = selected_guard_environment(program, caller, state, statement_index, site);
        }
        let Some(mut evaluated) = evaluated else {
            return false;
        };

        let mut bindings = Vec::new();
        for (parameter, argument) in parameters.iter().zip(arguments) {
            if crate::machine_calls::calls::expression_has_calls(program, *argument) {
                match frames
                    .as_ref()
                    .and_then(|frames| frames.expression_may_write_paths(caller, *argument))
                {
                    Some(writes) => evaluated.invalidate_call_paths(program, Some(state), &writes),
                    None => evaluated.invalidate_unknown_writes(program, Some(state)),
                }
            }
            let place = match program.expression_table.expression(*argument) {
                typed_trees::expression::ExpressionNode::Borrow(borrow) => borrow.target,
                _ => *argument,
            };
            let Some(operand) =
                ordered_values::operand(program, caller, state, place, frames.as_ref())
            else {
                return false;
            };
            bindings.push((ordered_values::Operand::parameter(parameter), operand));
        }
        super::live_integer_constraints::proves_condition(
            program,
            callee,
            callee_state,
            &evaluated,
            expression,
            &bindings,
        )
    }

    fn selected_guard_environment(
        program: &dyn crate::CheckingInput,
        caller: &Machine,
        state: &State,
        statement_index: usize,
        site: CallSite<'_>,
    ) -> Option<ValueEnvironment> {
        let Some(StatementNode::Transition(transition)) =
            program.statement_table.statement_at(state, statement_index)
        else {
            return None;
        };
        let TransitionGuardNode::When(condition) = transition.guard else {
            return None;
        };
        let matches_site = |target| match (program.statement_table.transition_target(target), site)
        {
            (
                TransitionTargetNode::Named {
                    path, arguments, ..
                },
                CallSite::TransitionNamed {
                    path: selected,
                    arguments: actuals,
                    ..
                },
            ) => std::ptr::eq(path, selected) && *arguments == actuals,
            (TransitionTargetNode::Value(value), CallSite::Expression { expression, .. }) => {
                *value == expression
            }
            _ => false,
        };
        let positive = match (
            transition.target.is_valid() && matches_site(transition.target),
            transition.continuation.is_valid() && matches_site(transition.continuation),
        ) {
            (true, false) => true,
            (false, true) => false,
            _ => return None,
        };
        Some(super::guard_narrowing::evaluated_condition_environment(
            program,
            caller,
            Some(state),
            condition,
            positive,
            &ValueEnvironment::new(),
        ))
    }
}
pub(crate) mod integer_carriers {
    use numerics::bignum::BigInt;
    use semantic_vocabulary::{IntegerSign, IntegerType, IntegerValue};
    use typed_trees::types::PrimitiveType;

    pub(crate) fn integer_type(primitive: PrimitiveType) -> Option<IntegerType> {
        let (sign, bits) = primitive.integer_sign_bits()?;
        IntegerType::new(sign, bits).ok()
    }

    pub(crate) fn admitted_integer(
        scalar_type: IntegerType,
        value: &BigInt,
    ) -> Option<IntegerValue> {
        let value = match scalar_type.sign() {
            IntegerSign::Signed => IntegerValue::Signed(i128::from(value.to_i64()?)),
            IntegerSign::Unsigned => IntegerValue::Unsigned(u128::from(value.to_u64()?)),
        };
        scalar_type.admits(value).then_some(value)
    }

    pub(crate) fn integer_magnitude(value: IntegerValue) -> BigInt {
        match value {
            IntegerValue::Signed(value) => BigInt::from_i128(value),
            IntegerValue::Unsigned(value) => BigInt::from_u128(value),
        }
    }
}
pub(crate) mod integer_ranges {
    use crate::CheckingInput;
    use crate::frozen_program::expression_table;
    use crate::proof_contracts::arithmetic_domains::expression_analysis::analyze;
    use crate::proof_contracts::arithmetic_domains::interval::Interval;
    use crate::proof_contracts::arithmetic_domains::place_paths::place_path;
    use crate::proof_contracts::arithmetic_domains::value_environment::ValueEnvironment;
    pub(crate) use crate::value_custody::atomic_operations::is_atomic_type;
    use crate::value_custody::places::declared_place_type_raw;
    use diagnostics::Diagnostic;
    use numerics::arithmetic::ArithmeticDomain;
    use typed_trees::expression::{ExpressionHandle, ExpressionNode};
    use typed_trees::machine::Machine;
    use typed_trees::state::State;
    use typed_trees::types::{PrimitiveType, TypeReferenceHandle};

    pub fn integer_widen_is_total(source: PrimitiveType, target: PrimitiveType) -> bool {
        fn shape(primitive: PrimitiveType) -> Option<(bool, u8)> {
            primitive
                .integer_sign_bits()
                .map(|(sign, bits)| (sign == semantic_vocabulary::IntegerSign::Signed, bits as u8))
        }
        let Some((source_signed, source_bits)) = shape(source) else {
            return false;
        };
        let Some((target_signed, target_bits)) = shape(target) else {
            return false;
        };
        source_bits < target_bits && (!source_signed || target_signed)
    }

    pub(crate) fn validate_anonymous_integer_range(
        program: &dyn CheckingInput,
        destination: TypeReferenceHandle,
        expression: ExpressionHandle,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> Option<(Interval, Option<PrimitiveType>, Option<ArithmeticDomain>)> {
        let primitive = program.primitive_type_reference(destination)?;
        validate_anonymous_integer_primitive_range(
            program,
            primitive,
            expression,
            owner,
            diagnostics,
        )
    }

    pub(crate) fn validate_anonymous_integer_primitive_range(
        program: &dyn CheckingInput,
        primitive: PrimitiveType,
        expression: ExpressionHandle,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> Option<(Interval, Option<PrimitiveType>, Option<ArithmeticDomain>)> {
        if !primitive.accepts_integer_literal() {
            return None;
        }
        if let Some(dispatch) = expression_table(program).match_node(expression) {
            let mut pending = expression_table(program)
                .match_arms(dispatch.arms)
                .iter()
                .map(|arm| arm.value)
                .collect::<Vec<_>>();
            let mut visited = vec![expression];
            while let Some(value) = pending.pop() {
                if !program.expression_table.expression_is_valid(value) || visited.contains(&value)
                {
                    continue;
                }
                visited.push(value);
                if let Some(nested) = expression_table(program).match_node(value) {
                    pending.extend(
                        expression_table(program)
                            .match_arms(nested.arms)
                            .iter()
                            .map(|arm| arm.value),
                    );
                } else {
                    validate_anonymous_integer_primitive_range(
                        program,
                        primitive,
                        value,
                        owner,
                        diagnostics,
                    );
                }
            }
            return None;
        }
        let evaluated = crate::value_custody::literals::anonymous_numeric_value(
            program,
            expression,
            &mut |expression| {
                crate::value_custody::literals::has_anonymous_operator_meaning(program, expression)
            },
        )?;
        let Some(value) = evaluated.value.to_integer_exact() else {
            diagnostics.push(
                Diagnostic::error(format!(
                    "anonymous value `{}` is not an integer and cannot land in `{}` in {owner}; \
             type an operand before division if integer division was intended",
                    evaluated.value,
                    primitive.name(),
                ))
                .with_source_span(expression_table(program).source_span(expression)),
            );
            return Some((Interval::UNBOUNDED, None, None));
        };
        if primitive == PrimitiveType::Addr && value.to_u64().is_some() {
            return None;
        }
        if let Some(literal) = crate::value_custody::literals::land_integer_value(&value, primitive)
        {
            return Some((literal_interval(&literal), Some(primitive), None));
        }
        diagnostics.push(Diagnostic::error(format!(
            "anonymous integer value `{value}` does not fit destination `{}` in {owner}",
            primitive.name()
        )));
        Some((Interval::UNBOUNDED, None, None))
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn validate_value_range(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        target_primitive: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> (Interval, Option<PrimitiveType>, Option<ArithmeticDomain>) {
        validate_value_range_with_decision_sink(
            program,
            machine,
            state,
            expression,
            environment,
            target_primitive,
            target_domain,
            owner,
            diagnostics,
            ArithmeticDecisionSink::Discard,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn validate_value_range_retaining_decisions(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        target_primitive: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
        decisions: &mut super::ArithmeticDecisions,
    ) -> (Interval, Option<PrimitiveType>, Option<ArithmeticDomain>) {
        validate_value_range_with_decision_sink(
            program,
            machine,
            state,
            expression,
            environment,
            target_primitive,
            target_domain,
            owner,
            diagnostics,
            ArithmeticDecisionSink::All(decisions),
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn validate_value_range_retaining_obligations(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        target_primitive: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
        obligations: &mut Vec<checked_trees::IntegerRangeObligation>,
    ) -> (Interval, Option<PrimitiveType>, Option<ArithmeticDomain>) {
        validate_value_range_with_decision_sink(
            program,
            machine,
            state,
            expression,
            environment,
            target_primitive,
            target_domain,
            owner,
            diagnostics,
            ArithmeticDecisionSink::Obligations(obligations),
        )
    }

    pub(crate) enum ArithmeticDecisionSink<'a> {
        Discard,
        Obligations(&'a mut Vec<checked_trees::IntegerRangeObligation>),
        All(&'a mut super::ArithmeticDecisions),
    }

    impl ArithmeticDecisionSink<'_> {
        fn retains_execution_receipts(&self) -> bool {
            matches!(self, Self::All(_))
        }

        fn publish(self, decisions: super::ArithmeticDecisions) {
            match self {
                Self::Discard => {}
                Self::Obligations(obligations) => {
                    obligations.extend(decisions.integer_range_obligations)
                }
                Self::All(retained) => retained.extend(decisions),
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn validate_value_range_with_decision_sink(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        target_primitive: Option<PrimitiveType>,
        target_domain: ArithmeticDomain,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
        retained: ArithmeticDecisionSink<'_>,
    ) -> (Interval, Option<PrimitiveType>, Option<ArithmeticDomain>) {
        let retain_trap_receipts = retained.retains_execution_receipts();
        let mut decisions = super::ArithmeticDecisions::default();
        if !expression.is_valid() {
            return (Interval::UNBOUNDED, None, None);
        }
        validate_anonymous_address_landing(
            program,
            machine,
            state,
            expression,
            target_primitive,
            owner,
            diagnostics,
            &mut decisions.integer_range_obligations,
        );
        let first_diagnostic = diagnostics.len();
        let analysis = analyze(
            program,
            machine,
            state,
            expression,
            environment,
            target_primitive,
            target_domain,
            owner,
            true,
            retain_trap_receipts,
            diagnostics,
        );
        if !diagnostics[first_diagnostic..]
            .iter()
            .any(Diagnostic::is_error)
        {
            decisions.extend(analysis.decisions);
        }
        retained.publish(decisions);
        (
            analysis.value.interval,
            analysis.value.primitive,
            analysis.value.domain,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn validate_anonymous_address_landing(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        target: Option<PrimitiveType>,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
        obligations: &mut Vec<checked_trees::IntegerRangeObligation>,
    ) {
        if target != Some(PrimitiveType::Addr)
            || !crate::value_custody::literals::has_anonymous_numeric_results(program, expression)
        {
            return;
        }
        let before = diagnostics.len();
        validate_anonymous_integer_primitive_range(
            program,
            PrimitiveType::Addr,
            expression,
            owner,
            diagnostics,
        );
        if diagnostics.len() != before {
            return;
        }
        let fit = crate::proof_contracts::contract_entailment::anonymous_value_fit_at_occurrence(
            program,
            machine,
            state,
            expression,
            PrimitiveType::Addr,
        );
        if !fit.retain(expression, machine.symbol, owner, obligations) {
            diagnostics.push(
                Diagnostic::error(format!(
                    "anonymous address value cannot prove fit in `addr::Bound` in {owner}",
                ))
                .with_source_span(expression_table(program).source_span(expression)),
            );
        }
    }

    pub(crate) fn literal_interval(literal: &numerics::literals::IntegerLiteral) -> Interval {
        match literal.value_i64() {
            Some(value) => Interval::constant(value),
            None if !literal.is_negative() => Interval {
                low: Some(i64::MAX),
                high: None,
            },
            None => Interval {
                low: None,
                high: Some(i64::MIN),
            },
        }
    }

    pub(crate) fn primitive_range(primitive: PrimitiveType) -> Option<Interval> {
        let (low, high): (Option<i64>, Option<i64>) = match primitive {
            PrimitiveType::I8 => (Some(i8::MIN as i64), Some(i8::MAX as i64)),
            PrimitiveType::U8 => (Some(0), Some(u8::MAX as i64)),
            PrimitiveType::I16 => (Some(i16::MIN as i64), Some(i16::MAX as i64)),
            PrimitiveType::U16 => (Some(0), Some(u16::MAX as i64)),
            PrimitiveType::I32 => (Some(i32::MIN as i64), Some(i32::MAX as i64)),
            PrimitiveType::U32 => (Some(0), Some(u32::MAX as i64)),
            PrimitiveType::I64 => (Some(i64::MIN), Some(i64::MAX)),
            PrimitiveType::U64 | PrimitiveType::Addr => (Some(0), None),
            PrimitiveType::Selector
            | PrimitiveType::Bool
            | PrimitiveType::F32
            | PrimitiveType::F64 => {
                return None;
            }
        };
        Some(Interval { low, high })
    }

    pub(crate) fn integer_interval_fits_primitive(
        source: Interval,
        source_primitive: PrimitiveType,
        target: PrimitiveType,
    ) -> bool {
        if target == PrimitiveType::Addr {
            return source_primitive == target;
        }
        let Some(source_range) = primitive_range(source_primitive) else {
            return false;
        };
        let Some((target_minimum, target_maximum)) = target.integer_bounds() else {
            return false;
        };
        let source = if source_range.contains(source) {
            source
        } else {
            source_range
        };
        let fixed_source = (source_primitive != PrimitiveType::Addr)
            .then(|| source_primitive.integer_bounds())
            .flatten();
        let minimum = source
            .low
            .map(i128::from)
            .or_else(|| fixed_source.map(|bounds| bounds.0));
        let maximum = source
            .high
            .map(i128::from)
            .or_else(|| fixed_source.map(|bounds| bounds.1));
        minimum.is_some_and(|minimum| minimum >= target_minimum)
            && maximum.is_some_and(|maximum| maximum <= target_maximum)
    }

    pub(crate) fn integer_bit_width(primitive: PrimitiveType) -> Option<i64> {
        match primitive {
            PrimitiveType::I8 | PrimitiveType::U8 => Some(8),
            PrimitiveType::I16 | PrimitiveType::U16 => Some(16),
            PrimitiveType::I32 | PrimitiveType::U32 => Some(32),
            PrimitiveType::I64 | PrimitiveType::U64 => Some(64),
            PrimitiveType::Addr
            | PrimitiveType::Selector
            | PrimitiveType::Bool
            | PrimitiveType::F32
            | PrimitiveType::F64 => None,
        }
    }

    pub(crate) fn exact_unsigned_widened_multiply_fits(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        left: ExpressionHandle,
        right: ExpressionHandle,
    ) -> bool {
        let operand = |expression| -> Option<(i64, PrimitiveType)> {
            let cast = expression_table(program).cast_node(expression)?;
            if cast.form.is_recast()
                || !cast.semantic_domain.is_empty()
                || cast.domain != ArithmeticDomain::Exact
            {
                return None;
            }
            let source_type = declared_place_type_raw(program, machine, state, cast.value)?;
            let source = program.primitive_type_reference(source_type)?;
            let target = program.primitive_type_reference(cast.target_type)?;
            if !matches!(
                source,
                PrimitiveType::U8 | PrimitiveType::U16 | PrimitiveType::U32
            ) || !matches!(
                target,
                PrimitiveType::U16 | PrimitiveType::U32 | PrimitiveType::U64
            ) {
                return None;
            }
            let source_width = integer_bit_width(source)?;
            let target_width = integer_bit_width(target)?;
            (source_width < target_width).then_some((source_width, target))
        };
        let Some((left_width, left_target)) = operand(left) else {
            return false;
        };
        let Some((right_width, right_target)) = operand(right) else {
            return false;
        };
        left_target == right_target
            && integer_bit_width(left_target).is_some_and(|width| left_width + right_width <= width)
    }

    pub(crate) fn u64_exact_shift_left_fits(value: Interval, count: Interval) -> bool {
        let (Some(value_low), Some(value_high), Some(count_low), Some(count_high)) =
            (value.low, value.high, count.low, count.high)
        else {
            return false;
        };
        if value_low < 0 || count_low < 0 || count_high >= 64 {
            return false;
        }
        u128::try_from(value_high)
            .ok()
            .and_then(|value| value.checked_shl(count_high as u32))
            .is_some_and(|maximum| maximum <= u128::from(u64::MAX))
    }

    pub(crate) fn literal_i64(
        program: &dyn CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<i64> {
        expression_table(program).constant_integer_value(expression)
    }

    pub(crate) fn literal_u64(
        program: &dyn CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<u64> {
        match expression_table(program).expression(expression) {
            ExpressionNode::Integer(literal) => literal.value_bignum()?.to_u64(),
            ExpressionNode::Borrow(inner) => literal_u64(program, inner.target),
            _ => None,
        }
    }

    pub(crate) fn known_u64_value(
        program: &dyn CheckingInput,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
    ) -> Option<u64> {
        literal_u64(program, expression)
            .or_else(|| {
                let path = place_path(program, expression)?;
                environment.known_u64_values.get(&path).copied()
            })
            .or_else(|| {
                crate::value_custody::constants::completed_integer_constant(program, expression)
                    .and_then(|value| value.value.to_u64())
            })
    }

    pub(crate) fn integer_source_bounds(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        primitive: PrimitiveType,
        environment: &ValueEnvironment,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> Option<(i128, i128)> {
        let (interval, _, _) = validate_value_range(
            program,
            machine,
            Some(state),
            expression,
            environment,
            None,
            ArithmeticDomain::Exact,
            "integer-to-float coercion source",
            diagnostics,
        );
        integer_source_bounds_from_interval(program, environment, expression, primitive, interval)
    }

    pub(crate) fn integer_source_bounds_from_interval(
        program: &dyn CheckingInput,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
        primitive: PrimitiveType,
        interval: Interval,
    ) -> Option<(i128, i128)> {
        let carrier = primitive_range(primitive)?;
        if let Some(value) = known_u64_value(program, environment, expression) {
            return Some((i128::from(value), i128::from(value)));
        }
        let interval = interval.intersect(carrier);
        let minimum = i128::from(interval.low?);
        let maximum = interval
            .high
            .map(i128::from)
            .or_else(|| (primitive == PrimitiveType::U64).then_some(i128::from(u64::MAX)))?;
        (minimum <= maximum).then_some((minimum, maximum))
    }

    pub(crate) fn primitive_name(primitive: PrimitiveType) -> &'static str {
        match primitive {
            PrimitiveType::I8 => "i8",
            PrimitiveType::U8 => "u8",
            PrimitiveType::I16 => "i16",
            PrimitiveType::U16 => "u16",
            PrimitiveType::I32 => "i32",
            PrimitiveType::U32 => "u32",
            PrimitiveType::I64 => "i64",
            PrimitiveType::U64 => "u64",
            PrimitiveType::Addr => "addr",
            PrimitiveType::Bool => "bool",
            PrimitiveType::Selector => "selector",
            PrimitiveType::F32 => "f32",
            PrimitiveType::F64 => "f64",
        }
    }
}
pub(crate) use integer_carriers::{admitted_integer, integer_magnitude, integer_type};
pub(crate) mod ordering_premises {
    use symbols::SymbolHandle;
    use typed_trees::expression::ExpressionHandle;

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum IntegerBound {
        Integer(i64),
        EntryRead(crate::ImmutableEntryReadIdentity),
        Symbol {
            symbol: SymbolHandle,
            offset: i64,
        },
        Storage {
            symbol: SymbolHandle,
        },
        Projected {
            symbol: SymbolHandle,
            segments: Vec<facts::PlaceSegment>,
        },
        StorageProjected {
            symbol: SymbolHandle,
            segments: Vec<facts::PlaceSegment>,
        },
        SymbolSum {
            first: SymbolHandle,
            second: SymbolHandle,
            offset: i64,
        },
        CallResult {
            expression: ExpressionHandle,
            segments: Vec<facts::PlaceSegment>,
        },
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum IntegerOrderingRelation {
        LessOrEqual,
        StrictlyBefore,
        Equal,
        NotEqual,
    }

    #[derive(Debug, Clone)]
    pub struct StatedOrderingPremise {
        pub relation: IntegerOrderingRelation,
        pub left: IntegerBound,
        pub right: IntegerBound,
        pub parameter_arguments: Option<Vec<(symbols::SymbolHandle, symbols::SymbolHandle)>>,
    }

    impl StatedOrderingPremise {
        pub fn equality_candidates(&self) -> Option<[IntegerBound; 2]> {
            matches!(self.relation, IntegerOrderingRelation::Equal)
                .then(|| [self.left.clone(), self.right.clone()])
        }

        pub fn captured_equality(left: IntegerBound, right: IntegerBound) -> Self {
            Self {
                relation: IntegerOrderingRelation::Equal,
                left,
                right,
                parameter_arguments: None,
            }
        }
    }

    pub fn prove_integer_ordering(
        premises: &[StatedOrderingPremise],
        left: IntegerBound,
        relation: IntegerOrderingRelation,
        right: IntegerBound,
    ) -> bool {
        const EQUALITY_CONSULTATIONS: usize = 4096;
        let mut remaining = premises
            .len()
            .saturating_mul(premises.len())
            .saturating_add(EQUALITY_CONSULTATIONS);
        if prove_from_premises(
            premises,
            left.clone(),
            relation,
            right.clone(),
            &mut remaining,
        ) {
            return true;
        }
        let mut candidates = Vec::new();
        for candidate in premises
            .iter()
            .filter_map(StatedOrderingPremise::equality_candidates)
            .flatten()
        {
            if !candidates.contains(&candidate) {
                candidates.push(candidate);
            }
        }
        let mut pending = vec![(left, right)];
        let mut visited = Vec::new();
        while let Some((left, right)) = pending.pop() {
            if visited.contains(&(left.clone(), right.clone())) {
                continue;
            }
            visited.push((left.clone(), right.clone()));
            for candidate in &candidates {
                for (subject, next) in [
                    (&left, (candidate.clone(), right.clone())),
                    (&right, (left.clone(), candidate.clone())),
                ] {
                    if subject == candidate || visited.contains(&next) || pending.contains(&next) {
                        continue;
                    }
                    if !prove_from_premises(
                        premises,
                        subject.clone(),
                        IntegerOrderingRelation::Equal,
                        candidate.clone(),
                        &mut remaining,
                    ) {
                        if remaining == 0 {
                            return false;
                        }
                        continue;
                    }
                    if prove_from_premises(
                        premises,
                        next.0.clone(),
                        relation,
                        next.1.clone(),
                        &mut remaining,
                    ) {
                        return true;
                    }
                    if remaining == 0 {
                        return false;
                    }
                    pending.push(next);
                }
            }
        }
        false
    }

    fn prove_from_premises(
        premises: &[StatedOrderingPremise],
        left: IntegerBound,
        relation: IntegerOrderingRelation,
        right: IntegerBound,
        remaining: &mut usize,
    ) -> bool {
        for premise in premises {
            if *remaining == 0 {
                return false;
            }
            *remaining -= 1;
            if premise_proves(premise, left.clone(), relation, right.clone()) {
                return true;
            }
        }
        for first_index in 0..premises.len() {
            for second_index in 0..premises.len() {
                if first_index == second_index {
                    continue;
                }
                if *remaining == 0 {
                    return false;
                }
                *remaining -= 1;
                if premise_chain_proves(
                    &premises[first_index],
                    &premises[second_index],
                    left.clone(),
                    relation,
                    right.clone(),
                ) {
                    return true;
                }
            }
        }
        false
    }

    pub fn premise_proves(
        premise: &StatedOrderingPremise,
        left: IntegerBound,
        query: IntegerOrderingRelation,
        right: IntegerBound,
    ) -> bool {
        let (Some(left), Some(right)) = (
            transport_query_bound(premise, left),
            transport_query_bound(premise, right),
        ) else {
            return false;
        };
        premise_orientation_proves(
            premise.left.clone(),
            premise.relation,
            premise.right.clone(),
            left.clone(),
            query,
            right.clone(),
        ) || (matches!(
            premise.relation,
            IntegerOrderingRelation::Equal | IntegerOrderingRelation::NotEqual
        ) && premise_orientation_proves(
            premise.right.clone(),
            premise.relation,
            premise.left.clone(),
            left,
            query,
            right,
        ))
    }

    fn transport_query_bound(
        premise: &StatedOrderingPremise,
        bound: IntegerBound,
    ) -> Option<IntegerBound> {
        let Some(bindings) = &premise.parameter_arguments else {
            return Some(bound);
        };
        let argument = |symbol| {
            bindings
                .iter()
                .find_map(|(parameter, argument)| (*parameter == symbol).then_some(*argument))
        };
        Some(match bound {
            IntegerBound::Integer(_) => bound,
            IntegerBound::EntryRead(_) => return None,
            IntegerBound::Symbol { symbol, offset } => IntegerBound::Symbol {
                symbol: argument(symbol)?,
                offset,
            },
            IntegerBound::Storage { symbol } => IntegerBound::Storage {
                symbol: argument(symbol)?,
            },
            IntegerBound::Projected { symbol, segments } => IntegerBound::Projected {
                symbol: argument(symbol)?,
                segments,
            },
            IntegerBound::StorageProjected { symbol, segments } => IntegerBound::StorageProjected {
                symbol: argument(symbol)?,
                segments,
            },
            IntegerBound::CallResult { .. } => bound,
            IntegerBound::SymbolSum {
                first,
                second,
                offset,
            } => {
                let first = argument(first)?;
                let second = argument(second)?;
                if first == second {
                    return None;
                }
                let (first, second) = if (first.arena_index(), first.generation())
                    < (second.arena_index(), second.generation())
                {
                    (first, second)
                } else {
                    (second, first)
                };
                IntegerBound::SymbolSum {
                    first,
                    second,
                    offset,
                }
            }
        })
    }

    fn premise_orientation_proves(
        premise_left: IntegerBound,
        premise: IntegerOrderingRelation,
        premise_right: IntegerBound,
        left: IntegerBound,
        query: IntegerOrderingRelation,
        right: IntegerBound,
    ) -> bool {
        let (Some(left_shift), Some(right_shift)) = (
            bound_shift(left, premise_left),
            bound_shift(right, premise_right),
        ) else {
            return false;
        };
        use IntegerOrderingRelation as Relation;
        match (premise, query) {
            (Relation::LessOrEqual, Relation::LessOrEqual) => left_shift <= right_shift,
            (Relation::LessOrEqual, Relation::StrictlyBefore) => left_shift < right_shift,
            (Relation::LessOrEqual, Relation::Equal) => false,
            (Relation::LessOrEqual, Relation::NotEqual) => left_shift < right_shift,
            (Relation::StrictlyBefore, Relation::LessOrEqual) => right_shift
                .checked_add(1)
                .is_none_or(|bound| left_shift <= bound),
            (Relation::StrictlyBefore, Relation::StrictlyBefore) => left_shift <= right_shift,
            (Relation::StrictlyBefore, Relation::Equal) => false,
            (Relation::StrictlyBefore, Relation::NotEqual) => left_shift <= right_shift,
            (Relation::Equal, Relation::LessOrEqual) => left_shift <= right_shift,
            (Relation::Equal, Relation::StrictlyBefore) => left_shift < right_shift,
            (Relation::Equal, Relation::Equal) => left_shift == right_shift,
            (Relation::Equal, Relation::NotEqual) => left_shift != right_shift,
            (Relation::NotEqual, Relation::NotEqual) => left_shift == right_shift,
            (Relation::NotEqual, _) => false,
        }
    }

    pub fn premise_chain_proves(
        first: &StatedOrderingPremise,
        second: &StatedOrderingPremise,
        left: IntegerBound,
        query: IntegerOrderingRelation,
        right: IntegerBound,
    ) -> bool {
        first_legs(first).into_iter().flatten().any(|first_leg| {
            second_legs(second).into_iter().flatten().any(|second_leg| {
                chained_legs_prove(
                    first_leg.clone(),
                    second_leg,
                    first,
                    second,
                    left.clone(),
                    query,
                    right.clone(),
                )
            })
        })
    }

    #[derive(Clone)]
    pub(crate) struct ChainLeg {
        outer: IntegerBound,
        relation: IntegerOrderingRelation,
        middle: IntegerBound,
    }

    fn legs(
        premise: &StatedOrderingPremise,
        outer: &IntegerBound,
        middle: &IntegerBound,
    ) -> [Option<ChainLeg>; 2] {
        let stored = Some(ChainLeg {
            outer: outer.clone(),
            relation: premise.relation,
            middle: middle.clone(),
        });
        let flipped = matches!(
            premise.relation,
            IntegerOrderingRelation::Equal | IntegerOrderingRelation::NotEqual
        )
        .then_some(ChainLeg {
            outer: middle.clone(),
            relation: premise.relation,
            middle: outer.clone(),
        });
        [stored, flipped]
    }

    fn first_legs(premise: &StatedOrderingPremise) -> [Option<ChainLeg>; 2] {
        legs(premise, &premise.left, &premise.right)
    }

    fn second_legs(premise: &StatedOrderingPremise) -> [Option<ChainLeg>; 2] {
        legs(premise, &premise.right, &premise.left)
    }

    fn chained_legs_prove(
        first_leg: ChainLeg,
        second_leg: ChainLeg,
        first: &StatedOrderingPremise,
        second: &StatedOrderingPremise,
        left: IntegerBound,
        query: IntegerOrderingRelation,
        right: IntegerBound,
    ) -> bool {
        use IntegerOrderingRelation as Relation;
        let transports_disequality = match (first_leg.relation, second_leg.relation) {
            (Relation::NotEqual, Relation::Equal) | (Relation::Equal, Relation::NotEqual) => true,
            (Relation::NotEqual, _) | (_, Relation::NotEqual) => return false,
            _ => false,
        };
        let Some(middle_gap) = bound_shift(second_leg.middle, first_leg.middle) else {
            return false;
        };
        if middle_gap < 0 || (transports_disequality && middle_gap != 0) {
            return false;
        }
        let relation = if transports_disequality {
            Relation::NotEqual
        } else if middle_gap > 0 {
            Relation::StrictlyBefore
        } else {
            match (first_leg.relation, second_leg.relation) {
                (Relation::Equal, relation) | (relation, Relation::Equal) => relation,
                (Relation::StrictlyBefore, _) | (_, Relation::StrictlyBefore) => {
                    Relation::StrictlyBefore
                }
                (Relation::LessOrEqual, Relation::LessOrEqual) => Relation::LessOrEqual,
                _ => return false,
            }
        };
        let (Some(left), Some(right)) = (
            transport_query_bound(first, left),
            transport_query_bound(second, right),
        ) else {
            return false;
        };
        premise_orientation_proves(
            first_leg.outer,
            relation,
            second_leg.outer,
            left,
            query,
            right,
        )
    }

    fn bound_shift(value: IntegerBound, base: IntegerBound) -> Option<i64> {
        match (value, base) {
            (IntegerBound::EntryRead(value), IntegerBound::EntryRead(base)) if value == base => {
                Some(0)
            }
            (IntegerBound::Integer(value), IntegerBound::Integer(base)) => value.checked_sub(base),
            (
                IntegerBound::Symbol {
                    symbol: value_symbol,
                    offset: value_offset,
                },
                IntegerBound::Symbol {
                    symbol: base_symbol,
                    offset: base_offset,
                },
            ) if value_symbol == base_symbol => value_offset.checked_sub(base_offset),
            (
                IntegerBound::Storage {
                    symbol: value_symbol,
                },
                IntegerBound::Storage {
                    symbol: base_symbol,
                },
            ) if value_symbol == base_symbol => Some(0),
            (
                IntegerBound::Projected {
                    symbol: value_symbol,
                    segments: value_segments,
                },
                IntegerBound::Projected {
                    symbol: base_symbol,
                    segments: base_segments,
                },
            ) if value_symbol == base_symbol && value_segments == base_segments => Some(0),
            (
                IntegerBound::StorageProjected {
                    symbol: value_symbol,
                    segments: value_segments,
                },
                IntegerBound::StorageProjected {
                    symbol: base_symbol,
                    segments: base_segments,
                },
            ) if value_symbol == base_symbol && value_segments == base_segments => Some(0),
            (
                IntegerBound::SymbolSum {
                    first: value_first,
                    second: value_second,
                    offset: value_offset,
                },
                IntegerBound::SymbolSum {
                    first: base_first,
                    second: base_second,
                    offset: base_offset,
                },
            ) if value_first == base_first && value_second == base_second => {
                value_offset.checked_sub(base_offset)
            }
            (
                IntegerBound::CallResult {
                    expression: value_expression,
                    segments: value_segments,
                },
                IntegerBound::CallResult {
                    expression: base_expression,
                    segments: base_segments,
                },
            ) if value_expression == base_expression && value_segments == base_segments => Some(0),
            _ => None,
        }
    }

    pub fn integer_bound_terms_equal(left: IntegerBound, right: IntegerBound) -> bool {
        match (left, right) {
            (IntegerBound::EntryRead(left), IntegerBound::EntryRead(right)) => left == right,
            (IntegerBound::Integer(_), IntegerBound::Integer(_)) => true,
            (
                IntegerBound::Symbol {
                    symbol: left_symbol,
                    ..
                },
                IntegerBound::Symbol {
                    symbol: right_symbol,
                    ..
                },
            ) => left_symbol == right_symbol,
            (
                IntegerBound::SymbolSum {
                    first: left_first,
                    second: left_second,
                    ..
                },
                IntegerBound::SymbolSum {
                    first: right_first,
                    second: right_second,
                    ..
                },
            ) => left_first == right_first && left_second == right_second,
            (
                IntegerBound::Projected {
                    symbol: left_symbol,
                    segments: left_segments,
                },
                IntegerBound::Projected {
                    symbol: right_symbol,
                    segments: right_segments,
                },
            ) => left_symbol == right_symbol && left_segments == right_segments,
            (
                IntegerBound::CallResult {
                    expression: left_expression,
                    segments: left_segments,
                },
                IntegerBound::CallResult {
                    expression: right_expression,
                    segments: right_segments,
                },
            ) => left_expression == right_expression && left_segments == right_segments,
            _ => false,
        }
    }

    pub fn integer_bound_offset(bound: IntegerBound) -> Option<i64> {
        match bound {
            IntegerBound::Integer(value) => Some(value),
            IntegerBound::EntryRead(_) => Some(0),
            IntegerBound::Symbol { offset, .. } => Some(offset),
            IntegerBound::Storage { .. } => Some(0),
            IntegerBound::Projected { .. } | IntegerBound::StorageProjected { .. } => Some(0),
            IntegerBound::CallResult { .. } => Some(0),
            IntegerBound::SymbolSum { offset, .. } => Some(offset),
        }
    }

    pub fn propagate_integer_upper_bounds<Subject: Clone + Eq, Collection: Clone + Eq>(
        orderings: &[(Subject, Subject, bool)],
        indexes: &mut Vec<(Collection, Subject)>,
        range_bounds: &mut Vec<(Collection, Subject)>,
    ) {
        loop {
            let mut grown = false;
            for (lower, upper, strict) in orderings {
                for (collection, _) in indexes
                    .clone()
                    .into_iter()
                    .filter(|(_, index)| index == upper)
                {
                    let consequence = (collection, lower.clone());
                    if !indexes.contains(&consequence) {
                        indexes.push(consequence);
                        grown = true;
                    }
                }
                for (collection, _) in range_bounds
                    .clone()
                    .into_iter()
                    .filter(|(_, bound)| bound == upper)
                {
                    let consequence = (collection, lower.clone());
                    if *strict {
                        if !indexes.contains(&consequence) {
                            indexes.push(consequence);
                            grown = true;
                        }
                    } else if !range_bounds.contains(&consequence) {
                        range_bounds.push(consequence);
                        grown = true;
                    }
                }
            }
            if !grown {
                break;
            }
        }
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn integer_premise_oracle_requires_each_exact_relation() {
            let mut symbols = symbols::SymbolTableBuilder::new();
            let mut subject = |name| IntegerBound::Symbol {
                symbol: symbols.insert_root(
                    symbols::SymbolKind::Root,
                    symbols::SymbolNameRef::Static(name),
                ),
                offset: 0,
            };
            let left = subject("left");
            let middle = subject("middle");
            let right = subject("right");
            let premise = |left, relation, right| StatedOrderingPremise {
                left,
                relation,
                right,
                parameter_arguments: None,
            };
            let first = premise(
                left.clone(),
                IntegerOrderingRelation::StrictlyBefore,
                middle.clone(),
            );
            let second = premise(
                middle.clone(),
                IntegerOrderingRelation::LessOrEqual,
                right.clone(),
            );
            assert!(prove_integer_ordering(
                &[first.clone(), second],
                left.clone(),
                IntegerOrderingRelation::StrictlyBefore,
                right.clone()
            ));
            assert!(!prove_integer_ordering(
                &[first],
                left.clone(),
                IntegerOrderingRelation::StrictlyBefore,
                right.clone()
            ));

            let different = premise(
                left.clone(),
                IntegerOrderingRelation::NotEqual,
                middle.clone(),
            );
            let equal = premise(
                middle.clone(),
                IntegerOrderingRelation::Equal,
                right.clone(),
            );
            assert!(prove_integer_ordering(
                &[different.clone(), equal.clone()],
                left.clone(),
                IntegerOrderingRelation::NotEqual,
                right.clone()
            ));
            assert!(!prove_integer_ordering(
                &[different.clone(), equal],
                left.clone(),
                IntegerOrderingRelation::StrictlyBefore,
                right.clone()
            ));
            let loose = premise(middle, IntegerOrderingRelation::LessOrEqual, right.clone());
            assert!(!prove_integer_ordering(
                &[different, loose],
                left,
                IntegerOrderingRelation::NotEqual,
                right
            ));
        }

        #[test]
        fn integer_upper_bound_closure_keeps_strictness_and_missing_links() {
            let mut indexes = Vec::new();
            let mut ranges = vec![("items", "end")];
            propagate_integer_upper_bounds(
                &[("first", "middle", false), ("middle", "end", true)],
                &mut indexes,
                &mut ranges,
            );
            assert!(indexes.contains(&("items", "first")));
            assert!(indexes.contains(&("items", "middle")));

            let mut missing_indexes = Vec::new();
            let mut missing_ranges = vec![("items", "end")];
            propagate_integer_upper_bounds(
                &[("first", "middle", false)],
                &mut missing_indexes,
                &mut missing_ranges,
            );
            assert!(missing_indexes.is_empty());
            assert_eq!(missing_ranges, vec![("items", "end")]);

            let mut loose_indexes = Vec::new();
            let mut loose_ranges = vec![("items", "end")];
            propagate_integer_upper_bounds(
                &[("first", "end", false)],
                &mut loose_indexes,
                &mut loose_ranges,
            );
            assert!(loose_indexes.is_empty());
            assert!(loose_ranges.contains(&("items", "first")));
        }
    }
}
pub use ordering_premises::{
    IntegerBound, IntegerOrderingRelation, StatedOrderingPremise, integer_bound_offset,
    integer_bound_terms_equal, premise_chain_proves, premise_proves,
    propagate_integer_upper_bounds, prove_integer_ordering,
};
pub(crate) mod expression_intervals {
    use facts::IntegerRange;
    use numerics::bignum::BigInt;
    use typed_trees::expression::ExpressionHandle;
    use typed_trees::types::PrimitiveType;

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct ExpressionInterval {
        pub expression: ExpressionHandle,
        pub low: Option<i64>,
        pub high: Option<i64>,
    }

    impl ExpressionInterval {
        pub fn carrier_range(&self, primitive: PrimitiveType) -> Option<IntegerRange> {
            let mut range = super::carrier_integer_range(primitive)?;
            if let Some(low) = self.low {
                range.minimum = range.minimum.max(BigInt::from_i64(low));
            }
            if let Some(high) = self.high {
                range.maximum = range.maximum.min(BigInt::from_i64(high));
            }
            (range.minimum <= range.maximum).then_some(range)
        }
    }

    pub fn expression_interval(
        intervals: &[ExpressionInterval],
        expression: ExpressionHandle,
    ) -> Option<&ExpressionInterval> {
        let position = checked_trees::operators::handle_position(expression);
        intervals
            .binary_search_by_key(&position, |interval| {
                checked_trees::operators::handle_position(interval.expression)
            })
            .ok()
            .map(|found| &intervals[found])
    }

    pub(crate) fn collect_expression_intervals(
        mut values: Vec<super::expression_analysis::CheckedIntegerValue>,
    ) -> Vec<ExpressionInterval> {
        values.sort_by_key(|value| checked_trees::operators::handle_position(value.expression));
        let mut intervals: Vec<ExpressionInterval> = Vec::new();
        for value in values {
            match intervals.last_mut() {
                Some(previous) if previous.expression == value.expression => {
                    let joined = super::Interval {
                        low: previous.low,
                        high: previous.high,
                    }
                    .union(value.interval);
                    previous.low = joined.low;
                    previous.high = joined.high;
                }
                _ => intervals.push(ExpressionInterval {
                    expression: value.expression,
                    low: value.interval.low,
                    high: value.interval.high,
                }),
            }
        }
        intervals
    }

    #[derive(Debug, Clone)]
    pub struct PredicateInterval {
        pub argument: ExpressionHandle,
        pub extent: bool,
        pub low: i128,
        pub high: i128,
    }
}
pub(crate) mod interval {
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
    pub struct Interval {
        pub low: Option<i64>,
        pub high: Option<i64>,
    }

    impl Interval {
        pub const UNBOUNDED: Interval = Interval {
            low: None,
            high: None,
        };

        pub fn low(&self) -> Option<i64> {
            self.low
        }

        pub fn high(&self) -> Option<i64> {
            self.high
        }

        pub fn constant(value: i64) -> Self {
            Self {
                low: Some(value),
                high: Some(value),
            }
        }

        pub(crate) fn excludes_zero(self) -> bool {
            self.low.is_some_and(|low| low >= 1) || self.high.is_some_and(|high| high <= -1)
        }

        pub(crate) fn is_exactly_zero(self) -> bool {
            self.low == Some(0) && self.high == Some(0)
        }

        pub(crate) fn add(self, other: Self) -> Self {
            Self {
                low: pair(self.low, other.low, i64::checked_add),
                high: pair(self.high, other.high, i64::checked_add),
            }
        }

        pub(crate) fn subtract(self, other: Self) -> Self {
            Self {
                low: pair(self.low, other.high, i64::checked_sub),
                high: pair(self.high, other.low, i64::checked_sub),
            }
        }

        pub(crate) fn multiply(self, other: Self) -> Self {
            if self.is_exactly_zero() || other.is_exactly_zero() {
                return Self::constant(0);
            }
            let (Some(a), Some(b), Some(c), Some(d)) = (self.low, self.high, other.low, other.high)
            else {
                return Interval::UNBOUNDED;
            };
            let corners = [
                a.checked_mul(c),
                a.checked_mul(d),
                b.checked_mul(c),
                b.checked_mul(d),
            ];
            if corners.iter().any(Option::is_none) {
                return Interval::UNBOUNDED;
            }
            let values: Vec<i64> = corners.into_iter().flatten().collect();
            Self {
                low: values.iter().min().copied(),
                high: values.iter().max().copied(),
            }
        }

        pub(crate) fn shift_left(self, count: Self) -> Self {
            let (Some(value_low), Some(value_high), Some(count_low), Some(count_high)) =
                (self.low, self.high, count.low, count.high)
            else {
                return Interval::UNBOUNDED;
            };
            let (Ok(count_low), Ok(count_high)) =
                (u32::try_from(count_low), u32::try_from(count_high))
            else {
                return Interval::UNBOUNDED;
            };
            let (Some(low_factor), Some(high_factor)) = (
                1_i128.checked_shl(count_low),
                1_i128.checked_shl(count_high),
            ) else {
                return Interval::UNBOUNDED;
            };
            let corners = [
                i128::from(value_low).checked_mul(low_factor),
                i128::from(value_low).checked_mul(high_factor),
                i128::from(value_high).checked_mul(low_factor),
                i128::from(value_high).checked_mul(high_factor),
            ];
            if corners.iter().any(Option::is_none) {
                return Interval::UNBOUNDED;
            }
            let values = corners.into_iter().flatten().collect::<Vec<_>>();
            let low = *values.iter().min().expect("four exact shift corners exist");
            let high = *values.iter().max().expect("four exact shift corners exist");
            let (Ok(low), Ok(high)) = (i64::try_from(low), i64::try_from(high)) else {
                return Interval::UNBOUNDED;
            };
            Self {
                low: Some(low),
                high: Some(high),
            }
        }

        pub(crate) fn shift_right(self, count: Self) -> Self {
            let (Some(value_low), Some(value_high), Some(count_low), Some(count_high)) =
                (self.low, self.high, count.low, count.high)
            else {
                return Interval::UNBOUNDED;
            };
            let (Ok(count_low), Ok(count_high)) =
                (u32::try_from(count_low), u32::try_from(count_high))
            else {
                return Interval::UNBOUNDED;
            };
            if count_high >= i64::BITS {
                return Interval::UNBOUNDED;
            }
            let values = [
                value_low >> count_low,
                value_low >> count_high,
                value_high >> count_low,
                value_high >> count_high,
            ];
            Self {
                low: values.iter().min().copied(),
                high: values.iter().max().copied(),
            }
        }

        pub(crate) fn modulo(self, divisor: Self) -> Self {
            if !divisor.excludes_zero() {
                return Interval::UNBOUNDED;
            }
            let dividend_bound = self.union(Self::constant(0));
            let Some(magnitude) = divisor.nonzero_magnitude_bound() else {
                return dividend_bound;
            };
            let Some(bound) = magnitude
                .checked_sub(1)
                .and_then(|bound| i64::try_from(bound).ok())
            else {
                return Interval::UNBOUNDED;
            };
            dividend_bound.intersect(Self {
                low: Some(-bound),
                high: Some(bound),
            })
        }

        pub(crate) fn divide(self, divisor: Self) -> Self {
            let (Some(low), Some(high)) = (self.low, self.high) else {
                return Interval::UNBOUNDED;
            };
            if low > high
                || divisor
                    .low
                    .zip(divisor.high)
                    .is_some_and(|(low, high)| low > high)
                || !divisor.excludes_zero()
            {
                return Interval::UNBOUNDED;
            }
            let quotient = |value: i64, endpoint: Option<i64>| match endpoint {
                Some(endpoint) => value.checked_div(endpoint),
                None => Some(0),
            };
            let [Some(first), Some(second), Some(third), Some(fourth)] = [
                quotient(low, divisor.low),
                quotient(low, divisor.high),
                quotient(high, divisor.low),
                quotient(high, divisor.high),
            ] else {
                return Interval::UNBOUNDED;
            };
            Self {
                low: Some(first.min(second).min(third).min(fourth)),
                high: Some(first.max(second).max(third).max(fourth)),
            }
        }

        pub(crate) fn min_with(self, other: Self) -> Self {
            Self {
                low: self.union(other).low,
                high: self.intersect(other).high,
            }
        }

        pub(crate) fn max_with(self, other: Self) -> Self {
            Self {
                low: self.intersect(other).low,
                high: self.union(other).high,
            }
        }

        pub(crate) fn nonzero_magnitude_bound(self) -> Option<u64> {
            let (low, high) = (self.low?, self.high?);
            if low >= 1 || high <= -1 {
                Some(low.unsigned_abs().max(high.unsigned_abs()))
            } else {
                None
            }
        }

        pub fn union(self, other: Self) -> Self {
            Self {
                low: match (self.low, other.low) {
                    (Some(a), Some(b)) => Some(a.min(b)),
                    _ => None,
                },
                high: match (self.high, other.high) {
                    (Some(a), Some(b)) => Some(a.max(b)),
                    _ => None,
                },
            }
        }

        pub fn intersect(self, other: Self) -> Self {
            Self {
                low: match (self.low, other.low) {
                    (Some(a), Some(b)) => Some(a.max(b)),
                    (Some(v), None) | (None, Some(v)) => Some(v),
                    (None, None) => None,
                },
                high: match (self.high, other.high) {
                    (Some(a), Some(b)) => Some(a.min(b)),
                    (Some(v), None) | (None, Some(v)) => Some(v),
                    (None, None) => None,
                },
            }
        }

        pub(crate) fn contains(self, inner: Interval) -> bool {
            self.intersect(inner) == inner
        }
    }

    fn pair(left: Option<i64>, right: Option<i64>, op: fn(i64, i64) -> Option<i64>) -> Option<i64> {
        left.zip(right).and_then(|(left, right)| op(left, right))
    }
}
pub(crate) use expression_intervals::collect_expression_intervals;
pub use expression_intervals::{ExpressionInterval, PredicateInterval, expression_interval};
pub(crate) mod integer_sets {
    use typed_trees::expression::BinaryOperator;

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub(crate) struct IntegerSet {
        ranges: Vec<(i128, i128)>,
    }

    impl IntegerSet {
        pub(crate) fn empty() -> Self {
            Self { ranges: Vec::new() }
        }

        pub(crate) fn range(low: i128, high: i128) -> Self {
            if low > high {
                return Self::empty();
            }
            Self {
                ranges: vec![(low, high)],
            }
        }

        pub(crate) fn singleton(value: i128) -> Self {
            Self::range(value, value)
        }

        pub(crate) fn is_empty(&self) -> bool {
            self.ranges.is_empty()
        }

        pub(crate) fn single_value(&self) -> Option<i128> {
            match self.ranges.as_slice() {
                [(low, high)] if low == high => Some(*low),
                _ => None,
            }
        }

        pub(crate) fn bounds(&self) -> Option<(i128, i128)> {
            Some((self.ranges.first()?.0, self.ranges.last()?.1))
        }

        pub(crate) fn interval_hull(&self) -> Option<Self> {
            let (low, high) = self.bounds()?;
            Some(Self::range(low, high))
        }

        pub(crate) fn union(&self, other: &Self) -> Self {
            let mut ranges = self.ranges.clone();
            ranges.extend_from_slice(&other.ranges);
            Self::normalized(ranges)
        }

        pub(crate) fn intersect(&self, other: &Self) -> Self {
            let mut ranges = Vec::new();
            for (left_low, left_high) in &self.ranges {
                for (right_low, right_high) in &other.ranges {
                    let low = (*left_low).max(*right_low);
                    let high = (*left_high).min(*right_high);
                    if low <= high {
                        ranges.push((low, high));
                    }
                }
            }
            Self::normalized(ranges)
        }

        pub(crate) fn difference(&self, other: &Self) -> Self {
            let mut remaining = self.ranges.clone();
            for (cut_low, cut_high) in &other.ranges {
                let mut next = Vec::with_capacity(remaining.len() + 1);
                for (low, high) in remaining {
                    if high < *cut_low || *cut_high < low {
                        next.push((low, high));
                        continue;
                    }
                    if low < *cut_low {
                        next.push((low, cut_low - 1));
                    }
                    if *cut_high < high {
                        next.push((cut_high + 1, high));
                    }
                }
                remaining = next;
            }
            Self::normalized(remaining)
        }

        pub(crate) fn is_subset_of(&self, other: &Self) -> bool {
            self.difference(other).is_empty()
        }

        pub(crate) fn satisfying(operator: BinaryOperator, bound: i128) -> Option<Self> {
            Some(match operator {
                BinaryOperator::Equal => Self::singleton(bound),
                BinaryOperator::NotEqual => {
                    Self::range(i128::MIN, i128::MAX).difference(&Self::singleton(bound))
                }
                BinaryOperator::Less => match bound.checked_sub(1) {
                    Some(high) => Self::range(i128::MIN, high),
                    None => Self::empty(),
                },
                BinaryOperator::LessOrEqual => Self::range(i128::MIN, bound),
                BinaryOperator::Greater => match bound.checked_add(1) {
                    Some(low) => Self::range(low, i128::MAX),
                    None => Self::empty(),
                },
                BinaryOperator::GreaterOrEqual => Self::range(bound, i128::MAX),
                _ => return None,
            })
        }

        pub(crate) fn range_count(&self) -> usize {
            self.ranges.len()
        }

        fn normalized(mut ranges: Vec<(i128, i128)>) -> Self {
            ranges.retain(|(low, high)| low <= high);
            ranges.sort_unstable();
            let mut merged: Vec<(i128, i128)> = Vec::with_capacity(ranges.len());
            for (low, high) in ranges {
                if let Some(last) = merged.last_mut()
                    && low <= last.1.saturating_add(1)
                {
                    last.1 = last.1.max(high);
                    continue;
                }
                merged.push((low, high));
            }
            Self { ranges: merged }
        }
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn integer_interval_unions_preserve_holes_and_carrier_edges() {
            let separated = IntegerSet::singleton(0).union(&IntegerSet::singleton(2));
            assert_eq!(separated.bounds(), Some((0, 2)));
            assert!(separated.is_subset_of(&IntegerSet::range(0, 2)));
            assert!(!IntegerSet::range(0, 2).is_subset_of(&separated));
            assert!(separated.intersect(&IntegerSet::singleton(1)).is_empty());
            let hull = separated.interval_hull().unwrap();
            assert!(separated.is_subset_of(&hull));
            assert!(IntegerSet::singleton(1).is_subset_of(&hull));
            assert_eq!(IntegerSet::empty().interval_hull(), None);
            assert_eq!(
                IntegerSet::range(-1, 1).difference(&IntegerSet::singleton(0)),
                IntegerSet::singleton(-1).union(&IntegerSet::singleton(1))
            );
            let universe = IntegerSet::range(i128::MIN, i128::MAX);
            let without_minimum =
                IntegerSet::satisfying(BinaryOperator::NotEqual, i128::MIN).unwrap();
            assert!(
                without_minimum
                    .intersect(&IntegerSet::singleton(i128::MIN))
                    .is_empty()
            );
            assert_eq!(
                universe.difference(&without_minimum),
                IntegerSet::singleton(i128::MIN)
            );
        }
    }
}
pub(crate) use integer_sets::IntegerSet;
pub(crate) mod integer_operations {
    use super::BigIntInterval;
    use facts::IntegerRange;
    use numerics::bignum::BigInt;
    use typed_trees::expression::BinaryOperator;

    pub fn integer_binary_range(
        operator: BinaryOperator,
        left: IntegerRange,
        right: IntegerRange,
    ) -> Option<IntegerRange> {
        if left.minimum > left.maximum || right.minimum > right.maximum {
            return None;
        }
        let first = BigIntInterval::from_closed(left.clone());
        let second = BigIntInterval::from_closed(right.clone());
        match operator {
            BinaryOperator::Add => first.add(&second).into_closed(),
            BinaryOperator::Subtract => first.subtract(&second).into_closed(),
            BinaryOperator::Multiply => first.multiply(&second).into_closed(),
            BinaryOperator::Divide if second.excludes_zero() => first.divide(&second).into_closed(),
            BinaryOperator::Modulo if second.excludes_zero() => {
                first.remainder(&second).into_closed()
            }
            BinaryOperator::ShiftRight => first
                .shift_right(right.minimum.to_u64()?, right.maximum.to_u64()?)
                .into_closed(),
            BinaryOperator::BitwiseAnd
                if !left.minimum.is_negative() && !right.minimum.is_negative() =>
            {
                Some(IntegerRange {
                    minimum: BigInt::zero(),
                    maximum: left.maximum.min(right.maximum),
                })
            }
            BinaryOperator::BitwiseOr | BinaryOperator::BitwiseXor
                if !left.minimum.is_negative() && !right.minimum.is_negative() =>
            {
                let bits = left.maximum.clone().max(right.maximum).bit_length();
                Some(IntegerRange {
                    minimum: if operator == BinaryOperator::BitwiseOr {
                        left.minimum.max(right.minimum)
                    } else {
                        BigInt::zero()
                    },
                    maximum: BigInt::from_i64(1).shl_bits(bits).sub(&BigInt::from_i64(1)),
                })
            }
            _ => None,
        }
    }

    pub fn folded_integer_binary(left: i64, operator: BinaryOperator, right: i64) -> Option<i64> {
        if !matches!(
            operator,
            BinaryOperator::Add
                | BinaryOperator::Subtract
                | BinaryOperator::Multiply
                | BinaryOperator::Divide
                | BinaryOperator::Modulo
        ) {
            return None;
        }
        let point = |value| IntegerRange {
            minimum: BigInt::from_i64(value),
            maximum: BigInt::from_i64(value),
        };
        let left_value = BigInt::from_i64(left);
        let right_value = BigInt::from_i64(right);
        if matches!(operator, BinaryOperator::Divide | BinaryOperator::Modulo) {
            let (quotient, remainder) = left_value.div_rem(&right_value)?;
            quotient.to_i64()?;
            return if operator == BinaryOperator::Divide {
                quotient.to_i64()
            } else {
                remainder.to_i64()
            };
        }
        let result = integer_binary_range(operator, point(left), point(right))?;
        (result.minimum == result.maximum)
            .then(|| result.minimum.to_i64())
            .flatten()
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        fn closed(low: i64, high: i64) -> IntegerRange {
            IntegerRange {
                minimum: BigInt::from_i64(low),
                maximum: BigInt::from_i64(high),
            }
        }

        #[test]
        fn integer_interval_operations_enclose_small_models() {
            for low in -3..=3 {
                for high in low..=3 {
                    for other_low in -3..=3 {
                        for other_high in other_low..=3 {
                            for operator in [
                                BinaryOperator::Add,
                                BinaryOperator::Subtract,
                                BinaryOperator::Multiply,
                                BinaryOperator::Divide,
                                BinaryOperator::Modulo,
                            ] {
                                if matches!(
                                    operator,
                                    BinaryOperator::Divide | BinaryOperator::Modulo
                                ) && other_low <= 0
                                    && other_high >= 0
                                {
                                    assert_eq!(
                                        integer_binary_range(
                                            operator,
                                            closed(low, high),
                                            closed(other_low, other_high)
                                        ),
                                        None
                                    );
                                    continue;
                                }
                                let bounds = integer_binary_range(
                                    operator,
                                    closed(low, high),
                                    closed(other_low, other_high),
                                )
                                .unwrap();
                                for left in low..=high {
                                    for right in other_low..=other_high {
                                        let value = match operator {
                                            BinaryOperator::Add => left + right,
                                            BinaryOperator::Subtract => left - right,
                                            BinaryOperator::Multiply => left * right,
                                            BinaryOperator::Divide => left / right,
                                            BinaryOperator::Modulo => left % right,
                                            _ => unreachable!("enumerated arithmetic operator"),
                                        };
                                        let value = BigInt::from_i64(value);
                                        assert!(
                                            bounds.minimum <= value && value <= bounds.maximum,
                                            "{operator:?} over [{low},{high}] and [{other_low},{other_high}] excludes {value:?}"
                                        );
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        #[test]
        fn integer_intervals_preserve_full_width_and_unbounded_edges() {
            let maximum = BigInt::from_u64(u64::MAX);
            let full_unsigned = BigIntInterval {
                low: Some(BigInt::zero()),
                high: Some(maximum.clone()),
            };
            assert_eq!(
                full_unsigned.divide(&BigIntInterval::constant(BigInt::from_i64(1))),
                full_unsigned
            );
            assert_eq!(
                full_unsigned
                    .divide(&BigIntInterval::constant(BigInt::from_i64(2)))
                    .high,
                Some(BigInt::from_u64(u64::MAX / 2))
            );
            assert_eq!(
                BigIntInterval::unbounded().multiply(&BigIntInterval::constant(BigInt::zero())),
                BigIntInterval::constant(BigInt::zero())
            );

            let signed = BigIntInterval::from_closed(closed(i64::MIN, i64::MAX));
            let remainder = signed.remainder(&BigIntInterval::constant(BigInt::from_i64(i64::MIN)));
            assert_eq!(remainder.into_closed(), Some(closed(-i64::MAX, i64::MAX)));

            assert_eq!(
                integer_binary_range(BinaryOperator::ShiftRight, closed(-3, -3), closed(1, 1)),
                Some(closed(-2, -2))
            );
            assert_eq!(
                super::super::floor_shift_right(&BigInt::from_i64(-3), u64::MAX),
                Some(BigInt::from_i64(-1))
            );
            assert_eq!(
                super::super::floor_shift_right(&maximum, u64::MAX),
                Some(BigInt::zero())
            );
            assert_eq!(
                folded_integer_binary(i64::MIN, BinaryOperator::Divide, -1),
                None
            );
            assert_eq!(
                folded_integer_binary(i64::MIN, BinaryOperator::Modulo, -1),
                None
            );
            assert_eq!(folded_integer_binary(1, BinaryOperator::Divide, 0), None);
        }
    }
}
pub use integer_operations::{folded_integer_binary, integer_binary_range};
pub(crate) mod invariant_bounds {
    use super::{
        ArithmeticDomain, BinaryOperator, ExpressionHandle, ExpressionNode, Interval, Machine,
        PrimitiveType, SignatureContractKind, State, TableCallExpression, TypeReferenceHandle,
        enforced_declared_range, literal_i64,
    };
    use crate::CheckingInput;
    use crate::proof_contracts::arithmetic_domains::integer_ranges::primitive_range;
    use language_core::OperatorSpelling;
    use numerics::bignum::BigInt;
    use symbols::SymbolHandle;

    pub(crate) mod fields {
        use typed_trees::expression::ExpressionHandle;
        use typed_trees::machine::Machine;
        use typed_trees::state::State;
        use typed_trees::types::TypeReferenceHandle;

        pub(crate) fn type_reference(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
            expression: ExpressionHandle,
            declared_mutable_leaves: bool,
        ) -> Option<TypeReferenceHandle> {
            let place = crate::canonical_place_from_expression(program, expression)?;
            let root = place.root.as_symbol()?;
            let parameters = program.state_parameters(state);
            let parameter = program.state_parameter_by_symbol(state, root)?;
            let owned_storage = program
                .data_binding_position(machine.attached_data_symbol, parameters)
                .is_some_and(|position| parameters[position].symbol == root);
            if parameter.is_const
                || (parameter.is_mutable && !declared_mutable_leaves && !owned_storage)
            {
                return None;
            }
            let field = crate::structural_scalar_field_at_coordinate(
                program,
                parameters,
                root,
                &place.segments,
            )?;
            let reference = crate::value_custody::places::declared_place_type_raw(
                program,
                machine,
                Some(state),
                expression,
            )?;
            (program.primitive_type_reference(reference) == Some(field.primitive_type))
                .then_some(reference)
        }
    }

    pub fn enforced_integer_type_bounds(
        program: &dyn CheckingInput,
        type_reference: TypeReferenceHandle,
    ) -> Option<(i64, i64)> {
        let primitive = exact_integer_primitive(program, type_reference)?;
        let carrier = primitive_range(primitive)?;
        let interval = enforced_declared_range(program, type_reference)
            .map_or(carrier, |range| range.intersect(carrier));
        let (low, high) = (interval.low?, interval.high?);
        (low <= high).then_some((low, high))
    }

    fn exact_integer_primitive(
        program: &dyn CheckingInput,
        type_reference: TypeReferenceHandle,
    ) -> Option<PrimitiveType> {
        let carrier_type = program
            .type_reference_table
            .unconstrained_type_reference(type_reference);
        let symbol = &program
            .type_reference_table
            .type_reference(carrier_type)
            .as_named_symbol()?;
        let primitive =
            PrimitiveType::from_builtin_atom(program.symbols.builtin_type_atom(*symbol)?)?;
        if program.arithmetic_domain_for_type_reference(type_reference) != ArithmeticDomain::Exact {
            return None;
        }
        Some(primitive)
    }

    pub fn immutable_integer_expression_bounds(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<(i64, i64)> {
        if !program
            .machine_states(machine)
            .iter()
            .any(|candidate| candidate.symbol == state.symbol)
        {
            return None;
        }
        let value = bounds(program, machine, Some(state), expression, false)?;
        Some((value.interval.low?, value.interval.high?))
    }

    pub(crate) fn standing_integer_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<Interval> {
        let place_type = crate::value_custody::places::declared_place_type_raw(
            program,
            machine,
            Some(state),
            expression,
        );
        let interval = immutable_integer_expression_interval(program, machine, state, expression)
            .or_else(|| stored_place_interval(program, machine, state, expression))?;
        (place_carrier_interval(program, place_type) != Some(interval)).then_some(interval)
    }

    fn place_carrier_interval(
        program: &dyn CheckingInput,
        place_type: Option<TypeReferenceHandle>,
    ) -> Option<Interval> {
        place_type
            .and_then(|handle| program.unwrapped_type_reference(handle))
            .and_then(|handle| program.primitive_type_reference(handle))
            .and_then(primitive_range)
    }

    pub(crate) fn upper_bound_beyond_place_carrier(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        high: i64,
    ) -> Option<i64> {
        let place_type = crate::value_custody::places::declared_place_type_raw(
            program,
            machine,
            Some(state),
            expression,
        );
        let carrier_high =
            place_carrier_interval(program, place_type).and_then(|carrier| carrier.high);
        carrier_high
            .is_none_or(|carrier_high| high < carrier_high)
            .then_some(high)
    }

    fn stored_place_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<Interval> {
        crate::value_custody::places::declared_place_type_raw(
            program,
            machine,
            Some(state),
            expression,
        )
        .and_then(|handle| super::range_constraint_interval(program, handle))
    }

    pub fn standing_integer_bounds(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<(Option<i64>, Option<i64>)> {
        standing_integer_interval(program, machine, state, expression)
            .map(|interval| (interval.low, interval.high))
    }

    pub fn stored_integer_bounds(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<(Option<i64>, Option<i64>)> {
        let carrier = crate::value_custody::places::declared_place_type_raw(
            program,
            machine,
            Some(state),
            expression,
        )
        .and_then(|handle| program.primitive_type_reference(handle))
        .and_then(super::integer_ranges::primitive_range)?;
        let interval = stored_place_interval(program, machine, state, expression)
            .map_or(carrier, |stored| stored.intersect(carrier));
        Some((interval.low, interval.high))
    }

    pub fn state_parameter_integer_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        parameter: SymbolHandle,
    ) -> Option<(Option<i64>, Option<i64>)> {
        let parameter = program
            .state_parameters(state)
            .iter()
            .find(|candidate| candidate.symbol == parameter)?;
        if parameter.is_const {
            return None;
        }
        let mut interval = type_bounds(program, parameter.type_reference)?.interval;
        if !parameter.is_mutable {
            interval = interval.intersect(requires_interval(
                program,
                machine,
                state,
                parameter.symbol,
                false,
            ));
        }
        Some((interval.low, interval.high))
    }

    pub(crate) fn immutable_integer_expression_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<Interval> {
        if let Some(observed) = super::atomic_result_interval(program, machine, state, expression) {
            return Some(observed);
        }
        if !program
            .machine_states(machine)
            .iter()
            .any(|candidate| candidate.symbol == state.symbol)
        {
            return None;
        }
        Some(bounds(program, machine, Some(state), expression, false)?.interval)
    }

    pub fn declared_integer_expression_lands(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> bool {
        if !program
            .machine_states(machine)
            .iter()
            .any(|candidate| candidate.symbol == state.symbol)
        {
            return false;
        }
        bounds(program, machine, Some(state), expression, true).is_some()
    }

    pub(crate) fn builtin_comparison_intervals(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<(Interval, Interval)> {
        if !program
            .machine_states(machine)
            .iter()
            .any(|candidate| candidate.symbol == state.symbol)
        {
            return None;
        }
        let binary = program.expression_table.binary_node(expression)?;
        let spelling = match binary.operator {
            BinaryOperator::Less => OperatorSpelling::Less,
            BinaryOperator::LessOrEqual => OperatorSpelling::LessEqual,
            BinaryOperator::Greater => OperatorSpelling::Greater,
            BinaryOperator::GreaterOrEqual => OperatorSpelling::GreaterEqual,
            _ => return None,
        };
        let left = bounds(program, machine, Some(state), binary.left, false)?;
        let right = bounds(program, machine, Some(state), binary.right, false)?;
        typed_trees::operator::has_builtin_spelled_expression_meaning(
            program,
            machine.symbol,
            expression,
            spelling,
            &[left.type_reference, right.type_reference],
        )
        .then_some((left.interval, right.interval))
    }

    pub(crate) struct Bounds {
        interval: Interval,
        constant_value: Option<BigInt>,
        primitive: Option<PrimitiveType>,
        type_reference: Option<TypeReferenceHandle>,
    }

    impl Bounds {
        fn constant(
            value: BigInt,
            primitive: Option<PrimitiveType>,
            type_reference: Option<TypeReferenceHandle>,
        ) -> Self {
            let interval = match value.to_i64() {
                Some(value) => Interval::constant(value),
                None if value.is_negative() => Interval {
                    low: None,
                    high: Some(i64::MIN),
                },
                None => Interval {
                    low: Some(i64::MAX),
                    high: None,
                },
            };
            Self {
                interval,
                constant_value: Some(value),
                primitive,
                type_reference,
            }
        }
    }

    fn type_bounds(
        program: &dyn CheckingInput,
        type_reference: TypeReferenceHandle,
    ) -> Option<Bounds> {
        let primitive = exact_integer_primitive(program, type_reference)?;
        let carrier = primitive_range(primitive)?;
        Some(Bounds {
            interval: enforced_declared_range(program, type_reference)
                .map_or(carrier, |range| range.intersect(carrier)),
            constant_value: None,
            primitive: Some(primitive),
            type_reference: Some(type_reference),
        })
    }

    fn bounds(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        declared_mutable_leaves: bool,
    ) -> Option<Bounds> {
        if !program.expression_table.expression_is_valid(expression) {
            return None;
        }
        if let Some(value) =
            crate::value_custody::literals::closed_record_integer_projection(program, expression)
                .or_else(|| program.closed_integer_value_in(expression, machine.symbol))
        {
            if let Some(primitive) = value.primitive {
                typed_trees::closed_numeric::land_integer(&value.value, primitive)?;
            }
            return Some(Bounds::constant(
                value.value,
                value.primitive,
                value.type_reference,
            ));
        }
        if let Some(value) =
            crate::value_custody::constants::completed_integer_constant(program, expression)
        {
            if let Some(primitive) = value.primitive {
                typed_trees::closed_numeric::land_integer(&value.value, primitive)?;
            }
            return Some(Bounds::constant(
                value.value,
                value.primitive,
                value.type_reference,
            ));
        }
        if let Some(receiver) = crate::value_custody::places::collection_length_receiver(
            program, machine, state, expression,
        ) && let Some(extent) = crate::value_custody::places::declared_collection_extent(
            program, machine, state, receiver,
        ) {
            let type_reference = crate::value_custody::places::declared_place_type_raw(
                program, machine, state, expression,
            );
            let primitive =
                type_reference.and_then(|reference| program.primitive_type_reference(reference));
            let value = BigInt::from_u64(u64::try_from(extent).ok()?);
            if let Some(primitive) = primitive {
                typed_trees::closed_numeric::land_integer(&value, primitive)?;
            }
            return Some(Bounds::constant(value, primitive, type_reference));
        }
        match program.expression_table.expression(expression) {
            ExpressionNode::Integer(_) => None,
            ExpressionNode::Name(path)
                if path.symbol.is_valid() && path.head_symbol == path.symbol =>
            {
                let state = state?;
                if let Some(parameter) = program.state_parameter_by_symbol(state, path.symbol) {
                    if parameter.is_const || (parameter.is_mutable && !declared_mutable_leaves) {
                        return None;
                    }
                    let declared = type_bounds(program, parameter.type_reference)?;
                    if parameter.is_mutable {
                        return Some(declared);
                    }
                    return Some(Bounds {
                        interval: declared.interval.intersect(requires_interval(
                            program,
                            machine,
                            state,
                            parameter.symbol,
                            false,
                        )),
                        ..declared
                    });
                }
                integer_binder_bounds(program, machine, state, path.symbol)
            }
            ExpressionNode::Member(_) => {
                let declared = type_bounds(
                    program,
                    fields::type_reference(
                        program,
                        machine,
                        state?,
                        expression,
                        declared_mutable_leaves,
                    )?,
                )?;
                Some(declared)
            }
            ExpressionNode::Cast(cast) => {
                if !crate::proof_contracts::arithmetic_domains::plain_exact_widening_cast(
                    program, cast,
                ) {
                    return None;
                }
                let source = bounds(program, machine, state, cast.value, declared_mutable_leaves)?;
                let target = exact_integer_primitive(program, cast.target_type)?;
                if !super::integer_ranges::integer_widen_is_total(source.primitive?, target) {
                    return None;
                }
                Some(Bounds {
                    primitive: Some(target),
                    type_reference: Some(cast.target_type),
                    ..source
                })
            }
            ExpressionNode::Call(call) => Some(call_result_bounds(
                program,
                machine.symbol,
                expression,
                call,
            )?),
            ExpressionNode::Binary(binary)
                if matches!(
                    binary.operator,
                    BinaryOperator::BitwiseAnd | BinaryOperator::ShiftRight
                ) =>
            {
                let (left, right) = binary_operand_bounds(
                    program,
                    machine,
                    state,
                    binary,
                    declared_mutable_leaves,
                )?;
                unsigned_bitwise_bounds(program, binary.operator, left, right)
            }
            ExpressionNode::Binary(binary) => {
                let spelling =
                    typed_trees::operator::arithmetic_operator_spelling(binary.operator)?;
                let (left, right) = binary_operand_bounds(
                    program,
                    machine,
                    state,
                    binary,
                    declared_mutable_leaves,
                )?;
                if left.primitive.is_none() && right.primitive.is_none() {
                    return None;
                }
                if state.is_none()
                    && program
                        .machine_specializations
                        .iter()
                        .any(|specialization| {
                            !typed_trees::operator::selected_trait_operator_meanings(
                                program,
                                specialization.instance,
                                spelling,
                                &[left.type_reference, right.type_reference],
                            )
                            .is_empty()
                        })
                {
                    return None;
                }
                if !typed_trees::operator::has_builtin_spelled_expression_meaning(
                    program,
                    machine.symbol,
                    expression,
                    spelling,
                    &[left.type_reference, right.type_reference],
                ) {
                    return None;
                }
                if left
                    .primitive
                    .zip(right.primitive)
                    .is_some_and(|(left, right)| left != right)
                {
                    return None;
                }
                let primitive = left.primitive.or(right.primitive)?;
                for value in [&left.constant_value, &right.constant_value]
                    .into_iter()
                    .flatten()
                {
                    typed_trees::closed_numeric::land_integer(value, primitive)?;
                }
                let result_type = program
                    .type_reference_table
                    .unconstrained_type_reference(left.type_reference.or(right.type_reference)?);
                let carrier = primitive_range(primitive)?;
                if !carrier.contains(left.interval) || !carrier.contains(right.interval) {
                    return None;
                }
                if primitive == PrimitiveType::U64
                    && matches!(
                        binary.operator,
                        BinaryOperator::Add | BinaryOperator::Subtract | BinaryOperator::Multiply
                    )
                    && !super::unsigned_representability::binary_fits(
                        binary.operator,
                        left.interval,
                        right.interval,
                        None,
                        None,
                    )
                {
                    return None;
                }
                if matches!(
                    binary.operator,
                    BinaryOperator::Divide | BinaryOperator::Modulo
                ) && primitive.is_signed_integer()
                    && left.interval.contains(Interval::constant(carrier.low?))
                    && right.interval.contains(Interval::constant(-1))
                {
                    return None;
                }
                let interval = match binary.operator {
                    BinaryOperator::Add => left.interval.add(right.interval),
                    BinaryOperator::Subtract => left.interval.subtract(right.interval),
                    BinaryOperator::Multiply => left.interval.multiply(right.interval),
                    BinaryOperator::Divide if primitive == PrimitiveType::U64 => {
                        super::unsigned_representability::divide_interval(
                            left.interval,
                            right.interval,
                            left.constant_value.as_ref().and_then(BigInt::to_u64),
                            right.constant_value.as_ref().and_then(BigInt::to_u64),
                        )
                    }
                    BinaryOperator::Divide => left.interval.divide(right.interval),
                    BinaryOperator::Modulo
                        if left.interval.low == left.interval.high
                            && right.interval.low == right.interval.high =>
                    {
                        Interval::constant(left.interval.low?.checked_rem(right.interval.low?)?)
                    }
                    BinaryOperator::Modulo => left.interval.modulo(right.interval),
                    _ => return None,
                };
                carrier.contains(interval).then_some(Bounds {
                    interval,
                    constant_value: None,
                    primitive: Some(primitive),
                    type_reference: Some(result_type),
                })
            }
            _ => None,
        }
    }

    fn binary_operand_bounds(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        binary: &typed_trees::expression::TableBinaryExpression,
        declared_mutable_leaves: bool,
    ) -> Option<(Bounds, Bounds)> {
        let left = bounds(
            program,
            machine,
            state,
            binary.left,
            declared_mutable_leaves,
        )?;
        let right = bounds(
            program,
            machine,
            state,
            binary.right,
            declared_mutable_leaves,
        )?;
        Some((left, right))
    }

    fn unsigned_bitwise_bounds(
        program: &dyn CheckingInput,
        operator: BinaryOperator,
        left: Bounds,
        right: Bounds,
    ) -> Option<Bounds> {
        let primitive = left.primitive?;
        if !matches!(
            primitive,
            typed_trees::unsigned_integer_primitive_pattern!()
        ) {
            return None;
        }
        if operator == BinaryOperator::BitwiseAnd
            && right.primitive.is_some_and(|other| other != primitive)
        {
            return None;
        }
        let right_carrier = right.primitive.unwrap_or(primitive);
        for (value, carrier) in [
            (&left.constant_value, primitive),
            (&right.constant_value, right_carrier),
        ] {
            if let Some(value) = value {
                typed_trees::closed_numeric::land_integer(value, carrier)?;
            }
        }
        if left.interval.low? < 0 || right.interval.low? < 0 {
            return None;
        }
        let interval = match operator {
            BinaryOperator::BitwiseAnd => super::bitwise::binary(
                operator,
                primitive,
                left.interval,
                right.interval,
                left.constant_value.as_ref().and_then(BigInt::to_u64),
                right.constant_value.as_ref().and_then(BigInt::to_u64),
            ),
            BinaryOperator::ShiftRight => {
                let width = super::integer_bit_width(primitive)?;
                let high_count = right.interval.high?;
                if high_count >= width {
                    return None;
                }
                super::bitwise::shift_right(
                    primitive,
                    left.interval,
                    right.interval,
                    left.constant_value.as_ref().and_then(BigInt::to_u64),
                )
            }
            _ => return None,
        };
        let result_type = program
            .type_reference_table
            .unconstrained_type_reference(left.type_reference?);
        Some(Bounds {
            interval,
            constant_value: None,
            primitive: Some(primitive),
            type_reference: Some(result_type),
        })
    }

    pub(crate) fn call_result_interval(
        program: &dyn CheckingInput,
        caller: symbols::SymbolHandle,
        expression: ExpressionHandle,
        call: &TableCallExpression,
    ) -> Option<Interval> {
        Some(call_result_bounds(program, caller, expression, call)?.interval)
    }

    fn call_result_bounds(
        program: &dyn CheckingInput,
        caller: symbols::SymbolHandle,
        expression: ExpressionHandle,
        call: &TableCallExpression,
    ) -> Option<Bounds> {
        let (callee, entry) =
            crate::machine_calls::calls::machine_state_by_symbol(program, call.target_symbol)?;
        let declared = type_bounds(program, entry.return_type)?;
        let ensured = if call.static_requirement_dispatch.is_some() {
            super::return_ranges::ensured_call_result_interval(
                program,
                caller,
                expression,
                call,
                &super::call_result_bounds::ArgumentBounds::default(),
            )
            .unwrap_or(Interval::UNBOUNDED)
        } else if crate::machine_calls::contract_dependencies::independent_call_application(
            program,
            caller,
            call.target_symbol,
            typed_trees::references::StaticArgumentCall::Expression(expression, call),
        ) {
            ensures_result_interval(program, callee, entry)
        } else {
            Interval::UNBOUNDED
        };
        Some(Bounds {
            interval: declared.interval.intersect(ensured),
            ..declared
        })
    }

    fn ensures_result_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        entry: &State,
    ) -> Interval {
        if machine.target_family_interface {
            let Some(members) =
                crate::machine_calls::calls::target_family_members(program, machine)
            else {
                return Interval::UNBOUNDED;
            };
            let mut union: Option<Interval> = None;
            for member in members {
                let Some(member_machine) = program.machine(member.machine) else {
                    return Interval::UNBOUNDED;
                };
                let Some(member_entry) = program.machine_states(member_machine).first() else {
                    return Interval::UNBOUNDED;
                };
                let member_interval =
                    declared_ensures_result_interval(program, member_machine, member_entry);
                union = Some(match union {
                    Some(existing) => existing.union(member_interval),
                    None => member_interval,
                });
            }
            return union.unwrap_or(Interval::UNBOUNDED);
        }
        declared_ensures_result_interval(program, machine, entry)
    }

    fn declared_ensures_result_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        entry: &State,
    ) -> Interval {
        let key = crate::frozen_program::frozen_program_memos(program).and_then(|memos| {
            let (machine_pos, state_pos, _) =
                crate::proof_contracts::bound_expression_meaning::meaning_key(
                    program,
                    machine,
                    Some(entry),
                    ExpressionHandle::default(),
                )?;
            Some((
                memos,
                (machine_pos, state_pos, SymbolHandle::invalid(), true),
            ))
        });
        if let Some((memos, key)) = key
            && let Ok(guard) = memos.parameter_requires_intervals.lock()
            && let Some(cached) = guard.get(&key).copied()
        {
            return cached;
        }
        let interval = contract_subject_interval(
            program,
            machine,
            entry,
            program.machine_contracts(machine),
            SignatureContractKind::Ensures,
            true,
            &|subject| program.expression_table.names_reserved_result(subject),
        );
        if let Some((memos, key)) = key
            && let Ok(mut guard) = memos.parameter_requires_intervals.lock()
        {
            guard.insert(key, interval);
        }
        interval
    }

    fn integer_binder_bounds(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        symbol: SymbolHandle,
    ) -> Option<Bounds> {
        let binder = program
            .machine_type_parameters(machine)
            .iter()
            .find(|parameter| parameter.symbol == symbol)?;
        let type_reference = match binder.kind {
            typed_trees::data::TypeParameterKind::Const { type_reference }
            | typed_trees::data::TypeParameterKind::Value { type_reference } => type_reference,
            _ => return None,
        };
        let declared = type_bounds(program, type_reference)?;
        let interval = solved_integer_binder_interval(program, machine, state, binder.symbol)
            .unwrap_or(declared.interval);
        Some(Bounds {
            interval,
            ..declared
        })
    }

    fn solved_integer_binder_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        symbol: SymbolHandle,
    ) -> Option<Interval> {
        let binders = integer_binders(program, machine);
        let position = binders
            .iter()
            .position(|(candidate, _)| *candidate == symbol)?;
        let mut current: Vec<Interval> = binders.iter().map(|(_, declared)| *declared).collect();
        let facts = binder_requirement_facts(program, machine, state);
        for _ in 0..binders.len() {
            let previous = current.clone();
            let mut changed = false;
            for (index, _) in binders.iter().enumerate() {
                let mut interval = binders[index].1;
                for fact in &facts {
                    if let Some(bound) = binder_fact_interval(
                        program,
                        machine,
                        state,
                        *fact,
                        binders[index].0,
                        &binders,
                        &previous,
                    ) {
                        interval = interval.intersect(bound);
                    }
                }
                if interval != current[index] {
                    changed = true;
                    current[index] = interval;
                }
            }
            if !changed {
                break;
            }
        }
        Some(current[position])
    }

    fn integer_binders(
        program: &dyn CheckingInput,
        machine: &Machine,
    ) -> Vec<(SymbolHandle, Interval)> {
        let mut binders = Vec::new();
        for parameter in program.machine_type_parameters(machine) {
            let type_reference = match parameter.kind {
                typed_trees::data::TypeParameterKind::Const { type_reference }
                | typed_trees::data::TypeParameterKind::Value { type_reference } => type_reference,
                _ => continue,
            };
            let Some(declared) = type_bounds(program, type_reference) else {
                continue;
            };
            binders.push((parameter.symbol, declared.interval));
        }
        binders
    }

    fn binder_requirement_facts(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
    ) -> Vec<ExpressionHandle> {
        program
            .machine_contracts(machine)
            .iter()
            .chain(program.state_contracts(state))
            .filter(|contract| contract.kind == SignatureContractKind::Requires)
            .flat_map(|contract| program.proof_facts.span_or_empty(contract.facts))
            .filter_map(|fact| fact.as_expression().copied())
            .collect()
    }

    fn contract_subject_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        machine_contracts: &[typed_trees::signature::SignatureContract],
        kind: SignatureContractKind,
        literal_bounds_only: bool,
        names_subject: &impl Fn(ExpressionHandle) -> bool,
    ) -> Interval {
        let mut interval = Interval::UNBOUNDED;
        for contract in machine_contracts
            .iter()
            .chain(program.state_contracts(state))
        {
            if contract.kind != kind {
                continue;
            }
            for fact in program.proof_facts.span_or_empty(contract.facts) {
                let Some(expression) = fact.as_expression() else {
                    continue;
                };
                if let Some(bound) = boolean_subject_interval(
                    program,
                    machine,
                    state,
                    *expression,
                    literal_bounds_only,
                    names_subject,
                ) {
                    interval = interval.intersect(bound);
                }
            }
        }
        interval
    }

    fn subject_fact_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        names_subject: &impl Fn(ExpressionHandle) -> bool,
        operand_interval: &impl Fn(ExpressionHandle) -> Option<Interval>,
    ) -> Option<Interval> {
        let (operator, left, right) = {
            let binary = program.expression_table.binary_node(expression)?;
            (binary.operator, binary.left, binary.right)
        };
        let recurse = |expression| {
            subject_fact_interval(
                program,
                machine,
                state,
                expression,
                names_subject,
                operand_interval,
            )
        };
        match operator {
            BinaryOperator::And => match (recurse(left), recurse(right)) {
                (Some(left_bound), Some(right_bound)) => Some(left_bound.intersect(right_bound)),
                (Some(bound), None) | (None, Some(bound)) => Some(bound),
                (None, None) => None,
            },
            BinaryOperator::Or => Some(recurse(left)?.union(recurse(right)?)),
            _ => comparison_subject_interval(
                program,
                machine,
                state,
                expression,
                operator,
                left,
                right,
                names_subject,
                operand_interval,
            ),
        }
    }

    fn binder_fact_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        subject_symbol: SymbolHandle,
        binders: &[(SymbolHandle, Interval)],
        previous: &[Interval],
    ) -> Option<Interval> {
        subject_fact_interval(
            program,
            machine,
            state,
            expression,
            &|subject| named_symbol(program, subject) == Some(subject_symbol),
            &|operand| binder_operand_interval(program, machine, state, operand, binders, previous),
        )
    }

    fn comparison_subject_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        operator: BinaryOperator,
        left: ExpressionHandle,
        right: ExpressionHandle,
        names_subject: &impl Fn(ExpressionHandle) -> bool,
        operand_interval: &impl Fn(ExpressionHandle) -> Option<Interval>,
    ) -> Option<Interval> {
        let builtin = match operator {
            BinaryOperator::Equal => super::guard_narrowing::has_builtin_equality(
                program,
                machine,
                Some(state),
                expression,
            ),
            _ => super::guard_narrowing::has_builtin_ordering(
                program,
                machine,
                Some(state),
                expression,
            ),
        };
        if !builtin {
            return None;
        }
        let mut interval: Option<Interval> = None;
        for (subject, operand, subject_on_left) in [(left, right, true), (right, left, false)] {
            if !names_subject(subject) {
                continue;
            }
            let Some(bound) = operand_interval(operand) else {
                continue;
            };
            let compared =
                super::guard_narrowing::comparison_interval(operator, bound, subject_on_left);
            if compared.low.is_none() && compared.high.is_none() {
                continue;
            }
            interval = Some(match interval {
                Some(existing) => existing.intersect(compared),
                None => compared,
            });
        }
        interval
    }

    fn binder_operand_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        operand: ExpressionHandle,
        binders: &[(SymbolHandle, Interval)],
        previous: &[Interval],
    ) -> Option<Interval> {
        if let Some(literal) = literal_i64(program, operand) {
            return Some(Interval::constant(literal));
        }
        if let Some(stored) = stored_place_interval(program, machine, state, operand) {
            return Some(stored);
        }
        let symbol = named_symbol(program, operand)?;
        binders
            .iter()
            .position(|(candidate, _)| *candidate == symbol)
            .map(|index| previous[index])
    }

    fn named_symbol(
        program: &dyn CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<SymbolHandle> {
        match program.expression_table.expression(expression) {
            ExpressionNode::Name(path)
                if path.symbol.is_valid() && path.head_symbol == path.symbol =>
            {
                Some(path.symbol)
            }
            _ => None,
        }
    }

    fn requires_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        parameter: SymbolHandle,
        include_machine_contracts: bool,
    ) -> Interval {
        let key = crate::frozen_program::frozen_program_memos(program).and_then(|memos| {
            let (machine_pos, state_pos, _) =
                crate::proof_contracts::bound_expression_meaning::meaning_key(
                    program,
                    machine,
                    Some(state),
                    ExpressionHandle::default(),
                )?;
            Some((
                memos,
                (machine_pos, state_pos, parameter, include_machine_contracts),
            ))
        });
        if let Some((memos, key)) = key
            && let Ok(guard) = memos.parameter_requires_intervals.lock()
            && let Some(cached) = guard.get(&key).copied()
        {
            return cached;
        }
        let entry = program
            .machine_states(machine)
            .first()
            .is_some_and(|entry| entry.symbol == state.symbol);
        let machine_contracts = if entry || include_machine_contracts {
            program.machine_contracts(machine)
        } else {
            &[]
        };
        let interval = contract_subject_interval(
            program,
            machine,
            state,
            machine_contracts,
            SignatureContractKind::Requires,
            false,
            &|subject| names_parameter(program, subject, parameter),
        );
        if let Some((memos, key)) = key
            && let Ok(mut guard) = memos.parameter_requires_intervals.lock()
        {
            guard.insert(key, interval);
        }
        interval
    }

    fn names_parameter(
        program: &dyn CheckingInput,
        subject: ExpressionHandle,
        parameter: SymbolHandle,
    ) -> bool {
        matches!(
            program.expression_table.expression(subject),
            ExpressionNode::Name(path)
                if path.symbol == parameter && path.head_symbol == path.symbol
        )
    }
    fn boolean_subject_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        literal_bounds_only: bool,
        names_subject: &impl Fn(ExpressionHandle) -> bool,
    ) -> Option<Interval> {
        subject_fact_interval(
            program,
            machine,
            state,
            expression,
            names_subject,
            &|operand| {
                subject_operand_interval(program, machine, state, operand, literal_bounds_only)
            },
        )
    }

    fn subject_operand_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        operand: ExpressionHandle,
        literal_bounds_only: bool,
    ) -> Option<Interval> {
        literal_i64(program, operand)
            .map(Interval::constant)
            .or_else(|| {
                if literal_bounds_only {
                    None
                } else {
                    stored_place_interval(program, machine, state, operand)
                }
            })
    }
}
pub use guard_requirements::evaluated_call_requires_proven;
pub(crate) mod live_integer_constraints {
    use super::ordered_values::{Operand, RelationConstraint};
    use super::{
        ArithmeticDomain, BinaryOperator, ExpressionHandle, Machine, State, ValueEnvironment,
    };
    use crate::{
        ScopedArithmeticComparison, ScopedArithmeticValue,
        scoped_arithmetic_comparisons_unsatisfiable,
    };
    use numerics::bignum::BigInt;

    pub(crate) fn proves_condition(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
        bindings: &[(Operand, Operand)],
    ) -> bool {
        let Some(binary) = program.expression_table.binary_node(expression) else {
            return program.expression_table.boolean_node(expression) == Some(&true);
        };
        if !crate::proof_contracts::bound_expression_meaning::has_builtin_binary_expression_meaning(
            program,
            machine,
            Some(state),
            expression,
        ) {
            return false;
        }
        match binary.operator {
            BinaryOperator::And => {
                return proves_condition(
                    program,
                    machine,
                    state,
                    environment,
                    binary.left,
                    bindings,
                ) && proves_condition(
                    program,
                    machine,
                    state,
                    environment,
                    binary.right,
                    bindings,
                );
            }
            BinaryOperator::Or => {
                return proves_condition(
                    program,
                    machine,
                    state,
                    environment,
                    binary.left,
                    bindings,
                ) || proves_condition(
                    program,
                    machine,
                    state,
                    environment,
                    binary.right,
                    bindings,
                );
            }
            _ => {}
        }
        let Some(operator) = binary.operator.complement() else {
            return false;
        };
        let mut observations = Observations::default();
        let Some(comparison) = integer_comparison(
            program,
            machine,
            state,
            expression,
            operator,
            bindings,
            &mut observations,
        ) else {
            return false;
        };
        contradicts(
            program,
            machine,
            environment,
            observations,
            vec![comparison],
        )
    }

    fn integer_comparison(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        operator: BinaryOperator,
        bindings: &[(Operand, Operand)],
        observations: &mut Observations,
    ) -> Option<ScopedArithmeticComparison> {
        let binary = program.expression_table.binary_node(expression)?;
        let integer = |value| {
            program.expression_table.integer_node(value).is_some()
                || crate::collection_length_receiver(program, machine, Some(state), value).is_some()
                || super::declared_place_type_raw(program, machine, Some(state), value)
                    .and_then(|reference| program.primitive_type_reference(reference))
                    .is_some_and(|primitive| {
                        matches!(
                            primitive,
                            typed_trees::types::PrimitiveType::I8
                                | typed_trees::types::PrimitiveType::I16
                                | typed_trees::types::PrimitiveType::I32
                                | typed_trees::types::PrimitiveType::I64
                                | typed_trees::types::PrimitiveType::U8
                                | typed_trees::types::PrimitiveType::U16
                                | typed_trees::types::PrimitiveType::U32
                                | typed_trees::types::PrimitiveType::U64
                        )
                    })
        };
        if !integer(binary.left) || !integer(binary.right) {
            return None;
        }
        let left = super::ordered_values::operand(program, machine, state, binary.left, None)?;
        let right = super::ordered_values::operand(program, machine, state, binary.right, None)?;
        let (left, right) = if bindings.is_empty() {
            (left, right)
        } else {
            let rebound_left = left.rebound(bindings);
            let rebound_right = right.rebound(bindings);
            let ([left], [right]) = (rebound_left.as_slice(), rebound_right.as_slice()) else {
                return None;
            };
            (left.clone(), right.clone())
        };
        Some(ScopedArithmeticComparison {
            operator,
            left: observations.value(&left)?,
            right: observations.value(&right)?,
        })
    }

    pub(crate) fn contradicting_premises(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        base: &ValueEnvironment,
        arm: &ValueEnvironment,
    ) -> Option<Vec<String>> {
        if program.symbols.authored_origin(machine.symbol) != machine.symbol {
            return None;
        }
        let impossible = |environment: &ValueEnvironment| {
            environment
            .intervals
            .values()
            .any(|interval| matches!((interval.low(), interval.high()), (Some(low), Some(high)) if low > high))
            || contradicts(
                program,
                machine,
                environment,
                Observations::default(),
                Vec::new(),
            )
        };
        if !impossible(arm) || impossible(base) {
            return None;
        }
        let mut core = arm.clone();
        let mut premises = Vec::new();
        for relation in &base.ordered_values {
            let Some(position) = core.ordered_values.iter().position(|kept| kept == relation)
            else {
                continue;
            };
            let mut trial = core.clone();
            trial.ordered_values.remove(position);
            if impossible(&trial) {
                core = trial;
            } else {
                premises.push(render_relation(relation));
            }
        }
        for (path, interval) in &base.intervals {
            for lower in [true, false] {
                let Some(narrowed) = core.intervals.get(path).copied() else {
                    break;
                };
                let (base_bound, narrowed_bound) = if lower {
                    (interval.low(), narrowed.low())
                } else {
                    (interval.high(), narrowed.high())
                };
                let Some(bound) = base_bound.filter(|bound| narrowed_bound == Some(*bound)) else {
                    continue;
                };
                let mut withdrawn = narrowed;
                if lower {
                    withdrawn.low = None;
                } else {
                    withdrawn.high = None;
                }
                let mut trial = core.clone();
                if withdrawn.low.is_none() && withdrawn.high.is_none() {
                    trial.intervals.remove(path);
                } else {
                    trial.intervals.insert(path.clone(), withdrawn);
                }
                if impossible(&trial) {
                    core = trial;
                } else {
                    let relation = if lower { ">=" } else { "<=" };
                    premises.push(format!("{path} {relation} {bound}"));
                }
            }
        }
        Some(premises)
    }

    fn render_relation(relation: &super::ordered_values::Relation) -> String {
        let left = render_operand(&relation.left);
        let right = render_operand(&relation.right);
        match relation.constraint {
            RelationConstraint::Unequal => format!("{left} != {right}"),
            RelationConstraint::MinimumDifference(0) => format!("{left} >= {right}"),
            RelationConstraint::MinimumDifference(floor) if floor > 0 => {
                format!("{left} >= {right} + {floor}")
            }
            RelationConstraint::MinimumDifference(floor) => {
                format!("{left} >= {right} - {}", floor.unsigned_abs())
            }
        }
    }

    fn render_operand(operand: &Operand) -> String {
        if let Some(path) = operand.static_path() {
            return path;
        }
        match operand {
            Operand::Integer(literal, _) => literal
                .value_bignum()
                .map_or_else(|| "a literal".to_owned(), |value| value.to_string()),
            Operand::CollectionLength(collection) => format!("{}.len", render_operand(collection)),
            Operand::Binary {
                operator, operands, ..
            } if operands.len() == 2 => {
                let symbol = match operator {
                    BinaryOperator::Add => "+",
                    BinaryOperator::Subtract => "-",
                    BinaryOperator::Multiply => "*",
                    BinaryOperator::Divide => "/",
                    BinaryOperator::Modulo => "%",
                    _ => return "a computed value".to_owned(),
                };
                format!(
                    "({} {symbol} {})",
                    render_operand(&operands[0]),
                    render_operand(&operands[1])
                )
            }
            _ => "a computed value".to_owned(),
        }
    }

    pub(crate) fn excludes_values(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        assignments: &[(ExpressionHandle, i64)],
    ) -> bool {
        let Some(state) = state else {
            return false;
        };
        let mut observations = Observations::default();
        let mut comparisons = Vec::new();
        for &(expression, value) in assignments {
            let Some(operand) =
                super::ordered_values::operand(program, machine, state, expression, None)
            else {
                return false;
            };
            let Some(left) = observations.value(&operand) else {
                return false;
            };
            comparisons.push(ScopedArithmeticComparison {
                operator: BinaryOperator::Equal,
                left,
                right: integer(value),
            });
        }
        contradicts(program, machine, environment, observations, comparisons)
    }

    pub(crate) fn proves_range(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
        minimum: Option<&BigInt>,
        maximum: Option<&BigInt>,
    ) -> bool {
        if environment.ordered_values.is_empty() {
            return false;
        }
        let Some(operand) =
            super::ordered_values::operand(program, machine, state, expression, None)
        else {
            return false;
        };
        [
            (BinaryOperator::Less, minimum),
            (BinaryOperator::Greater, maximum),
        ]
        .into_iter()
        .filter_map(|(operator, bound)| bound.map(|bound| (operator, bound)))
        .all(|(operator, bound)| {
            let mut observations = Observations::default();
            let Some(left) = observations.value(&operand) else {
                return false;
            };
            contradicts(
                program,
                machine,
                environment,
                observations,
                vec![ScopedArithmeticComparison {
                    operator,
                    left,
                    right: ScopedArithmeticValue::Integer(bound.clone()),
                }],
            )
        })
    }

    pub(crate) fn proves_collection_footprint(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        environment: &ValueEnvironment,
        collection: ExpressionHandle,
        start: ExpressionHandle,
        width: i64,
    ) -> bool {
        if width < 0 {
            return false;
        }
        let Some(start) = super::ordered_values::operand(program, machine, state, start, None)
        else {
            return false;
        };
        let mut observations = Observations::default();
        let (Some(length), Some(start)) = (
            collection_length(program, machine, state, collection, &mut observations),
            observations.value(&start),
        ) else {
            return false;
        };
        let end = ScopedArithmeticValue::IntegerOperation {
            operator: BinaryOperator::Add,
            left: Box::new(start.clone()),
            right: Box::new(integer(width)),
        };
        [
            (BinaryOperator::Less, start, integer(0)),
            (BinaryOperator::Greater, end, length),
        ]
        .into_iter()
        .all(|(operator, left, right)| {
            contradicts(
                program,
                machine,
                environment,
                observations.clone(),
                vec![ScopedArithmeticComparison {
                    operator,
                    left,
                    right,
                }],
            )
        })
    }

    fn collection_length(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        collection: ExpressionHandle,
        observations: &mut Observations,
    ) -> Option<ScopedArithmeticValue> {
        let observed = super::ordered_values::operand(program, machine, state, collection, None)?;
        let length = super::ordered_values::collection_length_operand(
            program, machine, state, collection, observed,
        )?;
        observations.value(&length)
    }

    fn contradicts(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        environment: &ValueEnvironment,
        mut observations: Observations,
        mut comparisons: Vec<ScopedArithmeticComparison>,
    ) -> bool {
        for (position, relation) in environment.ordered_values.iter().enumerate() {
            let equality = (relation.constraint == RelationConstraint::MinimumDifference(0))
                .then(|| {
                    environment.ordered_values.iter().position(|opposite| {
                        opposite.constraint == RelationConstraint::MinimumDifference(0)
                            && opposite.left == relation.right
                            && opposite.right == relation.left
                    })
                })
                .flatten();
            if equality.is_some_and(|opposite| opposite < position) {
                continue;
            }
            let (Some(left), Some(right)) = (
                observations.value(&relation.left),
                observations.value(&relation.right),
            ) else {
                continue;
            };
            let (operator, right) = match relation.constraint {
                RelationConstraint::Unequal => (BinaryOperator::NotEqual, right),
                RelationConstraint::MinimumDifference(0) if equality.is_some() => {
                    (BinaryOperator::Equal, right)
                }
                RelationConstraint::MinimumDifference(floor) => (
                    BinaryOperator::GreaterOrEqual,
                    ScopedArithmeticValue::IntegerOperation {
                        operator: BinaryOperator::Add,
                        left: Box::new(right),
                        right: Box::new(integer(floor)),
                    },
                ),
            };
            comparisons.push(ScopedArithmeticComparison {
                operator,
                left,
                right,
            });
        }
        let mut comparison =
            super::ordered_values::ValueComparison::new(&environment.ordered_values);
        for (position, operand) in observations.atoms.iter().enumerate() {
            for (other_position, other) in observations.atoms[..position].iter().enumerate() {
                if comparison.same_value(operand, other) {
                    comparisons.push(ScopedArithmeticComparison {
                        operator: BinaryOperator::Equal,
                        left: atom(position),
                        right: atom(other_position),
                    });
                }
            }
        }
        for (position, operand) in observations.atoms.iter().enumerate() {
            let primitive = match operand {
                Operand::Place { root, .. } => {
                    crate::value_custody::places::declaration_type_reference(program, *root)
                        .and_then(|reference| program.primitive_type_reference(reference))
                }
                Operand::CollectionLength(_) => Some(typed_trees::types::PrimitiveType::U64),
                Operand::Indexed { primitive, .. } | Operand::Field { primitive, .. } => *primitive,
                Operand::Binary { primitive, .. } => *primitive,
                _ => None,
            };
            if let Some((minimum, maximum)) = primitive
                .filter(|primitive| primitive.is_fixed_integer())
                .and_then(|primitive| primitive.integer_bounds())
            {
                for (operator, bound) in [
                    (BinaryOperator::GreaterOrEqual, minimum),
                    (BinaryOperator::LessOrEqual, maximum),
                ] {
                    comparisons.push(ScopedArithmeticComparison {
                        operator,
                        left: atom(position),
                        right: ScopedArithmeticValue::Integer(BigInt::from_i128(bound)),
                    });
                }
            }
            let Some(path) = operand.static_path() else {
                continue;
            };
            let Some(interval) = environment.intervals.get(&path) else {
                continue;
            };
            for (operator, bound) in [
                (BinaryOperator::GreaterOrEqual, interval.low()),
                (BinaryOperator::LessOrEqual, interval.high()),
            ] {
                if let Some(bound) = bound {
                    comparisons.push(ScopedArithmeticComparison {
                        operator,
                        left: atom(position),
                        right: integer(bound),
                    });
                }
            }
        }
        scoped_arithmetic_comparisons_unsatisfiable(program, machine, &comparisons)
    }

    #[derive(Clone, Default)]
    pub(crate) struct Observations {
        atoms: Vec<Operand>,
    }

    impl Observations {
        fn value(&mut self, operand: &Operand) -> Option<ScopedArithmeticValue> {
            match operand {
                Operand::Integer(literal, _) => {
                    literal.value_bignum().map(ScopedArithmeticValue::Integer)
                }
                // A value can only be observed after the operation that made
                // it returned. An Exact operation was proved representable,
                // and a Trapping one that returned did not trap, so both
                // equal the mathematical result. A Wrapping or Saturating
                // result may differ from it and stays an opaque atom.
                Operand::Binary {
                    operator,
                    domain: ArithmeticDomain::Exact | ArithmeticDomain::Trapping,
                    operands,
                    ..
                } if matches!(
                    operator,
                    BinaryOperator::Add
                        | BinaryOperator::Subtract
                        | BinaryOperator::Multiply
                        | BinaryOperator::Divide
                        | BinaryOperator::Modulo
                ) =>
                {
                    let [left, right] = operands.as_slice() else {
                        return None;
                    };
                    Some(ScopedArithmeticValue::IntegerOperation {
                        operator: *operator,
                        left: Box::new(self.value(left)?),
                        right: Box::new(self.value(right)?),
                    })
                }
                _ => {
                    let position = self
                        .atoms
                        .iter()
                        .position(|candidate| candidate == operand)
                        .unwrap_or_else(|| {
                            self.atoms.push(operand.clone());
                            self.atoms.len() - 1
                        });
                    Some(atom(position))
                }
            }
        }
    }

    fn atom(position: usize) -> ScopedArithmeticValue {
        ScopedArithmeticValue::Atom {
            identity: format!("observation:{position}"),
            unsigned: false,
        }
    }

    fn integer(value: i64) -> ScopedArithmeticValue {
        ScopedArithmeticValue::Integer(BigInt::from_i64(value))
    }
}
pub(crate) use live_integer_constraints::contradicting_premises;
pub(crate) mod monotonic_update {
    use super::{
        ArithmeticDomain, BinaryOperator, ExpressionHandle, ExpressionNode, Interval, Machine,
        PrimitiveType, State, declared_place_type_raw,
    };
    use crate::proof_contracts::arithmetic_domains::integer_ranges::primitive_range;
    use numerics::integer_policy::{
        IntegerPolicyPrimitive, IntegerResultLaw, integer_policy_bridge,
    };

    pub fn builtin_monotonic_integer_update_bounds(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        lower: Option<i64>,
        upper: Option<i64>,
    ) -> Option<(Option<i64>, Option<i64>)> {
        if !crate::has_builtin_bound_expression_meaning(program, machine, Some(state), expression) {
            return None;
        }
        let binary = program.expression_table.binary_node(expression)?;
        let (operand, literal) = match binary.operator {
            BinaryOperator::Add
                if matches!(
                    program.expression_table.expression(binary.left),
                    ExpressionNode::Integer(_)
                ) =>
            {
                (binary.right, binary.left)
            }
            BinaryOperator::Add | BinaryOperator::Subtract => (binary.left, binary.right),
            _ => return None,
        };
        let literal_value = program.expression_table.integer_node(literal)?;
        let step = literal_value.value_i64().filter(|step| *step > 0)?;
        let operand_type = declared_place_type_raw(program, machine, Some(state), operand)?;
        let primitive = program.primitive_type_reference(operand_type)?;
        if primitive == PrimitiveType::Addr {
            return None;
        }
        let carrier = primitive_range(primitive)?;
        if let Some(landing) = literal_value.landing() {
            let literal_type =
                crate::declarations::operators::landed_integer_literal_type_reference(
                    program, literal,
                )?;
            if program.primitive_type_reference(literal_type) != Some(primitive)
                || (landing.domain != ArithmeticDomain::Exact
                    && landing.domain != program.arithmetic_domain_for_type_reference(operand_type))
            {
                return None;
            }
        }
        let step = Interval::constant(step);
        if !carrier.contains(step) {
            return None;
        }
        let before = Interval {
            low: lower,
            high: upper,
        }
        .intersect(carrier);
        if empty(before) {
            return None;
        }
        let (mathematical, policy_primitive) = match binary.operator {
            BinaryOperator::Add => (before.add(step), IntegerPolicyPrimitive::Add),
            BinaryOperator::Subtract => (before.subtract(step), IntegerPolicyPrimitive::Subtract),
            _ => return None,
        };
        let policy = program.arithmetic_domain_for_type_reference(operand_type);
        let result_law = integer_policy_bridge(policy_primitive, policy).result_law;
        let after = match result_law {
            IntegerResultLaw::Mathematical => mathematical.intersect(carrier),
            IntegerResultLaw::ClampToCarrier => {
                let mut clamped = mathematical;
                if let Some(minimum) = carrier.low {
                    clamped = clamped.max_with(Interval::constant(minimum));
                }
                if let Some(maximum) = carrier.high {
                    clamped = clamped.min_with(Interval::constant(maximum));
                }
                clamped
            }
            IntegerResultLaw::WrapToCarrier => {
                if !carrier.contains(mathematical)
                    || (binary.operator == BinaryOperator::Add && mathematical.high.is_none())
                {
                    return None;
                }
                mathematical
            }
        };
        (!empty(after)).then_some((after.low, after.high))
    }

    fn empty(interval: Interval) -> bool {
        matches!((interval.low, interval.high), (Some(low), Some(high)) if low > high)
    }
}
pub(crate) mod operand_reports {
    use diagnostics::Diagnostic;
    use typed_trees::expression::{BinaryOperator, ExpressionHandle};
    use typed_trees::machine::Machine;
    use typed_trees::state::State;

    pub(crate) fn report_mismatched_integer_operands(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        operator: BinaryOperator,
        left: ExpressionHandle,
        right: ExpressionHandle,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> bool {
        if !matches!(
            operator,
            BinaryOperator::Add
                | BinaryOperator::Subtract
                | BinaryOperator::Multiply
                | BinaryOperator::Divide
                | BinaryOperator::Modulo
                | BinaryOperator::BitwiseAnd
                | BinaryOperator::BitwiseOr
                | BinaryOperator::BitwiseXor
        ) {
            return false;
        }
        let operand_integer = |operand| {
            if crate::value_custody::literals::has_anonymous_numeric_results(program, operand) {
                return None;
            }
            state
                .and_then(|state| {
                    crate::value_custody::expression_types::expression_result_type_reference(
                        program, machine, state, operand,
                    )
                })
                .or_else(|| {
                    crate::value_custody::places::declared_place_type(
                        program, machine, state, operand,
                    )
                })
                .and_then(|type_reference| program.primitive_type_reference(type_reference))
                .filter(|primitive| super::integer_bit_width(*primitive).is_some())
        };
        let (Some(left_primitive), Some(right_primitive)) =
            (operand_integer(left), operand_integer(right))
        else {
            return false;
        };
        if left_primitive == right_primitive {
            return false;
        }
        diagnostics.push(Diagnostic::error(format!(
        "machine `{}` state `{}` applies `{operator:?}` to a `{}` value and a `{}` value -- the \
         operands have different integer types and the operation would silently truncate or \
         reinterpret a value; convert one with an exact `as` cast so both are the same type",
        machine.name.as_str(),
        state.map(|state| state.name.as_str()).unwrap_or(""),
        left_primitive.name(),
        right_primitive.name(),
    )));
        true
    }

    pub(crate) fn arithmetic_operator_spelling(operator: BinaryOperator) -> &'static str {
        match operator {
            BinaryOperator::Add => "+",
            BinaryOperator::Subtract => "-",
            BinaryOperator::Multiply => "*",
            BinaryOperator::Divide => "/",
            BinaryOperator::Modulo => "%",
            BinaryOperator::ShiftLeft => "<<",
            BinaryOperator::ShiftRight => ">>",
            _ => "?",
        }
    }

    pub(crate) fn is_arithmetic(operator: BinaryOperator) -> bool {
        matches!(
            operator,
            BinaryOperator::Add
                | BinaryOperator::Subtract
                | BinaryOperator::Multiply
                | BinaryOperator::Divide
                | BinaryOperator::Modulo
                | BinaryOperator::ShiftLeft
                | BinaryOperator::ShiftRight
        )
    }
}
pub(crate) mod ordered_values {

    use super::{
        ArithmeticDomain, BinaryOperator, ExpressionHandle, ExpressionNode, Interval, Machine,
        PrimitiveType, State, ValueEnvironment, declared_place_type_raw, place_path,
    };
    use crate::CheckingInput;
    use crate::proof_contracts::arithmetic_domains::expression_analysis::analyze_meaning;
    use crate::proof_contracts::arithmetic_domains::integer_ranges::{
        literal_interval, primitive_range,
    };
    use crate::proof_contracts::arithmetic_domains::place_paths::place_paths_overlap;
    use crate::value_custody::places::collection_length_receiver;
    use congruence::EqualityQuery;
    use numerics::literals::IntegerLanding;
    use symbols::SymbolHandle;
    use typed_trees::data::TypeParameterKind;

    pub(crate) mod assignment_reads {
        use super::Operand;
        use super::storage::{ReadSegment, compatible_destination, disjoint};
        use facts::PlaceSegment;
        use typed_trees::expression::ExpressionHandle;

        impl Operand {
            #[allow(clippy::too_many_arguments)]
            pub(crate) fn assignment_reference_read_preserved(
                &self,
                program: &dyn crate::CheckingInput,
                machine: &typed_trees::machine::Machine,
                state: Option<&typed_trees::state::State>,
                statement: &typed_trees::statement::StatementNode,
                frames: Option<&crate::CallFrameResolver<'_>>,
                storage: Option<&crate::AssignmentStorageOrigins>,
            ) -> Option<bool> {
                let mut segments = Vec::new();
                let root = self.read_coordinate(&mut segments)?;
                let Some(state) = state else {
                    return Some(false);
                };
                let result = (|| {
                    let Some(mut reference) = crate::state_root_type(program, state, root) else {
                        return if self.is_immutable_snapshot(program, state) {
                            Ok(None)
                        } else {
                            Err("root-type")
                        };
                    };
                    let mut path = Vec::new();
                    let mut reference_read = false;
                    let mut dynamic = None;
                    let mut measure = false;
                    let mut slice_descriptor_measure = false;
                    for (ordinal, segment) in segments.iter().enumerate() {
                        while let Some(shell) = crate::reference_shell(program, reference) {
                            if dynamic.is_some() {
                                return Err("uncaptured-inner-selector");
                            }
                            if matches!(segment, ReadSegment::Length)
                                && crate::slice_view_shell(program, reference, &[]).is_some()
                            {
                                slice_descriptor_measure = true;
                            }
                            reference_read = true;
                            reference = shell.referee;
                        }
                        match segment {
                            ReadSegment::Field(symbol) => {
                                let start = path.len();
                                let parent = program.symbols.get(*symbol).parent;
                                if program.variant_owner(parent).is_some() {
                                    path.push(PlaceSegment::Case { variant: parent });
                                }
                                path.push(PlaceSegment::Field { symbol: *symbol });
                                reference = crate::project_type_reference_from_segments(
                                    program,
                                    reference,
                                    &path[start..],
                                )
                                .ok_or("field-type")?;
                            }
                            ReadSegment::Element(index) => {
                                reference =
                            crate::value_custody::places::collection_element_type_reference(
                                program, reference,
                            )
                            .ok_or("element-type")?;
                                path.push(match index {
                                    Some(index) => PlaceSegment::FixedIndex { index: *index },
                                    None => {
                                        dynamic.get_or_insert(path.len());
                                        PlaceSegment::Index {
                                            expression: ExpressionHandle::invalid(),
                                        }
                                    }
                                });
                            }
                            ReadSegment::Length => {
                                if ordinal + 1 != segments.len() {
                                    return Err("measure-suffix");
                                }
                                measure = true;
                            }
                            ReadSegment::Case(_) => return Err("unexpected-case-coordinate"),
                        }
                    }
                    if crate::reference_shell(program, reference).is_some() {
                        if dynamic.is_some() {
                            return Err("uncaptured-inner-selector");
                        }
                        reference_read = true;
                    }
                    if !reference_read {
                        return Ok(None);
                    }
                    if measure
                        && crate::stable_slice_descriptor_place(program, state, root, &path)
                            .is_some()
                    {
                        return Ok(Some(true));
                    }
                    let index = program
                        .statement_table
                        .statements(state.statement_nodes)
                        .iter()
                        .position(|candidate| std::ptr::eq(candidate, statement))
                        .ok_or("statement-owner")?;
                    let frames = frames.ok_or("read-owner")?;
                    let cutoff = dynamic.unwrap_or(path.len());
                    let backing = frames
                        .storage_read_backing_before_statement(
                            machine,
                            state,
                            index,
                            root,
                            &path[..cutoff],
                        )
                        .ok_or("read-backing")?;
                    if backing.sources.is_empty() {
                        return Err("empty-suppliers");
                    }
                    let storage = storage.ok_or("write-destinations")?;
                    let replaced_binding = if storage.destinations.is_empty() {
                        let assignment = statement.as_assignment().ok_or("binding-assignment")?;
                        let place =
                            crate::canonical_place_from_expression(program, assignment.target)
                                .ok_or("binding-home")?;
                        let replaced = place.root.as_symbol().ok_or("binding-root")?;
                        if !place.segments.is_empty()
                            || program.state_local_declaration(state, replaced).is_none()
                            || !matches!(storage.references.as_ref(), Some(references) if references.is_empty())
                        {
                            return Err("binding-role");
                        }
                        if root == replaced {
                            return Err("replaced-read-binding");
                        }
                        Some(replaced)
                    } else {
                        None
                    };
                    for binding in &backing.bindings {
                        if !source_namespace_is_exact(binding) {
                            return Err("binding-namespace");
                        }
                        let borrowed_root = program
                            .state_parameter_by_symbol(state, binding.root)
                            .is_some_and(|parameter| {
                                crate::reference_shell(program, parameter.type_reference).is_some()
                            });
                        if !borrowed_root && crate::value_custody::places::binding_observations::stable_reference_descriptor_place(
                    program, state, binding.root, &binding.segments,
                ).is_some() {
                    continue;
                }
                        if replaced_binding.is_some() {
                            return Err("descriptor-binding-replacement");
                        }
                        let read = read_segments(&binding.segments).ok_or("binding-coordinate")?;
                        if !storage.destinations.iter().all(|destination| {
                            compatible_destination(binding.root, destination)
                                && disjoint(&read, &destination.segments)
                        }) {
                            return Err("descriptor-binding-write");
                        }
                    }
                    if slice_descriptor_measure {
                        return Ok(Some(true));
                    }
                    let mut suffix = read_segments(&path[cutoff..]).ok_or("owned-suffix")?;
                    if measure {
                        suffix.push(ReadSegment::Length);
                    }
                    for source in &backing.sources {
                        if !source_namespace_is_exact(source) {
                            return Err("supplier-namespace");
                        }
                        if let Some(replaced) = replaced_binding {
                            if source.root == replaced {
                                return Err("replaced-supplier-root");
                            }
                            continue;
                        }
                        let mut read =
                            read_segments(&source.segments).ok_or("supplier-coordinate")?;
                        read.extend_from_slice(&suffix);
                        if !storage.destinations.iter().all(|destination| {
                            compatible_destination(source.root, destination)
                                && disjoint(&read, &destination.segments)
                        }) {
                            return Err("overlapping-store");
                        }
                    }
                    Ok(Some(true))
                })();
                match result {
                    Ok(preserved) => preserved,
                    Err(_) => Some(false),
                }
            }
        }

        fn source_namespace_is_exact(source: &crate::LocalWriteSource) -> bool {
            source.root.is_valid()
                && source.invocation_output.is_none()
                && source.invocation_result.is_none()
                && !source.is_image_storage
                && source.recasts.is_empty()
                && source.representation.is_none()
                && !source.collection_coarse
        }

        fn read_segments(path: &[PlaceSegment]) -> Option<Vec<ReadSegment>> {
            path.iter()
                .map(|segment| match segment {
                    PlaceSegment::Field { symbol } => Some(ReadSegment::Field(*symbol)),
                    PlaceSegment::Case { variant } => Some(ReadSegment::Case(*variant)),
                    PlaceSegment::FixedIndex { index } => Some(ReadSegment::Element(Some(*index))),
                    PlaceSegment::Index { .. } => Some(ReadSegment::Element(None)),
                    _ => None,
                })
                .collect()
        }
    }
    pub(crate) mod captured_references {
        use super::{ExpressionHandle, Machine, Operand, State};
        use facts::PlaceSegment;

        pub(crate) fn operand(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
            expression: ExpressionHandle,
            frames: Option<&crate::CallFrameResolver<'_>>,
        ) -> Option<Operand> {
            let prepared;
            let frames = match frames {
                Some(frames) => frames,
                None => {
                    prepared = crate::CallFrameResolver::new(program)?;
                    &prepared
                }
            };
            let sources = frames.completed_reference_read_sources(machine, state, expression)?;
            if crate::trace_flags::reference_slot_trace() {
                eprintln!(
                    "SLOT read-sources machine={} expression={expression:?} sources={sources:?}",
                    machine.name
                );
            }
            let mut sources = sources.iter();
            let first = source_operand(program, state, sources.next()?)?;
            for source in sources {
                if source_operand(program, state, source)? != first {
                    return None;
                }
            }
            Some(first)
        }

        fn source_operand(
            program: &dyn crate::CheckingInput,
            state: &State,
            source: &crate::LocalWriteSource,
        ) -> Option<Operand> {
            if source.collection_coarse
                || !source.root.is_valid()
                || source.invocation_output.is_some()
                || source.is_image_storage
                || !source.recasts.is_empty()
                || source.representation.is_some()
            {
                return None;
            }
            let declared_root = crate::state_root_type(program, state, source.root)?;
            let root_type = if program
                .state_parameter_by_symbol(state, source.root)
                .is_some()
            {
                crate::reference_shell(program, declared_root)
                    .map_or(declared_root, |shell| shell.referee)
            } else {
                declared_root
            };
            let selected =
                crate::owned_projection_type_reference(program, root_type, &source.segments)?;
            if crate::reference_shell(program, selected).is_some() {
                return None;
            }
            let mut value = Operand::Place {
                root: source.root,
                path: program.symbols.name(source.root).to_owned(),
            };
            for (ordinal, segment) in source.segments.iter().enumerate() {
                let selected = crate::owned_projection_type_reference(
                    program,
                    root_type,
                    &source.segments[..=ordinal],
                )?;
                match segment {
                    PlaceSegment::Case { .. } => {}
                    PlaceSegment::Field { symbol } if symbol.is_valid() => {
                        value = Operand::Field {
                            receiver: Box::new(value),
                            field: *symbol,
                            name: program.symbols.name(*symbol).to_owned(),
                            primitive: program.primitive_type_reference(selected),
                        };
                    }
                    PlaceSegment::FixedIndex { index } => {
                        value = Operand::Indexed {
                            collection: Box::new(value),
                            index: Box::new(Operand::Integer(
                                numerics::literals::IntegerLiteral::from_parts(
                                    false,
                                    numerics::literals::IntegerRadix::Decimal,
                                    &index.to_string(),
                                )
                                .ok()?,
                                None,
                            )),
                            primitive: program.primitive_type_reference(selected),
                        };
                    }
                    _ => return None,
                }
            }
            Some(value)
        }
    }
    pub(crate) mod congruence {
        use super::{Operand, Relation};

        pub(crate) mod difference_graph {
            use super::super::{Operand, Relation};

            pub(crate) struct Edge {
                source: usize,
                destination: usize,
                minimum_difference: i64,
            }

            pub(crate) struct DifferenceGraph<'relations> {
                operands: Vec<&'relations Operand>,
                edges: Vec<Edge>,
                has_outgoing: Vec<bool>,
                has_incoming: Vec<bool>,
                #[cfg(test)]
                component: Vec<u32>,
                core_component: Vec<u32>,
                core_component_edges: Vec<Vec<usize>>,
                #[cfg(test)]
                gaps: Vec<Option<Vec<Option<i64>>>>,
                core_gaps: Vec<Option<Vec<Option<i64>>>>,
            }

            impl<'relations> DifferenceGraph<'relations> {
                pub(crate) fn new(relations: &'relations [Relation]) -> Self {
                    let mut operands = Vec::new();
                    let mut edges = Vec::new();
                    for relation in relations {
                        let destination = retain_operand(&mut operands, &relation.left);
                        let source = retain_operand(&mut operands, &relation.right);
                        if let Some(minimum_difference) = relation.minimum_difference() {
                            edges.push(Edge {
                                source,
                                destination,
                                minimum_difference,
                            });
                        }
                    }
                    let len = operands.len();
                    let mut has_outgoing = vec![false; len];
                    let mut has_incoming = vec![false; len];
                    for edge in &edges {
                        has_outgoing[edge.source] = true;
                        has_incoming[edge.destination] = true;
                    }
                    #[cfg(test)]
                    let component = {
                        let mut component: Vec<u32> = (0..len as u32).collect();
                        for edge in &edges {
                            let mut root_a = edge.source as u32;
                            while component[root_a as usize] != root_a {
                                component[root_a as usize] =
                                    component[component[root_a as usize] as usize];
                                root_a = component[root_a as usize];
                            }
                            let mut root_b = edge.destination as u32;
                            while component[root_b as usize] != root_b {
                                component[root_b as usize] =
                                    component[component[root_b as usize] as usize];
                                root_b = component[root_b as usize];
                            }
                            if root_a != root_b {
                                component[root_b as usize] = root_a;
                            }
                        }
                        for index in 0..len {
                            let mut root = index as u32;
                            while component[root as usize] != root {
                                root = component[root as usize];
                            }
                            component[index] = root;
                        }
                        component
                    };
                    let mut core_component: Vec<u32> = (0..len as u32).collect();
                    for edge in &edges {
                        if !(has_outgoing[edge.source]
                            && has_incoming[edge.source]
                            && has_outgoing[edge.destination]
                            && has_incoming[edge.destination])
                        {
                            continue;
                        }
                        let mut root_a = edge.source as u32;
                        while core_component[root_a as usize] != root_a {
                            core_component[root_a as usize] =
                                core_component[core_component[root_a as usize] as usize];
                            root_a = core_component[root_a as usize];
                        }
                        let mut root_b = edge.destination as u32;
                        while core_component[root_b as usize] != root_b {
                            core_component[root_b as usize] =
                                core_component[core_component[root_b as usize] as usize];
                            root_b = core_component[root_b as usize];
                        }
                        if root_a != root_b {
                            core_component[root_b as usize] = root_a;
                        }
                    }
                    for index in 0..len {
                        let mut root = index as u32;
                        while core_component[root as usize] != root {
                            root = core_component[root as usize];
                        }
                        core_component[index] = root;
                    }
                    let mut core_component_edges: Vec<Vec<usize>> = vec![Vec::new(); len];
                    for (edge_index, edge) in edges.iter().enumerate() {
                        if has_outgoing[edge.source]
                            && has_incoming[edge.source]
                            && has_outgoing[edge.destination]
                            && has_incoming[edge.destination]
                        {
                            core_component_edges[core_component[edge.source] as usize]
                                .push(edge_index);
                        }
                    }
                    let core_gaps = vec![None; len];
                    Self {
                        operands,
                        edges,
                        has_outgoing,
                        has_incoming,
                        #[cfg(test)]
                        component,
                        core_component,
                        core_component_edges,
                        #[cfg(test)]
                        gaps: vec![None; len],
                        core_gaps,
                    }
                }

                pub(crate) fn operand_index(&self, operand: &Operand) -> Option<usize> {
                    self.operands.iter().position(|known| *known == operand)
                }

                pub(crate) fn mutual_nonnegative_gap(
                    &mut self,
                    left: &Operand,
                    right: &Operand,
                ) -> bool {
                    if left == right {
                        return true;
                    }
                    let Some(source) = self.operand_index(left) else {
                        return false;
                    };
                    if !self.has_outgoing[source] || !self.has_incoming[source] {
                        return false;
                    }
                    let Some(destination) = self.operand_index(right) else {
                        return false;
                    };
                    self.mutual_nonnegative_gap_indexed(source, destination)
                }

                pub(crate) fn mutual_nonnegative_gap_indexed(
                    &mut self,
                    source: usize,
                    destination: usize,
                ) -> bool {
                    if source == destination {
                        return true;
                    }
                    if !self.has_outgoing[source]
                        || !self.has_incoming[source]
                        || !self.has_outgoing[destination]
                        || !self.has_incoming[destination]
                        || self.core_component[source] != self.core_component[destination]
                    {
                        return false;
                    }
                    self.core_nonnegative_gap_indexed(source, destination)
                        && self.core_nonnegative_gap_indexed(destination, source)
                }

                fn core_nonnegative_gap_indexed(
                    &mut self,
                    source: usize,
                    destination: usize,
                ) -> bool {
                    if self.core_gaps[source].is_none() {
                        let target_component = self.core_component[source] as usize;
                        let component_edges = &self.core_component_edges[target_component];
                        let mut gaps: Vec<Option<i64>> = vec![None; self.operands.len()];
                        gaps[source] = Some(0);
                        for _ in 1..self.operands.len() {
                            let mut improved = false;
                            for &edge_index in component_edges {
                                let edge = &self.edges[edge_index];
                                let Some(source_gap) = gaps[edge.source] else {
                                    continue;
                                };
                                let Some(gap) = source_gap.checked_add(edge.minimum_difference)
                                else {
                                    continue;
                                };
                                if gaps[edge.destination].is_none_or(|known| known < gap) {
                                    gaps[edge.destination] = Some(gap);
                                    improved = true;
                                }
                            }
                            if !improved {
                                break;
                            }
                        }
                        self.core_gaps[source] = Some(gaps);
                    }
                    self.core_gaps[source]
                        .as_ref()
                        .is_some_and(|gaps| gaps[destination].is_some_and(|gap| gap >= 0))
                }

                #[cfg(test)]
                pub(crate) fn nonnegative_gap(&mut self, from: &Operand, to: &Operand) -> bool {
                    if from == to {
                        return true;
                    }
                    let Some(source) = self.operands.iter().position(|operand| *operand == from)
                    else {
                        return false;
                    };
                    if !self.has_outgoing[source] {
                        return false;
                    }
                    let Some(destination) = self.operands.iter().position(|operand| *operand == to)
                    else {
                        return false;
                    };
                    if !self.has_incoming[destination]
                        || self.component[source] != self.component[destination]
                    {
                        return false;
                    }
                    if self.has_incoming[source] && self.has_outgoing[destination] {
                        if self.core_component[source] != self.core_component[destination] {
                            return false;
                        }
                        return self.core_nonnegative_gap_indexed(source, destination);
                    }
                    if self.gaps[source].is_none() {
                        let target_component = self.component[source];
                        let mut gaps: Vec<Option<i64>> = vec![None; self.operands.len()];
                        gaps[source] = Some(0);
                        for _ in 1..self.operands.len() {
                            let mut improved = false;
                            for edge in &self.edges {
                                if self.component[edge.source] != target_component {
                                    continue;
                                }
                                let Some(source_gap) = gaps[edge.source] else {
                                    continue;
                                };
                                let Some(gap) = source_gap.checked_add(edge.minimum_difference)
                                else {
                                    continue;
                                };
                                if gaps[edge.destination].is_none_or(|known| known < gap) {
                                    gaps[edge.destination] = Some(gap);
                                    improved = true;
                                }
                            }
                            if !improved {
                                break;
                            }
                        }
                        self.gaps[source] = Some(gaps);
                    }
                    self.gaps[source]
                        .as_ref()
                        .is_some_and(|gaps| gaps[destination].is_some_and(|gap| gap >= 0))
                }
            }

            fn retain_operand<'relations>(
                operands: &mut Vec<&'relations Operand>,
                operand: &'relations Operand,
            ) -> usize {
                match operands.iter().position(|existing| *existing == operand) {
                    Some(position) => position,
                    None => {
                        operands.push(operand);
                        operands.len() - 1
                    }
                }
            }

            #[cfg(test)]
            pub(crate) mod tests {
                use super::super::super::RelationConstraint;
                use super::super::{EqualityQuery, ValueComparison};
                use super::{DifferenceGraph, Operand, Relation};

                fn place(position: u32) -> Operand {
                    Operand::Place {
                        root: symbols::SymbolHandle::from_arena_index(position),
                        path: format!("place{position}"),
                    }
                }

                fn relation(left: Operand, right: Operand, floor: i64) -> Relation {
                    Relation {
                        left,
                        right,
                        constraint: RelationConstraint::MinimumDifference(floor),
                    }
                }

                fn reference_gaps<'relations>(
                    relations: &'relations [Relation],
                    value: &'relations Operand,
                ) -> Vec<(&'relations Operand, i64)> {
                    let mut operands = vec![value];
                    for relation in relations {
                        for operand in [&relation.left, &relation.right] {
                            if !operands.contains(&operand) {
                                operands.push(operand);
                            }
                        }
                    }
                    let mut distances = vec![(value, 0_i64)];
                    for _ in 1..operands.len() {
                        let mut improved = false;
                        for relation in relations {
                            let Some(floor) = relation.minimum_difference() else {
                                continue;
                            };
                            let Some(gap) = distances
                                .iter()
                                .find(|(known, _)| *known == &relation.right)
                                .map(|(_, gap)| *gap)
                            else {
                                continue;
                            };
                            let Some(gap) = gap.checked_add(floor) else {
                                continue;
                            };
                            match distances
                                .iter_mut()
                                .find(|(known, _)| *known == &relation.left)
                            {
                                Some((_, known)) if *known >= gap => {}
                                Some((_, known)) => {
                                    *known = gap;
                                    improved = true;
                                }
                                None => {
                                    distances.push((&relation.left, gap));
                                    improved = true;
                                }
                            }
                        }
                        if !improved {
                            break;
                        }
                    }
                    distances
                }

                #[test]
                fn compact_difference_rows_match_symbolic_walk_with_cycles_and_overflow() {
                    let operands = (1..=7).map(place).collect::<Vec<_>>();
                    let floors = [i64::MIN, -4, -1, 0, 1, 4, i64::MAX];
                    let mut random = 0x853c_49e6_748f_ea9b_u64;
                    let mut next = || {
                        random ^= random << 13;
                        random ^= random >> 7;
                        random ^= random << 17;
                        random
                    };
                    for case in 0..256 {
                        let mut relations = Vec::new();
                        for _ in 0..case % 19 {
                            let left = operands[(next() % 6) as usize].clone();
                            let right = operands[(next() % 6) as usize].clone();
                            let constraint = if next() % 5 == 0 {
                                RelationConstraint::Unequal
                            } else {
                                RelationConstraint::MinimumDifference(
                                    floors[(next() % floors.len() as u64) as usize],
                                )
                            };
                            relations.push(Relation {
                                left,
                                right,
                                constraint,
                            });
                        }
                        let mut graph = DifferenceGraph::new(&relations);
                        for from in operands.iter().chain(operands.iter().rev()) {
                            let expected = reference_gaps(&relations, from);
                            for to in &operands {
                                let mutual = expected
                                    .iter()
                                    .any(|(operand, gap)| *operand == to && *gap >= 0)
                                    && reference_gaps(&relations, to)
                                        .iter()
                                        .any(|(operand, gap)| *operand == from && *gap >= 0);
                                assert_eq!(graph.mutual_nonnegative_gap(from, to), mutual);
                                if let (Some(source), Some(destination)) =
                                    (graph.operand_index(from), graph.operand_index(to))
                                {
                                    assert_eq!(
                                        graph.mutual_nonnegative_gap_indexed(source, destination),
                                        mutual
                                    );
                                }
                                assert_eq!(
                                    graph.nonnegative_gap(from, to),
                                    expected
                                        .iter()
                                        .any(|(operand, gap)| *operand == to && *gap >= 0),
                                    "case {case}, {from:?} -> {to:?}, relations {relations:?}"
                                );
                            }
                        }
                    }
                }

                #[test]
                fn constructor_congruence_keeps_denotations_events_and_declaration_generations() {
                    let left = place(1);
                    let right = place(2);
                    let relations = [
                        relation(left.clone(), right.clone(), 0),
                        relation(right.clone(), left.clone(), 0),
                    ];
                    let mut comparison = ValueComparison::new(&relations);
                    let call = |argument: Operand, target| Operand::Call {
                        target,
                        arguments: vec![argument],
                    };
                    let target = symbols::SymbolHandle::from_parts(3, 1);
                    let repeated_left = call(left.clone(), target);
                    let repeated_right = call(right.clone(), target);
                    assert!(comparison.same_value(&repeated_left, &repeated_right));
                    let different_target =
                        call(right.clone(), symbols::SymbolHandle::from_parts(4, 1));
                    let stale_target = call(right.clone(), symbols::SymbolHandle::from_parts(3, 2));
                    assert!(!comparison.same_value(&repeated_left, &different_target));
                    assert!(!comparison.same_value(&repeated_left, &stale_target));
                    let first_event = Operand::CompletedCall {
                        target: symbols::SymbolHandle::from_arena_index(3),
                        occurrence: typed_trees::expression::ExpressionHandle::from_parts(4, 1),
                    };
                    let second_event = Operand::CompletedCall {
                        target: symbols::SymbolHandle::from_arena_index(3),
                        occurrence: typed_trees::expression::ExpressionHandle::from_parts(4, 2),
                    };
                    assert!(!comparison.same_value(&first_event, &second_event));
                    let another_event = Operand::CompletedCall {
                        target: symbols::SymbolHandle::from_arena_index(3),
                        occurrence: typed_trees::expression::ExpressionHandle::from_parts(5, 1),
                    };
                    assert!(!comparison.same_value(&first_event, &another_event));
                    assert!(first_event.survives(&[]));
                    assert!(!first_event.survives(&["unrelated".into()]));
                    assert!(
                        first_event
                            .rebound(&[(left.clone(), right.clone())])
                            .is_empty()
                    );
                    assert!(!comparison.same_value(&first_event, &repeated_left));
                    let stale = Operand::Place {
                        root: symbols::SymbolHandle::from_parts(1, 2),
                        path: "place1".into(),
                    };
                    assert!(!comparison.same_value(&left, &stale));
                    assert!(comparison.same_value(
                        &Operand::CollectionLength(Box::new(left)),
                        &Operand::CollectionLength(Box::new(right))
                    ));
                }

                #[test]
                fn a_new_relation_environment_does_not_inherit_equalities() {
                    let left = place(1);
                    let right = place(2);
                    let forward = relation(left.clone(), right.clone(), 0);
                    let reverse = relation(right.clone(), left.clone(), 0);
                    assert!(
                        ValueComparison::new(&[forward.clone(), reverse]).same_value(&left, &right)
                    );
                    assert!(!ValueComparison::new(&[forward]).same_value(&left, &right));
                    assert!(
                        !ValueComparison::new(&[Relation {
                            left: left.clone(),
                            right: right.clone(),
                            constraint: RelationConstraint::Unequal
                        }])
                        .same_value(&left, &right)
                    );
                    assert!(!ValueComparison::new(&[]).same_value(&left, &right));
                }

                #[test]
                fn one_subject_closure_matches_separate_endpoint_queries() {
                    let operands = (1..=8).map(place).collect::<Vec<_>>();
                    let length =
                        |operand: &Operand| Operand::CollectionLength(Box::new(operand.clone()));
                    let mut random = 0x853c_49e6_748f_ea9b_u64;
                    let mut next = || {
                        random ^= random << 13;
                        random ^= random >> 7;
                        random ^= random << 17;
                        random
                    };
                    for case in 0..64 {
                        let mut relations = vec![
                            relation(operands[0].clone(), operands[1].clone(), 0),
                            relation(operands[1].clone(), operands[0].clone(), 0),
                            relation(operands[2].clone(), length(&operands[0]), 0),
                            relation(length(&operands[0]), operands[2].clone(), 0),
                        ];
                        for _ in 0..case % 12 {
                            let left = operands[(next() % 8) as usize].clone();
                            let right = operands[(next() % 8) as usize].clone();
                            relations.push(relation(left, right, (next() % 3) as i64 - 1));
                        }
                        let subject = length(&operands[1]);
                        let mut shared = EqualityQuery::new(&relations, &subject, &subject);
                        for relation in relations.iter().chain(relations.iter().rev()) {
                            for candidate in [&relation.left, &relation.right] {
                                let expected = ValueComparison::new(&relations)
                                    .same_value(&subject, candidate);
                                assert_eq!(
                                    shared.same_value(&subject, candidate),
                                    expected,
                                    "case {case}"
                                );
                            }
                        }
                        assert!(shared.same_value(&subject, &operands[2]));
                        assert!(
                            !EqualityQuery::new(&[], &subject, &subject)
                                .same_value(&subject, &operands[2])
                        );
                    }
                }

                #[test]
                fn one_subject_closure_preserves_answers_near_finite_limits() {
                    let length = |operand: Operand| Operand::CollectionLength(Box::new(operand));
                    let subject = length(place(2));
                    for count in [32, 128, 176, 180, 192, 250, 256, 257] {
                        let mut relations = vec![
                            relation(place(1), place(2), 0),
                            relation(place(2), place(1), 0),
                            relation(place(3), length(place(1)), 0),
                            relation(length(place(1)), place(3), 0),
                        ];
                        for position in 4..count {
                            relations.push(relation(place(position), place(1), 1));
                        }
                        for reverse in [false, true] {
                            if reverse {
                                relations.reverse();
                            }
                            let mut shared = EqualityQuery::new(&relations, &subject, &subject);
                            for candidate in [place(3), place(count - 1), place(1), place(3)] {
                                assert_eq!(
                                    shared.same_value(&subject, &candidate),
                                    ValueComparison::new(&relations)
                                        .same_value(&subject, &candidate),
                                    "{count} terms, reverse={reverse}"
                                );
                            }
                            assert!(shared.same_value(&place(1), &place(2)));
                        }
                    }
                }
            }
        }
        use difference_graph::DifferenceGraph;

        pub(crate) struct IndexedOrderGraph<'relations> {
            operands: Vec<&'relations Operand>,
            indexed_relations: Vec<(usize, usize, i64)>,
            same_cache: Vec<Option<bool>>,
        }

        impl<'relations> IndexedOrderGraph<'relations> {
            fn new(relations: &'relations [Relation]) -> Self {
                let mut operands: Vec<&'relations Operand> = Vec::new();
                let mut indexed_relations = Vec::with_capacity(relations.len());
                for relation in relations {
                    let left_idx = operands
                        .iter()
                        .position(|existing| *existing == &relation.left)
                        .unwrap_or_else(|| {
                            let idx = operands.len();
                            operands.push(&relation.left);
                            idx
                        });
                    let right_idx = operands
                        .iter()
                        .position(|existing| *existing == &relation.right)
                        .unwrap_or_else(|| {
                            let idx = operands.len();
                            operands.push(&relation.right);
                            idx
                        });
                    if let Some(floor) = relation.minimum_difference() {
                        indexed_relations.push((left_idx, right_idx, floor));
                    }
                }
                let count = operands.len();
                Self {
                    operands,
                    indexed_relations,
                    same_cache: vec![None; count * count],
                }
            }
        }

        const MAXIMUM_TERMS: usize = 256;
        const MAXIMUM_COMPARISONS: usize = 65_536;

        pub(crate) struct ValueComparison<'relations> {
            relations: &'relations [Relation],
            differences: Option<DifferenceGraph<'relations>>,
            order_graph: Option<IndexedOrderGraph<'relations>>,
        }

        impl<'relations> ValueComparison<'relations> {
            pub(crate) fn new(relations: &'relations [Relation]) -> Self {
                Self {
                    relations,
                    differences: None,
                    order_graph: None,
                }
            }

            pub(crate) fn ordered_gaps(
                &mut self,
                value: &'relations Operand,
            ) -> Vec<(&'relations Operand, i64)> {
                if self.relations.is_empty() {
                    return vec![(value, 0)];
                }
                let relations = self.relations;
                let graph = self
                    .order_graph
                    .get_or_insert_with(|| IndexedOrderGraph::new(relations));
                let differences = &mut self.differences;
                let n = graph.operands.len();
                if n == 0 {
                    return vec![(value, 0)];
                }
                let value_idx = graph
                    .operands
                    .iter()
                    .position(|existing| *existing == value);
                let round_bound = if value_idx.is_some() { n } else { n + 1 };
                let start_idx = value_idx.unwrap_or(n);
                let mut dist: Vec<(usize, &'relations Operand, i64)> = vec![(start_idx, value, 0)];
                let mut dist_slot: Vec<Option<usize>> = vec![None; n];
                let mut checked_dist_len: Vec<usize> = vec![0; n];
                if let Some(idx) = value_idx {
                    dist_slot[idx] = Some(0);
                    checked_dist_len[idx] = 1;
                }
                let mut same_with_value: Vec<Option<bool>> = if value_idx.is_none() {
                    vec![None; n]
                } else {
                    Vec::new()
                };

                let resolve_slot = |op_idx: usize,
                                    dist: &[(usize, &'relations Operand, i64)],
                                    dist_slot: &mut [Option<usize>],
                                    checked_dist_len: &mut [usize],
                                    same_cache: &mut [Option<bool>],
                                    same_with_value: &mut [Option<bool>],
                                    differences: &mut Option<DifferenceGraph<'relations>>|
                 -> Option<usize> {
                    if let Some(slot) = dist_slot[op_idx] {
                        return Some(slot);
                    }
                    for (slot_idx, &(known_idx, _, _)) in
                        dist.iter().enumerate().skip(checked_dist_len[op_idx])
                    {
                        let is_same = if known_idx == op_idx {
                            true
                        } else if known_idx == n {
                            if let Some(cached) = same_with_value[op_idx] {
                                cached
                            } else {
                                let result = Self::same_value_with_differences(
                                    relations,
                                    differences,
                                    value,
                                    graph.operands[op_idx],
                                );
                                same_with_value[op_idx] = Some(result);
                                result
                            }
                        } else {
                            let cell = known_idx * n + op_idx;
                            if let Some(cached) = same_cache[cell] {
                                cached
                            } else {
                                let result = Self::same_value_with_differences(
                                    relations,
                                    differences,
                                    graph.operands[known_idx],
                                    graph.operands[op_idx],
                                );
                                same_cache[cell] = Some(result);
                                same_cache[op_idx * n + known_idx] = Some(result);
                                result
                            }
                        };
                        if is_same {
                            dist_slot[op_idx] = Some(slot_idx);
                            checked_dist_len[op_idx] = dist.len();
                            return Some(slot_idx);
                        }
                    }
                    checked_dist_len[op_idx] = dist.len();
                    None
                };

                for _ in 1..round_bound {
                    let mut improved = false;
                    for &(left_idx, right_idx, floor) in &graph.indexed_relations {
                        let Some(right_slot) = resolve_slot(
                            right_idx,
                            &dist,
                            &mut dist_slot,
                            &mut checked_dist_len,
                            &mut graph.same_cache,
                            &mut same_with_value,
                            differences,
                        ) else {
                            continue;
                        };
                        let Some(gap) = dist[right_slot].2.checked_add(floor) else {
                            continue;
                        };
                        match resolve_slot(
                            left_idx,
                            &dist,
                            &mut dist_slot,
                            &mut checked_dist_len,
                            &mut graph.same_cache,
                            &mut same_with_value,
                            differences,
                        ) {
                            Some(left_slot) if dist[left_slot].2 >= gap => {}
                            Some(left_slot) => {
                                dist[left_slot].2 = gap;
                                improved = true;
                            }
                            None => {
                                let new_slot = dist.len();
                                dist.push((left_idx, graph.operands[left_idx], gap));
                                dist_slot[left_idx] = Some(new_slot);
                                checked_dist_len[left_idx] = dist.len();
                                improved = true;
                            }
                        }
                    }
                    if !improved {
                        break;
                    }
                }
                dist.into_iter()
                    .map(|(_, operand, gap)| (operand, gap))
                    .collect()
            }

            pub(crate) fn same_value(&mut self, left: &Operand, right: &Operand) -> bool {
                Self::same_value_with_differences(
                    self.relations,
                    &mut self.differences,
                    left,
                    right,
                )
            }

            fn same_value_with_differences(
                relations: &'relations [Relation],
                differences: &mut Option<DifferenceGraph<'relations>>,
                left: &Operand,
                right: &Operand,
            ) -> bool {
                if Self::compare_with_differences(relations, differences, left, right, 0) {
                    return true;
                }
                let differences =
                    differences.get_or_insert_with(|| DifferenceGraph::new(relations));
                Equalities::prepare(relations, [left, right], differences)
                    .is_some_and(|equalities| equalities.same_value(left, right))
            }

            fn compare(&mut self, left: &Operand, right: &Operand, depth: usize) -> bool {
                Self::compare_with_differences(
                    self.relations,
                    &mut self.differences,
                    left,
                    right,
                    depth,
                )
            }

            fn compare_with_differences(
                relations: &'relations [Relation],
                differences: &mut Option<DifferenceGraph<'relations>>,
                left: &Operand,
                right: &Operand,
                depth: usize,
            ) -> bool {
                if left == right {
                    return true;
                }
                if depth >= 128 {
                    return false;
                }
                if same_constructor(left, right, |left, right| {
                    Self::compare_with_differences(relations, differences, left, right, depth + 1)
                }) {
                    return true;
                }
                differences
                    .get_or_insert_with(|| DifferenceGraph::new(relations))
                    .mutual_nonnegative_gap(left, right)
            }
        }

        fn same_constructor(
            left: &Operand,
            right: &Operand,
            mut child: impl FnMut(&Operand, &Operand) -> bool,
        ) -> bool {
            fn same_children(
                left: &[Operand],
                right: &[Operand],
                child: &mut impl FnMut(&Operand, &Operand) -> bool,
            ) -> bool {
                left.len() == right.len()
                    && left
                        .iter()
                        .zip(right)
                        .all(|(left, right)| child(left, right))
            }
            match (left, right) {
                (Operand::Place { root: left, .. }, Operand::Place { root: right, .. }) => {
                    left.is_valid() && left == right
                }
                (Operand::Integer(left, _), Operand::Integer(right, _)) => left
                    .value_bignum()
                    .zip(right.value_bignum())
                    .is_some_and(|(left, right)| left == right),
                (
                    Operand::Field {
                        receiver: left,
                        field: left_field,
                        primitive: left_primitive,
                        ..
                    },
                    Operand::Field {
                        receiver: right,
                        field: right_field,
                        primitive: right_primitive,
                        ..
                    },
                ) => {
                    left_field.is_valid()
                        && left_field == right_field
                        && left_primitive == right_primitive
                        && child(left, right)
                }
                (
                    Operand::Indexed {
                        collection: left_collection,
                        index: left_index,
                        primitive: left_primitive,
                    },
                    Operand::Indexed {
                        collection: right_collection,
                        index: right_index,
                        primitive: right_primitive,
                    },
                ) => {
                    left_primitive == right_primitive
                        && child(left_collection, right_collection)
                        && child(left_index, right_index)
                }
                (Operand::CollectionLength(left), Operand::CollectionLength(right)) => {
                    child(left, right)
                }
                (
                    Operand::Call {
                        target: left_target,
                        arguments: left,
                    },
                    Operand::Call {
                        target: right_target,
                        arguments: right,
                    },
                ) => {
                    left_target.is_valid()
                        && left_target == right_target
                        && same_children(left, right, &mut child)
                }
                (
                    Operand::Binary {
                        operator: left_operator,
                        primitive: left_primitive,
                        domain: left_domain,
                        operands: left,
                    },
                    Operand::Binary {
                        operator: right_operator,
                        primitive: right_primitive,
                        domain: right_domain,
                        operands: right,
                    },
                ) => {
                    left_operator == right_operator
                        && left_primitive == right_primitive
                        && left_domain == right_domain
                        && same_children(left, right, &mut child)
                }
                _ => false,
            }
        }

        pub(crate) struct EqualityQuery<'terms> {
            comparison: ValueComparison<'terms>,
            roots: [&'terms Operand; 2],
            prepared: PreparedEqualities<'terms>,
        }

        pub(crate) enum PreparedEqualities<'terms> {
            Unprepared,
            Unavailable,
            Known(Equalities<'terms>),
        }

        impl<'terms> EqualityQuery<'terms> {
            pub(crate) fn new(
                relations: &'terms [Relation],
                left: &'terms Operand,
                right: &'terms Operand,
            ) -> Self {
                Self {
                    comparison: ValueComparison::new(relations),
                    roots: [left, right],
                    prepared: PreparedEqualities::Unprepared,
                }
            }

            pub(crate) fn same_value(&mut self, left: &Operand, right: &Operand) -> bool {
                if self.comparison.compare(left, right, 0) {
                    return true;
                }
                if matches!(self.prepared, PreparedEqualities::Unprepared) {
                    let differences = self
                        .comparison
                        .differences
                        .get_or_insert_with(|| DifferenceGraph::new(self.comparison.relations));
                    self.prepared = match Equalities::prepare(
                        self.comparison.relations,
                        self.roots,
                        differences,
                    ) {
                        Some(equalities) => PreparedEqualities::Known(equalities),
                        None => PreparedEqualities::Unavailable,
                    };
                }
                match &self.prepared {
                    PreparedEqualities::Known(equalities) => equalities.same_value(left, right),
                    _ => false,
                }
            }
        }

        pub(crate) struct KnownTerm<'terms> {
            operand: &'terms Operand,
            children: Vec<usize>,
        }

        pub(crate) struct Equalities<'terms> {
            terms: Vec<KnownTerm<'terms>>,
            classes: Vec<usize>,
        }

        impl<'terms> Equalities<'terms> {
            fn prepare(
                relations: &'terms [Relation],
                roots: [&'terms Operand; 2],
                differences: &mut DifferenceGraph<'_>,
            ) -> Option<Self> {
                let mut terms = Vec::new();
                for root in roots {
                    collect_term(&mut terms, root, 0)?;
                }
                let mut endpoints = Vec::new();
                for relation in relations {
                    for operand in [&relation.left, &relation.right] {
                        let index = collect_term(&mut terms, operand, 0)?;
                        if !endpoints.contains(&index) {
                            endpoints.push(index);
                        }
                    }
                }
                let graph_indices = endpoints
                    .iter()
                    .map(|&endpoint| differences.operand_index(terms[endpoint].operand))
                    .collect::<Option<Vec<_>>>()?;
                let mut comparisons = MAXIMUM_COMPARISONS;
                let mut reachable = vec![Vec::new(); terms.len()];
                for (&source, &graph_source) in endpoints.iter().zip(&graph_indices) {
                    for (&destination, &graph_destination) in endpoints.iter().zip(&graph_indices) {
                        if !consume_comparison(&mut comparisons) {
                            return None;
                        }
                        if differences
                            .mutual_nonnegative_gap_indexed(graph_source, graph_destination)
                        {
                            reachable[source].push(destination);
                        }
                    }
                }
                let mut classes: Vec<_> = (0..terms.len()).collect();
                let mut seeded = false;
                for &left in &endpoints {
                    for &right in &reachable[left] {
                        if reachable[right].contains(&left)
                            && merge_classes(&mut classes, left, right).is_some()
                        {
                            seeded = true;
                        }
                    }
                }
                if !seeded {
                    return None;
                }
                let mut uses = vec![Vec::new(); terms.len()];
                for (parent, term) in terms.iter().enumerate() {
                    for &child in &term.children {
                        let parents = &mut uses[classes[child]];
                        if !parents.contains(&parent) {
                            parents.push(parent);
                        }
                    }
                }
                let mut pending: Vec<_> = (0..terms.len()).collect();
                let mut queued = vec![true; terms.len()];
                let mut cursor = 0;
                while cursor < pending.len() {
                    let left = pending[cursor];
                    cursor += 1;
                    queued[left] = false;
                    for right in 0..terms.len() {
                        if classes[left] == classes[right] {
                            continue;
                        }
                        if !consume_comparison(&mut comparisons) {
                            return None;
                        }
                        if !same_constructor(terms[left].operand, terms[right].operand, |_, _| true)
                            || !terms[left]
                                .children
                                .iter()
                                .zip(&terms[right].children)
                                .all(|(&left, &right)| classes[left] == classes[right])
                        {
                            continue;
                        }
                        let (retained, removed) = merge_classes(&mut classes, left, right)?;
                        for parent in std::mem::take(&mut uses[removed]) {
                            if !uses[retained].contains(&parent) {
                                uses[retained].push(parent);
                            }
                        }
                        for &parent in &uses[retained] {
                            if !queued[parent] {
                                queued[parent] = true;
                                pending.push(parent);
                            }
                        }
                    }
                }
                Some(Self { terms, classes })
            }

            fn same_value(&self, left: &Operand, right: &Operand) -> bool {
                term_index(&self.terms, left)
                    .zip(term_index(&self.terms, right))
                    .is_some_and(|(left, right)| self.classes[left] == self.classes[right])
            }
        }

        fn term_index(terms: &[KnownTerm<'_>], operand: &Operand) -> Option<usize> {
            terms.iter().position(|term| term.operand == operand)
        }

        fn collect_term<'terms>(
            terms: &mut Vec<KnownTerm<'terms>>,
            operand: &'terms Operand,
            depth: usize,
        ) -> Option<usize> {
            if let Some(index) = term_index(terms, operand) {
                return Some(index);
            }
            if terms.len() >= MAXIMUM_TERMS || depth >= 128 {
                return None;
            }
            let index = terms.len();
            terms.push(KnownTerm {
                operand,
                children: Vec::new(),
            });
            let children: Vec<&Operand> = match operand {
                Operand::Place { .. } | Operand::Integer(..) => Vec::new(),
                #[cfg(test)]
                Operand::CompletedCall { .. } => Vec::new(),
                Operand::Field { receiver, .. } | Operand::CollectionLength(receiver) => {
                    vec![receiver]
                }
                Operand::Indexed {
                    collection, index, ..
                } => vec![collection, index],
                Operand::Call { arguments, .. }
                | Operand::Binary {
                    operands: arguments,
                    ..
                } => arguments.iter().collect(),
            };
            for child in children {
                let child = collect_term(terms, child, depth + 1)?;
                terms[index].children.push(child);
            }
            Some(index)
        }

        fn merge_classes(
            classes: &mut [usize],
            left: usize,
            right: usize,
        ) -> Option<(usize, usize)> {
            let left = classes[left];
            let right = classes[right];
            if left == right {
                return None;
            }
            let (retained, removed) = (left.min(right), left.max(right));
            for class in classes {
                if *class == removed {
                    *class = retained;
                }
            }
            Some((retained, removed))
        }

        fn consume_comparison(remaining: &mut usize) -> bool {
            if *remaining == 0 {
                return false;
            }
            *remaining -= 1;
            true
        }
    }
    pub(crate) use congruence::ValueComparison;
    pub(crate) mod match_joins {
        use super::super::dispatch_arm_environments;
        use super::{ExpressionHandle, ExpressionNode, Machine, State, ValueEnvironment};

        pub(crate) fn match_subtract_floor(
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
            environment: &ValueEnvironment,
            left: ExpressionHandle,
            right: ExpressionHandle,
            depth: usize,
        ) -> Option<i64> {
            let ExpressionNode::Match(dispatch) = program.expression_table.expression(right) else {
                return None;
            };
            let arms = program.expression_table.match_arms(dispatch.arms);
            if arms.is_empty() {
                return None;
            }
            let arm_environments = dispatch_arm_environments(
                program,
                machine,
                Some(state),
                right,
                dispatch,
                environment,
            );
            if arm_environments.len() != arms.len() {
                return None;
            }
            let mut floor = None;
            for (arm, arm_environment) in arms.iter().zip(&arm_environments) {
                let arm_floor = super::subtract_floor_limited(
                    program,
                    machine,
                    Some(state),
                    arm_environment,
                    left,
                    arm.value,
                    depth + 1,
                )?;
                floor = Some(floor.map_or(arm_floor, |existing: i64| existing.min(arm_floor)));
            }
            floor
        }
    }
    pub(crate) mod requirements {
        use crate::frozen_program::expression_table;
        use diagnostics::Diagnostic;
        use typed_trees::domain::ProofFact;
        use typed_trees::expression::ExpressionNode;
        use typed_trees::signature::SignatureContractKind;

        pub fn validate_ordered_requirement_call_totality(
            program: &dyn crate::CheckingInput,
            operational: &flow_effects::OperationalPlan,
            service_reaches: &flow_effects::ServiceReachInferencePlan,
            termination: &checked_trees::TerminationFacts,
            diagnostics: &mut Vec<Diagnostic>,
        ) {
            let mut pending = Vec::new();
            for machine in program.machines() {
                for contract in program
                    .machine_contracts(machine)
                    .iter()
                    .chain(
                        program
                            .machine_states(machine)
                            .iter()
                            .flat_map(|state| program.state_contracts(state)),
                    )
                    .filter(|contract| contract.kind == SignatureContractKind::Requires)
                {
                    for fact in program.proof_facts.span_or_empty(contract.facts) {
                        match fact {
                            ProofFact::Expression(expression) => pending.push(*expression),
                            ProofFact::Membership(membership) => pending.push(membership.value),
                            ProofFact::Proposition(application) => pending.extend_from_slice(
                                expression_table(program).expression_handles(application.arguments),
                            ),
                        }
                    }
                }
            }
            crate::queries::expression_traversal::visit_pre_order(program, pending, |_, node| {
                if let ExpressionNode::Call(call) = node
                    && let Ok((machine, _)) =
                        crate::machine_calls::denotational_calls::normal_return_call_candidate(
                            program,
                            call,
                            operational,
                            service_reaches,
                        )
                {
                    let mut summaries = termination
                        .machines
                        .iter()
                        .filter(|fact| fact.machine == machine.symbol);
                    let unconditional = summaries.next().is_some_and(|fact| {
                        matches!(&fact.plan.checked_summary,
                        language_semantics::TerminationGuarantee::Terminates { premises }
                            if premises.is_empty())
                    }) && summaries.next().is_none();
                    if !unconditional {
                        diagnostics.push(Diagnostic::error(format!(
                        "ordered requirement call `{}` is not denotational: the exact selected machine is not unconditionally terminating",
                        call.target,
                    )));
                    } else if !crate::machine_calls::denotational_calls::has_no_crash_routes(
                        program,
                        machine.symbol,
                        operational,
                    ) {
                        diagnostics.push(Diagnostic::error(format!(
                        "ordered requirement call `{}` is not denotational: the selected call closure has a crash route",
                        call.target,
                    )));
                    }
                }
                false
            });
        }
    }
    pub(crate) mod storage {
        use super::Operand;
        use crate::{AssignmentStorageOrigins, LocalWriteSource};
        use facts::PlaceSegment;
        use symbols::SymbolHandle;

        #[cfg(test)]
        mod tests {
            use super::*;

            #[test]
            fn unknown_reference_read_cannot_use_inline_field_disjointness() {
                let root = SymbolHandle::from_parts(1, 1);
                let changed = SymbolHandle::from_parts(2, 1);
                let sibling = SymbolHandle::from_parts(3, 1);
                let observation = |field, name: &str| Operand::Field {
                    receiver: Box::new(Operand::Place {
                        root,
                        path: "record".into(),
                    }),
                    field,
                    name: name.into(),
                    primitive: None,
                };
                let changed_value = observation(changed, "changed");
                let sibling_value = observation(sibling, "sibling");
                let written = ["record".to_owned()];
                let storage = AssignmentStorageOrigins {
                    destinations: vec![LocalWriteSource {
                        invocation_output: None,
                        invocation_result: None,
                        is_image_storage: false,
                        recasts: Vec::new(),
                        representation: None,
                        path: "record.changed".into(),
                        collection_coarse: false,
                        root,
                        segments: vec![PlaceSegment::Field { symbol: changed }],
                    }],
                    references: None,
                };
                assert!(
                    !changed_value.survives_assignment(&written, Some(&storage), &|_| Some(false))
                );
                assert!(
                    !sibling_value.survives_assignment(&written, Some(&storage), &|_| Some(false))
                );
                assert!(!changed_value.survives_assignment(&written, Some(&storage), &|_| None));
                assert!(sibling_value.survives_assignment(&written, Some(&storage), &|_| None));
            }
        }

        #[derive(Clone)]
        pub(crate) enum ReadSegment {
            Field(SymbolHandle),
            Case(SymbolHandle),
            Element(Option<usize>),
            Length,
        }

        impl Operand {
            pub(crate) fn has_stable_descriptor(
                &self,
                program: &dyn crate::CheckingInput,
                state: &typed_trees::state::State,
            ) -> bool {
                fn coordinate(
                    value: &Operand,
                    fields: &mut Vec<PlaceSegment>,
                ) -> Option<SymbolHandle> {
                    match value {
                        Operand::Place { root, .. } => Some(*root),
                        Operand::Field {
                            receiver, field, ..
                        } => {
                            let root = coordinate(receiver, fields)?;
                            fields.push(PlaceSegment::Field { symbol: *field });
                            Some(root)
                        }
                        _ => None,
                    }
                }
                let mut fields = Vec::new();
                coordinate(self, &mut fields).is_some_and(|root| {
                    crate::stable_slice_descriptor_place(program, state, root, &fields).is_some()
                })
            }

            pub(crate) fn survives_assignment(
                &self,
                written: &[String],
                storage: Option<&AssignmentStorageOrigins>,
                reference_read: &impl Fn(&Operand) -> Option<bool>,
            ) -> bool {
                if let Some(preserved) = reference_read(self) {
                    return preserved && self.selectors_survive(written, storage, reference_read);
                }
                match self {
                    Self::Integer(..) => true,
                    #[cfg(test)]
                    Self::CompletedCall { .. } => false,
                    Self::Call { arguments, .. }
                    | Self::Binary {
                        operands: arguments,
                        ..
                    } => arguments.iter().all(|argument| {
                        argument.survives_assignment(written, storage, reference_read)
                    }),
                    _ => {
                        if self.survives(written) {
                            return true;
                        }
                        let Some(storage) =
                            storage.filter(|storage| !storage.destinations.is_empty())
                        else {
                            return false;
                        };
                        let mut segments = Vec::new();
                        let Some(root) = self.read_coordinate(&mut segments) else {
                            return false;
                        };
                        if !self.selectors_survive(written, Some(storage), reference_read) {
                            return false;
                        }
                        storage.destinations.iter().all(|destination| {
                            compatible_destination(root, destination)
                                && disjoint(&segments, &destination.segments)
                        })
                    }
                }
            }

            pub(crate) fn read_coordinate(
                &self,
                segments: &mut Vec<ReadSegment>,
            ) -> Option<SymbolHandle> {
                match self {
                    Self::Place { root, .. } => Some(*root),
                    Self::Field {
                        receiver, field, ..
                    } => {
                        let root = receiver.read_coordinate(segments)?;
                        segments.push(ReadSegment::Field(*field));
                        Some(root)
                    }
                    Self::Indexed {
                        collection, index, ..
                    } => {
                        let root = collection.read_coordinate(segments)?;
                        let selected = match &**index {
                            Self::Integer(value, _) => value
                                .value_u64()
                                .and_then(|value| usize::try_from(value).ok()),
                            _ => None,
                        };
                        segments.push(ReadSegment::Element(selected));
                        Some(root)
                    }
                    Self::CollectionLength(collection) => {
                        let root = collection.read_coordinate(segments)?;
                        segments.push(ReadSegment::Length);
                        Some(root)
                    }
                    _ => None,
                }
            }

            fn selectors_survive(
                &self,
                written: &[String],
                storage: Option<&AssignmentStorageOrigins>,
                reference_read: &impl Fn(&Operand) -> Option<bool>,
            ) -> bool {
                match self {
                    Self::Place { .. } => true,
                    Self::Field { receiver, .. } => {
                        receiver.selectors_survive(written, storage, reference_read)
                    }
                    Self::CollectionLength(collection) => {
                        collection.selectors_survive(written, storage, reference_read)
                    }
                    Self::Indexed {
                        collection, index, ..
                    } => {
                        collection.selectors_survive(written, storage, reference_read)
                            && index.survives_assignment(written, storage, reference_read)
                    }
                    _ => false,
                }
            }
        }

        pub(crate) fn compatible_destination(
            root: SymbolHandle,
            destination: &LocalWriteSource,
        ) -> bool {
            destination.root == root
                && root.is_valid()
                && destination.recasts.is_empty()
                && destination.representation.is_none()
        }

        pub(crate) fn disjoint(read: &[ReadSegment], written: &[PlaceSegment]) -> bool {
            for (read, written) in read.iter().zip(written) {
                match (read, written) {
                    (ReadSegment::Case(read), PlaceSegment::Case { variant })
                        if read == variant => {}
                    (ReadSegment::Field(read), PlaceSegment::Field { symbol: written })
                        if read.is_valid() && written.is_valid() =>
                    {
                        if read != written {
                            return true;
                        }
                    }
                    (
                        ReadSegment::Element(Some(read)),
                        PlaceSegment::FixedIndex { index: written },
                    ) if read != written => {
                        return true;
                    }
                    (
                        ReadSegment::Element(_),
                        PlaceSegment::Index { .. } | PlaceSegment::FixedIndex { .. },
                    ) => {}
                    (
                        ReadSegment::Length,
                        PlaceSegment::Index { .. } | PlaceSegment::FixedIndex { .. },
                    ) => {
                        return true;
                    }
                    _ => return false,
                }
            }
            false
        }

        pub(crate) fn survives_delivery(
            program: &dyn crate::CheckingInput,
            state: &typed_trees::state::State,
            operand: &Operand,
            result: &Operand,
            written: Option<&[String]>,
        ) -> bool {
            let preserved = written.map_or_else(
                || operand.is_immutable_snapshot(program, state),
                |written| operand.survives_storage_writes(program, Some(state), written),
            );
            if operand == result || preserved {
                return true;
            }
            let survives =
                |operand: &Operand| survives_delivery(program, state, operand, result, written);
            match operand {
                Operand::Field { receiver, .. } => survives(receiver),
                Operand::CollectionLength(collection) => survives(collection),
                Operand::Indexed {
                    collection, index, ..
                } => survives(collection) && survives(index),
                Operand::Binary { operands, .. } => operands.iter().all(survives),
                _ => false,
            }
        }
    }
    pub(crate) mod transport {
        use super::{
            Operand, Relation, RelationConstraint, ValueComparison, ordered_gaps_with_comparison,
        };

        pub(crate) fn rebind_relations(
            relations: &[Relation],
            bindings: &[(Operand, Operand)],
        ) -> Vec<Relation> {
            if relations.is_empty() || bindings.is_empty() {
                return Vec::new();
            }
            let bindings = bind_equal_observations(relations, bindings);
            let mut rebound = Vec::new();
            for relation in relations
                .iter()
                .flat_map(|relation| relation.rebound(&bindings))
            {
                if !rebound.contains(&relation) {
                    rebound.push(relation);
                }
            }
            let mut operands = Vec::new();
            for relation in relations {
                for operand in [&relation.left, &relation.right] {
                    if !operands.contains(&operand) {
                        operands.push(operand);
                    }
                }
            }
            let delivered = operands
                .iter()
                .map(|operand| operand.rebound(&bindings))
                .collect::<Vec<_>>();
            if delivered.iter().all(|operands| !operands.is_empty()) {
                return rebound;
            }
            let mut comparison = ValueComparison::new(relations);
            for (operand, targets) in operands.iter().zip(&delivered) {
                if targets.is_empty() {
                    continue;
                }
                for (ceiling, floor) in
                    ordered_gaps_with_comparison(relations, operand, &mut comparison)
                {
                    if ceiling == *operand {
                        continue;
                    }
                    let Some(left_targets) = operands
                        .iter()
                        .position(|existing| *existing == ceiling)
                        .map(|idx| &delivered[idx])
                    else {
                        continue;
                    };
                    if left_targets.is_empty() {
                        continue;
                    }
                    for left in left_targets {
                        for right in targets {
                            let relation = Relation {
                                left: left.clone(),
                                right: right.clone(),
                                constraint: RelationConstraint::MinimumDifference(floor),
                            };
                            if !rebound.contains(&relation) {
                                rebound.push(relation);
                            }
                        }
                    }
                }
            }
            rebound
        }

        fn bind_equal_observations(
            relations: &[Relation],
            bindings: &[(Operand, Operand)],
        ) -> Vec<(Operand, Operand)> {
            let mut equalities = relations
                .iter()
                .filter(|relation| {
                    relation.constraint == RelationConstraint::MinimumDifference(0)
                        && relations.iter().any(|opposite| {
                            opposite.constraint == RelationConstraint::MinimumDifference(0)
                                && opposite.left == relation.right
                                && opposite.right == relation.left
                        })
                })
                .collect::<Vec<_>>();
            if equalities.is_empty() {
                return bindings.to_vec();
            }
            let mut bindings = bindings.to_vec();
            loop {
                let previous_count = bindings.len();
                equalities.retain(|equality| {
                    if !equality.left.rebound(&bindings).is_empty() {
                        return false;
                    }
                    if let Some(value) = equality.right.rebound(&bindings).into_iter().next() {
                        bindings.push((equality.left.clone(), value));
                        return false;
                    }
                    true
                });
                if bindings.len() == previous_count || equalities.is_empty() {
                    return bindings;
                }
            }
        }
    }
    use match_joins::match_subtract_floor;
    pub use requirements::validate_ordered_requirement_call_totality;
    pub(crate) use storage::survives_delivery;
    pub(crate) use transport::rebind_relations;

    #[derive(Clone, Debug, PartialEq)]
    pub(crate) enum Operand {
        Place {
            root: SymbolHandle,
            path: String,
        },
        Field {
            receiver: Box<Operand>,
            field: SymbolHandle,
            name: String,
            primitive: Option<PrimitiveType>,
        },
        Integer(numerics::literals::IntegerLiteral, Option<IntegerLanding>),
        Call {
            target: SymbolHandle,
            arguments: Vec<Operand>,
        },
        #[cfg(test)]
        CompletedCall {
            target: SymbolHandle,
            occurrence: ExpressionHandle,
        },
        CollectionLength(Box<Operand>),
        Indexed {
            collection: Box<Operand>,
            index: Box<Operand>,
            primitive: Option<PrimitiveType>,
        },
        Binary {
            operator: BinaryOperator,
            primitive: Option<PrimitiveType>,
            domain: ArithmeticDomain,
            operands: Vec<Operand>,
        },
    }

    #[derive(Clone, Debug)]
    pub(crate) struct Relation {
        pub(crate) left: Operand,
        pub(crate) right: Operand,
        pub(crate) constraint: RelationConstraint,
    }

    impl PartialEq for Relation {
        fn eq(&self, other: &Self) -> bool {
            self.constraint == other.constraint
                && ((self.left == other.left && self.right == other.right)
                    || (self.constraint == RelationConstraint::Unequal
                        && self.left == other.right
                        && self.right == other.left))
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq)]
    pub(crate) enum RelationConstraint {
        MinimumDifference(i64),
        Unequal,
    }

    impl Operand {
        pub(crate) fn parameter(parameter: &typed_trees::signature::StateParameter) -> Self {
            Self::Place {
                root: parameter.symbol,
                path: parameter.name.as_str().to_owned(),
            }
        }

        pub(crate) fn static_path(&self) -> Option<String> {
            match self {
                Self::Place { path, .. } => Some(path.clone()),
                Self::Field { receiver, name, .. } => {
                    Some(format!("{}.{}", receiver.static_path()?, name))
                }
                _ => None,
            }
        }

        pub(crate) fn survives(&self, written: &[String]) -> bool {
            self.survives_paths(written)
        }

        pub(crate) fn is_immutable_snapshot(
            &self,
            program: &dyn CheckingInput,
            state: &State,
        ) -> bool {
            match self {
                Self::Integer(..) => true,
                Self::Place { root, .. } => {
                    if !root.is_valid() {
                        return false;
                    }
                    let parameters =
                        program
                            .state_parameters(state)
                            .iter()
                            .filter_map(|parameter| {
                                (parameter.symbol == *root)
                                    .then_some((!parameter.is_mutable, parameter.type_reference))
                            });
                    let locals = program
                        .statement_table
                        .statements(state.statement_nodes)
                        .iter()
                        .filter_map(|statement| {
                            let local = statement.as_local_data()?;
                            (local.symbol == *root)
                                .then_some((!local.is_mutable, local.type_reference))
                        });
                    let static_value =
                        program
                            .machine_holding_state(state.symbol)
                            .is_some_and(|machine| {
                                program
                                    .machine_type_parameters(machine)
                                    .iter()
                                    .any(|parameter| {
                                        parameter.symbol == *root
                                            && match parameter.kind {
                                                TypeParameterKind::Value { type_reference }
                                                | TypeParameterKind::Const { type_reference } => {
                                                    program
                                                        .primitive_type_reference(type_reference)
                                                        .is_some_and(|primitive| {
                                                            primitive.is_fixed_integer()
                                                        })
                                                }
                                                _ => false,
                                            }
                                    })
                            });
                    if static_value {
                        return true;
                    }
                    let mut declarations = parameters.chain(locals);
                    declarations.next().is_some_and(|(immutable, reference)| {
                        immutable && program.primitive_type_reference(reference).is_some()
                    }) && declarations.next().is_none()
                }
                Self::Call { arguments, .. } => arguments
                    .iter()
                    .all(|value| value.is_immutable_snapshot(program, state)),
                #[cfg(test)]
                Self::CompletedCall { .. } => false,
                Self::Binary { operands, .. } => operands
                    .iter()
                    .all(|value| value.is_immutable_snapshot(program, state)),
                Self::CollectionLength(collection) => {
                    collection.has_stable_descriptor(program, state)
                }
                Self::Indexed { .. } | Self::Field { .. } => false,
            }
        }

        pub(crate) fn survives_storage_writes(
            &self,
            program: &dyn CheckingInput,
            state: Option<&State>,
            written: &[String],
        ) -> bool {
            self.survives_storage_writes_by(
                program,
                state,
                &|path| written.iter().any(|write| place_paths_overlap(path, write)),
                written.is_empty(),
            )
        }

        pub(super) fn survives_storage_writes_by(
            &self,
            program: &dyn CheckingInput,
            state: Option<&State>,
            overlaps: &impl Fn(&str) -> bool,
            empty: bool,
        ) -> bool {
            // A call's conservative storage frame cannot retarget an immutable
            // copied scalar or private descriptor observation. Their declaration-
            // checked snapshot identity supplies this distinction, never spelling.
            if self.survives_path_query(overlaps, empty)
                || state.is_some_and(|state| self.is_immutable_snapshot(program, state))
            {
                return true;
            }
            match self {
                Self::Binary { operands, .. } => operands
                    .iter()
                    .all(|value| value.survives_storage_writes_by(program, state, overlaps, empty)),
                Self::Call { arguments, .. } => arguments
                    .iter()
                    .all(|value| value.survives_storage_writes_by(program, state, overlaps, empty)),
                _ => false,
            }
        }

        fn survives_paths(&self, written: &[String]) -> bool {
            self.survives_path_query(
                &|path| written.iter().any(|write| place_paths_overlap(path, write)),
                written.is_empty(),
            )
        }

        fn survives_path_query(&self, overlaps: &impl Fn(&str) -> bool, empty: bool) -> bool {
            if empty {
                return true;
            }
            self.survives_paths_by(overlaps)
        }

        fn survives_paths_by(&self, overlaps: &impl Fn(&str) -> bool) -> bool {
            match self {
                Self::Place { path, .. } => !overlaps(path),
                Self::Field { receiver, .. } => self.static_path().map_or_else(
                    || receiver.survives_paths_by(overlaps),
                    |path| !overlaps(&path),
                ),
                Self::Integer(..) => true,
                Self::Call { arguments, .. } => arguments
                    .iter()
                    .all(|value| value.survives_paths_by(overlaps)),
                #[cfg(test)]
                Self::CompletedCall { .. } => false,
                Self::CollectionLength(collection) => collection.survives_paths_by(overlaps),
                Self::Indexed {
                    collection, index, ..
                } => collection.survives_paths_by(overlaps) && index.survives_paths_by(overlaps),
                Self::Binary { operands, .. } => operands
                    .iter()
                    .all(|value| value.survives_paths_by(overlaps)),
            }
        }

        pub(crate) fn rebound(&self, bindings: &[(Operand, Operand)]) -> Vec<Self> {
            let direct = bindings
                .iter()
                .filter(|(source, _)| source == self)
                .map(|(_, target)| target.clone())
                .collect::<Vec<_>>();
            if !direct.is_empty() {
                return direct;
            }
            match self {
                Self::Integer(..) => vec![self.clone()],
                Self::CollectionLength(collection) => collection
                    .rebound(bindings)
                    .into_iter()
                    .map(|collection| Self::CollectionLength(Box::new(collection)))
                    .collect(),
                Self::Indexed {
                    collection,
                    index,
                    primitive,
                } => {
                    let collections = collection.rebound(bindings);
                    let indices = index.rebound(bindings);
                    collections
                        .into_iter()
                        .flat_map(|collection| {
                            indices.iter().map(move |index| Self::Indexed {
                                collection: Box::new(collection.clone()),
                                index: Box::new(index.clone()),
                                primitive: *primitive,
                            })
                        })
                        .collect()
                }
                Self::Place { .. } => Vec::new(),
                Self::Field {
                    receiver,
                    field,
                    name,
                    primitive,
                } => receiver
                    .rebound(bindings)
                    .into_iter()
                    .map(|receiver| Self::Field {
                        receiver: Box::new(receiver),
                        field: *field,
                        name: name.clone(),
                        primitive: *primitive,
                    })
                    .collect(),
                #[cfg(test)]
                Self::CompletedCall { .. } => Vec::new(),
                Self::Call {
                    target, arguments, ..
                } => {
                    let mut combinations = vec![Vec::new()];
                    for argument in arguments {
                        let alternatives = argument.rebound(bindings);
                        combinations = combinations
                            .into_iter()
                            .flat_map(|prefix| {
                                alternatives.iter().map(move |argument| {
                                    let mut values = prefix.clone();
                                    values.push(argument.clone());
                                    values
                                })
                            })
                            .collect();
                    }
                    combinations
                        .into_iter()
                        .map(|arguments| Self::Call {
                            target: *target,
                            arguments,
                        })
                        .collect()
                }
                Self::Binary {
                    operator,
                    primitive,
                    domain,
                    operands,
                } => {
                    let [left, right] = operands.as_slice() else {
                        return Vec::new();
                    };
                    left.rebound(bindings)
                        .into_iter()
                        .flat_map(|left| {
                            right
                                .rebound(bindings)
                                .into_iter()
                                .map(move |right| Self::Binary {
                                    operator: *operator,
                                    primitive: *primitive,
                                    domain: *domain,
                                    operands: vec![left.clone(), right],
                                })
                        })
                        .collect()
                }
            }
        }
    }

    impl Relation {
        pub(crate) fn minimum_difference(&self) -> Option<i64> {
            match self.constraint {
                RelationConstraint::MinimumDifference(floor) => Some(floor),
                RelationConstraint::Unequal => None,
            }
        }

        pub(crate) fn rebound(&self, bindings: &[(Operand, Operand)]) -> Vec<Self> {
            self.left
                .rebound(bindings)
                .into_iter()
                .flat_map(|left| {
                    self.right
                        .rebound(bindings)
                        .into_iter()
                        .map(move |right| Self {
                            left: left.clone(),
                            right,
                            constraint: self.constraint,
                        })
                })
                .collect()
        }
    }

    pub(crate) fn operand(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        frames: Option<&crate::CallFrameResolver<'_>>,
    ) -> Option<Operand> {
        build_operand(program, machine, state, expression, 0, frames)
    }

    pub(crate) fn observation_survives_writes(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        written: Option<&[String]>,
    ) -> bool {
        operand(program, machine, state, expression, None).is_some_and(|observed| {
            written.map_or_else(
                || observed.is_immutable_snapshot(program, state),
                |written| observed.survives_storage_writes(program, Some(state), written),
            )
        })
    }

    pub(crate) fn collection_length_operand(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        collection: ExpressionHandle,
        observed_collection: Operand,
    ) -> Option<Operand> {
        if let Some(extent) = crate::value_custody::places::declared_collection_extent(
            program,
            machine,
            Some(state),
            collection,
        ) {
            let literal = numerics::literals::IntegerLiteral::from_parts(
                false,
                numerics::literals::IntegerRadix::Decimal,
                &extent.to_string(),
            )
            .ok()?;
            Some(Operand::Integer(literal, None))
        } else {
            Some(Operand::CollectionLength(Box::new(observed_collection)))
        }
    }

    fn build_operand(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
        depth: usize,
        frames: Option<&crate::CallFrameResolver<'_>>,
    ) -> Option<Operand> {
        if !expression.is_valid() || depth >= 128 {
            return None;
        }
        if let Some(source) = crate::value_custody::places::whole_collection_view_source(
            program,
            machine,
            Some(state),
            expression,
        ) {
            return build_operand(program, machine, state, source, depth + 1, frames);
        }
        if let Some(collection) =
            collection_length_receiver(program, machine, Some(state), expression)
        {
            let observed_collection =
                build_operand(program, machine, state, collection, depth + 1, frames)?;
            return collection_length_operand(
                program,
                machine,
                state,
                collection,
                observed_collection,
            );
        }
        if let Some((_, source)) = crate::integer_embedding_argument(program, expression) {
            return build_operand(program, machine, state, source, depth + 1, frames);
        }
        match program.expression_table.expression(expression) {
            ExpressionNode::Borrow(borrow) => {
                build_operand(program, machine, state, borrow.target, depth + 1, frames)
            }
            ExpressionNode::SavedSubject(_) => {
                captured_references::operand(program, machine, state, expression, frames)
            }
            ExpressionNode::Integer(literal) => {
                Some(Operand::Integer(literal.clone(), literal.landing()))
            }
            ExpressionNode::Name(path) => {
                if !path.symbol.is_valid() || path.symbol != path.head_symbol {
                    return None;
                }
                if crate::expression_result_type_reference(program, machine, state, expression)
                    .and_then(|reference| crate::reference_shell(program, reference))
                    .is_some()
                    && let Some(captured) =
                        captured_references::operand(program, machine, state, expression, frames)
                {
                    return Some(captured);
                }
                let parameters = program.state_parameters(state);
                let local = program
                    .state_local_declaration(state, path.symbol)
                    .is_some();
                let parameter = parameters
                    .iter()
                    .any(|parameter| parameter.symbol == path.symbol);
                let value_binder =
                    program
                        .machine_type_parameters(machine)
                        .iter()
                        .any(|parameter| {
                            parameter.symbol == path.symbol
                                && matches!(
                                    parameter.kind,
                                    TypeParameterKind::Value { .. }
                                        | TypeParameterKind::Const { .. }
                                )
                        });
                if !local && !parameter && !value_binder {
                    return None;
                }
                Some(Operand::Place {
                    root: path.symbol,
                    path: place_path(program, expression)?,
                })
            }
            ExpressionNode::Member(member) => {
                let receiver =
                    build_operand(program, machine, state, member.receiver, depth + 1, frames)?;
                let field = if member.case_variant.is_some() {
                    crate::value_custody::places::declared_case_projection_field(
                        program,
                        machine,
                        Some(state),
                        expression,
                    )?
                    .symbol
                } else if matches!(&receiver, Operand::Place { root, .. } if *root == machine.symbol)
                {
                    crate::exact_self_field(program, machine, expression)?.symbol
                } else {
                    crate::value_custody::places::declared_member_field_symbol(
                        program,
                        machine,
                        Some(state),
                        expression,
                    )?
                };
                let reference = declared_place_type_raw(program, machine, Some(state), expression)?;
                if !field.is_valid() {
                    return None;
                }
                Some(Operand::Field {
                    receiver: Box::new(receiver),
                    field,
                    name: member.member.as_str().to_owned(),
                    primitive: program.primitive_type_reference(reference),
                })
            }
            ExpressionNode::Call(call) => {
                crate::machine_calls::denotational_calls::plain_value_call_target(program, call)?;
                let plans = crate::operand_call_plans(program, frames);
                let (_, entry) =
                    crate::machine_calls::denotational_calls::normal_return_call_candidate(
                        program, call, &plans.0, &plans.1,
                    )
                    .ok()?;
                let arguments = program.expression_table.expression_handles(call.arguments);
                if arguments.len() != program.state_parameters(entry).len() {
                    return None;
                }
                Some(Operand::Call {
                    target: call.target_symbol,
                    arguments: arguments
                        .iter()
                        .map(|argument| {
                            build_operand(program, machine, state, *argument, depth + 1, frames)
                        })
                        .collect::<Option<Vec<_>>>()?,
                })
            }
            ExpressionNode::Indexed(indexed)
                if crate::place_has_builtin_coordinates(
                    program,
                    machine,
                    Some(state),
                    expression,
                ) && !matches!(
                    program.expression_table.expression(indexed.index),
                    ExpressionNode::Range(_)
                ) =>
            {
                let index =
                    build_operand(program, machine, state, indexed.index, depth + 1, frames)?;
                let primitive = declared_place_type_raw(program, machine, Some(state), expression)
                    .and_then(|reference| program.primitive_type_reference(reference));
                indexed_operand(
                    program,
                    machine,
                    state,
                    indexed.collection,
                    index,
                    primitive,
                    frames,
                    depth + 1,
                )
            }
            // Qualifying a value `in Trapping` changes which operations act
            // on it later and leaves the value itself alone, so the cast
            // observes its source like an Exact one. Wrapping and
            // Saturating casts stay unobserved: nothing below reads their
            // operations as mathematics.
            ExpressionNode::Cast(cast)
                if !cast.form.is_recast()
                    && cast.semantic_domain.is_empty()
                    && matches!(
                        cast.domain,
                        ArithmeticDomain::Exact | ArithmeticDomain::Trapping
                    ) =>
            {
                let source = integer_meaning(program, machine, state, cast.value)?.0;
                let target = program.primitive_type_reference(cast.target_type)?;
                if source == PrimitiveType::Addr
                    || target == PrimitiveType::Addr
                    || primitive_range(target).is_none()
                {
                    return None;
                }
                build_operand(program, machine, state, cast.value, depth + 1, frames)
            }
            ExpressionNode::Binary(binary)
                if crate::has_builtin_bound_expression_meaning(
                    program,
                    machine,
                    Some(state),
                    expression,
                ) =>
            {
                let (primitive, domain) = if let Some((primitive, domain)) =
                    integer_meaning(program, machine, state, expression)
                {
                    (Some(primitive), domain)
                } else {
                    let result = crate::expression_result_type_reference(
                        program, machine, state, expression,
                    )?;
                    let proof_int =
                        crate::proof_contracts::proof_embeddings::proof_int_type_reference(
                            program,
                        )?;
                    let identity = program.normalized_type_identity(proof_int);
                    if !identity.is_valid() || program.normalized_type_identity(result) != identity
                    {
                        return None;
                    }
                    (None, ArithmeticDomain::Exact)
                };
                Some(Operand::Binary {
                    operator: binary.operator,
                    primitive,
                    domain,
                    operands: vec![
                        build_operand(program, machine, state, binary.left, depth + 1, frames)?,
                        build_operand(program, machine, state, binary.right, depth + 1, frames)?,
                    ],
                })
            }
            ExpressionNode::Match(dispatch) => {
                let mut shared_operand = None;
                for arm in program.expression_table.match_arms(dispatch.arms) {
                    let arm_operand =
                        build_operand(program, machine, state, arm.value, depth + 1, frames)?;
                    match &shared_operand {
                        None => shared_operand = Some(arm_operand),
                        Some(current) if current == &arm_operand => {}
                        Some(_) => return None,
                    }
                }
                shared_operand
            }
            _ => None,
        }
    }

    fn integer_meaning(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<(PrimitiveType, ArithmeticDomain)> {
        let memo = crate::frozen_program::frozen_program_memos(program).and_then(|memos| {
            crate::proof_contracts::bound_expression_meaning::meaning_key(
                program,
                machine,
                Some(state),
                expression,
            )
            .map(|key| (memos, key))
        });
        if let Some((memos, key)) = memo
            && let Ok(meanings) = memos.ordered_integer_meanings.lock()
            && let Some(&cached) = meanings.get(&key)
        {
            return cached;
        }
        let computed = (|| {
            if collection_length_receiver(program, machine, Some(state), expression).is_some() {
                return Some((PrimitiveType::U64, ArithmeticDomain::Exact));
            }
            let analysis = analyze_meaning(
                program,
                machine,
                Some(state),
                expression,
                "ordered operand type",
            )
            .value;
            let declared_call = match program.expression_table.expression(expression) {
                ExpressionNode::Call(call) => super::return_ranges::call_return_type(program, call),
                _ => None,
            };
            let primitive = analysis.primitive.or_else(|| {
                declared_call.and_then(|reference| program.primitive_type_reference(reference))
            })?;
            (primitive != PrimitiveType::Addr && primitive_range(primitive).is_some()).then_some((
                primitive,
                analysis
                    .domain
                    .or_else(|| {
                        declared_call.map(|reference| {
                            program.arithmetic_domain_for_type_reference(reference)
                        })
                    })
                    .unwrap_or(ArithmeticDomain::Exact),
            ))
        })();
        if let Some((memos, key)) = memo
            && let Ok(mut meanings) = memos.ordered_integer_meanings.lock()
        {
            meanings.insert(key, computed);
        }
        computed
    }

    pub(crate) fn indexed_operand(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        collection: ExpressionHandle,
        index: Operand,
        primitive: Option<PrimitiveType>,
        frames: Option<&crate::CallFrameResolver<'_>>,
        depth: usize,
    ) -> Option<Operand> {
        if depth >= 128
            || !crate::place_has_builtin_coordinates(program, machine, Some(state), collection)
        {
            return None;
        }
        if let ExpressionNode::Borrow(borrow) = program.expression_table.expression(collection) {
            return indexed_operand(
                program,
                machine,
                state,
                borrow.target,
                index,
                primitive,
                frames,
                depth + 1,
            );
        }
        if let Some(window) = crate::value_custody::places::subslice_expression(program, collection)
        {
            let window = program.expression_table.indexed_node(window)?;
            let range = program.expression_table.range_node(window.index)?;
            let start = if range.start.is_valid() {
                build_operand(program, machine, state, range.start, depth + 1, frames)?
            } else {
                Operand::Integer(numerics::literals::IntegerLiteral::from_value(0), None)
            };
            let index = match &start {
                Operand::Integer(literal, _) if literal.value_u64() == Some(0) => index,
                _ => Operand::Binary {
                    operator: BinaryOperator::Add,
                    primitive: Some(PrimitiveType::U64),
                    domain: ArithmeticDomain::Exact,
                    operands: vec![start, index],
                },
            };
            return indexed_operand(
                program,
                machine,
                state,
                window.collection,
                index,
                primitive,
                frames,
                depth + 1,
            );
        }
        Some(Operand::Indexed {
            collection: Box::new(build_operand(
                program,
                machine,
                state,
                collection,
                depth + 1,
                frames,
            )?),
            index: Box::new(index),
            primitive,
        })
    }

    pub(crate) fn record(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        environment: &mut ValueEnvironment,
        comparison: &typed_trees::expression::TableBinaryExpression,
        positive: bool,
    ) {
        let unequal = matches!(
            (comparison.operator, positive),
            (BinaryOperator::NotEqual, true) | (BinaryOperator::Equal, false)
        );
        let (left, right, strict, equal) = match (comparison.operator, positive) {
            (BinaryOperator::GreaterOrEqual, true) | (BinaryOperator::Less, false) => {
                (comparison.left, comparison.right, false, false)
            }
            (BinaryOperator::Greater, true) | (BinaryOperator::LessOrEqual, false) => {
                (comparison.left, comparison.right, true, false)
            }
            (BinaryOperator::LessOrEqual, true) | (BinaryOperator::Greater, false) => {
                (comparison.right, comparison.left, false, false)
            }
            (BinaryOperator::Less, true) | (BinaryOperator::GreaterOrEqual, false) => {
                (comparison.right, comparison.left, true, false)
            }
            (BinaryOperator::Equal, true) | (BinaryOperator::NotEqual, false) => {
                (comparison.left, comparison.right, false, true)
            }
            (BinaryOperator::NotEqual, true) | (BinaryOperator::Equal, false) => {
                (comparison.left, comparison.right, false, false)
            }
            _ => return,
        };
        let left_meaning = integer_meaning(program, machine, state, left);
        let right_meaning = integer_meaning(program, machine, state, right);
        if !has_integer_order_meaning(program, machine, state, left)
            || !has_integer_order_meaning(program, machine, state, right)
        {
            return;
        }
        if unequal {
            let (Some(left), Some(right)) = (
                operand(program, machine, state, left, None),
                operand(program, machine, state, right, None),
            ) else {
                return;
            };
            for (meaning, excluded_expression, subject, excluded) in [
                (left_meaning, comparison.right, &left, &right),
                (right_meaning, comparison.left, &right, &left),
            ] {
                let Some((primitive, _)) = meaning else {
                    continue;
                };
                let Some(range) = primitive_range(primitive) else {
                    continue;
                };
                let ExpressionNode::Integer(literal) =
                    program.expression_table.expression(excluded_expression)
                else {
                    continue;
                };
                let Some(value) = literal.value_i64() else {
                    continue;
                };
                let order = if range.low == Some(value) {
                    Some((subject.clone(), excluded.clone()))
                } else if range.high == Some(value) {
                    Some((excluded.clone(), subject.clone()))
                } else {
                    None
                };
                if let Some((left, right)) = order {
                    let relation = Relation {
                        left,
                        right,
                        constraint: RelationConstraint::MinimumDifference(1),
                    };
                    if !environment.ordered_values.contains(&relation) {
                        environment.ordered_values.push(relation);
                    }
                }
            }
            let relation = Relation {
                left,
                right,
                constraint: RelationConstraint::Unequal,
            };
            if !environment.ordered_values.contains(&relation) {
                environment.ordered_values.push(relation);
            }
            return;
        }
        for (ceiling_expression, ceiling_meaning, value_expression) in std::iter::once((
            left,
            left_meaning,
            right,
        ))
        .chain(equal.then_some((right, right_meaning, left)))
        {
            let Some(value) = operand(program, machine, state, value_expression, None) else {
                continue;
            };
            let carrier_ceiling =
                ceiling_meaning.and_then(|(primitive, _)| integer_carrier_ceiling(primitive));
            for ceiling in operand(program, machine, state, ceiling_expression, None)
                .into_iter()
                .chain(carrier_ceiling)
            {
                let relation = Relation {
                    left: ceiling,
                    right: value.clone(),
                    constraint: RelationConstraint::MinimumDifference(i64::from(strict)),
                };
                if !environment.ordered_values.contains(&relation) {
                    environment.ordered_values.push(relation);
                }
            }
        }
    }

    fn has_integer_order_meaning(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> bool {
        if integer_meaning(program, machine, state, expression).is_some()
            || matches!(program.expression_table.expression(expression),
            ExpressionNode::Integer(literal)
                if literal.landing().is_none()
                    && (literal.value_i64().is_some()
                        || literal.value_bignum().and_then(|value| value.to_u64()).is_some()))
        {
            return true;
        }
        let Some(reference) =
            crate::expression_result_type_reference(program, machine, state, expression)
        else {
            return false;
        };
        let Some(proof_integer) =
            crate::proof_contracts::proof_embeddings::proof_int_type_reference(program)
        else {
            return false;
        };
        let identity = program.normalized_type_identity(proof_integer);
        identity.is_valid() && program.normalized_type_identity(reference) == identity
    }

    fn integer_carrier_ceiling(primitive: PrimitiveType) -> Option<Operand> {
        use numerics::literals::{IntegerLiteral, IntegerRadix};

        let literal = if primitive == PrimitiveType::U64 {
            IntegerLiteral::from_parts(false, IntegerRadix::Decimal, "18446744073709551615").ok()?
        } else {
            IntegerLiteral::from_value(primitive_range(primitive)?.high?)
        };
        Some(Operand::Integer(literal, None))
    }

    pub(crate) fn same_place(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        left: ExpressionHandle,
        right: ExpressionHandle,
    ) -> bool {
        if ![left, right].into_iter().all(|expression| {
            matches!(
                program.expression_table.expression(expression),
                ExpressionNode::Name(_) | ExpressionNode::Member(_)
            )
        }) {
            return false;
        }
        let Some(state) = state else {
            return false;
        };
        let Some(left) = operand(program, machine, state, left, None) else {
            return false;
        };
        left.static_path().is_some()
            && operand(program, machine, state, right, None).is_some_and(|right| left == right)
    }

    pub(crate) fn subtract_floor(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        left: ExpressionHandle,
        right: ExpressionHandle,
        preserves_storage: bool,
    ) -> Option<i64> {
        let state = state?;
        if !preserves_storage
            && ![left, right].into_iter().all(|expression| {
                operand(program, machine, state, expression, None)
                    .is_some_and(|value| value.is_immutable_snapshot(program, state))
            })
        {
            return None;
        }
        subtract_floor_limited(program, machine, Some(state), environment, left, right, 0)
    }

    pub(crate) fn subtract_floor_limited(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        left: ExpressionHandle,
        right: ExpressionHandle,
        depth: usize,
    ) -> Option<i64> {
        if depth > 8 {
            return None;
        }
        let state = state?;
        if matches!(
            program.expression_table.expression(right),
            ExpressionNode::Match(_)
        ) {
            return match_subtract_floor(program, machine, state, environment, left, right, depth);
        }
        if matches!(
            program.expression_table.expression(left),
            ExpressionNode::Match(_)
        ) {
            let ExpressionNode::Match(dispatch) = program.expression_table.expression(left) else {
                return None;
            };
            let arms = program.expression_table.match_arms(dispatch.arms);
            let arm_environments = super::dispatch_arm_environments(
                program,
                machine,
                Some(state),
                left,
                dispatch,
                environment,
            );
            if arms.is_empty() || arm_environments.len() != arms.len() {
                return None;
            }
            let mut floor = None;
            for (arm, arm_environment) in arms.iter().zip(&arm_environments) {
                let arm_floor = subtract_floor_limited(
                    program,
                    machine,
                    Some(state),
                    arm_environment,
                    arm.value,
                    right,
                    depth + 1,
                )?;
                floor = Some(floor.map_or(arm_floor, |existing: i64| existing.min(arm_floor)));
            }
            return floor;
        }
        let left_named = operand(program, machine, state, left, None);
        let right_named = operand(program, machine, state, right, None);
        if let (Some(left_named), Some(right_named)) = (&left_named, &right_named)
            && left_named == right_named
        {
            return Some(0);
        }
        let (Some(left_operand), Some(right_operand)) = (left_named, right_named) else {
            return None;
        };
        let mut left_comparison =
            EqualityQuery::new(&environment.ordered_values, &left_operand, &left_operand);
        let mut right_comparison =
            EqualityQuery::new(&environment.ordered_values, &right_operand, &right_operand);
        environment
            .ordered_values
            .iter()
            .filter(|relation| {
                left_comparison.same_value(&left_operand, &relation.left)
                    && right_comparison.same_value(&right_operand, &relation.right)
            })
            .filter_map(Relation::minimum_difference)
            .max()
    }

    pub(crate) fn excludes_integer_value(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
        value: i64,
    ) -> bool {
        if environment.ordered_values.is_empty() {
            return false;
        }
        let Some(subject) =
            state.and_then(|state| operand(program, machine, state, expression, None))
        else {
            return false;
        };
        let mut comparison = ValueComparison::new(&environment.ordered_values);
        environment.ordered_values.iter().any(|relation| {
            for (candidate, opposite, subject_is_left) in [
                (&relation.left, &relation.right, true),
                (&relation.right, &relation.left, false),
            ] {
                let Operand::Integer(literal, _) = opposite else {
                    continue;
                };
                let Some(constant) = literal.value_i64() else {
                    continue;
                };
                let excludes = match relation.constraint {
                    RelationConstraint::Unequal => constant == value,
                    RelationConstraint::MinimumDifference(floor) if subject_is_left => {
                        i128::from(constant) + i128::from(floor) > i128::from(value)
                    }
                    RelationConstraint::MinimumDifference(floor) => {
                        i128::from(constant) - i128::from(floor) < i128::from(value)
                    }
                };
                if excludes && comparison.same_value(&subject, candidate) {
                    return true;
                }
            }
            false
        })
    }

    pub(crate) fn refine_place_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
        mut interval: Interval,
    ) -> Interval {
        if environment.ordered_values.is_empty() {
            return interval;
        }
        let Some(subject) =
            state.and_then(|state| operand(program, machine, state, expression, None))
        else {
            return interval;
        };
        let mut comparison: Option<EqualityQuery<'_>> = None;
        for exact_only in [true, false] {
            for relation in &environment.ordered_values {
                let RelationConstraint::MinimumDifference(distance) = relation.constraint else {
                    continue;
                };
                for (candidate, opposite, subject_on_left) in [
                    (&relation.left, &relation.right, true),
                    (&relation.right, &relation.left, false),
                ] {
                    let Operand::Integer(literal, _) = opposite else {
                        continue;
                    };
                    let Some(constant) = literal.value_i64() else {
                        continue;
                    };
                    let endpoint = if subject_on_left {
                        i128::from(constant) + i128::from(distance)
                    } else {
                        i128::from(constant) - i128::from(distance)
                    };
                    let Ok(endpoint) = i64::try_from(endpoint) else {
                        continue;
                    };
                    let tightens = if subject_on_left {
                        interval.low.is_none_or(|low| endpoint > low)
                    } else {
                        interval.high.is_none_or(|high| endpoint < high)
                    };
                    if !tightens {
                        continue;
                    }
                    let matched = if exact_only {
                        &subject == candidate
                    } else {
                        &subject != candidate
                            && comparison
                                .get_or_insert_with(|| {
                                    EqualityQuery::new(
                                        &environment.ordered_values,
                                        &subject,
                                        &subject,
                                    )
                                })
                                .same_value(&subject, candidate)
                    };
                    if matched {
                        interval = interval.intersect(if subject_on_left {
                            Interval {
                                low: Some(endpoint),
                                high: None,
                            }
                        } else {
                            Interval {
                                low: None,
                                high: Some(endpoint),
                            }
                        });
                    }
                }
            }
        }
        interval
    }

    pub(crate) fn unsigned_increase_fits(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        value: ExpressionHandle,
        increase: Interval,
        ceiling: Option<i64>,
    ) -> bool {
        let (Some(state), Some(low), Some(high)) = (state, increase.low, increase.high) else {
            return false;
        };
        if low < 0 || high < low {
            return false;
        }
        if high > 0 && environment.ordered_values.is_empty() {
            return false;
        }
        let Some(value) = operand(program, machine, state, value, None) else {
            return false;
        };
        composed_ceiling_gap(&environment.ordered_values, &value, high, |operand| {
            operand_carrier_within_ceiling(program, machine, state, operand, ceiling)
        })
    }

    fn operand_carrier_bound(
        program: &dyn CheckingInput,
        operand: &Operand,
    ) -> Option<Option<i64>> {
        match operand {
            Operand::Integer(literal, _) => Some(literal_interval(literal).high),
            Operand::Place { root, .. } => {
                let type_reference =
                    crate::value_custody::places::declaration_type_reference(program, *root)?;
                let primitive = program.primitive_type_reference(type_reference)?;
                Some(primitive_range(primitive).and_then(|range| range.high))
            }
            Operand::Binary { primitive, .. } => {
                primitive.map(|primitive| primitive_range(primitive).and_then(|range| range.high))
            }
            Operand::CollectionLength(_) => Some(None),
            Operand::Indexed { primitive, .. } | Operand::Field { primitive, .. } => {
                primitive.and_then(primitive_range).map(|range| range.high)
            }
            Operand::Call { .. } => None,
            #[cfg(test)]
            Operand::CompletedCall { .. } => None,
        }
    }

    fn operand_carrier_within_ceiling(
        program: &dyn CheckingInput,
        _machine: &Machine,
        _state: &State,
        operand: &Operand,
        ceiling: Option<i64>,
    ) -> bool {
        let Some(ceiling) = ceiling else {
            return true;
        };
        matches!(
            operand_carrier_bound(program, operand),
            Some(Some(bound)) if bound <= ceiling
        )
    }

    fn composed_ceiling_gap(
        relations: &[Relation],
        value: &Operand,
        needed: i64,
        admits: impl Fn(&Operand) -> bool,
    ) -> bool {
        if needed <= 0 {
            return true;
        }
        ordered_gaps(relations, value).any(|(operand, gap)| gap >= needed && admits(operand))
    }

    fn ordered_gaps<'relations>(
        relations: &'relations [Relation],
        value: &'relations Operand,
    ) -> impl Iterator<Item = (&'relations Operand, i64)> {
        let mut comparison = congruence::ValueComparison::new(relations);
        ordered_gaps_with_comparison(relations, value, &mut comparison).into_iter()
    }

    pub(crate) fn ordered_gaps_with_comparison<'relations>(
        _relations: &'relations [Relation],
        value: &'relations Operand,
        comparison: &mut congruence::ValueComparison<'relations>,
    ) -> Vec<(&'relations Operand, i64)> {
        comparison.ordered_gaps(value)
    }
}
pub(crate) use ordered_values::{Operand as ScalarOperand, operand as scalar_operand};
pub(crate) mod place_paths {
    use crate::frozen_program::expression_table;
    use symbols::JoinedPath;
    use typed_trees::expression::{ExpressionHandle, ExpressionNode};

    pub(crate) fn canonical_path_pair(left: String, right: String) -> (String, String) {
        if left <= right {
            (left, right)
        } else {
            (right, left)
        }
    }

    pub(crate) fn place_paths_overlap(left: &str, right: &str) -> bool {
        crate::machine_calls::calls::frame_paths_overlap(left, right)
    }

    pub(crate) fn place_path_pair(
        program: &dyn crate::CheckingInput,
        left: ExpressionHandle,
        right: ExpressionHandle,
    ) -> Option<(String, String)> {
        let left = place_path(program, left)?;
        let right = place_path(program, right)?;
        Some((left, right))
    }

    pub(crate) fn place_path(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<String> {
        match expression_table(program).expression(expression) {
            ExpressionNode::SavedSubject(saved) => {
                program.saved_value_source(saved)?;
                Some(capture_path(
                    expression_table(program)
                        .value_capture(saved.capture)
                        .value_anchor,
                ))
            }
            ExpressionNode::Name(path) => {
                let members = expression_table(program).name_path_members(path.members);
                if members.is_empty() {
                    return None;
                }
                Some(members.joined_path_with("."))
            }
            ExpressionNode::Member(member) => {
                let receiver = place_path(program, member.receiver)?;
                Some(format!("{receiver}.{}", member.member.as_str()))
            }
            _ => None,
        }
    }

    pub(crate) fn element_place(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
    ) -> Option<super::value_environment::ElementPlace> {
        use super::ordered_values::Operand;
        let ExpressionNode::Indexed(indexed) = expression_table(program).expression(expression)
        else {
            return None;
        };
        let collection = place_path(program, indexed.collection)?;
        let index = match expression_table(program).expression(indexed.index) {
            ExpressionNode::Integer(literal) => {
                Operand::Integer(literal.clone(), literal.landing())
            }
            ExpressionNode::Name(path)
                if path.symbol.is_valid()
                    && path.symbol == path.head_symbol
                    && matches!(
                        program.symbols.get(path.symbol).kind,
                        symbols::SymbolKind::Local
                            | symbols::SymbolKind::Parameter
                            | symbols::SymbolKind::Const
                    ) =>
            {
                Operand::Place {
                    root: path.symbol,
                    path: place_path(program, indexed.index)?,
                }
            }
            _ => return None,
        };
        Some(super::value_environment::ElementPlace { collection, index })
    }

    pub(crate) fn capture_path(anchor: ExpressionHandle) -> String {
        format!("\0capture:{anchor:?}")
    }
}
pub(crate) mod range_constraints {
    use crate::CheckingInput;
    use crate::proof_contracts::arithmetic_domains::ValueEnvironment;
    use crate::proof_contracts::arithmetic_domains::interval::Interval;
    use diagnostics::Diagnostic;
    use numerics::bignum::BigInt;
    use typed_trees::expression::ExpressionHandle;
    use typed_trees::machine::Machine;
    use typed_trees::state::State;
    use typed_trees::types::PrimitiveType;
    use typed_trees::types::{TypeConstraintNode, TypeReferenceHandle, TypeReferenceNode};

    #[derive(Clone, Copy)]
    pub(crate) struct IntegerValueObservation<'a> {
        pub machine: &'a Machine,
        pub state: Option<&'a State>,
        pub expression: ExpressionHandle,
        pub environment: &'a ValueEnvironment,
        pub interval: Interval,
    }

    impl IntegerValueObservation<'_> {
        fn fits(self, program: &dyn CheckingInput, stated: Interval) -> bool {
            if stated
                .low
                .zip(stated.high)
                .is_some_and(|(low, high)| low > high)
            {
                return false;
            }
            let lower_proven = stated
                .low
                .is_none_or(|bound| self.interval.low.is_some_and(|low| low >= bound));
            let upper_proven = stated
                .high
                .is_none_or(|bound| self.interval.high.is_some_and(|high| high <= bound));
            if lower_proven && upper_proven {
                return true;
            }
            let Some(state) = self.state else {
                return false;
            };
            let minimum = stated.low.map(BigInt::from_i64);
            let maximum = stated.high.map(BigInt::from_i64);
            if super::live_integer_constraints::proves_range(
                program,
                self.machine,
                state,
                self.environment,
                self.expression,
                if lower_proven { None } else { minimum.as_ref() },
                if upper_proven { None } else { maximum.as_ref() },
            ) {
                return true;
            }
            let Some(statement_index) =
                crate::proof_contracts::contract_entailment::expression_statement_index(
                    program,
                    state,
                    self.expression,
                )
            else {
                return false;
            };
            crate::proof_contracts::contract_entailment::completed_value_fits_integer_interval(
                program,
                self.machine,
                state,
                statement_index,
                self.expression,
                stated,
            )
        }
    }

    pub(crate) fn range_constraint_interval(
        program: &dyn CheckingInput,
        handle: TypeReferenceHandle,
    ) -> Option<Interval> {
        if floating_range_carrier(program, handle) {
            return None;
        }
        match program.type_reference_table.type_reference(handle) {
            TypeReferenceNode::Reference { referee, .. } => {
                range_constraint_interval(program, *referee)
            }
            TypeReferenceNode::Constrained {
                base_type,
                constraints,
            } => program
                .type_reference_table
                .constraints(*constraints)
                .iter()
                .filter_map(|constraint| match constraint {
                    TypeConstraintNode::Domain(domain) => {
                        super::domain_intervals::declared_domain_predicate_bounds(program, domain)
                            .map(|(minimum, maximum)| Interval {
                                low: minimum.to_i64(),
                                high: maximum.to_i64(),
                            })
                    }
                    _ => None,
                })
                .chain(range_constraint_interval(program, *base_type))
                .reduce(Interval::intersect),
            _ => None,
        }
    }

    pub(crate) fn check_requires_interval_containment(
        program: &dyn CheckingInput,
        stated: Interval,
        value: IntegerValueObservation<'_>,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> bool {
        if !value.fits(program, stated) {
            diagnostics.push(Diagnostic::error(format!(
            "{owner} stores a value not provably within its data's `requires` facts: every read \
             trusts them (indexes, exact arithmetic), so the stored value must be proven to \
             honor them. Narrow the value with a dominating guard or a requires coupling",
        )));
            return false;
        }
        true
    }

    fn floating_range_carrier(program: &dyn CheckingInput, reference: TypeReferenceHandle) -> bool {
        crate::unwrapped_type_reference(program, reference)
            .and_then(|carrier| program.primitive_type_reference(carrier))
            .is_some_and(|primitive| matches!(primitive, PrimitiveType::F32 | PrimitiveType::F64))
    }
}
pub(crate) mod return_ranges {
    use crate::proof_contracts::arithmetic_domains::assignments::{
        check_narrowing_assignment, stored_value_carrier,
    };
    use crate::proof_contracts::arithmetic_domains::integer_ranges::validate_anonymous_integer_range;
    use crate::proof_contracts::arithmetic_domains::interval::Interval;
    use crate::proof_contracts::arithmetic_domains::range_constraints::range_constraint_interval;
    use crate::proof_contracts::arithmetic_domains::value_environment::ValueEnvironment;
    use checked_trees::IntegerRangeRecipe;
    use diagnostics::Diagnostic;
    use numerics::arithmetic::ArithmeticDomain;
    use typed_trees::expression::{ExpressionHandle, TableCallExpression};
    use typed_trees::machine::Machine;
    use typed_trees::state::State;
    use typed_trees::types::{PrimitiveType, TypeReferenceHandle};

    pub(crate) fn overflow_operand_value_call_target(
        program: &dyn crate::CheckingInput,
        operand: ExpressionHandle,
    ) -> Option<String> {
        let call = program.expression_table.call_node(operand)?;
        let return_type = call_return_type(program, call)?;
        program
            .primitive_type_reference(return_type)
            .filter(|primitive| primitive.accepts_integer_literal())
            .map(|_| call.target.as_str().to_string())
    }

    pub(crate) fn call_return_type(
        program: &dyn crate::CheckingInput,
        call: &TableCallExpression,
    ) -> Option<TypeReferenceHandle> {
        if crate::proof_contracts::proof_embeddings::is_exact_embed_call(program, call) {
            return crate::proof_contracts::proof_embeddings::proof_int_type_reference(program);
        }
        if let Some(operator) = typed_trees::operator::resolve_named_expression_call(program, call)
            && operator.return_type.is_valid()
        {
            return Some(operator.return_type);
        }

        crate::machine_calls::calls::resolved_call_result_type(program, call)
    }

    pub(crate) fn ensured_call_result_interval(
        program: &dyn crate::CheckingInput,
        caller: symbols::SymbolHandle,
        expression: ExpressionHandle,
        call: &TableCallExpression,
        actuals: &super::call_result_bounds::ArgumentBounds,
    ) -> Option<Interval> {
        if !crate::machine_calls::contract_dependencies::independent_call_application(
            program,
            caller,
            call.target_symbol,
            typed_trees::references::StaticArgumentCall::Expression(expression, call),
        ) {
            return None;
        }
        if let Some((machine, state)) =
            crate::machine_calls::calls::machine_state_by_symbol(program, call.target_symbol)
            && machine.target_family_interface
            && program.machine_states(machine).first()?.symbol == state.symbol
        {
            let parameters = program.state_parameters(state);
            let members = crate::machine_calls::calls::target_family_members(program, machine)?;
            let mut union: Option<Interval> = None;
            for member in members {
                let member_machine = program.machine(member.machine)?;
                let member_entry = program.machine_states(member_machine).first()?;
                let member_callee = crate::machine_calls::calls::callee_entry_contract(
                    program,
                    member_entry.symbol,
                )?;
                if member_callee.parameters.len() != parameters.len() {
                    return None;
                }
                let remap = |items: &[(symbols::SymbolHandle, Interval)]| {
                    parameters
                        .iter()
                        .zip(member_callee.parameters)
                        .filter_map(|(interface_param, member_param)| {
                            items
                                .iter()
                                .find(|(symbol, _)| *symbol == interface_param.symbol)
                                .map(|(_, interval)| (member_param.symbol, *interval))
                        })
                        .collect::<Vec<_>>()
                };
                let member_actuals = super::call_result_bounds::ArgumentBounds {
                    values: remap(&actuals.values),
                    lengths: remap(&actuals.lengths),
                };
                let member_interval = super::call_result_bounds::normal_return_interval(
                    program,
                    &member_callee,
                    Interval::UNBOUNDED,
                    &member_actuals,
                );
                union = Some(match union {
                    Some(existing) => existing.union(member_interval),
                    None => member_interval,
                });
            }
            let interval = union?;
            return (interval != Interval::UNBOUNDED).then_some(interval);
        }
        let callee = crate::machine_calls::calls::call_contract(program, call)?;
        let interval = super::call_result_bounds::normal_return_interval(
            program,
            &callee,
            Interval::UNBOUNDED,
            actuals,
        );
        (interval != Interval::UNBOUNDED).then_some(interval)
    }

    pub fn normal_return_integer_bounds(
        program: &dyn crate::CheckingInput,
        caller: symbols::SymbolHandle,
        expression: ExpressionHandle,
        call: &TableCallExpression,
    ) -> Option<(Option<i64>, Option<i64>)> {
        if !call.selects_only_nominal_route()
            || !program
                .primitive_type_reference(call_return_type(program, call)?)
                .is_some_and(PrimitiveType::is_fixed_integer)
        {
            return None;
        }
        let interval = ensured_call_result_interval(
            program,
            caller,
            expression,
            call,
            &super::call_result_bounds::ArgumentBounds::default(),
        )?;
        if interval
            .low
            .zip(interval.high)
            .is_some_and(|(low, high)| low > high)
        {
            return None;
        }
        Some((interval.low, interval.high))
    }

    pub(crate) fn infer_return_interval(
        program: &dyn crate::CheckingInput,
        callee_machine: &Machine,
        callee_state: &State,
        target_primitive: Option<PrimitiveType>,
        actuals: &[(symbols::SymbolHandle, Interval, Option<IntegerRangeRecipe>)],
    ) -> Option<(Interval, Option<IntegerRangeRecipe>)> {
        super::guard_narrowing::inferred_normal_return_interval(
            program,
            callee_machine,
            callee_state,
            target_primitive,
            actuals,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn analyzed_return_interval_and_narrowing(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        return_expression: ExpressionHandle,
        environment: &ValueEnvironment,
        return_primitive: Option<PrimitiveType>,
        return_domain: ArithmeticDomain,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
        decisions: &mut super::ArithmeticDecisions,
    ) -> Interval {
        let before = diagnostics.len();
        let (interval, source, source_domain) = super::validate_value_range_retaining_decisions(
            program,
            machine,
            Some(state),
            return_expression,
            environment,
            return_primitive,
            return_domain,
            owner,
            diagnostics,
            decisions,
        );
        if diagnostics.len() == before
            && !program.static_type_context_is_unreachable(return_expression)
        {
            let (source, source_domain) = stored_value_carrier(
                program,
                machine,
                Some(state),
                return_expression,
                source,
                source_domain,
            );
            check_narrowing_assignment(
                return_primitive,
                return_domain,
                interval,
                source,
                source_domain,
                owner,
                diagnostics,
            );
        }
        interval
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn validate_return_value_range(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        return_expression: ExpressionHandle,
        environment: &ValueEnvironment,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
        decisions: &mut super::ArithmeticDecisions,
    ) {
        let return_primitive = program.primitive_type_reference(state.return_type);
        let return_domain = program.arithmetic_domain_for_type_reference(state.return_type);

        if validate_anonymous_integer_range(
            program,
            state.return_type,
            return_expression,
            owner,
            diagnostics,
        )
        .is_some()
        {
            return;
        }
        if range_constraint_interval(program, state.return_type).is_some() {
            analyzed_return_interval_and_narrowing(
                program,
                machine,
                state,
                return_expression,
                environment,
                return_primitive,
                return_domain,
                owner,
                diagnostics,
                decisions,
            );

            return;
        }
        analyzed_return_interval_and_narrowing(
            program,
            machine,
            state,
            return_expression,
            environment,
            return_primitive,
            return_domain,
            owner,
            diagnostics,
            decisions,
        );
    }
}
pub(crate) mod selected_scalar_intervals {
    use super::{admitted_integer, integer_magnitude, integer_type};
    use checked_trees::{
        CheckedBooleanExpression, CheckedIntegerBinaryKind, CheckedIntegerComparisonKind,
        CheckedScalarExpression, CheckedStructuralPredicatePathSegment,
    };
    use facts::IntegerRange;
    use numerics::arithmetic::ArithmeticDomain;
    use numerics::bignum::BigInt;
    use symbols::SymbolHandle;
    use typed_trees::expression::BinaryOperator;
    use typed_trees::types::PrimitiveType;

    pub trait SelectedScalarIntervalSource {
        fn binding(
            &mut self,
            position: usize,
            primitive_type: PrimitiveType,
        ) -> Option<IntegerRange>;
        fn storage(
            &mut self,
            symbol: SymbolHandle,
            primitive_type: PrimitiveType,
        ) -> Option<IntegerRange>;
        fn structural_field(
            &mut self,
            position: u32,
            path: &[CheckedStructuralPredicatePathSegment],
        ) -> Option<IntegerRange>;
        fn indexed_read(
            &mut self,
            root: checked_trees::CheckedStorageRoot,
            path: &[CheckedStructuralPredicatePathSegment],
            index: &checked_trees::CheckedScalarSelector,
            element_path: &[checked_trees::CheckedScalarReadProjection],
            primitive: PrimitiveType,
        ) -> Option<IntegerRange>;
        fn byte_length(
            &mut self,
            _position: u32,
            _path: &[CheckedStructuralPredicatePathSegment],
        ) -> Option<IntegerRange> {
            carrier_integer_range(PrimitiveType::U64)
        }
    }

    pub fn selected_scalar_interval(
        expression: &CheckedScalarExpression,
        source: &mut impl SelectedScalarIntervalSource,
    ) -> Option<IntegerRange> {
        integer(expression, source).map(|(_, bounds)| bounds)
    }

    pub fn selected_boolean_decision(
        expression: &CheckedBooleanExpression,
        source: &mut impl SelectedScalarIntervalSource,
    ) -> Option<bool> {
        use CheckedBooleanExpression as Boolean;
        use CheckedIntegerComparisonKind as Comparison;
        match expression {
            Boolean::Constant(value) => Some(*value),
            Boolean::Not(operand) => selected_boolean_decision(operand, source).map(|value| !value),
            Boolean::Equal { left, right } => Some(
                selected_boolean_decision(left, source)?
                    == selected_boolean_decision(right, source)?,
            ),
            Boolean::And { left, right } => match (
                selected_boolean_decision(left, source),
                selected_boolean_decision(right, source),
            ) {
                (Some(false), _) | (_, Some(false)) => Some(false),
                (Some(true), Some(true)) => Some(true),
                _ => None,
            },
            Boolean::Or { left, right } => match (
                selected_boolean_decision(left, source),
                selected_boolean_decision(right, source),
            ) {
                (Some(true), _) | (_, Some(true)) => Some(true),
                (Some(false), Some(false)) => Some(false),
                _ => None,
            },
            Boolean::IntegerComparison { kind, left, right } => {
                let (left_type, left) = integer(left, source)?;
                let (right_type, right) = integer(right, source)?;
                if left_type != right_type {
                    return None;
                }
                match kind {
                    Comparison::Equal
                        if left.maximum < right.minimum || right.maximum < left.minimum =>
                    {
                        Some(false)
                    }
                    Comparison::Equal
                        if left.minimum == left.maximum && right.minimum == right.maximum =>
                    {
                        Some(left.minimum == right.minimum)
                    }
                    Comparison::LessThan if left.maximum < right.minimum => Some(true),
                    Comparison::LessThan if left.minimum >= right.maximum => Some(false),
                    Comparison::LessOrEqual if left.maximum <= right.minimum => Some(true),
                    Comparison::LessOrEqual if left.minimum > right.maximum => Some(false),
                    _ => None,
                }
            }
            _ => None,
        }
    }

    fn integer(
        expression: &CheckedScalarExpression,
        source: &mut impl SelectedScalarIntervalSource,
    ) -> Option<(PrimitiveType, IntegerRange)> {
        use CheckedScalarExpression as Expression;
        let (primitive, bounds) = match expression {
            Expression::StructuralSequenceLength { root, path } => (
                PrimitiveType::U64,
                match (
                    root.parameter(),
                    checked_trees::CheckedScalarReadProjection::static_path(path),
                ) {
                    (Some(position), Some(path)) => source.byte_length(position, &path)?,
                    _ => carrier_integer_range(PrimitiveType::U64)?,
                },
            ),
            Expression::Parameter {
                position,
                primitive_type,
            }
            | Expression::Local {
                position,
                primitive_type,
            } => (*primitive_type, source.binding(*position, *primitive_type)?),
            Expression::ConstantApplication { .. }
            | Expression::ErasedParameter { .. }
            | Expression::StructuralLocalField { .. } => {
                return None;
            }
            Expression::StorageRead {
                symbol,
                primitive_type,
            } => (*primitive_type, source.storage(*symbol, *primitive_type)?),
            Expression::StructuralParameterField {
                parameter_position,
                path,
                primitive_type,
                ..
            } => (
                *primitive_type,
                source.structural_field(*parameter_position, path)?,
            ),
            Expression::StructuralParameterIndexedRead {
                root,
                path,
                index,
                element_path,
                primitive_type,
                ..
            } => (
                *primitive_type,
                source.indexed_read(*root, path, index, element_path, *primitive_type)?,
            ),
            Expression::IntegerLiteral { literal } => {
                let primitive =
                    PrimitiveType::non_address_landed_integer(literal.landing()?.landed_type)?;
                let value = literal.value_bignum()?;
                (
                    primitive,
                    IntegerRange {
                        minimum: value.clone(),
                        maximum: value,
                    },
                )
            }
            Expression::IntegerBinary {
                kind,
                primitive_type,
                left,
                right,
                ..
            } => {
                let left_eval = integer(left, source);
                let right_eval = integer(right, source);
                let (left_type, left) = left_eval?;
                let (right_type, right) = right_eval?;
                if left_type != *primitive_type
                    || (right_type != *primitive_type
                        && !matches!(
                            kind,
                            CheckedIntegerBinaryKind::ExactShiftLeft
                                | CheckedIntegerBinaryKind::ExactShiftRight
                        ))
                {
                    return None;
                }
                (
                    *primitive_type,
                    binary(*kind, *primitive_type, right_type, left, right)?,
                )
            }
            Expression::IntegerWiden {
                primitive_type,
                operand,
            } => {
                let (source_type, bounds) = integer(operand, source)?;
                if !integer_range_contains(
                    &carrier_integer_range(*primitive_type)?,
                    &carrier_integer_range(source_type)?,
                ) {
                    return None;
                }
                (*primitive_type, bounds)
            }
            Expression::IntegerExactCast {
                primitive_type,
                operand,
                range,
                ..
            } => {
                let (_, bounds) = integer(operand, source)?;
                (
                    *primitive_type,
                    IntegerRange {
                        minimum: bounds.minimum.max(range.minimum.clone()),
                        maximum: bounds.maximum.min(range.maximum.clone()),
                    },
                )
            }
            Expression::RepresentationView {
                primitive_type,
                operand,
            } => {
                let (_, bounds) = integer(operand, source)?;
                let carrier = carrier_integer_range(*primitive_type)?;
                (
                    *primitive_type,
                    if integer_range_contains(&carrier, &bounds) {
                        bounds
                    } else {
                        carrier
                    },
                )
            }
            Expression::IntegerBitwiseNot {
                primitive_type,
                operand,
            } => {
                let (_, bounds) = integer(operand, source)?;
                let carrier = integer_type(*primitive_type)?;
                let low = admitted_integer(carrier, &bounds.minimum)?;
                let high = admitted_integer(carrier, &bounds.maximum)?;
                (
                    *primitive_type,
                    IntegerRange {
                        minimum: integer_magnitude(carrier.bitwise_not(high)?),
                        maximum: integer_magnitude(carrier.bitwise_not(low)?),
                    },
                )
            }
            Expression::Boolean(_)
            | Expression::IeeeFloatLiteral { .. }
            | Expression::ImplementationSelection { .. } => return None,
        };
        integer_range_contains(&carrier_integer_range(primitive)?, &bounds)
            .then_some((primitive, bounds))
    }

    pub(crate) fn binary(
        kind: CheckedIntegerBinaryKind,
        primitive: PrimitiveType,
        right_primitive: PrimitiveType,
        left: IntegerRange,
        right: IntegerRange,
    ) -> Option<IntegerRange> {
        use CheckedIntegerBinaryKind as Kind;
        if matches!(kind, Kind::ExactShiftLeft | Kind::ExactShiftRight) {
            let carrier = integer_type(primitive)?;
            let count_type = integer_type(right_primitive)?;
            let value = (
                admitted_integer(carrier, &left.minimum)?,
                admitted_integer(carrier, &left.maximum)?,
            );
            let count = (
                admitted_integer(count_type, &right.minimum)?,
                admitted_integer(count_type, &right.maximum)?,
            );
            let (low, high) = match kind {
                Kind::ExactShiftLeft => carrier.exact_shift_left_bounds(value, count_type, count),
                Kind::ExactShiftRight => carrier.exact_shift_right_bounds(value, count_type, count),
                _ => None,
            }?;
            return Some(IntegerRange {
                minimum: integer_magnitude(low),
                maximum: integer_magnitude(high),
            });
        }
        if matches!(kind, Kind::BitwiseAnd | Kind::BitwiseOr | Kind::BitwiseXor) {
            let carrier = integer_type(primitive)?;
            let left = (
                admitted_integer(carrier, &left.minimum)?,
                admitted_integer(carrier, &left.maximum)?,
            );
            let right = (
                admitted_integer(carrier, &right.minimum)?,
                admitted_integer(carrier, &right.maximum)?,
            );
            let (low, high) = match kind {
                Kind::BitwiseAnd => carrier.bitwise_and_bounds(left, right),
                Kind::BitwiseOr => carrier.bitwise_or_bounds(left, right),
                Kind::BitwiseXor => carrier.bitwise_xor_bounds(left, right),
                _ => None,
            }?;
            return Some(IntegerRange {
                minimum: integer_magnitude(low),
                maximum: integer_magnitude(high),
            });
        }
        if matches!(
            kind,
            Kind::ExactRemainder | Kind::WrappingRemainder | Kind::SaturatingRemainder
        ) {
            return remainder(&left, &right);
        }
        if matches!(
            kind,
            Kind::ExactDivide | Kind::WrappingDivide | Kind::SaturatingDivide
        ) {
            return quotient(&left, &right);
        }
        let operator = match kind {
            Kind::ExactAdd | Kind::WrappingAdd | Kind::SaturatingAdd => BinaryOperator::Add,
            Kind::ExactSubtract | Kind::WrappingSubtract | Kind::SaturatingSubtract => {
                BinaryOperator::Subtract
            }
            Kind::ExactMultiply | Kind::WrappingMultiply | Kind::SaturatingMultiply => {
                BinaryOperator::Multiply
            }
            _ => return None,
        };
        let mut bounds = super::integer_binary_range(operator, left, right)?;
        let carrier = carrier_integer_range(primitive)?;
        match kind {
            Kind::ExactAdd | Kind::ExactSubtract | Kind::ExactMultiply => {
                integer_range_contains(&carrier, &bounds).then_some(bounds)
            }
            Kind::WrappingAdd | Kind::WrappingSubtract | Kind::WrappingMultiply => {
                let modulus = carrier
                    .maximum
                    .sub(&carrier.minimum)
                    .add(&BigInt::from_u64(1));
                let reduce = |value: &BigInt| {
                    let shifted = value.sub(&carrier.minimum);
                    let (quotient, remainder) = shifted.div_rem(&modulus)?;
                    Some(if remainder.is_negative() {
                        (quotient.sub(&BigInt::from_u64(1)), remainder.add(&modulus))
                    } else {
                        (quotient, remainder)
                    })
                };
                let (low_period, low) = reduce(&bounds.minimum)?;
                let (high_period, high) = reduce(&bounds.maximum)?;
                Some(if low_period == high_period {
                    IntegerRange {
                        minimum: low.add(&carrier.minimum),
                        maximum: high.add(&carrier.minimum),
                    }
                } else {
                    carrier
                })
            }
            Kind::SaturatingAdd | Kind::SaturatingSubtract | Kind::SaturatingMultiply => {
                bounds.minimum = bounds
                    .minimum
                    .max(carrier.minimum.clone())
                    .min(carrier.maximum.clone());
                bounds.maximum = bounds.maximum.max(carrier.minimum).min(carrier.maximum);
                Some(bounds)
            }
            _ => None,
        }
    }

    fn excludes_zero(divisor: &IntegerRange) -> bool {
        divisor.minimum >= BigInt::from_u64(1) || divisor.maximum <= BigInt::from_i64(-1)
    }

    pub fn checked_integer_binary_kind(
        operator: BinaryOperator,
        domain: ArithmeticDomain,
    ) -> Option<CheckedIntegerBinaryKind> {
        match (operator, domain) {
            (BinaryOperator::BitwiseAnd, _) => Some(CheckedIntegerBinaryKind::BitwiseAnd),
            (BinaryOperator::BitwiseOr, _) => Some(CheckedIntegerBinaryKind::BitwiseOr),
            (BinaryOperator::BitwiseXor, _) => Some(CheckedIntegerBinaryKind::BitwiseXor),
            (BinaryOperator::ShiftLeft, ArithmeticDomain::Wrapping) => {
                Some(CheckedIntegerBinaryKind::WrappingShiftLeft)
            }
            (BinaryOperator::ShiftRight, ArithmeticDomain::Wrapping) => {
                Some(CheckedIntegerBinaryKind::WrappingShiftRight)
            }
            (BinaryOperator::ShiftRight, ArithmeticDomain::Exact) => {
                Some(CheckedIntegerBinaryKind::ExactShiftRight)
            }
            (BinaryOperator::ShiftLeft, ArithmeticDomain::Exact) => {
                Some(CheckedIntegerBinaryKind::ExactShiftLeft)
            }
            (BinaryOperator::ShiftLeft, ArithmeticDomain::Saturating) => {
                Some(CheckedIntegerBinaryKind::SaturatingShiftLeft)
            }
            (BinaryOperator::ShiftRight, ArithmeticDomain::Saturating) => {
                Some(CheckedIntegerBinaryKind::SaturatingShiftRight)
            }
            (BinaryOperator::ShiftLeft, ArithmeticDomain::Trapping) => {
                Some(CheckedIntegerBinaryKind::TrappingShiftLeft)
            }
            (BinaryOperator::ShiftRight, ArithmeticDomain::Trapping) => {
                Some(CheckedIntegerBinaryKind::TrappingShiftRight)
            }
            (BinaryOperator::Add, ArithmeticDomain::Trapping) => {
                Some(CheckedIntegerBinaryKind::TrappingAdd)
            }
            (BinaryOperator::Subtract, ArithmeticDomain::Trapping) => {
                Some(CheckedIntegerBinaryKind::TrappingSubtract)
            }
            (BinaryOperator::Multiply, ArithmeticDomain::Trapping) => {
                Some(CheckedIntegerBinaryKind::TrappingMultiply)
            }
            (BinaryOperator::Divide, ArithmeticDomain::Trapping) => {
                Some(CheckedIntegerBinaryKind::TrappingDivide)
            }
            (BinaryOperator::Modulo, ArithmeticDomain::Trapping) => {
                Some(CheckedIntegerBinaryKind::TrappingRemainder)
            }
            (BinaryOperator::Add, ArithmeticDomain::Exact) => {
                Some(CheckedIntegerBinaryKind::ExactAdd)
            }
            (BinaryOperator::Subtract, ArithmeticDomain::Exact) => {
                Some(CheckedIntegerBinaryKind::ExactSubtract)
            }
            (BinaryOperator::Multiply, ArithmeticDomain::Exact) => {
                Some(CheckedIntegerBinaryKind::ExactMultiply)
            }
            (BinaryOperator::Divide, ArithmeticDomain::Exact) => {
                Some(CheckedIntegerBinaryKind::ExactDivide)
            }
            (BinaryOperator::Modulo, ArithmeticDomain::Exact) => {
                Some(CheckedIntegerBinaryKind::ExactRemainder)
            }
            (BinaryOperator::Divide, ArithmeticDomain::Wrapping) => {
                Some(CheckedIntegerBinaryKind::WrappingDivide)
            }
            (BinaryOperator::Modulo, ArithmeticDomain::Wrapping) => {
                Some(CheckedIntegerBinaryKind::WrappingRemainder)
            }
            (BinaryOperator::Divide, ArithmeticDomain::Saturating) => {
                Some(CheckedIntegerBinaryKind::SaturatingDivide)
            }
            (BinaryOperator::Modulo, ArithmeticDomain::Saturating) => {
                Some(CheckedIntegerBinaryKind::SaturatingRemainder)
            }
            (BinaryOperator::Add, ArithmeticDomain::Wrapping) => {
                Some(CheckedIntegerBinaryKind::WrappingAdd)
            }
            (BinaryOperator::Add, ArithmeticDomain::Saturating) => {
                Some(CheckedIntegerBinaryKind::SaturatingAdd)
            }
            (BinaryOperator::Subtract, ArithmeticDomain::Wrapping) => {
                Some(CheckedIntegerBinaryKind::WrappingSubtract)
            }
            (BinaryOperator::Subtract, ArithmeticDomain::Saturating) => {
                Some(CheckedIntegerBinaryKind::SaturatingSubtract)
            }
            (BinaryOperator::Multiply, ArithmeticDomain::Wrapping) => {
                Some(CheckedIntegerBinaryKind::WrappingMultiply)
            }
            (BinaryOperator::Multiply, ArithmeticDomain::Saturating) => {
                Some(CheckedIntegerBinaryKind::SaturatingMultiply)
            }
            _ => None,
        }
    }

    fn remainder(dividend: &IntegerRange, divisor: &IntegerRange) -> Option<IntegerRange> {
        if !excludes_zero(divisor) {
            return None;
        }
        super::BigIntInterval::from_closed(dividend.clone())
            .remainder(&super::BigIntInterval::from_closed(divisor.clone()))
            .into_closed()
    }

    fn quotient(dividend: &IntegerRange, divisor: &IntegerRange) -> Option<IntegerRange> {
        if !excludes_zero(divisor) {
            return None;
        }
        super::BigIntInterval::from_closed(dividend.clone())
            .divide(&super::BigIntInterval::from_closed(divisor.clone()))
            .into_closed()
    }

    pub fn integer_range_contains(outer: &IntegerRange, inner: &IntegerRange) -> bool {
        outer.minimum <= inner.minimum
            && inner.minimum <= inner.maximum
            && inner.maximum <= outer.maximum
    }

    pub fn carrier_integer_range(primitive: PrimitiveType) -> Option<IntegerRange> {
        let (minimum, maximum) = primitive.integer_bounds()?;
        Some(IntegerRange {
            minimum: BigInt::from_i128(minimum),
            maximum: BigInt::from_i128(maximum),
        })
    }
}
pub(crate) mod slice_lengths {
    use super::ordered_values::{self, Operand, Relation, RelationConstraint};
    use super::{
        ArithmeticDomain, BinaryOperator, ExpressionHandle, ExpressionNode, Interval, Machine,
        PrimitiveType, State, ValueEnvironment,
    };
    use crate::CheckingInput;
    use crate::value_custody::places::{
        declared_collection_extent, has_builtin_subslice_meaning, subslice_expression,
    };
    use numerics::literals::IntegerLiteral;

    pub(crate) fn publish_slice_length(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &mut ValueEnvironment,
        destination: &str,
        destination_symbol: symbols::SymbolHandle,
        initializer: ExpressionHandle,
    ) {
        let Some(interval) =
            slice_length_interval(program, machine, state, environment, initializer)
        else {
            return;
        };
        environment.set(format!("{destination}.len"), interval);
        let Some(state) = state else {
            return;
        };
        if !destination_symbol.is_valid() {
            return;
        }
        let Some(measure) = length_measure(program, machine, state, initializer) else {
            return;
        };
        relate_equal(
            environment,
            Operand::CollectionLength(Box::new(Operand::Place {
                root: destination_symbol,
                path: destination.to_owned(),
            })),
            measure,
        );
    }

    pub(crate) fn denoted_collection_length(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
    ) -> Option<Operand> {
        match program.expression_table.expression(expression) {
            ExpressionNode::Match(dispatch) => {
                let mut shared = None;
                for arm in program.expression_table.match_arms(dispatch.arms) {
                    let arm_length =
                        denoted_collection_length(program, machine, state, environment, arm.value)?;
                    match &shared {
                        None => shared = Some(arm_length),
                        Some(length) if length != &arm_length => return None,
                        Some(_) => {}
                    }
                }
                shared
            }
            ExpressionNode::Call(call) => measured_call_length(program, machine, state, call),
            _ => {
                let observed = ordered_values::operand(program, machine, state, expression, None)?;
                collection_length_of(environment, observed)
            }
        }
    }

    pub(crate) fn carried_slice_length(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        collection: ExpressionHandle,
    ) -> Option<Interval> {
        let collection = strip_borrow(program, collection);
        if let Some(path) = super::place_path(program, collection)
            && let Some(interval) = environment.get(&format!("{path}.len"))
        {
            return Some(interval);
        }
        slice_length_interval(program, machine, state, environment, collection)
    }

    fn slice_length_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
    ) -> Option<Interval> {
        let operation = subslice_expression(program, expression)?;
        if !has_builtin_subslice_meaning(program, machine, state, operation) {
            return None;
        }
        let indexed = program.expression_table.indexed_node(operation)?;
        let range = program.expression_table.range_node(indexed.index)?;
        let start = if range.start.is_valid() {
            observed_integer_interval(program, environment, range.start)
        } else {
            Interval::constant(0)
        };
        let mut end = if range.end.is_valid() {
            observed_integer_interval(program, environment, range.end)
        } else if range.end_inclusive {
            return None;
        } else {
            collection_extent_interval(program, machine, state, environment, indexed.collection)?
        };
        if range.end_inclusive {
            end = end.add(Interval::constant(1));
        }
        nonnegative_difference(end, start)
    }

    fn collection_extent_interval(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        environment: &ValueEnvironment,
        collection: ExpressionHandle,
    ) -> Option<Interval> {
        let collection = strip_borrow(program, collection);
        if let Some(extent) = declared_collection_extent(program, machine, state, collection) {
            return i64::try_from(extent).ok().map(Interval::constant);
        }
        let path = super::place_path(program, collection)?;
        environment.get(&format!("{path}.len"))
    }

    fn observed_integer_interval(
        program: &dyn CheckingInput,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
    ) -> Interval {
        if let Some(value) = super::integer_ranges::literal_i64(program, expression) {
            return Interval::constant(value);
        }
        let Some(path) = super::place_path(program, expression) else {
            return Interval::UNBOUNDED;
        };
        environment.get(&path).unwrap_or(Interval::UNBOUNDED)
    }

    fn nonnegative_difference(end: Interval, start: Interval) -> Option<Interval> {
        let low = end.low?.checked_sub(start.high?)?;
        if low < 0 {
            return None;
        }
        let high = match (end.high, start.low) {
            (Some(end_high), Some(start_low)) => end_high.checked_sub(start_low),
            _ => None,
        };
        if high.is_some_and(|high| high < low) {
            return None;
        }
        Some(Interval {
            low: Some(low),
            high,
        })
    }

    fn strip_borrow(
        program: &dyn CheckingInput,
        mut expression: ExpressionHandle,
    ) -> ExpressionHandle {
        for _ in 0..8 {
            let ExpressionNode::Borrow(borrow) = program.expression_table.expression(expression)
            else {
                break;
            };
            if !matches!(
                borrow.access,
                language_core::ReferenceAccess::Shared | language_core::ReferenceAccess::Mutable
            ) {
                break;
            }
            expression = borrow.target;
        }
        expression
    }

    fn collection_length_of(environment: &ValueEnvironment, observed: Operand) -> Option<Operand> {
        if matches!(observed, Operand::CollectionLength(_)) {
            return Some(observed);
        }
        environment.ordered_values.iter().find_map(|relation| {
            let Operand::CollectionLength(_) = &relation.right else {
                return None;
            };
            (relation.left == observed
                && relation.constraint == RelationConstraint::MinimumDifference(0)
                && environment.ordered_values.iter().any(|opposite| {
                    opposite.constraint == RelationConstraint::MinimumDifference(0)
                        && opposite.left == relation.right
                        && opposite.right == relation.left
                }))
            .then(|| relation.right.clone())
        })
    }

    fn measured_call_length(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        call: &typed_trees::expression::TableCallExpression,
    ) -> Option<Operand> {
        let collection = super::normal_return_length_collection(program, call)?;
        let collection = strip_borrow(program, collection);
        let receiver = ordered_values::operand(program, machine, state, collection, None)?;
        ordered_values::collection_length_operand(program, machine, state, collection, receiver)
    }

    fn length_measure(
        program: &dyn CheckingInput,
        machine: &Machine,
        state: &State,
        expression: ExpressionHandle,
    ) -> Option<Operand> {
        let operation = subslice_expression(program, expression)?;
        if !has_builtin_subslice_meaning(program, machine, Some(state), operation) {
            return None;
        }
        let indexed = program.expression_table.indexed_node(operation)?;
        let range = program.expression_table.range_node(indexed.index)?;
        let start = if range.start.is_valid() {
            ordered_values::operand(program, machine, state, range.start, None)?
        } else {
            integer_operand(0)
        };
        let end = if range.end.is_valid() {
            ordered_values::operand(program, machine, state, range.end, None)?
        } else if range.end_inclusive {
            return None;
        } else {
            let collection = strip_borrow(program, indexed.collection);
            let receiver = ordered_values::operand(program, machine, state, collection, None)?;
            ordered_values::collection_length_operand(
                program, machine, state, collection, receiver,
            )?
        };
        let mut measure = if is_zero(&start) {
            end
        } else {
            binary_operand(BinaryOperator::Subtract, end, start)
        };
        if range.end_inclusive {
            measure = binary_operand(BinaryOperator::Add, measure, integer_operand(1));
        }
        Some(measure)
    }

    fn integer_operand(value: i64) -> Operand {
        Operand::Integer(IntegerLiteral::from_value(value), None)
    }

    fn is_zero(operand: &Operand) -> bool {
        matches!(operand, Operand::Integer(literal, _) if literal.value_i64() == Some(0))
    }

    fn binary_operand(operator: BinaryOperator, left: Operand, right: Operand) -> Operand {
        Operand::Binary {
            operator,
            primitive: Some(PrimitiveType::U64),
            domain: ArithmeticDomain::Exact,
            operands: vec![left, right],
        }
    }

    fn relate_equal(environment: &mut ValueEnvironment, left: Operand, right: Operand) {
        if left == right {
            return;
        }
        for (left, right) in [(left.clone(), right.clone()), (right, left)] {
            let relation = Relation {
                left,
                right,
                constraint: RelationConstraint::MinimumDifference(0),
            };
            if !environment.ordered_values.contains(&relation) {
                environment.ordered_values.push(relation);
            }
        }
    }
}
pub use bigint_interval::{BigIntInterval, bitwise_carrier_bounds, floor_shift_right};
pub use interval::Interval;
pub(crate) use return_ranges::infer_return_interval;
pub use return_ranges::normal_return_integer_bounds;
pub(crate) use selected_scalar_intervals::binary as selected_integer_binary_interval;
pub use selected_scalar_intervals::{
    SelectedScalarIntervalSource, carrier_integer_range, checked_integer_binary_kind,
    integer_range_contains, selected_boolean_decision, selected_scalar_interval,
};
pub(crate) use slice_lengths::{carried_slice_length, publish_slice_length};
pub(crate) mod stored_integer_writes {
    use super::integer_ranges::known_u64_value;
    use super::{Interval, ValueEnvironment};
    use crate::value_custody::places;
    use checked_trees::{CheckedStoredIntegerWrite, StoredIntegerWriteSite};
    use diagnostics::Diagnostic;
    use facts::{FactPlan, PlaceSegment};
    use semantic_vocabulary::{IntegerSign, IntegerType};
    use symbols::SymbolHandle;
    use typed_trees::data::DataMember;
    use typed_trees::expression::ExpressionHandle;
    use typed_trees::machine::Machine;
    use typed_trees::state::State;
    use typed_trees::types::{PrimitiveType, TypeReferenceHandle, TypeReferenceNode};

    pub(crate) mod recast_history {
        use super::*;

        pub(crate) fn projection(
            program: &dyn crate::CheckingInput,
            state: &State,
            source: &crate::LocalWriteSource,
            suffix: &[PlaceSegment],
        ) -> Result<Option<(SymbolHandle, IntegerType)>, ()> {
            let (mut carrier, mut path) = source_coordinates(program, state, source)?;
            path.extend_from_slice(suffix);
            let current = typed_storage_projection(program, carrier, &path)?;
            if !source_geometry::stored_integer_source_may_require_fit(program, state, source)? {
                return Ok(current.stored);
            }
            let logical_primitive = program.primitive_type_reference(
                places::unwrapped_type_reference(program, current.reference).ok_or(())?,
            );
            let mut stored = current.stored;
            let predecessors = source
                .recasts
                .iter()
                .map(|recast| {
                    let (carrier, path) = predecessor_coordinates(program, state, recast)?;
                    let needs_fit =
                        source_geometry::coordinate_requires_fit(program, carrier, &path)?;
                    Ok((carrier, path, needs_fit))
                })
                .collect::<Result<Vec<_>, ()>>()?;
            for (index, recast) in source.recasts.iter().enumerate().rev() {
                if !predecessors[..=index].iter().any(|(_, _, needed)| *needed) {
                    break;
                }
                if carrier != recast.target_type {
                    return Err(());
                }
                let (previous_carrier, mut previous_path, _) = predecessors[index].clone();
                let previous = typed_storage_projection(program, previous_carrier, &previous_path)?;
                let previous_type =
                    places::unwrapped_type_reference(program, previous.reference).ok_or(())?;
                let target_type =
                    places::unwrapped_type_reference(program, recast.target_type).ok_or(())?;
                let relative = if path.is_empty() {
                    Vec::new()
                } else if program.normalized_type_identity(previous_type)
                    == program.normalized_type_identity(target_type)
                {
                    path.clone()
                } else if let [PlaceSegment::Field { symbol }] = path.as_slice() {
                    crate::recast_record_source_leaf(program, previous_type, target_type, *symbol)
                        .ok_or(())?
                        .path
                        .into_iter()
                        .map(|segment| match segment {
                            crate::RecastLeafSegment::Field(symbol) => {
                                Ok(PlaceSegment::Field { symbol })
                            }
                            crate::RecastLeafSegment::Element(index) => {
                                Ok(PlaceSegment::FixedIndex { index })
                            }
                        })
                        .collect::<Result<Vec<_>, ()>>()?
                } else {
                    return Err(());
                };
                previous_path.extend(relative);
                let selected = typed_storage_projection(program, previous_carrier, &previous_path)?;
                if let Some(candidate) = selected.stored {
                    let primitive = program.primitive_type_reference(
                        places::unwrapped_type_reference(program, selected.reference).ok_or(())?,
                    );
                    if primitive.is_none() || primitive != logical_primitive {
                        return Err(());
                    }
                    if stored.is_some_and(|(_, storage)| storage != candidate.1) {
                        return Err(());
                    }
                    stored = Some(candidate);
                }
                carrier = previous_carrier;
                path = previous_path;
            }
            Ok(stored)
        }

        pub(crate) fn predecessor_coordinates(
            program: &dyn crate::CheckingInput,
            state: &State,
            recast: &crate::RecastSource,
        ) -> Result<(TypeReferenceHandle, Vec<PlaceSegment>), ()> {
            let declared = crate::state_root_type(program, state, recast.root).ok_or(())?;
            let (carrier, path) = recast
                .representation
                .as_ref()
                .map(|(carrier, path)| (*carrier, path.clone()))
                .unwrap_or_else(|| (declared, recast.segments.clone()));
            program
                .type_reference_table
                .contains_type_reference(carrier)
                .then_some((carrier, path))
                .ok_or(())
        }
    }
    pub(crate) mod source_geometry {
        use super::*;

        #[derive(Clone, Copy, Default)]
        pub struct StoredIntegerReach {
            pub requires_fit: bool,
            pub has_open_parameters: bool,
        }

        impl StoredIntegerReach {
            fn join(&mut self, other: Self) {
                self.requires_fit |= other.requires_fit;
                self.has_open_parameters |= other.has_open_parameters;
            }

            fn concrete(self) -> Result<bool, ()> {
                if self.has_open_parameters {
                    Err(())
                } else {
                    Ok(self.requires_fit)
                }
            }
        }

        pub(crate) fn stored_integer_source_may_require_fit(
            program: &dyn crate::CheckingInput,
            state: &State,
            source: &crate::LocalWriteSource,
        ) -> Result<bool, ()> {
            stored_integer_source_reach(program, state, source)
                .map_err(|UnestablishedStoredEncoding| ())?
                .concrete()
        }

        pub fn stored_integer_source_reach(
            program: &dyn crate::CheckingInput,
            state: &State,
            source: &crate::LocalWriteSource,
        ) -> Result<StoredIntegerReach, UnestablishedStoredEncoding> {
            let targets = crate::layout_checking_targets(
                program,
                source_layout_roots(program, state, source)?,
            )?;
            let mut reach = StoredIntegerReach::default();
            for target in targets {
                let alternative = crate::LayoutCheckingContext::new(program, target);
                reach.join(source_reach_alternative(&alternative, state, source)?);
            }
            Ok(reach)
        }

        fn source_reach_alternative(
            program: &dyn crate::CheckingInput,
            state: &State,
            source: &crate::LocalWriteSource,
        ) -> Result<StoredIntegerReach, ()> {
            let (carrier, path) = source_coordinates(program, state, source)?;
            let mut reach = coordinate_reach(program, carrier, &path)?;
            for recast in &source.recasts {
                let (carrier, path) =
                    recast_history::predecessor_coordinates(program, state, recast)?;
                let previous_reach = coordinate_reach(program, carrier, &path)?;
                reach.has_open_parameters |= previous_reach.has_open_parameters;
                if previous_reach.requires_fit {
                    let previous = typed_storage_projection(program, carrier, &path)?;
                    if !crate::value_custody::recasts::recast_representations_equivalent(
                        program,
                        previous.reference,
                        recast.target_type,
                        previous.stored.map(|(_, storage)| storage),
                    ) {
                        reach.requires_fit = true;
                    }
                }
            }
            Ok(reach)
        }

        pub(crate) fn coordinate_requires_fit(
            program: &dyn crate::CheckingInput,
            carrier: TypeReferenceHandle,
            path: &[PlaceSegment],
        ) -> Result<bool, ()> {
            coordinate_reach(program, carrier, path)?.concrete()
        }

        fn coordinate_reach(
            program: &dyn crate::CheckingInput,
            carrier: TypeReferenceHandle,
            path: &[PlaceSegment],
        ) -> Result<StoredIntegerReach, ()> {
            let projection = typed_storage_projection(program, carrier, path)?;
            if let Some((field, _)) = projection.stored {
                return Ok(StoredIntegerReach {
                    requires_fit: field_requires_fit(
                        program,
                        projection.storage_carrier.ok_or(())?,
                        field,
                    )?,
                    has_open_parameters: false,
                });
            }
            if !path.is_empty() && crate::reference_shell(program, projection.reference).is_some() {
                return Err(());
            }
            let reference =
                places::unwrapped_type_reference(program, projection.reference).ok_or(())?;
            descendants_reach(program, reference, &mut Vec::new())
        }

        fn field_requires_fit(
            program: &dyn crate::CheckingInput,
            carrier: TypeReferenceHandle,
            field: SymbolHandle,
        ) -> Result<bool, ()> {
            let plan = program.plan_laid_layout_for_type(carrier).ok_or(())?;
            let index = plan
                .field_symbols
                .iter()
                .position(|candidate| *candidate == field)
                .ok_or(())?;
            let geometry = plan
                .geometry_for_target(program.typed_program(), program.layout_target())
                .ok_or(())?;
            let integer = geometry
                .integer_fields
                .iter()
                .find(|integer| integer.field_index == index)
                .ok_or(())?;
            Ok(!integer.write_is_total)
        }

        fn descendants_reach(
            program: &dyn crate::CheckingInput,
            reference: TypeReferenceHandle,
            active: &mut Vec<TypeReferenceHandle>,
        ) -> Result<StoredIntegerReach, ()> {
            if !program
                .type_reference_table
                .contains_type_reference(reference)
                || crate::reference_shell(program, reference).is_some()
            {
                return Err(());
            }
            let reference = places::unwrapped_type_reference(program, reference).ok_or(())?;
            if crate::proof_only_classification(program)
                .proof_only_mention(program, reference)
                .is_some()
            {
                return Ok(StoredIntegerReach::default());
            }
            if active.contains(&reference) {
                return Ok(StoredIntegerReach::default());
            }
            if program.primitive_type_reference(reference).is_some() {
                return Ok(StoredIntegerReach::default());
            }
            match program.type_reference_table.type_reference(reference) {
                TypeReferenceNode::Unit => return Ok(StoredIntegerReach::default()),
                TypeReferenceNode::Named { symbol, .. }
                    if symbol.is_valid()
                        && program.symbols.get(*symbol).kind
                            == symbols::SymbolKind::TypeParameter =>
                {
                    return Ok(StoredIntegerReach {
                        requires_fit: false,
                        has_open_parameters: true,
                    });
                }
                TypeReferenceNode::FixedArray { element_type, .. }
                | TypeReferenceNode::Slice { element_type } => {
                    active.push(reference);
                    let result = descendants_reach(program, *element_type, active);
                    active.pop();
                    return result;
                }
                _ => {}
            }
            let data = places::data_definition_for_type(program, reference).ok_or(())?;
            active.push(reference);
            let result = (|| {
                let mut reach = StoredIntegerReach::default();
                for field in program.data_member_fields(program.data_members(data)) {
                    if field.relevance.is_erased() {
                        continue;
                    }
                    if stored_integer_field_type(program, reference, field.symbol)?.is_some()
                        && field_requires_fit(program, reference, field.symbol)?
                    {
                        reach.requires_fit = true;
                    }
                    reach.join(descendants_reach(program, field.type_reference, active)?);
                }
                Ok(reach)
            })();
            active.pop();
            result
        }
    }
    pub use source_geometry::{StoredIntegerReach, stored_integer_source_reach};

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct UnestablishedStoredEncoding;

    impl From<()> for UnestablishedStoredEncoding {
        fn from((): ()) -> Self {
            Self
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn validate_stored_integer_write(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        destination: ExpressionHandle,
        value: ExpressionHandle,
        origins: Option<&[crate::LocalWriteOrigin]>,
        interval: Interval,
        primitive: Option<PrimitiveType>,
        environment: &ValueEnvironment,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> Vec<CheckedStoredIntegerWrite> {
        let destination_primitive =
            places::declared_place_type_raw(program, machine, state, destination)
                .map(|reference| places::assignment_value_type(program, reference))
                .and_then(|reference| program.primitive_type_reference(reference));
        if !destination_primitive.is_some_and(|primitive| primitive.accepts_integer_literal())
            || !program.plan_laid_layouts.iter().any(|plan| {
                plan.geometries(program.typed_program())
                    .any(|geometry| !geometry.integer_fields.is_empty())
            })
        {
            return Vec::new();
        }
        let Some(state) = state else {
            return Vec::new();
        };
        let roots = destination_layout_roots(program, state, destination, origins);
        let targets = roots.and_then(|roots| crate::layout_checking_targets(program, roots));
        let Ok(targets) = targets else {
            diagnostics.push(Diagnostic::error(format!(
                "IntegerAt store in {owner} has no complete exact layout alternative roster"
            )));
            return Vec::new();
        };
        let mut projections = Vec::new();
        for target in targets {
            let alternative = crate::LayoutCheckingContext::new(program, target);
            let Ok(selected) =
                destination_projections(&alternative, machine, state, destination, origins)
            else {
                diagnostics.push(Diagnostic::error(format!(
                "IntegerAt store in {owner} has no exact stored field geometry or reference origin"
            )));
                return Vec::new();
            };
            projections.extend(selected);
        }

        let mut writes = Vec::new();
        for (field, stored) in projections {
            let fits =
                stored_integer_value_fits(program, value, interval, primitive, environment, stored);
            if !fits {
                diagnostics.push(Diagnostic::error(format!(
                    "IntegerAt store in {owner} requires a value proven to fit {}-bit {} storage",
                    stored.bits(),
                    match stored.sign() {
                        IntegerSign::Signed => "signed",
                        IntegerSign::Unsigned => "unsigned",
                    },
                )));
                return Vec::new();
            }
            let write = CheckedStoredIntegerWrite {
                machine: machine.symbol,
                state: state.symbol,
                site: StoredIntegerWriteSite::Assignment { destination },
                value,
                field,
                stored_type: stored,
            };
            if !writes.contains(&write) {
                writes.push(write);
            }
        }
        writes
    }

    fn destination_layout_roots(
        program: &dyn crate::CheckingInput,
        state: &State,
        destination: ExpressionHandle,
        origins: Option<&[crate::LocalWriteOrigin]>,
    ) -> Result<Vec<TypeReferenceHandle>, ()> {
        let mut facts = FactPlan::default();
        let place = facts.append_place_from_expression(program, destination);
        let place = facts.places.get(place);
        let root = place.root.as_symbol().ok_or(())?;
        let segments = facts.place_segments.span_or_empty(place.segments);
        let mut roots = vec![crate::state_root_type(program, state, root).ok_or(())?];
        let candidates: Vec<_> = origins
            .unwrap_or(&[])
            .iter()
            .filter(|origin| {
                origin.local_symbol == root && segments.starts_with(&origin.local_segments)
            })
            .collect();
        if let Some(longest) = candidates
            .iter()
            .map(|origin| origin.local_segments.len())
            .max()
        {
            for origin in candidates
                .into_iter()
                .filter(|origin| origin.local_segments.len() == longest)
            {
                if let Some(source) = &origin.source {
                    roots.extend(source_layout_roots(program, state, source)?);
                }
            }
        }
        Ok(roots)
    }

    pub(crate) fn source_layout_roots(
        program: &dyn crate::CheckingInput,
        state: &State,
        source: &crate::LocalWriteSource,
    ) -> Result<Vec<TypeReferenceHandle>, ()> {
        let mut roots = vec![source_coordinates(program, state, source)?.0];
        for recast in &source.recasts {
            roots.push(recast.target_type);
            roots.push(recast_history::predecessor_coordinates(program, state, recast)?.0);
        }
        Ok(roots)
    }

    pub fn stored_integer_source_projections(
        program: &dyn crate::CheckingInput,
        state: &State,
        source: &crate::LocalWriteSource,
        suffix: &[PlaceSegment],
    ) -> Result<Vec<(SymbolHandle, IntegerType)>, UnestablishedStoredEncoding> {
        let targets =
            crate::layout_checking_targets(program, source_layout_roots(program, state, source)?)?;
        let mut projections = Vec::new();
        for target in targets {
            let alternative = crate::LayoutCheckingContext::new(program, target);
            if let Some(projection) =
                stored_integer_source_projection(&alternative, state, source, suffix)?
                && !projections.contains(&projection)
            {
                projections.push(projection);
            }
        }
        Ok(projections)
    }

    fn destination_projections(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: &State,
        destination: ExpressionHandle,
        origins: Option<&[crate::LocalWriteOrigin]>,
    ) -> Result<Vec<(SymbolHandle, IntegerType)>, ()> {
        let mut facts = FactPlan::default();
        let place = facts.append_place_from_expression(program, destination);
        let place = facts.places.get(place);
        let Some(root) = place.root.as_symbol() else {
            return Err(());
        };
        let segments = facts.place_segments.span_or_empty(place.segments);
        if !crate::place_has_builtin_coordinates(program, machine, Some(state), destination) {
            return Err(());
        }
        let direct_type = crate::state_root_type(program, state, root).ok_or(())?;
        if matches!(segments.last(), Some(PlaceSegment::Field { .. }))
            && places::declared_place_type_raw(program, machine, Some(state), destination)
                .is_some_and(|reference| {
                    crate::reference_shell(program, reference).is_none()
                        && program.primitive_type_reference(reference).is_some()
                })
            && let Ok(projection) = typed_projection(program, direct_type, segments)
        {
            return Ok(projection.into_iter().collect());
        }
        let origins = origins.unwrap_or(&[]);
        let candidates = origins
            .iter()
            .filter(|origin| {
                origin.local_symbol == root && segments.starts_with(&origin.local_segments)
            })
            .collect::<Vec<_>>();
        let longest = candidates
            .iter()
            .map(|origin| origin.local_segments.len())
            .max();
        if let Some(longest) = longest {
            let mut projections = Vec::new();
            for origin in candidates
                .into_iter()
                .filter(|origin| origin.local_segments.len() == longest)
            {
                let source = origin.source.as_ref().ok_or(())?;
                if let Some(projection) =
                    stored_integer_source_projection(program, state, source, &segments[longest..])?
                    && !projections.contains(&projection)
                {
                    projections.push(projection);
                }
            }
            return Ok(projections);
        }
        if program.state_local_declaration(state, root).is_some()
            && crate::reference_shell(program, direct_type).is_some()
        {
            return Err(());
        }
        Ok(typed_projection(program, direct_type, segments)?
            .into_iter()
            .collect())
    }

    pub(crate) fn stored_integer_source_projection(
        program: &dyn crate::CheckingInput,
        state: &State,
        source: &crate::LocalWriteSource,
        suffix: &[PlaceSegment],
    ) -> Result<Option<(SymbolHandle, IntegerType)>, ()> {
        if source.collection_coarse && !suffix.is_empty() {
            return Err(());
        }
        recast_history::projection(program, state, source, suffix)
    }

    fn source_coordinates(
        program: &dyn crate::CheckingInput,
        state: &State,
        source: &crate::LocalWriteSource,
    ) -> Result<(TypeReferenceHandle, Vec<PlaceSegment>), ()> {
        if !source.root.is_valid() && source.invocation_result.is_none() {
            return Err(());
        }
        let declared = match source.invocation_result {
            Some(home) => home.referent,
            None => crate::state_root_type(program, state, source.root).ok_or(())?,
        };
        let (carrier, path) = match &source.representation {
            Some((carrier, path)) => (*carrier, path.clone()),
            None => (declared, source.segments.clone()),
        };
        program
            .type_reference_table
            .contains_type_reference(carrier)
            .then_some((carrier, path))
            .ok_or(())
    }

    fn typed_projection(
        program: &dyn crate::CheckingInput,
        carrier: TypeReferenceHandle,
        path: &[PlaceSegment],
    ) -> Result<Option<(SymbolHandle, IntegerType)>, ()> {
        Ok(typed_storage_projection(program, carrier, path)?.stored)
    }

    pub(crate) struct StorageProjection {
        reference: TypeReferenceHandle,
        stored: Option<(SymbolHandle, IntegerType)>,
        storage_carrier: Option<TypeReferenceHandle>,
    }

    fn structural_collection_carrier(
        program: &dyn crate::CheckingInput,
        mut carrier: TypeReferenceHandle,
    ) -> Result<TypeReferenceHandle, ()> {
        for _ in 0..8 {
            carrier = places::unwrapped_type_reference(program, carrier).ok_or(())?;
            match program.type_reference_table.type_reference(carrier) {
                TypeReferenceNode::FixedArray { .. } | TypeReferenceNode::Slice { .. } => {
                    return Ok(carrier);
                }
                TypeReferenceNode::Named { symbol, .. } => {
                    let Some(origin) = program
                        .data_definition_by_symbol(*symbol)
                        .and_then(|data| data.generic_instance)
                        .filter(|origin| origin.is_valid() && *origin != carrier)
                    else {
                        return Ok(carrier);
                    };
                    carrier = program
                        .type_reference_table
                        .unconstrained_type_reference(origin);
                }
                _ => return Ok(carrier),
            }
        }
        Err(())
    }

    fn typed_storage_projection(
        program: &dyn crate::CheckingInput,
        mut carrier: TypeReferenceHandle,
        path: &[PlaceSegment],
    ) -> Result<StorageProjection, ()> {
        let mut selected_case = None;
        for (position, segment) in path.iter().enumerate() {
            if position != 0 && crate::reference_shell(program, carrier).is_some() {
                return Err(());
            }
            carrier = places::unwrapped_type_reference(program, carrier).ok_or(())?;
            match segment {
                PlaceSegment::Field { symbol } => {
                    let data = places::data_definition_for_type(program, carrier).ok_or(())?;
                    let field = if let Some(case) = selected_case.take() {
                        let variant = program
                            .data_members(data)
                            .iter()
                            .find_map(|member| match member {
                                DataMember::Variant(variant) if variant.symbol == case => {
                                    Some(variant)
                                }
                                _ => None,
                            })
                            .ok_or(())?;
                        program.data_payload_field_by_symbol(variant, *symbol)
                    } else {
                        program
                            .data_members(data)
                            .iter()
                            .find_map(|member| match member {
                                DataMember::Field(field) if field.symbol == *symbol => Some(field),
                                _ => None,
                            })
                    }
                    .ok_or(())?;
                    if position + 1 == path.len() {
                        return Ok(StorageProjection {
                            storage_carrier: Some(carrier),
                            reference: field.type_reference,
                            stored: stored_integer_field_type(program, carrier, field.symbol)?
                                .map(|stored| (field.symbol, stored)),
                        });
                    }
                    carrier = field.type_reference;
                }
                PlaceSegment::FixedIndex { index } => {
                    carrier = structural_collection_carrier(program, carrier)?;
                    carrier = match program.type_reference_table.type_reference(carrier) {
                        TypeReferenceNode::FixedArray {
                            element_type,
                            length: typed_trees::types::FixedArrayLength::Literal(length),
                        } if index < length => *element_type,
                        TypeReferenceNode::Slice { element_type } => *element_type,
                        _ => return Err(()),
                    };
                }
                PlaceSegment::Index { .. } => {
                    match program.type_reference_table.type_reference(carrier) {
                        TypeReferenceNode::FixedArray { element_type, .. }
                        | TypeReferenceNode::Slice { element_type } => carrier = *element_type,
                        _ => return Err(()),
                    }
                }
                PlaceSegment::Case { variant } => {
                    if selected_case.replace(*variant).is_some() {
                        return Err(());
                    }
                }
                PlaceSegment::OpaqueRange => {
                    match program.type_reference_table.type_reference(carrier) {
                        TypeReferenceNode::FixedArray { .. } | TypeReferenceNode::Slice { .. } => {}
                        _ => return Err(()),
                    }
                }
                PlaceSegment::FixedRange { start, end } => {
                    if start > end {
                        return Err(());
                    }
                    match program.type_reference_table.type_reference(carrier) {
                        TypeReferenceNode::FixedArray {
                            length: typed_trees::types::FixedArrayLength::Literal(length),
                            ..
                        } if end <= length => {}
                        TypeReferenceNode::Slice { .. } => {}
                        _ => return Err(()),
                    }
                }
            }
        }
        if selected_case.is_some() {
            return Err(());
        }
        Ok(StorageProjection {
            storage_carrier: None,
            reference: carrier,
            stored: None,
        })
    }

    pub(crate) fn stored_integer_field_type(
        program: &dyn crate::CheckingInput,
        carrier: TypeReferenceHandle,
        field: SymbolHandle,
    ) -> Result<Option<IntegerType>, ()> {
        let carrier = places::unwrapped_type_reference(program, carrier).ok_or(())?;
        let data = places::data_definition_for_type(program, carrier).ok_or(())?;
        let Some(plan) = program.plan_laid_layout_for_data(data) else {
            return Ok(None);
        };
        let index = plan
            .field_symbols
            .iter()
            .position(|candidate| *candidate == field)
            .ok_or(())?;
        let geometry = plan
            .geometry_for_target(program.typed_program(), program.layout_target())
            .ok_or(())?;
        let Some(integer) = geometry
            .integer_fields
            .iter()
            .find(|integer| integer.field_index == index)
        else {
            return Ok(None);
        };
        let sign = match integer.interpretation {
            layout_plans::IntegerInterpretation::Signed => IntegerSign::Signed,
            layout_plans::IntegerInterpretation::Unsigned => IntegerSign::Unsigned,
        };
        IntegerType::new(sign, integer.stored_width_bits)
            .map(Some)
            .map_err(|_| ())
    }

    pub(crate) fn stored_integer_value_fits(
        program: &dyn crate::CheckingInput,
        value: ExpressionHandle,
        interval: Interval,
        primitive: Option<PrimitiveType>,
        environment: &ValueEnvironment,
        stored: IntegerType,
    ) -> bool {
        if let Some(value) = known_u64_value(program, environment, value) {
            fits_bounds(stored, i128::from(value), i128::from(value))
        } else {
            interval_fits(stored, interval, primitive)
        }
    }

    fn interval_fits(
        stored: IntegerType,
        interval: Interval,
        primitive: Option<PrimitiveType>,
    ) -> bool {
        let carrier = primitive
            .filter(|primitive| primitive.accepts_integer_literal())
            .and_then(|primitive| {
                let bits = primitive.scalar_byte_size()?.checked_mul(8)?;
                Some(if primitive.is_signed_integer() {
                    (-(1_i128 << (bits - 1)), (1_i128 << (bits - 1)) - 1)
                } else {
                    (0, (1_i128 << bits) - 1)
                })
            });
        let low = match (interval.low().map(i128::from), carrier) {
            (Some(low), Some((minimum, _))) => Some(low.max(minimum)),
            (low, None) => low,
            (None, Some((minimum, _))) => Some(minimum),
        };
        let high = match (interval.high().map(i128::from), carrier) {
            (Some(high), Some((_, maximum))) => Some(high.min(maximum)),
            (high, None) => high,
            (None, Some((_, maximum))) => Some(maximum),
        };
        low.zip(high)
            .is_some_and(|(low, high)| low <= high && fits_bounds(stored, low, high))
    }

    fn fits_bounds(stored: IntegerType, low: i128, high: i128) -> bool {
        let bits = stored.bits();
        if bits == 0 || bits > 64 || !bits.is_multiple_of(8) {
            return false;
        }
        let (minimum, maximum) = match stored.sign() {
            IntegerSign::Signed => (-(1_i128 << (bits - 1)), (1_i128 << (bits - 1)) - 1),
            IntegerSign::Unsigned => (0, (1_i128 << bits) - 1),
        };
        low >= minimum && high <= maximum
    }
}
pub(crate) use guard_narrowing::{
    OccurrenceValueEnvironments, occurrence_integer_child_values, occurrence_value_environment,
    occurrence_value_environments,
};
pub(crate) mod storage_formations {
    use diagnostics::Diagnostic;
    use symbols::SymbolHandle;
    use typed_trees::expression::ExpressionHandle;

    #[derive(Debug, Clone, PartialEq, Eq)]
    pub(crate) struct PendingIntegerFormation {
        pub(crate) machine: SymbolHandle,
        pub(crate) state: SymbolHandle,
        pub(crate) expression: ExpressionHandle,
        pub(crate) other_conditions_proven: bool,
        pub(crate) diagnostic: String,
    }

    pub(crate) struct DischargedFormations {
        pub(crate) proven: Vec<ExpressionHandle>,
        pub(crate) overflow: Vec<Diagnostic>,
    }

    pub(crate) fn discharge(
        program: &dyn crate::CheckingInput,
        pending: &[PendingIntegerFormation],
    ) -> Result<DischargedFormations, Vec<Diagnostic>> {
        let mut proven = Vec::new();
        let mut diagnostics = Vec::new();
        for obligation in pending {
            let fits = program.machine(obligation.machine).is_some_and(|machine| {
            program
                .state_in_machine(machine, obligation.state)
                .is_some_and(|state| {
                    crate::proof_contracts::contract_entailment::exact_binary_formation_at_occurrence(
                        program,
                        machine,
                        state,
                        obligation.expression,
                    )
                    .proven
                })
        });
            if !fits {
                let mut diagnostic = Diagnostic::error(obligation.diagnostic.clone());
                let expression_span = program.expression_table.source_span(obligation.expression);
                diagnostic.source_span = (expression_span != source::SourceSpan::default())
                    .then_some(expression_span)
                    .or_else(|| {
                        program
                            .symbols
                            .symbol_provenance_source_span(obligation.machine)
                    });
                diagnostics.push(diagnostic);
            } else if obligation.other_conditions_proven {
                proven.push(obligation.expression);
            }
        }
        let (overflow, blocking): (Vec<_>, Vec<_>) = diagnostics
            .into_iter()
            .partition(crate::program_validation::is_exact_overflow_diagnostic);
        if !blocking.is_empty() {
            let mut diagnostics = overflow;
            diagnostics.extend(blocking);
            return Err(diagnostics);
        }
        Ok(DischargedFormations { proven, overflow })
    }
}
pub(crate) mod total_specification {
    use super::guard_narrowing::{comparison_bound, narrow_environment_by_condition};
    use super::{
        ArithmeticDomain, BinaryOperator, Diagnostic, ExpressionHandle, ExpressionNode, Interval,
        Machine, PrimitiveType, ProofFact, SignatureContractKind, State, TypeReferenceHandle,
        TypeReferenceNode, ValueEnvironment, abstract_shift_count, division_definedness,
        is_arithmetic, literal_i64, place_path, range_constraint_interval,
    };
    use crate::frozen_program::expression_table;
    use crate::machine_calls::machine_parameters::contract_facts::contract_kind_name;
    use crate::proof_contracts::arithmetic_domains::expression_analysis::analyze;
    use crate::proof_contracts::arithmetic_domains::integer_ranges::{
        integer_interval_fits_primitive, primitive_name, primitive_range,
        validate_anonymous_integer_primitive_range,
    };
    use crate::proof_contracts::arithmetic_domains::operand_reports::arithmetic_operator_spelling;
    use language_core::is_self_receiver;

    pub(crate) fn validate_total_specification_arithmetic(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> super::ArithmeticDecisions {
        validate_total_specification_arithmetic_with_premises(
            program,
            machine,
            state,
            expression,
            environment,
            None,
            owner,
            diagnostics,
        )
    }

    fn validate_total_specification_arithmetic_with_premises(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        state: Option<&State>,
        expression: ExpressionHandle,
        environment: &ValueEnvironment,
        prior_facts: Option<&[ExpressionHandle]>,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) -> super::ArithmeticDecisions {
        let diagnostics_before = diagnostics.len();
        if let Some(state) = state {
            crate::value_custody::expression_types::validate_float_expression_formats(
                program,
                state.symbol,
                expression,
                &|operand| {
                    crate::expression_result_type_reference(program, machine, state, operand)
                },
                diagnostics,
            );
        }
        let mut formation_diagnostics = Vec::new();
        let analyze_term = |candidate, diagnostics: &mut Vec<Diagnostic>| {
            if let Some(prior_facts) = prior_facts {
                super::expression_analysis::analyze_specification(
                    program,
                    machine,
                    state,
                    candidate,
                    environment,
                    prior_facts,
                    owner,
                    diagnostics,
                )
            } else {
                analyze(
                    program,
                    machine,
                    state,
                    candidate,
                    environment,
                    None,
                    ArithmeticDomain::Exact,
                    owner,
                    true,
                    false,
                    diagnostics,
                )
            }
        };
        let formed = analyze_term(expression, &mut formation_diagnostics);
        diagnostics.extend(
            formation_diagnostics
                .into_iter()
                .filter(Diagnostic::is_error),
        );
        let analyzed = |candidate| {
            let mut ignored_diagnostics = Vec::new();
            analyze_term(candidate, &mut ignored_diagnostics)
        };
        let expression_domain = |candidate| analyzed(candidate).value.domain;
        let expression_interval = |candidate| Some(analyzed(candidate).value.interval);
        validate_total_specification_arithmetic_for_domains(
            program,
            expression,
            owner,
            &expression_domain,
            &expression_interval,
            &|candidate| {
                crate::proof_contracts::bound_expression_meaning::builtin_arithmetic(
                    program, machine, state, candidate,
                )
            },
            &|_, _, _| {},
            true,
            diagnostics,
        );
        if diagnostics[diagnostics_before..]
            .iter()
            .any(Diagnostic::is_error)
        {
            super::ArithmeticDecisions::default()
        } else {
            formed.decisions
        }
    }

    fn validate_total_specification_arithmetic_for_domains(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
        owner: &str,
        expression_domain: &impl Fn(ExpressionHandle) -> Option<ArithmeticDomain>,
        expression_interval: &impl Fn(ExpressionHandle) -> Option<Interval>,
        builtin_arithmetic: &impl Fn(ExpressionHandle) -> bool,
        numeric_coercion: &impl Fn(ExpressionHandle, TypeReferenceHandle, &mut Vec<Diagnostic>),
        integer_formation_prevalidated: bool,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        #[allow(clippy::too_many_arguments)]
        fn walk(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            owner: &str,
            expression_domain: &impl Fn(ExpressionHandle) -> Option<ArithmeticDomain>,
            expression_interval: &impl Fn(ExpressionHandle) -> Option<Interval>,
            builtin_arithmetic: &impl Fn(ExpressionHandle) -> bool,
            numeric_coercion: &impl Fn(ExpressionHandle, TypeReferenceHandle, &mut Vec<Diagnostic>),
            integer_formation_prevalidated: bool,
            diagnostics: &mut Vec<Diagnostic>,
            visited: &mut Vec<ExpressionHandle>,
        ) {
            if !expression.is_valid() || visited.contains(&expression) {
                return;
            }
            visited.push(expression);

            let recurse = |child, diagnostics: &mut Vec<Diagnostic>, visited: &mut Vec<_>| {
                walk(
                    program,
                    child,
                    owner,
                    expression_domain,
                    expression_interval,
                    builtin_arithmetic,
                    numeric_coercion,
                    integer_formation_prevalidated,
                    diagnostics,
                    visited,
                );
            };
            match expression_table(program).expression(expression) {
                ExpressionNode::Binary(binary) => {
                    recurse(binary.left, diagnostics, visited);
                    recurse(binary.right, diagnostics, visited);
                    if !is_arithmetic(binary.operator) || !builtin_arithmetic(expression) {
                        return;
                    }

                    let selected = expression_domain(expression);
                    if selected == Some(ArithmeticDomain::Trapping) {
                        diagnostics.push(Diagnostic::error(format!(
                        "direct Trapping arithmetic `{}` is illegal in {owner}: specification terms are total and cannot transfer runtime control. Use `embed(..)` for unbounded proof `Int` mathematics, or explicitly cast the operands to the same unqualified carrier and discharge the resulting Exact formation obligations",
                        arithmetic_operator_spelling(binary.operator),
                    )));
                    }
                    if !integer_formation_prevalidated
                        && matches!(
                            selected,
                            Some(ArithmeticDomain::Wrapping | ArithmeticDomain::Saturating)
                        )
                        && matches!(
                            binary.operator,
                            BinaryOperator::Divide | BinaryOperator::Modulo
                        )
                    {
                        let divisor = expression_interval(binary.right);
                        let proven_nonzero = divisor.is_some_and(Interval::excludes_zero);
                        if !proven_nonzero {
                            let operation = if binary.operator == BinaryOperator::Divide {
                                "division"
                            } else {
                                "remainder"
                            };
                            diagnostics.push(Diagnostic::error(format!(
                            "partial {operation} in {owner}: `{}` defines carrier overflow but not a zero divisor; the divisor must be proven nonzero by an independently accepted prior fact",
                            selected.expect("selected total arithmetic policy").name(),
                        )));
                        }
                    }
                }
                ExpressionNode::Cast(cast) => {
                    recurse(cast.value, diagnostics, visited);
                    if integer_formation_prevalidated || cast.form.is_recast() {
                        return;
                    }
                    numeric_coercion(cast.value, cast.target_type, diagnostics);
                }
                ExpressionNode::Call(call) => {
                    recurse(call.receiver, diagnostics, visited);
                    for argument in expression_table(program).expression_handles(call.arguments) {
                        recurse(*argument, diagnostics, visited);
                    }
                    if !integer_formation_prevalidated
                        && call.exact_coercion_target.is_valid()
                        && let [operand] =
                            expression_table(program).expression_handles(call.arguments)
                    {
                        numeric_coercion(*operand, call.exact_coercion_target, diagnostics);
                    }
                }
                other => crate::queries::expression_traversal::children(program, other, |child| {
                    recurse(child, diagnostics, visited);
                }),
            }
        }

        walk(
            program,
            expression,
            owner,
            expression_domain,
            expression_interval,
            builtin_arithmetic,
            numeric_coercion,
            integer_formation_prevalidated,
            diagnostics,
            &mut Vec::new(),
        );
    }

    pub(crate) fn validate_machine_total_specification_arithmetic(
        program: &dyn crate::CheckingInput,
        machine: &Machine,
        diagnostics: &mut Vec<Diagnostic>,
        formation_obligations: &mut Vec<checked_trees::IntegerRangeObligation>,
    ) -> super::ArithmeticDecisions {
        let mut decisions = super::ArithmeticDecisions::default();
        let entry_state = program.machine_states(machine).first();
        let mut machine_environment = ValueEnvironment::new();
        let mut machine_prior_facts = Vec::new();
        let mut completion_environment = ValueEnvironment::new();
        let mut completion_prior_facts = Vec::new();
        for contract in program.machine_contracts(machine) {
            let owner = format!(
                "machine `{}` {} contract",
                machine.name,
                contract_kind_name(&contract.kind),
            );
            for fact in program.proof_facts.span_or_empty(contract.facts) {
                let diagnostics_before = diagnostics.len();
                let obligations_before = formation_obligations.len();
                let (environment, prior_facts) = if contract.kind == SignatureContractKind::Ensures
                {
                    (&completion_environment, &completion_prior_facts)
                } else {
                    (&machine_environment, &machine_prior_facts)
                };
                crate::proof_contracts::contract_entailment::validate_specification_call_requirements(
                program,
                machine,
                entry_state,
                fact,
                prior_facts,
                &owner,
                diagnostics,
                formation_obligations,
            );
                crate::proof_contracts::contract_entailment::validate_proof_fact_integer_formation(
                    program,
                    machine.symbol,
                    fact,
                    prior_facts,
                    &owner,
                    &|candidate| {
                        crate::proof_contracts::bound_expression_meaning::builtin_arithmetic(
                            program,
                            machine,
                            entry_state,
                            candidate,
                        )
                    },
                    diagnostics,
                );
                if let Some(expression) = fact.as_expression() {
                    decisions.extend(validate_total_specification_arithmetic_with_premises(
                        program,
                        machine,
                        entry_state,
                        *expression,
                        environment,
                        Some(prior_facts),
                        &owner,
                        diagnostics,
                    ));
                    if contract.kind == SignatureContractKind::Requires
                        && diagnostics.len() == diagnostics_before
                    {
                        machine_prior_facts.push(*expression);
                        if let Some(entry_state) = entry_state {
                            narrow_environment_by_condition(
                                program,
                                machine,
                                Some(entry_state),
                                &mut machine_environment,
                                *expression,
                                true,
                            );
                        }
                    }
                    // Earlier, fully formed postconditions guard later clauses of
                    // that same conjunction. They are not entry assumptions or
                    // evidence for proving the machine's postconditions.
                    if matches!(
                        contract.kind,
                        SignatureContractKind::Requires | SignatureContractKind::Ensures
                    ) && diagnostics.len() == diagnostics_before
                        && formation_obligations.len() == obligations_before
                    {
                        completion_prior_facts.push(*expression);
                        if let Some(entry_state) = entry_state {
                            narrow_environment_by_condition(
                                program,
                                machine,
                                Some(entry_state),
                                &mut completion_environment,
                                *expression,
                                true,
                            );
                        }
                    }
                }
            }
        }
        for state in program.machine_states(machine) {
            let mut state_environment = machine_environment.clone();
            let mut state_prior_facts = machine_prior_facts.clone();
            let mut state_completion_environment = machine_environment.clone();
            let mut state_completion_facts = machine_prior_facts.clone();
            for contract in program.state_contracts(state) {
                let owner = format!(
                    "machine `{}` state `{}` {} contract",
                    machine.name,
                    state.name,
                    contract_kind_name(&contract.kind),
                );
                for fact in program.proof_facts.span_or_empty(contract.facts) {
                    let diagnostics_before = diagnostics.len();
                    let obligations_before = formation_obligations.len();
                    let (environment, prior_facts) =
                        if contract.kind == SignatureContractKind::Ensures {
                            (&state_completion_environment, &state_completion_facts)
                        } else {
                            (&state_environment, &state_prior_facts)
                        };
                    crate::proof_contracts::contract_entailment::validate_specification_call_requirements(
                    program, machine, Some(state), fact, prior_facts, &owner, diagnostics,
                    formation_obligations,
                );
                    crate::proof_contracts::contract_entailment::validate_proof_fact_integer_formation(
                    program,
                    state.symbol,
                    fact,
                    prior_facts,
                    &owner,
                    &|candidate| {
                        crate::proof_contracts::bound_expression_meaning::builtin_arithmetic(
                            program,
                            machine,
                            Some(state),
                            candidate,
                        )
                    },
                    diagnostics,
                );
                    if let Some(expression) = fact.as_expression() {
                        decisions.extend(validate_total_specification_arithmetic_with_premises(
                            program,
                            machine,
                            Some(state),
                            *expression,
                            environment,
                            Some(prior_facts),
                            &owner,
                            diagnostics,
                        ));
                        if contract.kind == SignatureContractKind::Requires
                            && diagnostics.len() == diagnostics_before
                        {
                            state_prior_facts.push(*expression);
                            narrow_environment_by_condition(
                                program,
                                machine,
                                Some(state),
                                &mut state_environment,
                                *expression,
                                true,
                            );
                        }
                        if matches!(
                            contract.kind,
                            SignatureContractKind::Requires | SignatureContractKind::Ensures
                        ) && diagnostics.len() == diagnostics_before
                            && formation_obligations.len() == obligations_before
                        {
                            state_completion_facts.push(*expression);
                            narrow_environment_by_condition(
                                program,
                                machine,
                                Some(state),
                                &mut state_completion_environment,
                                *expression,
                                true,
                            );
                        }
                    }
                }
            }
        }
        decisions
    }

    #[derive(Clone, Copy, Default)]
    pub(crate) struct AbstractSpecificationBindings<'program> {
        owner_symbol: symbols::SymbolHandle,
        parameters: &'program [typed_trees::signature::StateParameter],
        result_type: Option<TypeReferenceHandle>,
        domain: Option<&'program typed_trees::domain::DomainDefinition>,
        data: Option<&'program typed_trees::data::DataDefinition>,
    }

    fn abstract_specification_result_type(
        program: &dyn crate::CheckingInput,
        bindings: AbstractSpecificationBindings<'_>,
        expression: ExpressionHandle,
    ) -> Option<TypeReferenceHandle> {
        crate::value_custody::expression_types::declaration_expression_result_type_reference(
            program,
            bindings.owner_symbol,
            None,
            &|expression| abstract_specification_place_type(program, bindings, expression),
            expression,
        )
    }

    pub(crate) fn abstract_specification_builtin_arithmetic(
        program: &dyn crate::CheckingInput,
        bindings: AbstractSpecificationBindings<'_>,
        expression: ExpressionHandle,
    ) -> bool {
        let Some(binary) = expression_table(program).binary_node(expression) else {
            return false;
        };
        crate::proof_contracts::bound_expression_meaning::builtin_arithmetic_for_operand_types(
            program,
            bindings.owner_symbol,
            expression,
            &[
                abstract_specification_result_type(program, bindings, binary.left),
                abstract_specification_result_type(program, bindings, binary.right),
            ],
        )
    }

    fn abstract_specification_constant_has_builtin_meaning(
        program: &dyn crate::CheckingInput,
        bindings: AbstractSpecificationBindings<'_>,
        expression: ExpressionHandle,
    ) -> bool {
        crate::proof_contracts::bound_expression_meaning::folded_constant_has_builtin_meaning(
            program,
            expression,
            &|expression| abstract_specification_builtin_arithmetic(program, bindings, expression),
        )
    }

    pub(crate) fn abstract_specification_place_type(
        program: &dyn crate::CheckingInput,
        bindings: AbstractSpecificationBindings<'_>,
        expression: ExpressionHandle,
    ) -> Option<TypeReferenceHandle> {
        fn segments(
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
            output: &mut Vec<String>,
        ) -> Option<()> {
            match expression_table(program).expression(expression) {
                ExpressionNode::Name(path) => {
                    output.extend(
                        expression_table(program)
                            .name_path_members(path.members)
                            .iter()
                            .map(ToString::to_string),
                    );
                    Some(())
                }
                ExpressionNode::Member(member) => {
                    segments(program, member.receiver, output)?;
                    output.push(member.member.to_string());
                    Some(())
                }
                ExpressionNode::Borrow(value) => segments(program, value.target, output),
                _ => None,
            }
        }

        fn data_field_type(
            program: &dyn crate::CheckingInput,
            data: &typed_trees::data::DataDefinition,
            name: &str,
        ) -> Option<TypeReferenceHandle> {
            program
                .data_field_named(data, name)
                .map(|field| field.type_reference)
        }

        fn named_data(
            program: &dyn crate::CheckingInput,
            type_reference: TypeReferenceHandle,
        ) -> Option<&typed_trees::data::DataDefinition> {
            let peeled = program
                .type_reference_table
                .peeled_type_reference(type_reference);
            let (symbol, name) = match program.type_reference_table.type_reference(peeled) {
                TypeReferenceNode::Named { symbol, name }
                | TypeReferenceNode::Generic {
                    base_symbol: symbol,
                    base_name: name,
                    ..
                } => (*symbol, name),
                _ => return None,
            };
            if symbol.is_valid() {
                return crate::declarations::data_queries::data_definition_by_symbol(
                    program, symbol,
                );
            }
            let mut candidates = program
                .data_definitions()
                .iter()
                .filter(|data| data.name.as_str() == name.as_str());
            let first = candidates.next()?;
            candidates.next().is_none().then_some(first)
        }

        if let Some(domain) = bindings.domain {
            fn domain_place_type(
                program: &dyn crate::CheckingInput,
                domain: &typed_trees::domain::DomainDefinition,
                expression: ExpressionHandle,
            ) -> Option<TypeReferenceHandle> {
                if let Some(reference) =
                    crate::exact_domain_subject_type(program, domain, expression)
                {
                    return Some(reference);
                }
                match expression_table(program).expression(expression) {
                    ExpressionNode::Borrow(borrow) => {
                        domain_place_type(program, domain, borrow.target)
                    }
                    ExpressionNode::Member(member) => {
                        let reference = domain_place_type(program, domain, member.receiver)?;
                        let data = named_data(program, reference)?;
                        crate::value_custody::places::exact_data_member_field(
                            program,
                            data,
                            member.member_symbol,
                            member.member.as_str(),
                            None,
                        )
                        .map(|field| field.type_reference)
                    }
                    _ => None,
                }
            }
            if let Some(reference) = domain_place_type(program, domain, expression) {
                return Some(reference);
            }
        }
        let mut path = Vec::new();
        segments(program, expression, &mut path)?;
        let (mut type_reference, consumed) = match path.as_slice() {
            [name, ..] if language_core::is_reserved_result(name) => (bindings.result_type?, 1),
            [name, ..] if is_self_receiver(name) => {
                if bindings.data.is_some() {
                    let field = path.get(1)?;
                    (data_field_type(program, bindings.data?, field)?, 2)
                } else {
                    return None;
                }
            }
            [name, ..] => {
                if let Some(parameter) = bindings.parameters.iter().find(|parameter| {
                    parameter.name.as_str() == name.as_str()
                        || (parameter.symbol.is_valid()
                            && matches!(expression_table(program).expression(expression),
                            ExpressionNode::Name(path) if path.symbol == parameter.symbol))
                }) {
                    (parameter.type_reference, 1)
                } else {
                    (data_field_type(program, bindings.data?, name)?, 1)
                }
            }
            [] => return None,
        };

        for field in &path[consumed..] {
            type_reference = data_field_type(program, named_data(program, type_reference)?, field)?;
        }
        Some(type_reference)
    }

    pub(crate) fn abstract_specification_interval(
        program: &dyn crate::CheckingInput,
        bindings: AbstractSpecificationBindings<'_>,
        environment: &ValueEnvironment,
        expression: ExpressionHandle,
    ) -> Option<Interval> {
        if let Some(literal) = literal_i64(program, expression)
            && abstract_specification_constant_has_builtin_meaning(program, bindings, expression)
        {
            return Some(Interval::constant(literal));
        }
        let type_reference = abstract_specification_result_type(program, bindings, expression)?;
        let primitive = program.primitive_type_reference(type_reference)?;
        place_path(program, expression)
            .and_then(|path| environment.get(&path))
            .or_else(|| range_constraint_interval(program, type_reference))
            .or_else(|| primitive_range(primitive))
    }

    fn validate_abstract_numeric_coercion(
        program: &dyn crate::CheckingInput,
        bindings: AbstractSpecificationBindings<'_>,
        environment: &ValueEnvironment,
        operand: ExpressionHandle,
        target_reference: TypeReferenceHandle,
        owner: &str,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        let Some(target) = program.primitive_type_reference(target_reference) else {
            return;
        };
        let result_type =
            |expression| abstract_specification_result_type(program, bindings, expression);
        let mut source =
            result_type(operand).and_then(|reference| program.primitive_type_reference(reference));
        let mut source_interval =
            abstract_specification_interval(program, bindings, environment, operand)
                .or_else(|| source.and_then(primitive_range));
        let anonymous = if primitive_range(target).is_some() {
            validate_anonymous_integer_primitive_range(program, target, operand, owner, diagnostics)
        } else {
            None
        };
        if let Some((interval, primitive, _)) = anonymous {
            source = primitive;
            source_interval = Some(interval);
        }
        let float_bounds = |expression| {
            super::float_source_bounds(
                program,
                bindings.owner_symbol,
                environment,
                expression,
                &result_type,
            )
        };
        let integer_bounds = || {
            super::integer_ranges::integer_source_bounds_from_interval(
                program,
                environment,
                operand,
                source?,
                source_interval?,
            )
        };

        if anonymous.is_some() {
            return;
        }
        if let Some(proven) = source.and_then(|source| {
            crate::value_custody::expression_types::float_coercion_preserves_denotation(
                source,
                target,
                || float_bounds(operand),
                integer_bounds,
            )
        }) {
            if !proven {
                diagnostics.push(Diagnostic::error(format!(
                "Exact numeric cast in {owner} to `{}` is not provably denotation preserving; \
                 prove source integrality and exact representability independently or use a named numeric conversion",
                primitive_name(target),
            )).with_source_span(expression_table(program).source_span(operand)));
            }
            return;
        }
        if primitive_range(target).is_none() {
            return;
        }
        let fits = source.is_some_and(|source| {
            source == PrimitiveType::Bool
                || source_interval.is_some_and(|interval| {
                    integer_interval_fits_primitive(interval, source, target)
                })
        });
        if !fits {
            diagnostics.push(Diagnostic::error(format!(
            "Exact integer cast in {owner} to `{}` is not provably representable; \
             constrain the source with an independently accepted prior fact or use a named numeric conversion",
            primitive_name(target),
        )).with_source_span(expression_table(program).source_span(operand)));
        }
    }

    fn validate_abstract_exact_policy_erasure_formation(
        program: &dyn crate::CheckingInput,
        expression: ExpressionHandle,
        owner: &str,
        bindings: AbstractSpecificationBindings<'_>,
        environment: &ValueEnvironment,
        diagnostics: &mut Vec<Diagnostic>,
    ) {
        fn direct_operand(
            program: &dyn crate::CheckingInput,
            bindings: AbstractSpecificationBindings<'_>,
            environment: &ValueEnvironment,
            expression: ExpressionHandle,
        ) -> Option<(Option<PrimitiveType>, Interval, bool)> {
            if let Some(literal) = literal_i64(program, expression)
                && abstract_specification_constant_has_builtin_meaning(
                    program, bindings, expression,
                )
            {
                return Some((None, Interval::constant(literal), false));
            }
            let (type_reference, place, erased) = match expression_table(program)
                .expression(expression)
            {
                ExpressionNode::Cast(cast)
                    if !cast.form.is_recast()
                        && cast.semantic_domain.is_empty()
                        && cast.domain == ArithmeticDomain::Exact =>
                {
                    let source_type =
                        abstract_specification_result_type(program, bindings, cast.value)?;
                    if program.arithmetic_domain_for_type_reference(source_type)
                        == ArithmeticDomain::Exact
                    {
                        return None;
                    }
                    let source_primitive = program.primitive_type_reference(source_type)?;
                    let target_primitive = program.primitive_type_reference(cast.target_type)?;
                    if source_primitive != target_primitive {
                        return None;
                    }
                    (source_type, cast.value, true)
                }
                _ => {
                    let type_reference =
                        abstract_specification_result_type(program, bindings, expression)?;
                    if program.arithmetic_domain_for_type_reference(type_reference)
                        != ArithmeticDomain::Exact
                    {
                        return None;
                    }
                    (type_reference, expression, false)
                }
            };
            let primitive = program.primitive_type_reference(type_reference)?;
            let interval = place_path(program, place)
                .and_then(|path| environment.get(&path))
                .or_else(|| range_constraint_interval(program, type_reference))
                .or_else(|| primitive_range(primitive))?;
            Some((Some(primitive), interval, erased))
        }

        let mut check = |expression, binary: &typed_trees::expression::TableBinaryExpression| {
            if !abstract_specification_builtin_arithmetic(program, bindings, expression) {
                return;
            }
            let Some((left_primitive, left, left_erased)) =
                direct_operand(program, bindings, environment, binary.left)
            else {
                return;
            };
            let Some((right_primitive, right, right_erased)) =
                direct_operand(program, bindings, environment, binary.right)
            else {
                return;
            };
            if !left_erased && !right_erased {
                return;
            }
            let primitive = match (left_primitive, right_primitive) {
                (Some(left), Some(right)) if left != right => return,
                (Some(primitive), _) | (_, Some(primitive)) => primitive,
                (None, None) => return,
            };
            let interval = match binary.operator {
                BinaryOperator::Add => left.add(right),
                BinaryOperator::Subtract => left.subtract(right),
                BinaryOperator::Multiply => left.multiply(right),
                BinaryOperator::ShiftLeft => left.shift_left(right),
                _ => return,
            };
            if let Some(range) = primitive_range(primitive)
                && !range.contains(interval)
            {
                diagnostics.push(Diagnostic::error(format!(
                "exact arithmetic in {owner} may overflow `{}`: explicit same-carrier policy erasure retains the ordinary representability obligation, which must be discharged by prior facts",
                primitive_name(primitive),
            )));
            }
        };
        super::visit_binary_operators(
            program,
            expression,
            &[
                BinaryOperator::Add,
                BinaryOperator::Subtract,
                BinaryOperator::Multiply,
                BinaryOperator::ShiftLeft,
            ],
            &mut check,
        );
    }

    fn narrow_abstract_specification_environment(
        program: &dyn crate::CheckingInput,
        bindings: AbstractSpecificationBindings<'_>,
        environment: &mut ValueEnvironment,
        expression: ExpressionHandle,
    ) {
        let source_type =
            |expression| abstract_specification_result_type(program, bindings, expression);
        let Some(comparison) = crate::proof_contracts::bound_expression_meaning::guard_comparison(
            program,
            bindings.owner_symbol,
            expression,
            &source_type,
        ) else {
            return;
        };
        if comparison.operator == BinaryOperator::And {
            narrow_abstract_specification_environment(
                program,
                bindings,
                environment,
                comparison.left,
            );
            narrow_abstract_specification_environment(
                program,
                bindings,
                environment,
                comparison.right,
            );
            return;
        }
        if crate::proof_contracts::bound_expression_meaning::has_builtin_or_sealed_float_comparison_meaning(
        program, bindings.owner_symbol, expression, comparison.operator,
        &[source_type(comparison.left), source_type(comparison.right)],
    ) && super::float_arithmetic::record_float_comparison_bounds(
        program, environment, &comparison, &source_type,
    ) {
        return;
    }
        if !abstract_specification_constant_has_builtin_meaning(program, bindings, comparison.left)
            || !abstract_specification_constant_has_builtin_meaning(
                program,
                bindings,
                comparison.right,
            )
        {
            return;
        }
        let Some((path, low, high)) = comparison_bound(program, expression) else {
            return;
        };
        let place = if literal_i64(program, comparison.right).is_some() {
            comparison.left
        } else {
            comparison.right
        };
        let Some(type_reference) = abstract_specification_place_type(program, bindings, place)
        else {
            return;
        };
        let mut interval = Interval { low, high };
        if let Some(carrier) = program
            .primitive_type_reference(type_reference)
            .and_then(primitive_range)
        {
            interval = interval.intersect(carrier);
        }
        if let Some(declared) = range_constraint_interval(program, type_reference) {
            interval = interval.intersect(declared);
        }
        environment.narrow(path, interval);
    }

    pub(crate) fn validate_abstract_total_specification_arithmetic(
        program: &dyn crate::CheckingInput,
        diagnostics: &mut Vec<Diagnostic>,
        formation_obligations: &mut Vec<checked_trees::IntegerRangeObligation>,
    ) {
        #[derive(Clone, Copy, PartialEq, Eq)]
        enum FormationPremises {
            None,
            Entry,
            Completion,
        }

        fn validate_facts(
            program: &dyn crate::CheckingInput,
            facts: &[ProofFact],
            owner: &str,
            bindings: AbstractSpecificationBindings<'_>,
            premises: FormationPremises,
            environment: &mut ValueEnvironment,
            prior_facts: &mut Vec<ExpressionHandle>,
            seen: &mut Vec<ExpressionHandle>,
            diagnostics: &mut Vec<Diagnostic>,

            formation_obligations: &mut Vec<checked_trees::IntegerRangeObligation>,
        ) {
            let mut parameters = bindings.parameters.to_vec();
            if let Some(domain) = bindings.domain {
                parameters.extend(program.domain_type_parameters(domain).iter().filter_map(
                    |parameter| {
                        let (typed_trees::data::TypeParameterKind::Const { type_reference }
                        | typed_trees::data::TypeParameterKind::Value { type_reference }) =
                            parameter.kind
                        else {
                            return None;
                        };
                        Some(typed_trees::signature::StateParameter {
                            symbol: parameter.symbol,
                            name: parameter.name.clone(),
                            type_reference,
                            ..Default::default()
                        })
                    },
                ));
                parameters.push(typed_trees::signature::StateParameter {
                    symbol: domain.subject_symbol,
                    name: domain.subject_name.clone(),
                    type_reference: domain.target_type,
                    ..Default::default()
                });
            }
            if let Some(data) = bindings.data {
                if data.predicate_subject_symbol.is_valid()
                    && data.predicate_subject_type.is_valid()
                {
                    parameters.push(typed_trees::signature::StateParameter {
                        symbol: data.predicate_subject_symbol,
                        name: typed_trees::name::Identifier::from("self"),
                        type_reference: data.predicate_subject_type,
                        ..Default::default()
                    });
                }
                parameters.extend(program.data_members(data).iter().filter_map(|member| {
                    let typed_trees::data::DataMember::Field(field) = member else {
                        return None;
                    };
                    Some(typed_trees::signature::StateParameter {
                        symbol: field.symbol,
                        name: field.name.clone(),
                        type_reference: field.type_reference,
                        ..Default::default()
                    })
                }));
            }
            for fact in facts {
                let diagnostics_before = diagnostics.len();
                let obligations_before = formation_obligations.len();
                crate::proof_contracts::contract_entailment::specification_calls::validate_declaration_call_requirements(
                program, bindings.owner_symbol, &parameters, fact, prior_facts, owner, diagnostics,
                formation_obligations,
            );
                crate::proof_contracts::contract_entailment::validate_proof_fact_integer_formation(
                    program,
                    bindings.owner_symbol,
                    fact,
                    prior_facts,
                    owner,
                    &|candidate| {
                        abstract_specification_builtin_arithmetic(program, bindings, candidate)
                    },
                    diagnostics,
                );
                let Some(expression) = fact.as_expression() else {
                    continue;
                };
                if seen.contains(expression) {
                    continue;
                }
                seen.push(*expression);
                crate::value_custody::expression_types::validate_float_expression_formats(
                    program,
                    bindings.owner_symbol,
                    *expression,
                    &|operand| abstract_specification_result_type(program, bindings, operand),
                    diagnostics,
                );
                abstract_shift_count::validate(
                    program,
                    *expression,
                    owner,
                    bindings,
                    environment,
                    diagnostics,
                );
                division_definedness::validate_abstract(
                    program,
                    *expression,
                    owner,
                    bindings,
                    environment,
                    diagnostics,
                );
                validate_abstract_exact_policy_erasure_formation(
                    program,
                    *expression,
                    owner,
                    bindings,
                    environment,
                    diagnostics,
                );
                let expression_domain = |candidate| {
                    abstract_specification_result_type(program, bindings, candidate).map(
                        |type_reference| {
                            program.arithmetic_domain_for_type_reference(type_reference)
                        },
                    )
                };
                let expression_interval = |candidate| {
                    abstract_specification_interval(program, bindings, environment, candidate)
                };
                let builtin_arithmetic = |candidate| {
                    abstract_specification_builtin_arithmetic(program, bindings, candidate)
                };
                let numeric_coercion = |operand, target, diagnostics: &mut Vec<Diagnostic>| {
                    validate_abstract_numeric_coercion(
                        program,
                        bindings,
                        environment,
                        operand,
                        target,
                        owner,
                        diagnostics,
                    );
                };
                validate_total_specification_arithmetic_for_domains(
                    program,
                    *expression,
                    owner,
                    &expression_domain,
                    &expression_interval,
                    &builtin_arithmetic,
                    &numeric_coercion,
                    false,
                    diagnostics,
                );
                if premises != FormationPremises::None
                    && diagnostics.len() == diagnostics_before
                    && (premises != FormationPremises::Completion
                        || formation_obligations.len() == obligations_before)
                {
                    prior_facts.push(*expression);
                    narrow_abstract_specification_environment(
                        program,
                        bindings,
                        environment,
                        *expression,
                    );
                }
            }
        }

        fn validate_contracts(
            program: &dyn crate::CheckingInput,
            contracts: &[typed_trees::signature::SignatureContract],
            owner: &str,
            bindings: AbstractSpecificationBindings<'_>,
            seen: &mut Vec<ExpressionHandle>,
            diagnostics: &mut Vec<Diagnostic>,

            formation_obligations: &mut Vec<checked_trees::IntegerRangeObligation>,
        ) {
            let mut environment = ValueEnvironment::new();
            let mut prior_facts = Vec::new();
            let mut completion_environment = ValueEnvironment::new();
            let mut completion_prior_facts = Vec::new();
            for contract in contracts {
                let contract_owner =
                    format!("{owner} {} contract", contract_kind_name(&contract.kind));
                let requires_before = prior_facts.len();
                let (formation_environment, formation_facts) =
                    if contract.kind == SignatureContractKind::Ensures {
                        (&mut completion_environment, &mut completion_prior_facts)
                    } else {
                        (&mut environment, &mut prior_facts)
                    };
                validate_facts(
                    program,
                    program.proof_facts.span_or_empty(contract.facts),
                    &contract_owner,
                    bindings,
                    match contract.kind {
                        SignatureContractKind::Requires => FormationPremises::Entry,
                        SignatureContractKind::Ensures => FormationPremises::Completion,
                        _ => FormationPremises::None,
                    },
                    formation_environment,
                    formation_facts,
                    seen,
                    diagnostics,
                    formation_obligations,
                );
                if contract.kind == SignatureContractKind::Requires {
                    for &expression in &prior_facts[requires_before..] {
                        completion_prior_facts.push(expression);
                        narrow_abstract_specification_environment(
                            program,
                            bindings,
                            &mut completion_environment,
                            expression,
                        );
                    }
                }
            }
        }

        let mut seen = Vec::new();

        for definition in program.mathematical_definitions() {
            let parameters =
                crate::mathematical_applications::ordinary_parameters(program, definition);
            for expression in
                crate::mathematical_applications::definition_roots(program, definition)
            {
                validate_facts(
                    program,
                    &[ProofFact::Expression(expression)],
                    &format!("mathematical definition `{}`", definition.name),
                    AbstractSpecificationBindings {
                        owner_symbol: definition.symbol,
                        parameters: &parameters,
                        ..Default::default()
                    },
                    FormationPremises::None,
                    &mut ValueEnvironment::new(),
                    &mut Vec::new(),
                    &mut seen,
                    diagnostics,
                    formation_obligations,
                );
            }
        }

        for proposition in program.propositions() {
            use typed_trees::proposition::{PropositionBody, PropositionFormula};
            if let PropositionBody::Transparent {
                proposition: formula,
            } = &proposition.body
            {
                let bindings = AbstractSpecificationBindings {
                    owner_symbol: proposition.symbol,
                    parameters: program.proposition_parameters(proposition),
                    ..Default::default()
                };
                let owner = format!("proposition `{}`", proposition.name);
                let mut environment = ValueEnvironment::new();
                let mut prior_facts = Vec::new();
                let mut validate_term = |expression| {
                    validate_facts(
                        program,
                        &[ProofFact::Expression(expression)],
                        &owner,
                        bindings,
                        FormationPremises::None,
                        &mut environment,
                        &mut prior_facts,
                        &mut seen,
                        diagnostics,
                        formation_obligations,
                    );
                };
                match formula {
                    PropositionFormula::BooleanExpression(expression) => {
                        validate_term(*expression);
                    }
                    PropositionFormula::Application(application) => {
                        for argument in
                            expression_table(program).expression_handles(application.arguments)
                        {
                            validate_term(*argument);
                        }
                    }
                }
            }
        }

        for domain in program.domain_definitions() {
            let mut environment = ValueEnvironment::new();
            let mut prior_facts = Vec::new();
            validate_facts(
                program,
                program.proof_facts(domain),
                &format!("domain `{}` predicate", domain.name),
                AbstractSpecificationBindings {
                    owner_symbol: domain.symbol,
                    domain: Some(domain),
                    ..Default::default()
                },
                FormationPremises::Entry,
                &mut environment,
                &mut prior_facts,
                &mut seen,
                diagnostics,
                formation_obligations,
            );
        }

        for data in program.data_definitions() {
            let mut environment = ValueEnvironment::new();
            let mut prior_facts = Vec::new();
            validate_facts(
                program,
                program.proof_facts.span_or_empty(data.requires_facts),
                &format!("data `{}` default-domain predicate", data.name),
                AbstractSpecificationBindings {
                    owner_symbol: data.symbol,
                    data: Some(data),
                    ..Default::default()
                },
                FormationPremises::Entry,
                &mut environment,
                &mut prior_facts,
                &mut seen,
                diagnostics,
                formation_obligations,
            );
            for member in program.data_members(data) {
                let typed_trees::data::DataMember::Variant(variant) = member else {
                    continue;
                };
                let payload = program
                    .data_payload_fields(variant)
                    .iter()
                    .map(|field| typed_trees::signature::StateParameter {
                        symbol: field.symbol,
                        name: field.name.clone(),
                        type_reference: field.type_reference,
                        ..Default::default()
                    })
                    .collect::<Vec<_>>();
                validate_facts(
                    program,
                    program.proof_facts.span_or_empty(variant.requires_facts),
                    &format!("data `{}` case `{}` predicate", data.name, variant.name),
                    AbstractSpecificationBindings {
                        owner_symbol: variant.symbol,
                        parameters: &payload,
                        data: Some(data),
                        ..Default::default()
                    },
                    FormationPremises::Entry,
                    &mut environment.clone(),
                    &mut prior_facts.clone(),
                    &mut seen,
                    diagnostics,
                    formation_obligations,
                );
            }
        }

        fn validate_state_signature(
            program: &dyn crate::CheckingInput,
            signature: &typed_trees::signature::StateSignature,
            owner: String,
            seen: &mut Vec<ExpressionHandle>,
            diagnostics: &mut Vec<Diagnostic>,

            formation_obligations: &mut Vec<checked_trees::IntegerRangeObligation>,
        ) {
            validate_contracts(
                program,
                program.state_signature_contracts(signature),
                &owner,
                AbstractSpecificationBindings {
                    owner_symbol: signature.symbol,
                    parameters: program.state_signature_parameters(signature),
                    result_type: signature
                        .return_type
                        .is_valid()
                        .then_some(signature.return_type),
                    ..Default::default()
                },
                seen,
                diagnostics,
                formation_obligations,
            );
        }

        for trait_definition in program.traits() {
            for signature in program.trait_machine_signatures(trait_definition) {
                validate_state_signature(
                    program,
                    signature,
                    format!(
                        "trait `{}` state `{}`",
                        trait_definition.name, signature.name
                    ),
                    &mut seen,
                    diagnostics,
                    formation_obligations,
                );
            }
        }

        for (parameter, signature) in
            crate::proof_contracts::contract_results::machine_parameter_contract_signatures(program)
        {
            validate_state_signature(
                program,
                signature,
                format!("machine-parameter requirement `{}`", parameter.name),
                &mut seen,
                diagnostics,
                formation_obligations,
            );
        }

        for operator in program.all_operators() {
            let name = program.operator_path_string(operator.name);
            validate_contracts(
                program,
                program.operator_contracts(operator),
                &format!("operator `{name}`"),
                AbstractSpecificationBindings {
                    owner_symbol: operator.symbol,
                    parameters: program.operator_parameters(operator),
                    result_type: operator
                        .return_type
                        .is_valid()
                        .then_some(operator.return_type),
                    ..Default::default()
                },
                &mut seen,
                diagnostics,
                formation_obligations,
            );
        }
    }

    pub(crate) fn direct_abstract_operand(
        program: &dyn crate::CheckingInput,
        bindings: AbstractSpecificationBindings<'_>,
        expression: ExpressionHandle,
    ) -> Option<(PrimitiveType, ArithmeticDomain)> {
        let type_reference = abstract_specification_result_type(program, bindings, expression)?;
        Some((
            program.primitive_type_reference(type_reference)?,
            program.arithmetic_domain_for_type_reference(type_reference),
        ))
    }
}
pub(crate) mod unsigned_representability {
    use super::{BinaryOperator, Interval};

    pub(crate) fn divide_interval(
        left: Interval,
        right: Interval,
        left_known: Option<u64>,
        right_known: Option<u64>,
    ) -> Interval {
        let (Some((left_low, left_high)), Some((right_low, right_high))) = (
            value_bounds(left, left_known),
            value_bounds(right, right_known),
        ) else {
            return Interval::UNBOUNDED;
        };
        if right_low == 0 {
            return Interval::UNBOUNDED;
        }
        let low = left_low / right_high;
        let high = left_high / right_low;
        Interval {
            low: Some(i64::try_from(low).unwrap_or(i64::MAX)),
            high: i64::try_from(high).ok(),
        }
    }

    pub(crate) fn binary_fits(
        operator: BinaryOperator,
        left: Interval,
        right: Interval,
        left_known: Option<u64>,
        right_known: Option<u64>,
    ) -> bool {
        let Some((left_low, left_high)) = value_bounds(left, left_known) else {
            return false;
        };
        if operator == BinaryOperator::ShiftLeft && right_known.is_none() && right.low.is_none() {
            return false;
        }
        let Some((right_low, right_high)) = value_bounds(right, right_known) else {
            return false;
        };
        let maximum = u128::from(u64::MAX);
        match operator {
            BinaryOperator::Add => left_high
                .checked_add(right_high)
                .is_some_and(|high| high <= maximum),
            BinaryOperator::Subtract => left_low >= right_high,
            BinaryOperator::Multiply => left_high
                .checked_mul(right_high)
                .is_some_and(|high| high <= maximum),
            BinaryOperator::ShiftLeft => {
                if right_low >= 64 || right_high >= 64 {
                    return false;
                }
                left_high
                    .checked_shl(right_high as u32)
                    .is_some_and(|high| high <= maximum)
            }
            _ => false,
        }
    }

    fn value_bounds(interval: Interval, known: Option<u64>) -> Option<(u128, u128)> {
        if let Some(known) = known {
            let known = u128::from(known);
            return Some((known, known));
        }
        let low = match interval.low {
            Some(low) => u128::try_from(low).ok()?,
            None => 0,
        };
        let high = match interval.high {
            Some(high) => u128::try_from(high).ok()?,
            None => u128::from(u64::MAX),
        };
        (low <= high && high <= u128::from(u64::MAX)).then_some((low, high))
    }
}
pub(crate) mod value_environment {

    use super::{ExpressionHandle, Interval, Machine, State, ordered_values};
    use crate::proof_contracts::arithmetic_domains::place_paths::{
        canonical_path_pair, place_path_pair, place_paths_overlap,
    };
    use ordered_values::Operand;
    use std::collections::{BTreeMap, BTreeSet};

    #[derive(Debug, Clone, PartialEq)]
    pub(crate) struct StoredIntegerRange {
        pub place: crate::value_custody::places::CanonicalPlace,
        pub path: String,
        pub recipe: checked_trees::IntegerRangeRecipe,
    }

    #[derive(Debug, Clone, Copy, PartialEq)]
    pub(crate) struct FloatInterval {
        pub(crate) low: Option<f64>,
        pub(crate) high: Option<f64>,
    }

    impl FloatInterval {
        pub(crate) const UNBOUNDED: FloatInterval = FloatInterval {
            low: None,
            high: None,
        };

        pub(crate) fn intersect(self, other: FloatInterval) -> FloatInterval {
            FloatInterval {
                low: match (self.low, other.low) {
                    (Some(left), Some(right)) => Some(left.max(right)),
                    (left, right) => left.or(right),
                },
                high: match (self.high, other.high) {
                    (Some(left), Some(right)) => Some(left.min(right)),
                    (left, right) => left.or(right),
                },
            }
        }

        pub(crate) fn union(self, other: FloatInterval) -> FloatInterval {
            FloatInterval {
                low: self.low.zip(other.low).map(|(left, right)| left.min(right)),
                high: self
                    .high
                    .zip(other.high)
                    .map(|(left, right)| left.max(right)),
            }
        }
    }

    #[derive(Debug, Clone, PartialEq)]
    pub(crate) struct ElementPlace {
        pub(crate) collection: String,
        pub(crate) index: Operand,
    }

    #[derive(Debug, Clone, PartialEq)]
    pub(crate) struct FloatElementFact {
        pub(crate) place: ElementPlace,
        pub(crate) interval: FloatInterval,
        pub(crate) non_nan: bool,
    }

    impl FloatElementFact {
        fn narrow(
            facts: &mut Vec<Self>,
            place: ElementPlace,
            interval: FloatInterval,
            non_nan: bool,
        ) {
            match facts.iter_mut().find(|fact| fact.place == place) {
                Some(fact) => {
                    fact.interval = fact.interval.intersect(interval);
                    fact.non_nan |= non_nan;
                }
                None => facts.push(Self {
                    place,
                    interval,
                    non_nan,
                }),
            }
        }

        fn intersect(left: &[Self], right: &[Self]) -> Vec<Self> {
            left.iter()
                .filter_map(|fact| {
                    let other = right.iter().find(|other| other.place == fact.place)?;
                    Some(Self {
                        place: fact.place.clone(),
                        interval: fact.interval.union(other.interval),
                        non_nan: fact.non_nan && other.non_nan,
                    })
                })
                .collect()
        }
    }

    pub(crate) fn rebound_paths(path: &str, bindings: &[(String, String)]) -> Vec<String> {
        bindings
            .iter()
            .filter_map(|(source, target)| {
                if path == source {
                    Some(target.clone())
                } else {
                    path.strip_prefix(source)
                        .filter(|suffix| suffix.starts_with('.') || suffix.starts_with('['))
                        .map(|suffix| format!("{target}{suffix}"))
                }
            })
            .collect()
    }

    #[derive(Debug, Default, Clone, PartialEq)]
    pub(crate) struct ValueEnvironment {
        pub(crate) numeric_observations: StatementNumericObservations,
        pub(crate) integer_ranges: Vec<StoredIntegerRange>,
        pub(crate) boolean_values: Vec<super::guard_narrowing::BooleanValue>,
        pub(crate) ordered_values: Vec<ordered_values::Relation>,
        pub(crate) intervals: BTreeMap<String, Interval>,
        pub(crate) known_u64_values: BTreeMap<String, u64>,
        pub(crate) float_intervals: BTreeMap<String, FloatInterval>,
        pub(crate) non_nan: BTreeSet<String>,
        pub(crate) float_aliases: BTreeSet<(String, String)>,
        pub(crate) float_elements: Vec<FloatElementFact>,
        pub(crate) joint_subtract_bounds: BTreeSet<(String, String)>,
        pub(crate) signed_joint_subtract_lower_bounds: BTreeSet<(String, String)>,
        pub(crate) signed_joint_subtract_upper_bounds: BTreeSet<(String, String)>,
        pub(crate) joint_multiply_bounds: BTreeSet<(String, String)>,
        pub(crate) signed_joint_multiply_lower_bounds: BTreeSet<(String, String)>,
        pub(crate) signed_joint_multiply_upper_bounds: BTreeSet<(String, String)>,
        pub(crate) signed_joint_multiply_negation_bounds: BTreeSet<String>,
    }

    #[derive(Debug, Default, Clone, PartialEq)]
    pub(crate) struct StatementNumericObservations {
    state: symbols::SymbolHandle,
    statement_index: usize,
    scalar_values: Vec<crate::CapturedScalarObservation>,
    pub(crate) integer_operations: Vec<crate::CapturedIntegerOperation>,
    pub(crate) scalar_associations:
        Vec<crate::proof_contracts::contract_entailment::numeric_observations::CapturedScalarAssociation>,
    }

    #[derive(Debug, Default, Clone, PartialEq)]
    pub(crate) struct IeeeConditionalFacts {
        pub(crate) intervals: BTreeMap<String, FloatInterval>,
        pub(crate) non_nan: BTreeSet<String>,
        pub(crate) aliases: BTreeSet<(String, String)>,
        pub(crate) elements: Vec<FloatElementFact>,
    }

    impl IeeeConditionalFacts {
        pub(crate) fn is_empty(&self) -> bool {
            self.intervals.is_empty()
                && self.non_nan.is_empty()
                && self.aliases.is_empty()
                && self.elements.is_empty()
        }

        fn connect_float_aliases(&mut self, left: &[String], right: &[String]) {
            let paths = || left.iter().chain(right);
            let interval = paths()
                .filter_map(|path| self.intervals.get(path).copied())
                .reduce(FloatInterval::intersect);
            let is_non_nan = paths().any(|path| self.non_nan.contains(path));
            if let Some(interval) = interval {
                for path in paths() {
                    self.intervals.insert(path.clone(), interval);
                }
            }
            if is_non_nan {
                self.non_nan.extend(paths().cloned());
            }
            for left in left {
                for right in right {
                    self.aliases
                        .insert(canonical_path_pair(left.clone(), right.clone()));
                }
            }
        }

        pub(crate) fn apply_to(&self, environment: &mut ValueEnvironment) {
            for (left, right) in &self.aliases {
                environment.mark_float_alias(left.clone(), right.clone());
            }
            for (path, interval) in &self.intervals {
                environment.narrow_float(path.clone(), *interval);
            }
            for path in &self.non_nan {
                environment.mark_non_nan(path.clone());
            }
            for fact in &self.elements {
                FloatElementFact::narrow(
                    &mut environment.float_elements,
                    fact.place.clone(),
                    fact.interval,
                    fact.non_nan,
                );
            }
        }

        pub(crate) fn retain(&mut self, keep_path: impl Fn(&str) -> bool) {
            self.intervals.retain(|path, _| keep_path(path));
            self.non_nan.retain(|path| keep_path(path));
            self.aliases
                .retain(|(left, right)| keep_path(left) && keep_path(right));
        }

        pub(crate) fn retain_elements(&mut self, keep: impl Fn(&ElementPlace) -> bool) {
            self.elements.retain(|fact| keep(&fact.place));
        }

        fn intersect(&self, other: &Self) -> Self {
            let mut joined = Self::default();
            for (path, interval) in &self.intervals {
                if let Some(other_interval) = other.intervals.get(path) {
                    joined
                        .intervals
                        .insert(path.clone(), interval.union(*other_interval));
                }
            }
            joined.non_nan = self.non_nan.intersection(&other.non_nan).cloned().collect();
            joined.aliases = self.aliases.intersection(&other.aliases).cloned().collect();
            joined.elements = FloatElementFact::intersect(&self.elements, &other.elements);
            joined
        }

        pub(crate) fn rebound(&self, paths: &impl Fn(&str) -> Vec<String>) -> Self {
            let mut rebound = Self::default();
            for (path, interval) in &self.intervals {
                for path in paths(path) {
                    rebound.intervals.insert(path, *interval);
                }
            }
            for path in &self.non_nan {
                rebound.non_nan.extend(paths(path));
            }
            for (left, right) in &self.aliases {
                for left in paths(left) {
                    for right in paths(right) {
                        rebound
                            .aliases
                            .insert(canonical_path_pair(left.clone(), right));
                    }
                }
            }
            rebound
        }
    }

    impl ValueEnvironment {
        pub(crate) fn clear_numeric_observations(&mut self) {
            self.numeric_observations = StatementNumericObservations::default();
        }

        pub(crate) fn prepare_numeric_observations(
            &mut self,
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: &State,
            statement_index: usize,
        ) {
            self.clear_numeric_observations();
            let observations = crate::captured_numeric_observations(
                program,
                machine,
                state,
                statement_index,
                false,
                crate::NumericObservationDemand {
                    scalar_values: crate::ScalarObservationDemand::Statement,
                    integer_operations: true,
                    scalar_associations: true,
                },
            );
            self.numeric_observations = StatementNumericObservations {
                state: state.symbol,
                statement_index,
                scalar_values: observations.scalar_values,
                integer_operations: observations.integer_operations,
                scalar_associations: observations.scalar_associations,
            };
        }

        pub(crate) fn captured_integer_interval(
            &self,
            state: symbols::SymbolHandle,
            expression: ExpressionHandle,
        ) -> Option<Interval> {
            if !state.is_valid() || self.numeric_observations.state != state {
                return None;
            }
            let observation = self
                .numeric_observations
                .scalar_values
                .iter()
                .find(|value| value.expression == expression)?;
            let crate::ScopedArithmeticValue::Integer(value) = &observation.value else {
                return None;
            };
            let value = value.to_i64()?;
            Some(Interval {
                low: Some(value),
                high: Some(value),
            })
        }

        pub(crate) fn range_recipe(
            &self,
            program: &dyn crate::CheckingInput,
            expression: ExpressionHandle,
        ) -> Option<&checked_trees::IntegerRangeRecipe> {
            let place =
                crate::value_custody::places::canonical_place_from_expression(program, expression)?;
            self.integer_ranges
                .iter()
                .find(|value| value.place == place)
                .map(|value| &value.recipe)
        }
        pub(crate) fn rebind(&self, bindings: &[(String, String)]) -> Self {
            let paths = |path: &str| rebound_paths(path, bindings);
            let mut rebound = Self::new();
            macro_rules! maps {
            ($($field:ident),* $(,)?) => {$(
                for (path, value) in &self.$field {
                    for path in paths(path) { rebound.$field.insert(path, *value); }
                }
            )*};
        }
            macro_rules! sets {
            ($($field:ident),* $(,)?) => {$(
                for path in &self.$field { rebound.$field.extend(paths(path)); }
            )*};
        }
            macro_rules! pairs {
            ($canonical:literal; $($field:ident),* $(,)?) => {$(
                for (left, right) in &self.$field {
                    for left in paths(left) {
                        for right in paths(right) {
                            let pair = if $canonical { canonical_path_pair(left.clone(), right) }
                                else { (left.clone(), right) };
                            rebound.$field.insert(pair);
                        }
                    }
                }
            )*};
        }
            maps!(intervals, known_u64_values, float_intervals);
            sets!(non_nan, signed_joint_multiply_negation_bounds);
            pairs!(true;
            float_aliases, joint_multiply_bounds, signed_joint_multiply_lower_bounds,
            signed_joint_multiply_upper_bounds);
            pairs!(false; joint_subtract_bounds, signed_joint_subtract_lower_bounds,
            signed_joint_subtract_upper_bounds);
            rebound
        }

        pub(crate) fn copy_path_facts(&mut self, source: &str, target: &str) {
            let rebound = self.rebind(&[(source.to_owned(), target.to_owned())]);
            for (path, interval) in rebound.intervals {
                self.narrow(path, interval);
            }
            for (path, interval) in rebound.float_intervals {
                self.narrow_float(path, interval);
            }
            self.known_u64_values.extend(rebound.known_u64_values);
            self.non_nan.extend(rebound.non_nan);
            self.float_aliases.extend(rebound.float_aliases);
            self.joint_subtract_bounds
                .extend(rebound.joint_subtract_bounds);
            self.signed_joint_subtract_lower_bounds
                .extend(rebound.signed_joint_subtract_lower_bounds);
            self.signed_joint_subtract_upper_bounds
                .extend(rebound.signed_joint_subtract_upper_bounds);
            self.joint_multiply_bounds
                .extend(rebound.joint_multiply_bounds);
            self.signed_joint_multiply_lower_bounds
                .extend(rebound.signed_joint_multiply_lower_bounds);
            self.signed_joint_multiply_upper_bounds
                .extend(rebound.signed_joint_multiply_upper_bounds);
            self.signed_joint_multiply_negation_bounds
                .extend(rebound.signed_joint_multiply_negation_bounds);
        }

        pub(crate) fn new() -> Self {
            Self::default()
        }

        pub(crate) fn clear(&mut self) {
            self.clear_numeric_observations();
            self.integer_ranges.clear();
            self.boolean_values.clear();
            self.intervals.clear();
            self.known_u64_values.clear();
            self.float_intervals.clear();
            self.non_nan.clear();
            self.float_aliases.clear();
            self.float_elements.clear();
            self.ordered_values.clear();
            self.clear_joint_relations();
        }

        fn clear_joint_relations(&mut self) {
            self.joint_subtract_bounds.clear();
            self.signed_joint_subtract_lower_bounds.clear();
            self.signed_joint_subtract_upper_bounds.clear();
            self.joint_multiply_bounds.clear();
            self.signed_joint_multiply_lower_bounds.clear();
            self.signed_joint_multiply_upper_bounds.clear();
            self.signed_joint_multiply_negation_bounds.clear();
        }

        pub(crate) fn invalidate_unknown_writes(
            &mut self,
            program: &dyn crate::CheckingInput,
            state: Option<&State>,
        ) {
            let Some(state) = state else {
                self.clear();
                return;
            };
            let mut frozen = BTreeMap::new();
            let mut declaration = |name, immutable, reference| {
                let copied_scalar =
                    immutable && program.primitive_type_reference(reference).is_some();
                frozen
                    .entry(name)
                    .and_modify(|unique| *unique = false)
                    .or_insert(copied_scalar);
            };
            for parameter in program.state_parameters(state) {
                declaration(
                    parameter.name.as_str(),
                    !parameter.is_mutable,
                    parameter.type_reference,
                );
            }
            for statement in program.statement_table.statements(state.statement_nodes) {
                if let Some(local) = statement.as_local_data() {
                    declaration(local.name.as_str(), !local.is_mutable, local.type_reference);
                }
            }
            let retained = |path: &str| frozen.get(path) == Some(&true);
            self.integer_ranges.retain(|value| {
                if !value.place.segments.is_empty() {
                    return false;
                }
                let facts::PlaceRoot::Symbol(symbol) = value.place.root else {
                    return false;
                };
                program
                    .state_parameter_by_symbol(state, symbol)
                    .is_some_and(|parameter| {
                        !parameter.is_mutable
                            && program
                                .primitive_type_reference(parameter.type_reference)
                                .is_some()
                    })
                    || program
                        .state_local_declaration(state, symbol)
                        .is_some_and(|(_, local)| {
                            !local.is_mutable
                                && program
                                    .primitive_type_reference(local.type_reference)
                                    .is_some()
                        })
            });
            self.intervals.retain(|path, _| retained(path));
            self.known_u64_values.retain(|path, _| retained(path));
            self.float_intervals.retain(|path, _| retained(path));
            self.non_nan.retain(|path| retained(path));
            self.float_aliases
                .retain(|(left, right)| retained(left) && retained(right));
            self.float_elements.clear();
            self.ordered_values.retain(|relation| {
                relation.left.is_immutable_snapshot(program, state)
                    && relation.right.is_immutable_snapshot(program, state)
            });
            self.boolean_values.retain_mut(|value| {
                if !value.binding.is_immutable_snapshot(program, state) {
                    return false;
                }
                for alternative in &mut value.alternatives {
                    alternative.relations.retain(|relation| {
                        relation.left.is_immutable_snapshot(program, state)
                            && relation.right.is_immutable_snapshot(program, state)
                    });
                    alternative.ieee.retain(|path| retained(path));
                    alternative.ieee.retain_elements(|_| false);
                }
                true
            });
            self.clear_joint_relations();
        }

        pub(crate) fn invalidate_written_paths(&mut self, written: &[String]) {
            self.invalidate_storage(written, |operand| operand.survives(written));
        }

        pub(crate) fn invalidate_call_paths(
            &mut self,
            program: &dyn crate::CheckingInput,
            state: Option<&State>,
            written: &[String],
        ) {
            if crate::trace_flags::reference_slot_trace() && !written.is_empty() {
                eprintln!(
                    "SLOT invalidation-before state={:?} written={written:?} intervals={:?} relations={:?}",
                    state.map(|state| state.symbol),
                    self.intervals,
                    self.ordered_values
                );
            }
            self.invalidate_storage(written, |operand| {
                operand.survives_storage_writes(program, state, written)
            });
            if crate::trace_flags::reference_slot_trace() && !written.is_empty() {
                eprintln!(
                    "SLOT invalidation-after state={:?} intervals={:?} relations={:?}",
                    state.map(|state| state.symbol),
                    self.intervals,
                    self.ordered_values
                );
            }
        }

        /// Rebinding a saved subject cannot revive any source fact changed by an
        /// earlier evaluated pattern. The prefix owns only completed operands.
        pub(super) fn invalidate_call_prefix(
            &mut self,
            program: &dyn crate::CheckingInput,
            state: Option<&State>,
            prefix: &super::evaluated_writes::EvaluatedWritePrefix,
        ) {
            if prefix.is_unknown() {
                self.invalidate_unknown_writes(program, state);
                return;
            }
            let overlaps = |path: &str| prefix.overlaps(path);
            self.invalidate_storage_by(overlaps, |operand| {
                operand.survives_storage_writes_by(program, state, &overlaps, prefix.is_empty())
            });
        }

        fn invalidate_storage(&mut self, written: &[String], survives: impl Fn(&Operand) -> bool) {
            self.invalidate_storage_by(
                |path| written.iter().any(|write| place_paths_overlap(path, write)),
                survives,
            );
        }

        fn invalidate_storage_by(
            &mut self,
            overlaps: impl Fn(&str) -> bool,
            survives: impl Fn(&Operand) -> bool,
        ) {
            self.boolean_values.retain_mut(|value| {
                if !survives(&value.binding) {
                    return false;
                }
                for alternative in &mut value.alternatives {
                    alternative
                        .relations
                        .retain(|relation| survives(&relation.left) && survives(&relation.right));
                    alternative.ieee.retain(|path| !overlaps(path));
                    alternative.ieee.retain_elements(|place| {
                        !overlaps(&place.collection) && survives(&place.index)
                    });
                }
                true
            });
            self.ordered_values
                .retain(|relation| survives(&relation.left) && survives(&relation.right));
            let keep_pair = |(left, right): &(String, String)| !overlaps(left) && !overlaps(right);
            self.integer_ranges.retain(|value| !overlaps(&value.path));
            self.intervals.retain(|path, _| !overlaps(path));
            self.known_u64_values.retain(|path, _| !overlaps(path));
            self.float_intervals.retain(|path, _| !overlaps(path));
            self.non_nan.retain(|path| !overlaps(path));
            self.float_aliases.retain(keep_pair);
            self.float_elements
                .retain(|fact| !overlaps(&fact.place.collection) && survives(&fact.place.index));
            self.joint_subtract_bounds.retain(keep_pair);
            self.signed_joint_subtract_lower_bounds.retain(keep_pair);
            self.signed_joint_subtract_upper_bounds.retain(keep_pair);
            self.joint_multiply_bounds.retain(keep_pair);
            self.signed_joint_multiply_lower_bounds.retain(keep_pair);
            self.signed_joint_multiply_upper_bounds.retain(keep_pair);
            self.signed_joint_multiply_negation_bounds
                .retain(|value| !overlaps(value));
        }

        pub(crate) fn invalidate_assignment_paths(
            &mut self,
            program: &dyn crate::CheckingInput,
            machine: &Machine,
            state: Option<&State>,
            statement: &typed_trees::statement::StatementNode,
            frames: Option<&crate::CallFrameResolver<'_>>,
            written: &[String],
        ) {
            let prepared_frames = (frames.is_none()
                && (!self.ordered_values.is_empty() || !self.boolean_values.is_empty()))
            .then(|| crate::CallFrameResolver::new(program))
            .flatten();
            let frames = frames.or(prepared_frames.as_ref());
            let storage = (!self.ordered_values.is_empty() || !self.boolean_values.is_empty())
                .then(|| {
                    let target = statement.as_assignment()?.target;
                    crate::place_has_builtin_coordinates(program, machine, state, target)
                        .then_some(())?;
                    frames?.assignment_storage_origins(machine, statement).ok()
                })
                .flatten();
            let reference_read = |operand: &Operand| {
                operand.assignment_reference_read_preserved(
                    program,
                    machine,
                    state,
                    statement,
                    frames,
                    storage.as_ref(),
                )
            };
            self.invalidate_storage(written, |operand| {
                operand.survives_assignment(written, storage.as_ref(), &reference_read)
            });
        }

        pub(crate) fn get(&self, path: &str) -> Option<Interval> {
            self.intervals.get(path).copied()
        }

        pub(crate) fn set(&mut self, path: String, interval: Interval) {
            self.intervals.insert(path, interval);
        }

        pub(crate) fn mark_known_u64(&mut self, path: String, value: u64) {
            self.known_u64_values.insert(path, value);
        }

        pub(crate) fn narrow(&mut self, path: String, interval: Interval) {
            let merged = match self.intervals.get(&path) {
                Some(existing) => existing.intersect(interval),
                None => interval,
            };
            self.intervals.insert(path, merged);
        }

        fn narrow_float_single(&mut self, path: String, interval: FloatInterval) {
            let merged = match self.float_intervals.get(&path) {
                Some(existing) => existing.intersect(interval),
                None => interval,
            };
            self.float_intervals.insert(path, merged);
        }

        pub(crate) fn float_alias_partners<'a>(
            &'a self,
            target: &'a str,
        ) -> impl Iterator<Item = String> + 'a {
            self.float_aliases.iter().filter_map(move |(left, right)| {
                if left == target {
                    Some(right.clone())
                } else if right == target {
                    Some(left.clone())
                } else {
                    None
                }
            })
        }

        pub(crate) fn narrow_float(&mut self, path: String, interval: FloatInterval) {
            let aliases: Vec<String> = self.float_alias_partners(&path).collect();
            self.narrow_float_single(path, interval);
            for alias in aliases {
                self.narrow_float_single(alias, interval);
            }
        }

        pub(crate) fn mark_non_nan(&mut self, path: String) {
            let aliases: Vec<String> = self.float_alias_partners(&path).collect();
            self.non_nan.insert(path);
            self.non_nan.extend(aliases);
        }

        pub(crate) fn mark_float_alias(&mut self, left: String, right: String) {
            if left == right || place_paths_overlap(&left, &right) {
                return;
            }
            let mut left_group = vec![left.clone()];
            left_group.extend(self.float_alias_partners(&left));
            let mut right_group = vec![right.clone()];
            right_group.extend(self.float_alias_partners(&right));
            for left_member in &left_group {
                for right_member in &right_group {
                    if left_member != right_member
                        && !place_paths_overlap(left_member, right_member)
                    {
                        self.float_aliases.insert(canonical_path_pair(
                            left_member.clone(),
                            right_member.clone(),
                        ));
                    }
                }
            }
            for value in &mut self.boolean_values {
                for facts in &mut value.alternatives {
                    facts.ieee.connect_float_aliases(&left_group, &right_group);
                }
            }
            let combined_interval = match (
                self.float_intervals.get(&left).copied(),
                self.float_intervals.get(&right).copied(),
            ) {
                (Some(left_interval), Some(right_interval)) => {
                    Some(left_interval.intersect(right_interval))
                }
                (left_interval, right_interval) => left_interval.or(right_interval),
            };
            let is_non_nan = self.non_nan.contains(&left) || self.non_nan.contains(&right);
            if let Some(interval) = combined_interval {
                self.narrow_float(left.clone(), interval);
            }
            if is_non_nan {
                self.mark_non_nan(left);
            }
        }

        pub(crate) fn mark_joint_subtract_bound(&mut self, left: String, right: String) {
            self.joint_subtract_bounds.insert((left, right));
        }

        pub(crate) fn mark_signed_joint_subtract_lower_bound(
            &mut self,
            left: String,
            right: String,
        ) {
            self.signed_joint_subtract_lower_bounds
                .insert((left, right));
        }

        pub(crate) fn mark_signed_joint_subtract_upper_bound(
            &mut self,
            left: String,
            right: String,
        ) {
            self.signed_joint_subtract_upper_bounds
                .insert((left, right));
        }

        pub(crate) fn mark_joint_multiply_bound(&mut self, left: String, right: String) {
            self.joint_multiply_bounds
                .insert(canonical_path_pair(left, right));
        }

        pub(crate) fn mark_signed_joint_multiply_lower_bound(
            &mut self,
            left: String,
            right: String,
        ) {
            self.signed_joint_multiply_lower_bounds
                .insert(canonical_path_pair(left, right));
        }

        pub(crate) fn mark_signed_joint_multiply_upper_bound(
            &mut self,
            left: String,
            right: String,
        ) {
            self.signed_joint_multiply_upper_bounds
                .insert(canonical_path_pair(left, right));
        }

        pub(crate) fn mark_signed_joint_multiply_negation_bound(&mut self, value: String) {
            self.signed_joint_multiply_negation_bounds.insert(value);
        }

        pub(crate) fn proves_joint_subtract_bound(
            &self,
            program: &dyn crate::CheckingInput,
            left: ExpressionHandle,
            right: ExpressionHandle,
        ) -> bool {
            let Some((left, right)) = place_path_pair(program, left, right) else {
                return false;
            };
            self.joint_subtract_bounds.contains(&(left, right))
        }

        pub(crate) fn proves_signed_joint_subtract_lower_bound(
            &self,
            program: &dyn crate::CheckingInput,
            left: ExpressionHandle,
            right: ExpressionHandle,
        ) -> bool {
            let Some((left, right)) = place_path_pair(program, left, right) else {
                return false;
            };
            self.signed_joint_subtract_lower_bounds
                .contains(&(left, right))
        }

        pub(crate) fn proves_signed_joint_subtract_upper_bound(
            &self,
            program: &dyn crate::CheckingInput,
            left: ExpressionHandle,
            right: ExpressionHandle,
        ) -> bool {
            let Some((left, right)) = place_path_pair(program, left, right) else {
                return false;
            };
            self.signed_joint_subtract_upper_bounds
                .contains(&(left, right))
        }

        pub(crate) fn proves_joint_multiply_bound(
            &self,
            program: &dyn crate::CheckingInput,
            left: ExpressionHandle,
            right: ExpressionHandle,
        ) -> bool {
            let Some((left, right)) = place_path_pair(program, left, right) else {
                return false;
            };
            self.joint_multiply_bounds
                .contains(&canonical_path_pair(left, right))
        }

        pub(crate) fn proves_signed_joint_multiply_bounds(
            &self,
            program: &dyn crate::CheckingInput,
            left: ExpressionHandle,
            right: ExpressionHandle,
        ) -> bool {
            let Some((left, right)) = place_path_pair(program, left, right) else {
                return false;
            };
            let pair = canonical_path_pair(left, right);
            self.signed_joint_multiply_lower_bounds.contains(&pair)
                && self.signed_joint_multiply_upper_bounds.contains(&pair)
        }

        pub(crate) fn proves_signed_joint_multiply_negation_bound(
            &self,
            program: &dyn crate::CheckingInput,
            left: ExpressionHandle,
            right: ExpressionHandle,
        ) -> bool {
            for (value, factor) in [(left, right), (right, left)] {
                let Some((value, factor)) = place_path_pair(program, value, factor) else {
                    continue;
                };
                let factor_is_negative_one = self
                    .get(&factor)
                    .is_some_and(|interval| interval.low == Some(-1) && interval.high == Some(-1));
                if self.signed_joint_multiply_negation_bounds.contains(&value)
                    && factor_is_negative_one
                {
                    return true;
                }
            }
            false
        }

        pub(crate) fn float_fact(&self, path: &str) -> (FloatInterval, bool) {
            (
                self.float_intervals
                    .get(path)
                    .copied()
                    .unwrap_or(FloatInterval::UNBOUNDED),
                self.non_nan.contains(path),
            )
        }

        pub(crate) fn float_element_fact(&self, place: &ElementPlace) -> (FloatInterval, bool) {
            self.float_elements
                .iter()
                .find(|fact| fact.place == *place)
                .map_or((FloatInterval::UNBOUNDED, false), |fact| {
                    (fact.interval, fact.non_nan)
                })
        }

        pub(crate) fn narrow_float_element(
            &mut self,
            place: ElementPlace,
            interval: FloatInterval,
        ) {
            FloatElementFact::narrow(&mut self.float_elements, place, interval, false);
        }

        pub(crate) fn mark_non_nan_element(&mut self, place: ElementPlace) {
            FloatElementFact::narrow(
                &mut self.float_elements,
                place,
                FloatInterval::UNBOUNDED,
                true,
            );
        }

        pub(crate) fn ieee_conditional_facts(&self) -> IeeeConditionalFacts {
            IeeeConditionalFacts {
                intervals: self.float_intervals.clone(),
                non_nan: self.non_nan.clone(),
                aliases: self.float_aliases.clone(),
                elements: self.float_elements.clone(),
            }
        }

        pub(crate) fn join(&self, other: &ValueEnvironment) -> ValueEnvironment {
            let mut joined = ValueEnvironment::new();
            if self.numeric_observations.state.is_valid()
                && self.numeric_observations == other.numeric_observations
            {
                joined.numeric_observations = self.numeric_observations.clone();
            }
            joined.integer_ranges.extend(
                self.integer_ranges
                    .iter()
                    .filter(|value| {
                        other
                            .integer_ranges
                            .iter()
                            .any(|other| other.place == value.place && other.recipe == value.recipe)
                    })
                    .cloned(),
            );
            for value in &self.boolean_values {
                if let Some(other) = other
                    .boolean_values
                    .iter()
                    .find(|other| other.binding == value.binding)
                {
                    let mut common = value.clone();
                    for (alternative, other) in
                        common.alternatives.iter_mut().zip(&other.alternatives)
                    {
                        alternative
                            .relations
                            .retain(|relation| other.relations.contains(relation));
                        alternative.ieee = alternative.ieee.intersect(&other.ieee);
                    }
                    joined.boolean_values.push(common);
                }
            }
            joined.ordered_values.extend(
                self.ordered_values
                    .iter()
                    .filter(|relation| other.ordered_values.contains(relation))
                    .cloned(),
            );
            for (path, interval) in &self.intervals {
                if let Some(other_interval) = other.intervals.get(path) {
                    joined
                        .intervals
                        .insert(path.clone(), interval.union(*other_interval));
                }
            }
            for (path, value) in &self.known_u64_values {
                if other.known_u64_values.get(path) == Some(value) {
                    joined.known_u64_values.insert(path.clone(), *value);
                }
            }
            for (path, interval) in &self.float_intervals {
                if let Some(other_interval) = other.float_intervals.get(path) {
                    joined
                        .float_intervals
                        .insert(path.clone(), interval.union(*other_interval));
                }
            }
            joined
                .non_nan
                .extend(self.non_nan.intersection(&other.non_nan).cloned());
            joined.float_aliases.extend(
                self.float_aliases
                    .intersection(&other.float_aliases)
                    .cloned(),
            );
            joined.float_elements =
                FloatElementFact::intersect(&self.float_elements, &other.float_elements);
            joined.joint_subtract_bounds.extend(
                self.joint_subtract_bounds
                    .intersection(&other.joint_subtract_bounds)
                    .cloned(),
            );
            joined.signed_joint_subtract_lower_bounds.extend(
                self.signed_joint_subtract_lower_bounds
                    .intersection(&other.signed_joint_subtract_lower_bounds)
                    .cloned(),
            );
            joined.signed_joint_subtract_upper_bounds.extend(
                self.signed_joint_subtract_upper_bounds
                    .intersection(&other.signed_joint_subtract_upper_bounds)
                    .cloned(),
            );
            joined.joint_multiply_bounds.extend(
                self.joint_multiply_bounds
                    .intersection(&other.joint_multiply_bounds)
                    .cloned(),
            );
            joined.signed_joint_multiply_lower_bounds.extend(
                self.signed_joint_multiply_lower_bounds
                    .intersection(&other.signed_joint_multiply_lower_bounds)
                    .cloned(),
            );
            joined.signed_joint_multiply_upper_bounds.extend(
                self.signed_joint_multiply_upper_bounds
                    .intersection(&other.signed_joint_multiply_upper_bounds)
                    .cloned(),
            );
            joined.signed_joint_multiply_negation_bounds.extend(
                self.signed_joint_multiply_negation_bounds
                    .intersection(&other.signed_joint_multiply_negation_bounds)
                    .cloned(),
            );
            joined
        }
    }
}

